local config = {
  str_homestory_800601001_0_dialog_content = "Carleen...",
  str_homestory_800601001_1_dialog_content = "Hola, PlayerName.",
  str_homestory_800601001_2_dialog_content = "Qué estás haciendo, Carleen?",
  str_homestory_800601001_3_dialog_content = "Estoy murmurando para mí mismo.",
  str_homestory_800601001_4_dialog_content = "¿Quieres decir \"orando\"?",
  str_homestory_800601001_5_dialog_content = "...",
  str_homestory_800601001_6_dialog_content = "Sí. Por favor, no te rías de mí.",
  str_homestory_800601001_7_dialog_content = "¿Por qué habría? Es perfectamente normal orar.",
  str_homestory_800601001_8_dialog_content = "Los niños que no pueden sostener una espada rezan a los adultos para que los protejan.",
  str_homestory_800601001_9_dialog_content = "Un paciente moribundo reza a los dioses para que se recupere.",
  str_homestory_800601001_10_dialog_content = "Pero, ¿por qué una persona capaz dependería de las \"oraciones\"?",
  str_homestory_800601001_11_dialog_content = "(Aceptar)",
  str_homestory_800601001_12_dialog_content = "Eso es un poco duro, pero tienes un punto...",
  str_homestory_800601001_13_dialog_content = "Si uno pudiera controlar su propio destino, no tendría por qué depender de nadie más.",
  str_homestory_800601001_14_dialog_content = "Sin embargo, tantas cosas en este mundo están fuera de nuestro control. Su afirmación es correcta, PlayerName.",
  str_homestory_800601001_15_dialog_content = "Destino.",
  str_homestory_800601001_16_dialog_content = "Consideramos todas las cosas que son irreversibles como \"destino\" y nos hace sentir mejor.",
  str_homestory_800601001_17_dialog_content = "Pero para mí, el destino se puede cambiar.",
  str_homestory_800601001_18_dialog_content = "(Discrepar)",
  str_homestory_800601001_19_dialog_content = "¿No es una práctica común en Lumopolis rezar al Dios de la Luz?",
  str_homestory_800601001_20_dialog_content = "Pensé que todos hacían eso, incluyéndote a ti.",
  str_homestory_800601001_21_dialog_content = "Sí, a menudo compartimos nuestros pensamientos y deseos con el Dios de la Luz.",
  str_homestory_800601001_22_dialog_content = "Pero para mí, es solo una forma de buscar consuelo y alivio espiritual.",
  str_homestory_800601001_23_dialog_content = "Después de que terminan las oraciones, las dificultades frente a mí todavía están esperando ser superadas. Esto nunca cambia.",
  str_homestory_800601001_24_dialog_content = "...",
  str_homestory_800601001_25_dialog_content = "Hmm... Cuando pienso en eso, me siento muy afortunado.",
  str_homestory_800601001_26_dialog_content = "¿Afortunado? ¿Porqué es eso?",
  str_homestory_800601001_27_dialog_content = "Porque no estoy solo frente al enemigo.",
  str_homestory_800601001_28_dialog_content = "Estoy súper agradecida de tener todos estos amigos.",
  str_homestory_800601001_29_dialog_content = "¡No puedo estar más de acuerdo! Es nuestra fortuna tenernos unos a otros en este viaje.",
  str_homestory_800601001_30_dialog_content = "Sí.",
  str_homestory_800601001_31_dialog_content = "¿Pareces un poco sentimental hoy?",
  str_homestory_800601001_32_dialog_content = "Creo que es este lugar... Es perfecto para reflexionar.",
  str_homestory_800601001_33_dialog_content = "No a la guerra. No piojosos príncipes y nobles. Todo es tan pacífico y tranquilo.",
  str_homestory_800601001_34_dialog_content = "Te lo dejo. Disfruta de la soledad.",
  str_homestory_800601001_35_dialog_content = "Gracias, PlayerName.",
  str_homestory_800601001_36_dialog_content = "De nada, Carleen.",
  str_homestory_800201001_0_dialog_content = "Saludos Comandante Hiiro.",
  str_homestory_800201001_1_dialog_content = "¿Qué te trajo aquí?",
  str_homestory_800201001_2_dialog_content = "¿También tienes un deseo que hacer?",
  str_homestory_800201001_3_dialog_content = "Ah, sí.",
  str_homestory_800201001_4_dialog_content = "Te vi aquí, así que vine a saludarte.",
  str_homestory_800201001_5_dialog_content = "Bien.",
  str_homestory_800201001_6_dialog_content = "Estás... ¿Meditando?",
  str_homestory_800201001_7_dialog_content = "Yo estoy rezando.<sprite=emo_mojing size=60 />",
  str_homestory_800201001_8_dialog_content = "¡...!",
  str_homestory_800201001_9_dialog_content = "Pareces sorprendido.",
  str_homestory_800201001_10_option_content = "Admitir",
  str_homestory_800201001_11_dialog_content = "Yo... no pensé que rezarías.",
  str_homestory_800201001_12_option_content = "Negar",
  str_homestory_800201001_13_dialog_content = "Es más un shock que una sorpresa...",
  str_homestory_800201001_14_dialog_content = "Eres tan poderoso... No pensé que asuntos triviales te molestarían.",
  str_homestory_800201001_15_dialog_content = "Lo tomaré como un cumplido.",
  str_homestory_800201001_16_dialog_content = "Estoy rezando para mí mismo, no para ningún dios.",
  str_homestory_800201001_17_dialog_content = "orar a ti mismo?",
  str_homestory_800201001_18_dialog_content = "Estoy un poco confundido...",
  str_homestory_800201001_19_dialog_content = "Escuché que mucha gente vendría aquí a orar.",
  str_homestory_800201001_20_dialog_content = "Creo que una oración podría dejar más claro en nuestros corazones lo que realmente queremos.",
  str_homestory_800201001_21_dialog_content = "En otras palabras, orar aquí puede ayudarnos a descubrir nuestros deseos.",
  str_homestory_800201001_22_dialog_content = "Ah... lo tengo.",
  str_homestory_800201001_23_dialog_content = "¿Es como encontrar \"la misión que realmente queremos completar\"?",
  str_homestory_800201001_24_dialog_content = "Exactamente.",
  str_homestory_800201001_25_dialog_content = "Entonces... ¿Lo has encontrado ahora?",
  str_homestory_800201001_26_dialog_content = "Sí.",
  str_homestory_800201001_27_dialog_content = "La \"oración\" no lo dejó tan claro como esperaba... Pero he encontrado mi camino.",
  str_homestory_800201001_28_dialog_content = "¿No sabías qué camino tomar antes?",
  str_homestory_800201001_29_dialog_content = "Siempre ha tenido claro qué camino debo tomar.",
  str_homestory_800201001_30_dialog_content = "Pero no estaba muy seguro de qué camino quería o deseaba mi corazón.",
  str_homestory_800201001_31_dialog_content = "Ahora puedo entender totalmente por qué la gente está tan dispuesta a orar.",
  str_homestory_800201001_32_dialog_content = "Sí...",
  str_homestory_800201001_33_dialog_content = "Para una figura poderosa como Commander Hiiro, orar puede ayudarte a entender las cosas que tu corazón realmente desea...",
  str_homestory_800201001_34_dialog_content = "Para aquellos que luchan por ganarse la vida, las oraciones son su sustento devoto.",
  str_homestory_800201001_35_dialog_content = "Entonces, por eso la Fuente de la Esperanza es esencial.",
  str_homestory_800201001_36_dialog_content = "Usted y Vice trabajado duro para este lugar.",
  str_homestory_800201001_37_dialog_content = "(La conversación de repente se convirtió en una advertencia a un subordinado...)",
  str_homestory_800201001_38_dialog_content = "No perderé más de su precioso tiempo. Ve y reza, PlayerName.",
  str_homestory_800201001_39_dialog_content = "Adiós.",
  str_homestory_800201001_40_dialog_content = "Ah... Sí, Comandante Hiiro!",
  str_homestory_802501001_0_dialog_content = "¿Está recitando un poema?",
  str_homestory_802501001_1_dialog_content = "Nada mal...",
  str_homestory_802501001_2_dialog_content = "¿Nada mal?",
  str_homestory_802501001_3_dialog_content = "Mmm. Tengo que decir...",
  str_homestory_802501001_4_dialog_content = "¡Nada mal! ¡Esta etapa no está nada mal!<sprite=emo_yinfu size=60 />",
  str_homestory_802501001_5_dialog_content = "¿Escenario?",
  str_homestory_802501001_6_dialog_content = "Oye, PlayerName. Tiempo perfecto.",
  str_homestory_802501001_7_dialog_content = "¡Mirar! Una pequeña plaza fuera de la Torre Jacinto...",
  str_homestory_802501001_8_dialog_content = "¿No es esto perfecto para una obra de teatro en movimiento?",
  str_homestory_802501001_9_dialog_content = "PlayerName, no desperdicies esta luz y espacio.",
  str_homestory_802501001_10_dialog_content = "¡Permítanme esta oportunidad de montar un espectáculo legendario aquí mismo!",
  str_homestory_802501001_11_option_content = "Aceptar",
  str_homestory_802501001_12_dialog_content = "Claro... Pero no hagas demasiado ruido...",
  str_homestory_802501001_13_dialog_content = "¡Imposible!",
  str_homestory_802501001_14_dialog_content = "¡Trenes! ¡Llamas! ¡Tazas manchadas de sangre! ¡Metal pesado! ¡Vinilo! ¡Y altavoces!",
  str_homestory_802501001_15_dialog_content = "¡Me aseguraré de que mi obra llegue a todos los rincones de la isla!",
  str_homestory_802501001_16_dialog_content = "... ¿Esto no molestaría a los residentes?",
  str_homestory_802501001_17_dialog_content = "molestar a los residentes? ¿No saben apreciar el arte?",
  str_homestory_802501001_18_dialog_content = "¡Ah, ja, ja! ¡Ese no es el caso!",
  str_homestory_802501001_19_dialog_content = "¡Una pieza independiente a menudo es apreciada por solo unas pocas personas con un interés especial!",
  str_homestory_802501001_20_dialog_content = "Sin embargo, creo que su espectáculo será mejor en la quietud de la noche.",
  str_homestory_802501001_21_dialog_content = "Escuchar, Charon...",
  str_homestory_802501001_22_option_content = "Rechazar",
  str_homestory_802501001_23_dialog_content = "¿Qué debo hacer?",
  str_homestory_802501001_24_dialog_content = "¡Tu frío rechazo acaba de despertar nuevas ideas en mi cabeza!",
  str_homestory_802501001_25_dialog_content = "¡Las ideas entrelazadas están gritando y desgarrando profundamente en mi alma como corceles salvajes!",
  str_homestory_802501001_26_dialog_content = "¿Qué es gruñir? ¡Arte! Una actuación fuera de control...",
  str_homestory_802501001_27_dialog_content = "¡Ahora es el momento! ¡Que este espectáculo resuene en Eraveil!",
  str_homestory_802501001_28_dialog_content = "(Mi rechazo no pareció funcionar en absoluto...)",
  str_homestory_802501001_29_dialog_content = "¿Qué tal otro día?",
  str_homestory_802501001_30_dialog_content = "... ¿Otro día?",
  str_homestory_802501001_31_dialog_content = "Ah... Un estallido de tristeza de repente llenó mi corazón.",
  str_homestory_802501001_32_dialog_content = "PlayerName, has aprendido a ignorar a los demás.",
  str_homestory_802501001_33_dialog_content = "Está bien, consideraré darte un \"papel frío y distante\" en mi programa.",
  str_homestory_802501001_34_dialog_content = "...",
  str_homestory_810501001_0_dialog_content = "Estas tan ocupado, Eve!",
  str_homestory_810501001_1_dialog_content = "¡Qué bueno verte, navegante!<sprite=emo_aixin size=60 />",
  str_homestory_810501001_2_dialog_content = "Estaré contigo en breve. Ahora debo pensar en qué más necesito...",
  str_homestory_810501001_3_dialog_content = "Ah... ¡No te preocupes por mí!",
  str_homestory_810501001_4_dialog_content = "Si estás buscando algo, tal vez pueda ayudarte.",
  str_homestory_810501001_5_dialog_content = "Aww... ¡Has preparado tanto para nosotros!",
  str_homestory_810501001_6_dialog_content = "Quiero hacer algunos regalos.",
  str_homestory_810501001_7_dialog_content = "Estaba pensando en qué color es mejor para una flor bordada o un portavasos.",
  str_homestory_810501001_8_dialog_content = "flor bordada? ¿Posavasos?",
  str_homestory_810501001_9_dialog_content = "Sí.",
  str_homestory_810501001_10_dialog_content = "hice un top para Dawn<sprite=emo_qunzi size=60 />. Me gustaría agregarle algunas flores del amanecer...",
  str_homestory_810501001_11_dialog_content = "Hmm... El portavasos... Sabes que mi hermano siempre lleva una botella de agua para que beba...",
  str_homestory_810501001_12_dialog_content = "Un lindo portavasos sería un buen regalo para él.",
  str_homestory_810501001_13_dialog_content = "Jejeje. Navegante, ¿qué te parece?",
  str_homestory_810501001_14_dialog_content = "¡Fantástico!",
  str_homestory_810501001_15_dialog_content = "Estos son regalos muy considerados. Estoy seguro Dawn y tu hermano sería muy feliz.",
  str_homestory_810501001_16_dialog_content = "¡Sí! Me alegro mucho de escuchar...",
  str_homestory_810501001_17_dialog_content = "Entonces... ¿Qué color debo elegir?",
  str_homestory_810501001_18_dialog_content = "Dawn las flores suelen ser blancas, pero puede ser divertido usar un color diferente...",
  str_homestory_810501001_19_dialog_content = "Para el portavasos, no puedo decidir entre rojo y negro. ¿Cuál le gustaría más al hermano?",
  str_homestory_810501001_20_dialog_content = "Ahh... Es una decisión difícil.",
  str_homestory_810501001_21_dialog_content = "Hmm...",
  str_homestory_810501001_22_dialog_content = "¿De qué color es la parte superior que hiciste para Dawn?",
  str_homestory_810501001_23_dialog_content = "¡Negro!",
  str_homestory_810501001_24_dialog_content = "Creo que las flores blancas del amanecer se verían muy bien en él.",
  str_homestory_810501001_25_dialog_content = "Trate de hacer el patrón levantado sobre la tela para que Dawn puede sentir las flores del amanecer con sus manos.",
  str_homestory_810501001_26_dialog_content = "Flores blancas del amanecer...",
  str_homestory_810501001_27_dialog_content = "Ah... ¡Es una idea fantástica!",
  str_homestory_810501001_28_dialog_content = "Me alegro de poder ser de ayuda.",
  str_homestory_810501001_29_dialog_content = "¿Qué tal el portavasos para mi hermano? Navigator, ¿alguna idea al respecto?",
  str_homestory_810501001_30_option_content = "Si",
  str_homestory_810501001_31_dialog_content = "Si no puede decidir entre los dos colores, ¿por qué no hacer uno a cuadros negro y rojo?",
  str_homestory_810501001_32_dialog_content = "Sin embargo, Eve...",
  str_homestory_810501001_33_option_content = "Realmente no",
  str_homestory_810501001_34_dialog_content = "Para ser sincero, Eve...",
  str_homestory_810501001_35_dialog_content = "Sinsa estará fuera de sí de alegría por cualquier cosa que le regales.",
  str_homestory_810501001_36_dialog_content = "Incluso una hoja al azar o un puñado de arena de ti vale la pena presumir como los tesoros más raros.",
  str_homestory_810501001_37_dialog_content = "Hmm...",
  str_homestory_810501001_38_dialog_content = "Sí estoy de acuerdo con usted...",
  str_homestory_810501001_39_dialog_content = "En este caso, elegiré mi color favorito. Jejeje.",
  str_homestory_810501001_40_dialog_content = "Hmm... Creo que estará bien.",
  str_homestory_810501001_41_dialog_content = "Eve... Estás trabajando tan duro para Dawn y Sinsaregalos de . ¿Algo para ti?",
  str_homestory_810501001_42_dialog_content = "¿Mmm? Lo siento, Navegante. No entiendo...",
  str_homestory_810501001_43_dialog_content = "¿Qué debo preparar para mí?",
  str_homestory_810501001_44_dialog_content = "Ah... quiero decir...",
  str_homestory_810501001_45_dialog_content = "Mirar. Me pediste tierra nutritiva y semillas de flores del amanecer hace un tiempo. Esos eran para Dawn, ¿Correcto?",
  str_homestory_810501001_46_dialog_content = "Para que pueda cultivar flores aquí felizmente.",
  str_homestory_810501001_47_dialog_content = "Y obtuviste algunos refrigerios Rediesel Wrench de Vice porque estabas preocupado Sinsa podría no tener nada para acompañar sus bebidas.",
  str_homestory_810501001_48_dialog_content = "Ah... Navegante, lo sabes todo...",
  str_homestory_810501001_49_dialog_content = "Tienes razón.",
  str_homestory_810501001_50_dialog_content = "Pero...",
  str_homestory_810501001_51_dialog_content = "¿Por qué no preparar algo para ti?",
  str_homestory_810501001_52_dialog_content = "Hmm... preparé esto para Dawn y mi hermano para que pudieran ser más felices aquí.",
  str_homestory_810501001_53_dialog_content = "Ya estoy en la luna estando cerca de ellos todo el tiempo.",
  str_homestory_810501001_54_dialog_content = "Ah... y tú y Vice!",
  str_homestory_810501001_55_dialog_content = "¡Tu presencia me hace feliz!",
  str_homestory_810501001_56_dialog_content = "No necesito preparar nada para mí.",
  str_homestory_810501001_57_dialog_content = "¿Es eso así?.",
  str_homestory_810501001_58_dialog_content = "Eres tan considerado y dulce...",
  str_homestory_810501001_59_dialog_content = "¡Tú también, Navegante!",
  str_homestory_810501001_60_dialog_content = "Boo-hoo...",
  str_homestory_810501001_61_dialog_content = "¿Qué pasa?",
  str_homestory_810501001_62_dialog_content = "Navegante, ¿por qué de repente derramas lágrimas?",
  str_homestory_810501001_63_dialog_content = "*Sollozo* Desearía tener una hermana como Eve...<sprite=emo_daku size=60 />",
  str_homestory_811201001_0_dialog_content = "Smokey?",
  str_homestory_811201001_1_dialog_content = "Qué sucedió, Smokey?",
  str_homestory_811201001_2_dialog_content = "Te ves muy enojado.",
  str_homestory_811201001_3_dialog_content = "Hola, Navegador.",
  str_homestory_811201001_4_dialog_content = "¿No crees que esta tienda tiene una selección de productos demasiado pequeña para ofrecer?<sprite=emo_shengqi size=60 />",
  str_homestory_811201001_5_dialog_content = "¡Ay! ¿Estás enojado con esto?",
  str_homestory_811201001_6_dialog_content = "¿Hay algo en particular que no puedas encontrar aquí? Sólo házmelo saber.",
  str_homestory_811201001_7_dialog_content = "¿Estás seguro de que quieres escuchar?",
  str_homestory_811201001_8_dialog_content = "Sí. Avanzar.",
  str_homestory_811201001_9_dialog_content = "Entonces iré al grano.",
  str_homestory_811201001_10_dialog_content = "En primer lugar, no hay detergente accesorio en absoluto.",
  str_homestory_811201001_11_dialog_content = "Entonces, ¡los botones disponibles en la tienda son absolutamente terribles!",
  str_homestory_811201001_12_dialog_content = "Confía en mí. Nadie querría poner nada de esto en su ropa.",
  str_homestory_811201001_13_dialog_content = "Perdóname. A esos tipos de Illumina les podrían gustar estos en realidad.",
  str_homestory_811201001_14_dialog_content = "Botones... Siempre y cuando haga el trabajo...",
  str_homestory_811201001_15_dialog_content = "No puedo culparte. Después de todo, la mayoría de ustedes no sabe mucho sobre moda.",
  str_homestory_811201001_16_dialog_content = "No te menosprecies a ti mismo. Me tienes aquí.",
  str_homestory_811201001_17_dialog_content = "Gracias...",
  str_homestory_811201001_18_dialog_content = "Además, este lugar es mucho más cálido y soleado que Umbraton.",
  str_homestory_811201001_19_dialog_content = "Veo sombrillas aquí, pero ¿dónde están las sombras y los protectores solares? ¡No tienes ninguno!",
  str_homestory_811201001_20_dialog_content = "Pues tienes razón...",
  str_homestory_811201001_21_dialog_content = "(Smokey no puede ser el único Aurorian que lucha por encontrar lo que necesita aquí.)",
  str_homestory_811201001_22_dialog_content = "(¿Qué debo hacer? Tomará mucho tiempo hablar con ellos uno por uno...)",
  str_homestory_811201001_23_dialog_content = "Oye, ¿qué estás murmurando?",
  str_homestory_811201001_24_dialog_content = "¿Soy demasiado para ti? ¿Le preocupa que pueda haber otros compradores quisquillosos como yo?",
  str_homestory_811201001_25_option_content = "Asentir",
  str_homestory_811201001_26_dialog_content = "Bien. La honestidad es oro.",
  str_homestory_811201001_27_dialog_content = "Estoy más preocupada que preocupada...",
  str_homestory_811201001_28_option_content = "Sacudir la cabeza",
  str_homestory_811201001_29_dialog_content = "No, Smokey, no me molesta en absoluto...",
  str_homestory_811201001_30_dialog_content = "En realidad, problemas o no, no es el punto aquí.",
  str_homestory_811201001_31_dialog_content = "Es posible que haya otras personas que enfrenten un problema similar al tuyo, pero no estoy seguro de cómo abordarlo...",
  str_homestory_811201001_32_dialog_content = "... Necesitas desarrollar un Sistema de Pedidos Eraveil.",
  str_homestory_811201001_33_dialog_content = "Todos pueden registrar los productos que necesitan en el sistema regularmente. Luego, los pedidos se realizan a través de Astra en consecuencia.",
  str_homestory_811201001_34_dialog_content = "Entrega... Apuesto a que puedes descubrir alguna tecnología especial, ¿verdad?",
  str_homestory_811201001_35_dialog_content = "El sindicato de mensajería<sprite=emo_gezitou size=60 />, luciérnagas y tal.",
  str_homestory_811201001_36_dialog_content = "Ah... Buena idea...",
  str_homestory_811201001_37_dialog_content = "De esta manera no es necesario que nos hables uno por uno. Y no recibirás otra queja como la mía.",
  str_homestory_811201001_38_dialog_content = "Sabes que algunos Aurorianos son bastante especiales.",
  str_homestory_811201001_39_dialog_content = "Pueden ser aficionados a los ataúdes, a los pinceles de pintura de todo tipo, a los bichos extraños...",
  str_homestory_811201001_40_dialog_content = "Y algunos de ellos no pueden vivir sin ginebra.",
  str_homestory_811201001_41_dialog_content = "Espera... ¿Dijiste ginebra?",
  str_homestory_811201001_42_dialog_content = "Estas hablando de... Genevieve?",
  str_homestory_811201001_43_dialog_content = "¿Es ella la única a la que le encanta tomar una copa?",
  str_homestory_811201001_44_dialog_content = "... ¡No entiendo cómo funciona tu cerebro!",
  str_homestory_811201001_45_dialog_content = "Vale... Así que no estás hablando de ella. ¡Hay otro gran fanático de la ginebra!",
  str_homestory_811201001_46_dialog_content = "¡Así es! Muchas personas disfrutan de una bebida o dos, ¿de acuerdo?<sprite=emo_nuhuo size=60 />",
  str_homestory_811201001_47_dialog_content = "Claro... ¡No te enfades! Y no prendan fuego a nada...",
  str_homestory_811201001_48_dialog_content = "Hmph.",
  str_homestory_811201001_49_dialog_content = "Gracias, Smokey!",
  str_homestory_811201001_50_dialog_content = "¡Tu consejo es muy útil!",
  str_homestory_811201001_51_dialog_content = "Me tengo que ir. Nos vemos.",
  str_homestory_811201001_52_dialog_content = "¡Nos vemos!",
  str_homestory_807101001_0_dialog_content = "Takicometa...",
  str_homestory_807101001_1_dialog_content = "Ejem... Taki...",
  str_homestory_807101001_2_dialog_content = "¿Eh? PlayerName?",
  str_homestory_807101001_3_dialog_content = "Um... vi tu cometa...",
  str_homestory_807101001_4_dialog_content = "Estaba en el suelo.",
  str_homestory_807101001_5_dialog_content = "... Vaya.",
  str_homestory_807101001_6_dialog_content = "Pero lo recogí rápidamente.",
  str_homestory_807101001_7_dialog_content = "...<sprite=emo_yihuo size=60 />",
  str_homestory_807101001_8_dialog_content = "(Ese no es el punto...)",
  str_homestory_807101001_9_dialog_content = "Bueno. Basado en eso, creo que tu habilidad para volar cometas es...",
  str_homestory_807101001_10_option_content = "¡Bastante bien!",
  str_homestory_807101001_11_dialog_content = "Niño, ¿tratando de dar consuelo?",
  str_homestory_807101001_12_dialog_content = "Ejem... Sólo quería ser de apoyo...",
  str_homestory_807101001_13_dialog_content = "Entendido, pero los elogios falsos son lo mínimo que necesito.",
  str_homestory_807101001_14_dialog_content = "Ya veo. Mientras no perdieras tu corazón...",
  str_homestory_807101001_15_option_content = "¡Inexistente!",
  str_homestory_807101001_16_dialog_content = "Estoy feliz de enseñarte.",
  str_homestory_807101001_17_dialog_content = "Bueno. Enséñame entonces.",
  str_homestory_807101001_18_dialog_content = "¿Eh? Eso fue fácil.",
  str_homestory_807101001_19_dialog_content = "Por supuesto.",
  str_homestory_807101001_20_dialog_content = "No es una pena aprender de los mejores.",
  str_homestory_807101001_21_dialog_content = "Admitir lo que no entendemos y la comunicación será más efectiva. Es particularmente cierto para cualquier hombre de negocios.",
  str_homestory_807101001_22_dialog_content = "¡El propietario de Odd Jobs nunca deja de impresionarme!",
  str_homestory_807101001_23_dialog_content = "Entonces, ¿cuál es el truco para volar una cometa? Dime.",
  str_homestory_807101001_24_dialog_content = "Primero, debes asegurarte de que estás de espaldas al viento.",
  str_homestory_807101001_25_dialog_content = "La cometa atrapará el viento de esta manera.",
  str_homestory_807101001_26_dialog_content = "Luego comienzas a soltar un poco de línea para ayudar a que la cometa suba más alto en el aire. Si no hay suficiente viento, debe enrollar la línea rápidamente.",
  str_homestory_807101001_27_dialog_content = "Corre despacio mientras vuelas la cometa. Vigílalo siempre.",
  str_homestory_807101001_28_dialog_content = "Si tu cometa está volando constantemente alto en el aire...",
  str_homestory_807101001_29_dialog_content = "Puedes atarlo a un árbol o a un poste indicador y encontrar un lugar cómodo para verlo volar.",
  str_homestory_807101001_30_dialog_content = "De acuerdo... La dirección del viento... La fuerza del viento... Carrera lenta... Y la interacción con la cometa...<sprite=emo_wuyu size=60 />",
  str_homestory_807101001_31_dialog_content = "¿Ah? ¿Lo estás recitando?",
  str_homestory_807101001_32_dialog_content = "Puedo repetir todo lo que acabo de decir si quieres...",
  str_homestory_807101001_33_dialog_content = "No hay necesidad. Lo he memorizado todo.",
  str_homestory_807101001_34_dialog_content = "¿Mmm? ¿Por qué sigues murmurando para ti mismo entonces?",
  str_homestory_807101001_35_dialog_content = "Umm... Quiero decir... ¿Por qué no intentarlo?",
  str_homestory_807101001_36_dialog_content = "Estoy planeando cómo imprimir este libro \"Cómo volar una cometa\" para mejorar las ventas.",
  str_homestory_807101001_37_dialog_content = "... ¿Ah?",
  str_homestory_807101001_38_dialog_content = "Imagina esto. Si Odd Jobs comenzara a vender cometas y realmente aumentara la publicidad...",
  str_homestory_807101001_39_dialog_content = "Compre una cometa y obtenga una sesión de entrenamiento gratis solo por tiempo limitado.",
  str_homestory_807101001_40_dialog_content = "¿Qué sucede si uno no puede volar una cometa después de la sesión de entrenamiento? Compre el libro \"Cómo volar una cometa\".",
  str_homestory_807101001_41_dialog_content = "Podemos tener todo tipo de cometas. Tal vez incluso con un tiro en la cabeza del Señor de las Sombras...",
  str_homestory_807101001_42_dialog_content = "¡Alto ahí!",
  str_homestory_807101001_43_dialog_content = "Así que estás aquí volando una cometa y aprendiendo habilidades de vuelo de cometas de mí...",
  str_homestory_807101001_44_dialog_content = "¿Para hacer dinero?",
  str_homestory_807101001_45_dialog_content = "Sí.",
  str_homestory_807101001_46_dialog_content = "Chico, soy un hombre de negocios.",
  str_homestory_807101001_47_dialog_content = "¿Tiene usted un problema?",
  str_homestory_807101001_48_dialog_content = "No, en absoluto...",
  str_homestory_807101001_49_dialog_content = "¡Admiro tu fuerte sentido de los negocios!",
  str_homestory_807101001_50_dialog_content = "No me pasaría el presupuesto todos los días si supiera cómo ganar dinero con las cosas que me rodean...",
  str_homestory_807101001_51_dialog_content = "Hmm... Estás preocupado por el dinero.",
  str_homestory_807101001_52_dialog_content = "Escuchar. Ya que obtuve algo de inspiración tuya para este negocio...",
  str_homestory_807101001_53_dialog_content = "La mitad de la ganancia será tuya cuando realmente suceda en Odd Jobs.",
  str_homestory_807101001_54_dialog_content = "¡¿?!",
  str_homestory_807101001_55_dialog_content = "¿Hablas en serio?",
  str_homestory_807101001_56_dialog_content = "Sí, pero no te emociones demasiado todavía.",
  str_homestory_807101001_57_dialog_content = "Este negocio podría ser un desastre total.",
  str_homestory_807101001_58_dialog_content = "No hay problema. Taki, ¡Tengo fe en ti!",
  str_homestory_807101001_59_dialog_content = "Bueno. Debo practicar mis habilidades de vuelo de cometas ahora.",
  str_homestory_807101001_60_dialog_content = "Chico, debes estar ocupado. Sigue adelante con tu día.",
  str_homestory_807101001_61_dialog_content = "¡Lo tienes! Taki!",
  str_homestory_807101001_62_dialog_content = "(... ¡Sí! ¡Lo he decidido!)",
  str_homestory_807101001_63_dialog_content = "(Por mi mitad de las ganancias... Me aseguraré Taki practica y mejora cada día!)<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_0_dialog_content = "Vice?",
  str_homestory_803301001_1_dialog_content = "Inhalar... Vice, ¡Puedes hacerlo!",
  str_homestory_803301001_2_dialog_content = "Respira profundamente... Exhala...<sprite=emo_tanqi size=60 />",
  str_homestory_803301001_3_dialog_content = "¿Exhalar?",
  str_homestory_803301001_4_dialog_content = "Vice, tú... ¿Estás practicando la respiración?",
  str_homestory_803301001_5_dialog_content = "¡Ah! PlayerName?",
  str_homestory_803301001_6_dialog_content = "... ¿Practicar la respiración?",
  str_homestory_803301001_7_dialog_content = "No estoy...",
  str_homestory_803301001_8_dialog_content = "¿Que estas haciendo entonces?",
  str_homestory_803301001_9_dialog_content = "Estoy llevando cuentas.",
  str_homestory_803301001_10_dialog_content = "Ah... La cuenta de gastos me está dando dolor de cabeza.",
  str_homestory_803301001_11_dialog_content = "Ojalá fuera solo un ejercicio de respiración...",
  str_homestory_803301001_12_dialog_content = "Al menos respirar no cuesta nada.",
  str_homestory_803301001_13_option_content = "Pedir Vice",
  str_homestory_803301001_14_dialog_content = "¿Puedo ayudar?",
  str_homestory_803301001_15_dialog_content = "Revisé nuestro libro de cuentas anoche.",
  str_homestory_803301001_16_dialog_content = "No soy muy bueno en la contabilidad, pero estoy dispuesto a ayudar.",
  str_homestory_803301001_17_option_content = "guarda silencio",
  str_homestory_803301001_18_dialog_content = "¿Por qué estás tan callado?",
  str_homestory_803301001_19_dialog_content = "Ahh... No quise culparte...",
  str_homestory_803301001_20_dialog_content = "Lo sé. Estoy pensando en cómo puedo ser de alguna ayuda.",
  str_homestory_803301001_21_dialog_content = "Revisé nuestro libro de cuentas anoche. Nos sobrepasamos un poco...",
  str_homestory_803301001_22_dialog_content = "Ah... Vice... ¡Gracias por todo lo que has hecho!",
  str_homestory_803301001_23_dialog_content = "Déjame pensar en lo que vi en el libro de cuentas anoche...",
  str_homestory_803301001_24_dialog_content = "\"Solo los componentes de la Fuente de la Esperanza, la plaza y la rocalla costarán una fortuna\".",
  str_homestory_803301001_25_dialog_content = "\"Y mucho menos abastecer los dormitorios y el museo\"...",
  str_homestory_803301001_26_dialog_content = "\"Debemos tomar en consideración la preferencia de todos y cada uno de nuestros amigos...\"",
  str_homestory_803301001_27_dialog_content = "\"Como un caballito balancín, una silla colgante y esculturas...\"",
  str_homestory_803301001_28_dialog_content = "\"Estas cosas por sí solas no son demasiado caras, pero los números se suman rápidamente\".",
  str_homestory_803301001_29_dialog_content = "\"Hay mucho que aprender sobre cómo comunicarse con los artesanos. La instalación puede ser un desafío\".",
  str_homestory_803301001_30_dialog_content = "\"Sin embargo... Supongo que todos los esfuerzos de PlayerName y no soy para nada si nuestros huéspedes pueden tener una estancia confortable.\"",
  str_homestory_803301001_31_dialog_content = "Ah... Lo viste todo.",
  str_homestory_803301001_32_dialog_content = "Sí... No puedo deshacerme de este viejo hábito de escribir mis pensamientos... Hahah.",
  str_homestory_803301001_33_dialog_content = "Vice, honestamente, ¡eres fabuloso!",
  str_homestory_803301001_34_dialog_content = "Navegante, ¿por qué de repente eres tan generoso con tus cumplidos?",
  str_homestory_803301001_35_dialog_content = "¡Lo digo en serio!",
  str_homestory_803301001_36_dialog_content = "Mirar. Usted dibuja planos de construcción, organiza cronogramas de proyectos y hace planificación regional...",
  str_homestory_803301001_37_dialog_content = "No soy de ayuda en absoluto. no puedo dibujar Tampoco soy bueno para planear o arreglar.",
  str_homestory_803301001_38_dialog_content = "Cloud Gardens se lo debe todo a usted.",
  str_homestory_803301001_39_dialog_content = "... Ah... Eso es verdad...",
  str_homestory_803301001_40_dialog_content = "¡Pero no hay necesidad de agradecer!",
  str_homestory_803301001_41_dialog_content = "Solo quiero animarte.",
  str_homestory_803301001_42_dialog_content = "Trabajemos juntos para mantenernos fuera del rojo.",
  str_homestory_803301001_43_dialog_content = "¡Sí! ¡Estás absolutamente en lo correcto!",
  str_homestory_803301001_44_dialog_content = "Ah... Ya que es bastante difícil comprar cosas en los Jardines de las Nubes...",
  str_homestory_803301001_45_dialog_content = "¿Qué tal si aumentamos nuestros precios para todo diez veces?<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_46_dialog_content = "... Err... No creo que sea necesario...",
  str_homestory_803301001_47_dialog_content = "Jejeje. ¡Navegador, eso era una broma!",
  str_homestory_803301001_48_dialog_content = "En serio, ¿cómo podemos ganar algo de dinero? Déjame pensar...",
  str_homestory_804101001_0_dialog_content = "Sra. Blanc...",
  str_homestory_804101001_1_dialog_content = "Oye, PlayerName.",
  str_homestory_804101001_2_dialog_content = "Es un lindo día<sprite=emo_pugongying size=60 />, Sra. Blanc.",
  str_homestory_804101001_3_dialog_content = "Sí.",
  str_homestory_804101001_4_dialog_content = "¿Estás dando un paseo o de camino a alguna parte?",
  str_homestory_804101001_5_option_content = "Solo caminando",
  str_homestory_804101001_6_dialog_content = "Una buena eleccion.",
  str_homestory_804101001_7_dialog_content = "Es hermoso aquí, con muchas instalaciones recreativas...",
  str_homestory_804101001_8_dialog_content = "Y mucha gente que nunca he conocido antes.",
  str_homestory_804101001_9_option_content = "Ir de pesca",
  str_homestory_804101001_10_dialog_content = "ah ¿Eres bueno pescando?",
  str_homestory_804101001_11_option_content = "Muy bueno",
  str_homestory_804101001_12_dialog_content = "¿En serio?",
  str_homestory_804101001_13_dialog_content = "Vendré y comprobaré.",
  str_homestory_804101001_14_dialog_content = "¡Bienvenidos!",
  str_homestory_804101001_15_dialog_content = "Jejeje ¡Un joven muy confiado!",
  str_homestory_804101001_16_option_content = "Tan-tan...",
  str_homestory_804101001_17_dialog_content = "La pesca requiere mucha paciencia.",
  str_homestory_804101001_18_dialog_content = "Pensé que eras demasiado joven para esto.",
  str_homestory_804101001_19_dialog_content = "Hmm... Lo encuentro útil con mi concentración.",
  str_homestory_804101001_20_dialog_content = "mmm...",
  str_homestory_804101001_21_dialog_content = "Solo aquellos que \"tienen problemas para concentrarse\" necesitan hacer cosas que ayuden a mejorar la concentración.",
  str_homestory_804101001_22_dialog_content = "Pero te beneficiarás con el tiempo.",
  str_homestory_804101001_23_dialog_content = "Si...",
  str_homestory_804101001_24_dialog_content = "Sra. Blanc, ¿por qué está parada debajo de este cartel de madera?",
  str_homestory_804101001_25_dialog_content = "estoy observando",
  str_homestory_804101001_26_dialog_content = "¿Observando?",
  str_homestory_804101001_27_dialog_content = "No puedo ayudar con eso.",
  str_homestory_804101001_28_dialog_content = "Todos estos nuevos edificios y caminos... Quiero grabarlos todos en mi cabeza.",
  str_homestory_804101001_29_dialog_content = "Ya veo.",
  str_homestory_804101001_30_dialog_content = "Los caminos aquí no son complicados. Tal vez la Sra. Blanc pueda relajarse un poco.",
  str_homestory_804101001_31_dialog_content = "¿Relax?",
  str_homestory_804101001_32_dialog_content = "Eso es un verdadero lujo...",
  str_homestory_804101001_33_dialog_content = "Pero debo prestar atención a su consejo.",
  str_homestory_804101001_34_dialog_content = "PlayerName, tenga un buen descanso usted mismo.",
  str_homestory_804101001_35_dialog_content = "El exceso de trabajo acelerará el envejecimiento.<sprite=emo_guilian size=60 />",
  str_homestory_804101001_36_dialog_content = "Okay...",
  str_homestory_804101001_37_dialog_content = "¡Deseo! Sra. Blanc!",
  str_homestory_813801001_0_dialog_content = "Siobhan!",
  str_homestory_813801001_1_dialog_content = "¿PlayerName?",
  str_homestory_813801001_2_dialog_content = "Ah... Gracias a Dios que estás aquí...<sprite=emo_tanqi size=60 />",
  str_homestory_813801001_3_dialog_content = "Que pasa, Siobhan? Te ves cansado.",
  str_homestory_813801001_4_dialog_content = "Porque... Me quedé despierto toda la noche para ver todos los artículos coleccionados en el museo.",
  str_homestory_813801001_5_dialog_content = "Estos coleccionables son un registro perfecto del pasado de Eraveil y de todas las tecnologías que Caelestites desarrolló...",
  str_homestory_813801001_6_dialog_content = "Tengo que admitir mi admiración por su destreza científica.",
  str_homestory_813801001_7_dialog_content = "Gracias. Illumina lo está haciendo muy bien en ciencia y tecnología.",
  str_homestory_813801001_8_dialog_content = "No sé por qué, pero no puedo quitarme de encima este sentimiento...",
  str_homestory_813801001_9_dialog_content = "La tecnología de Caelestites no se parece en nada a la de Illumina.",
  str_homestory_813801001_10_dialog_content = "La alta tecnología de Illumina se basa en elaboradas redes mecánicas desarrolladas con sólidos conocimientos y precisión...",
  str_homestory_813801001_11_dialog_content = "Pero Caelestites... Todo se siente tan fresco y diferente.",
  str_homestory_813801001_12_dialog_content = "Similar a esas tecnologías antiguas de alguna manera.",
  str_homestory_813801001_13_dialog_content = "Bueno, yo no sé nada de esto...",
  str_homestory_813801001_14_dialog_content = "Ho-hum...",
  str_homestory_813801001_15_dialog_content = "Sentir sueño de repente...<sprite=emo_xuanyun size=60 />",
  str_homestory_813801001_16_dialog_content = "¿Que estas esperando? Vuelve y duerme.",
  str_homestory_813801001_17_dialog_content = "Estoy tratando de hacer coincidir estos coleccionables con los documentos que leí antes. Con suerte, habrá descubrimientos intrigantes.",
  str_homestory_813801001_18_dialog_content = "Podría haber Caelestites en algún otro lugar de este continente mucho antes de nuestro tiempo...",
  str_homestory_813801001_19_dialog_content = "La gente no tenía idea de que en realidad eran caelestitas y, por lo tanto, confundieron su tecnología con la antigua.",
  str_homestory_813801001_20_dialog_content = "... Jajajaja. No importa.",
  str_homestory_813801001_21_dialog_content = "Me estoy volviendo un poco irreal aquí. Probablemente debería irme a la cama.",
  str_homestory_813801001_22_dialog_content = "Siobhan, Estoy preocupado por ti.",
  str_homestory_813801001_23_dialog_content = "¿Por qué tienes que terminarlo ahora?",
  str_homestory_813801001_24_dialog_content = "No creo que puedas trabajar bien en este estado...",
  str_homestory_813801001_25_dialog_content = "¿No estás alojando aquí a unos cuantos ciudadanos de Lumopolis?",
  str_homestory_813801001_26_dialog_content = "Aunque eres un caelestita, no creo que saboteen el museo...",
  str_homestory_813801001_27_dialog_content = "Yo... ¡Solo estoy preocupado!",
  str_homestory_813801001_28_dialog_content = "Siento que necesito registrar y analizar todo lo antes posible.",
  str_homestory_813801001_29_dialog_content = "¿Quién sabe cómo piensan realmente los que odian la tecnología sobre este lugar?",
  str_homestory_813801001_30_dialog_content = "Ok...",
  str_homestory_813801001_31_dialog_content = "No te preocupes. Que yo sepa, hay muchos museos en Lumopolis.",
  str_homestory_813801001_32_dialog_content = "Son mis invitados aquí. Lo que sea que te preocupe, no sucederá.",
  str_homestory_813801001_33_dialog_content = "¿Estoy pensando demasiado?",
  str_homestory_813801001_34_dialog_content = "¿El exceso de trabajo me hace preocuparme demasiado?<sprite=emo_sikao size=60 />",
  str_homestory_813801001_35_dialog_content = "Creo que solo estás cansado.",
  str_homestory_813801001_36_dialog_content = "¿Qué tal si nos tomamos un descanso y volvemos a eso más tarde?",
  str_homestory_813801001_37_dialog_content = "Bien. Eso es lo que haré... PlayerName.",
  str_homestory_813801001_38_dialog_content = "Me voy a la cama. ¿Y usted?",
  str_homestory_813801001_39_dialog_content = "¿Apuesto a que te vendría bien un poco de descanso?",
  str_homestory_813801001_40_option_content = "Aceptar",
  str_homestory_813801001_41_dialog_content = "Sí, también estoy cansado.",
  str_homestory_813801001_42_dialog_content = "Pero...",
  str_homestory_813801001_43_option_content = "Objeto",
  str_homestory_813801001_44_dialog_content = "¡Mi cuerpo puede estar cansado pero mi espíritu se siente realizado!",
  str_homestory_813801001_45_dialog_content = "No me importa todo este trabajo mientras todos puedan pasar un buen rato aquí.",
  str_homestory_813801001_46_dialog_content = "Puede que seas joven, pero tu sentido del liderazgo es fuerte.",
  str_homestory_813801001_47_dialog_content = "Gracias...",
  str_homestory_813801001_48_dialog_content = "No sé por qué sigo queriendo ir al río, pero tengo demasiado sueño para hacerlo.",
  str_homestory_813801001_49_dialog_content = "Hablaremos más sobre la tecnología Caelestite después de mi siesta, PlayerName.",
  str_homestory_813801001_50_dialog_content = "Descansa bien, Siobhan.",
  str_homestory_814501001_0_dialog_content = "¿Qué está mirando?",
  str_homestory_814501001_1_dialog_content = "Amemori?",
  str_homestory_814501001_2_dialog_content = "Cállate.<sprite=emo_baiyan size=60 />",
  str_homestory_814501001_3_dialog_content = "?",
  str_homestory_814501001_4_dialog_content = "¿Qué estás haciendo?",
  str_homestory_814501001_5_dialog_content = "observando",
  str_homestory_814501001_6_dialog_content = "Estoy examinando este lugar con mucho cuidado y minuciosidad.",
  str_homestory_814501001_7_dialog_content = "¿Hay algo inusual en ello?",
  str_homestory_814501001_8_dialog_content = "¿No crees que el diseño de Cloud Gardens es exquisitamente intrincado?",
  str_homestory_814501001_9_dialog_content = "Fantaseaba con construir un lugar así cuando era joven.",
  str_homestory_814501001_10_dialog_content = "Uno desde el que es fácil lanzar un ataque, fácil de defender y un gran cónclave para personas con ideas afines.",
  str_homestory_814501001_11_dialog_content = "¡Oh!",
  str_homestory_814501001_12_dialog_content = "¿Has estado haciendo un plan a largo plazo desde la infancia, Amemori?",
  str_homestory_814501001_13_dialog_content = "Bueno, el sueño para mí en ese entonces probablemente era solo un ímpetu para \"seguir viviendo\".",
  str_homestory_814501001_14_dialog_content = "Pero no está mal que ahora pueda vivir aquí arriba.",
  str_homestory_814501001_15_dialog_content = "Lo siento.",
  str_homestory_814501001_16_dialog_content = "¿Quieres que te muestre los alrededores?",
  str_homestory_814501001_17_dialog_content = "No te molestes.",
  str_homestory_814501001_18_dialog_content = "Ya descubrí la disposición del terreno en mi primer día.",
  str_homestory_814501001_19_dialog_content = "¡Vaya, qué perspicaz!",
  str_homestory_814501001_20_dialog_content = "Eso es lo que hace un ninja.",
  str_homestory_814501001_21_dialog_content = "En realidad, me gustaría saber quién diseñó este lugar.",
  str_homestory_814501001_22_dialog_content = "Navegante, ¿por casualidad lo sabes?",
  str_homestory_814501001_23_option_content = "Si",
  str_homestory_814501001_24_dialog_content = "Vice, de mi y las sugerencias de los artesanos.",
  str_homestory_814501001_25_option_content = "No",
  str_homestory_814501001_26_dialog_content = "Puedo preguntarle si quieres.",
  str_homestory_814501001_27_dialog_content = "Incursioné en el plan real, pero ella lo sabe mejor.",
  str_homestory_814501001_28_dialog_content = "Amemori, ¿por qué quieres saber tanto?",
  str_homestory_814501001_29_dialog_content = "¿Estás interesado en construir otro Cloud Gardens en Cloud Island?",
  str_homestory_814501001_30_dialog_content = "Ese pensamiento cruzó mi mente.",
  str_homestory_814501001_31_dialog_content = "Imagínese, una vez que Cloud Island tenga viviendas en este nivel, la gente disfrutaría de una vida mucho mejor.",
  str_homestory_814501001_32_dialog_content = "Por supuesto, eso es solo el principio...",
  str_homestory_814501001_33_dialog_content = "Si verdaderamente aprendiéramos esta tecnología avanzada, sería más fácil para nosotros defendernos de los enemigos.",
  str_homestory_814501001_34_dialog_content = "Tecnología Caelestite con un concepto y una planificación tan maravillosos... Vale la pena que lo investiguemos.",
  str_homestory_814501001_35_dialog_content = "Ya veo.",
  str_homestory_814501001_36_dialog_content = "¡Te daré la respuesta!",
  str_homestory_814501001_37_dialog_content = "Gracias, Navegador.",
  str_homestory_814601001_0_dialog_content = "Moviendo la cabeza...",
  str_homestory_814601001_1_dialog_content = "Todos los Aurorianos...",
  str_homestory_814601001_2_dialog_content = "Pasando por los Jardines de las Nubes.",
  str_homestory_814601001_3_dialog_content = "?",
  str_homestory_814601001_4_dialog_content = "El arco se eleva desde el suelo plano...",
  str_homestory_814601001_5_dialog_content = "¡Con un bollo relleno en la mano!<sprite=emo_yaosu size=60 />",
  str_homestory_814601001_6_dialog_content = "...",
  str_homestory_814601001_7_dialog_content = "Yao, estás recitando un poema?",
  str_homestory_814601001_8_dialog_content = "¡Hola, Navegador!",
  str_homestory_814601001_9_dialog_content = "No estoy recitando.",
  str_homestory_814601001_10_dialog_content = "¡Pero componer! ¿Qué piensas?",
  str_homestory_814601001_11_option_content = "¡Bueno!",
  str_homestory_814601001_12_dialog_content = "¡Realmente bueno!",
  str_homestory_814601001_13_dialog_content = "Yao, eres un poeta dotado!",
  str_homestory_814601001_14_option_content = "Nada mal",
  str_homestory_814601001_15_dialog_content = "Yo diría que este poema está en algún lugar entre Charon y Viceobras de .",
  str_homestory_814601001_16_dialog_content = "Ni demasiado exagerada ni demasiado realista, revela el verdadero deseo del Poeta...",
  str_homestory_814601001_17_dialog_content = "Ejem... Pero, ¿qué tiene que ver el arco con los bollos rellenos?",
  str_homestory_814601001_18_dialog_content = "Solo mira a este arquero. ¿No ves mi futura tienda de bollos rellenos?",
  str_homestory_814601001_19_dialog_content = "¿Aún estás pensando en abrir una tienda de bollos rellenos?",
  str_homestory_814601001_20_dialog_content = "¿Cansado de defender la justicia y ayudar a los débiles?",
  str_homestory_814601001_21_dialog_content = "Quiero hacer los dos.",
  str_homestory_814601001_22_dialog_content = "¿No es agradable retirarse de la vida marcial a una tienda de bollos rellenos cuando tengo canas?",
  str_homestory_814601001_23_dialog_content = "Sabes. Los guerreros legendarios a menudo eligen retirarse en algún lugar de un mercado concurrido...",
  str_homestory_814601001_24_dialog_content = "¡Pueden seguir escuchando la leyenda que dejaron atrás!",
  str_homestory_814601001_25_dialog_content = "¿No tienen estos guerreros mejores cosas que hacer?",
  str_homestory_814601001_26_dialog_content = "Olvídate de ellos. ¡Ven y conoce mi plan!",
  str_homestory_814601001_27_dialog_content = "Avanzar. Soy todo oídos.",
  str_homestory_814601001_28_dialog_content = "En primer lugar, la tienda de bollos rellenos debe tener tres pisos.",
  str_homestory_814601001_29_dialog_content = "La mitad del primer piso es para que Anzu y Momo vendan su sabrosa comida. ¡La otra mitad es para mis deliciosos platos!",
  str_homestory_814601001_30_dialog_content = "El segundo piso es más como una taberna para que mis amigos no tengan que preocuparse por el alojamiento cuando charlamos hasta altas horas de la noche.",
  str_homestory_814601001_31_dialog_content = "¡El tercer piso es donde vivo!",
  str_homestory_814601001_32_dialog_content = "habrá cuartos para mí, Amemori, y Rinne. Navegador y Vice también...",
  str_homestory_814601001_33_dialog_content = "Y Kayano. Y mis amigos del clan Lin, mi hermana de juramento y mis padres...",
  str_homestory_814601001_34_dialog_content = "¿Debo tener una habitación para Taki? Puede que no le guste estar rodeado de tantas chicas.<sprite=emo_sikao size=60 />",
  str_homestory_814601001_35_dialog_content = "Y Dayna y Robyn?",
  str_homestory_814601001_36_dialog_content = "Esperar... Yao, No creo que puedas ganar dinero de esta manera...",
  str_homestory_814601001_37_dialog_content = "Te costará una fortuna preparar todas estas habitaciones para tus amigos.",
  str_homestory_814601001_38_dialog_content = "Algunas personas prefieren la soledad. Este tipo de vida comunal no es para todos...",
  str_homestory_814601001_39_dialog_content = "¡El dinero no es un problema!",
  str_homestory_814601001_40_dialog_content = "Hmm... Pero la preferencia personal es un problema...",
  str_homestory_814601001_41_dialog_content = "De todos modos, son mis amigos y prepararé sus habitaciones.",
  str_homestory_814601001_42_dialog_content = "Pero depende completamente de ellos si quieren venir o no.",
  str_homestory_814601001_43_dialog_content = "Jejeje Todos están felices. Sin reticencias ni compromisos.",
  str_homestory_814601001_44_dialog_content = "Sí tienes razón...",
  str_homestory_814601001_45_dialog_content = "Esta es una solución exclusiva para los súper ricos...",
  str_homestory_816301001_0_dialog_content = "¿Estás dibujando?",
  str_homestory_816301001_1_dialog_content = "¡Guau! <sprite=emo_wuzui size=60 />El jefe de la aeronavePlayerName!",
  str_homestory_816301001_2_dialog_content = "¡Finalmente! Te he estado buscando por todas partes...",
  str_homestory_816301001_3_dialog_content = "Err... ¿Cómo puedo ayudar?",
  str_homestory_816301001_4_dialog_content = "Estaba de gira haciendo arreglos con la gente para sus contribuciones cuando descubrí este tablero de dibujo...",
  str_homestory_816301001_5_dialog_content = "Señorita Vice Dijiste que compraste esto contra todas las voces disidentes.",
  str_homestory_816301001_6_dialog_content = "¿Puedo tomarlo como...",
  str_homestory_816301001_7_dialog_content = "¿Finalmente aceptaste crear obras de arte para Al***my St**s?<sprite=emo_yaosu size=60 />",
  str_homestory_816301001_8_option_content = "Confirmar",
  str_homestory_816301001_9_dialog_content = "Sí, he estado jugando con esta idea.",
  str_homestory_816301001_10_dialog_content = "¡Guau! ¡Finalmente estás dispuesto a enfrentar tu regalo!",
  str_homestory_816301001_11_dialog_content = "Err... Necesito hacer algo para ayudar con la crisis financiera.",
  str_homestory_816301001_12_dialog_content = "Mis habilidades no están mejorando en el corto plazo.",
  str_homestory_816301001_13_dialog_content = "Prefiero dejar esto a alguien que realmente disfruta dibujar, como tú...",
  str_homestory_816301001_14_option_content = "Negar",
  str_homestory_816301001_15_dialog_content = "Ejem... Conozco mis habilidades...",
  str_homestory_816301001_16_dialog_content = "Este tablero es para cualquier apasionado del dibujo.",
  str_homestory_816301001_17_dialog_content = "Airship Boss, por favor ponga su mano en su pecho.",
  str_homestory_816301001_18_dialog_content = "Siente ese corazón latir de amor por el dibujo.",
  str_homestory_816301001_19_dialog_content = "Hablando de amor por el dibujo, eres insuperable.",
  str_homestory_816301001_20_dialog_content = "Señor. Tourdog.",
  str_homestory_816301001_21_dialog_content = "¡...!",
  str_homestory_816301001_22_dialog_content = "Día y noche te acercas a la gente por sus contribuciones a tu juego. ¿Cuándo fue la última vez que tuviste un sueño adecuado?",
  str_homestory_816301001_23_dialog_content = "Para mi juego, no necesito dormir ni cenar.",
  str_homestory_816301001_24_dialog_content = "Entonces, ¿cuánto tiempo hace que no dibujas libremente?",
  str_homestory_816301001_25_dialog_content = "Wow...",
  str_homestory_816301001_26_dialog_content = "¿De verdad quieres que dibuje en tu pizarra?<sprite=emo_yihuo size=60 />",
  str_homestory_816301001_27_dialog_content = "si el Sr. Tourdog, la celebridad de Astra, dibujaría algo aquí...",
  str_homestory_816301001_28_dialog_content = "¡Sería perfecto!",
  str_homestory_816301001_29_dialog_content = "Primero, encuentre el punto débil del objetivo y tenga una charla de ánimo. Luego, elogie al objetivo antes de hacer su pedido.<sprite=emo_sikao size=60 />",
  str_homestory_816301001_30_dialog_content = "¿Es así como juegas el juego mental?",
  str_homestory_816301001_31_dialog_content = "Después de pedir tantas contribuciones, casi caigo en tu trampa. ¡Interesante!",
  str_homestory_816301001_32_dialog_content = "¡El protagonista elegido por los inversores es realmente impresionante!",
  str_homestory_816301001_33_dialog_content = "La trama del juego no será aburrida mientras sigas aquí.",
  str_homestory_816301001_34_option_content = "Preguntar por los inversores",
  str_homestory_816301001_35_dialog_content = "¿Inversores?",
  str_homestory_816301001_36_dialog_content = "Un grupo de jefes capaces que comparten una fuerte fe en ti.",
  str_homestory_816301001_37_dialog_content = "No necesitas saber quiénes son.",
  str_homestory_816301001_38_option_content = "Preguntar por el protagonista",
  str_homestory_816301001_39_dialog_content = "¿Protagonista?",
  str_homestory_816301001_40_dialog_content = "La figura central de este juego, la estrella absoluta amada por todos.",
  str_homestory_816301001_41_dialog_content = "Esta posición no es para todos.",
  str_homestory_816301001_42_dialog_content = "Me estas perdiendo.",
  str_homestory_816301001_43_dialog_content = "Considerándolo todo, Airship Boss.",
  str_homestory_816301001_44_dialog_content = "¡Te dibujaré una pintura en pergamino de Cloud Gardens gratis!",
  str_homestory_816301001_45_dialog_content = "Como mi cuota de matrícula para su juego mental único para solicitar contribuciones.",
  str_homestory_816301001_46_dialog_content = "Esperamos con interés trabajar con usted.<sprite=emo_guilian size=60 />",
  str_homestory_816301001_47_dialog_content = "Umm... igualmente...",
  str_homestory_816301001_48_dialog_content = "Excelente. Necesito planificar la composición de este dibujo.",
  str_homestory_816301001_49_dialog_content = "Normalmente, un dibujo no me toma más de 3 segundos, pero debo dar lo mejor de mí para el Airship Boss.",
  str_homestory_816301001_50_dialog_content = "Hmm...",
  str_homestory_816301001_51_dialog_content = "¿Cómo debo empezar?",
  str_homestory_816301001_52_dialog_content = "os lo dejo...",
  str_homestory_816301001_53_dialog_content = "(No creo que pueda oírme.)",
  str_homestory_816301001_54_dialog_content = "(Me voy de aquí...)",
  str_homestory_814801001_0_dialog_content = "¿Ella está aquí?",
  str_homestory_814801001_1_dialog_content = "Azure...",
  str_homestory_814801001_2_dialog_content = "¿Eh?",
  str_homestory_814801001_3_dialog_content = "¿De quién es esta linda cara? Absolutamente adorable.",
  str_homestory_814801001_4_dialog_content = "Ven aquí. Déjame sentir si es suave.",
  str_homestory_814801001_5_dialog_content = "Ah<sprite=emo_yundao size=60 />... ¡Esperar!",
  str_homestory_814801001_6_dialog_content = "Soy yo... PlayerName.",
  str_homestory_814801001_7_dialog_content = "PlayerName? Suena familiar.",
  str_homestory_814801001_8_dialog_content = "¡Ay! Jajajaja ¡Ahora recuerdo!",
  str_homestory_814801001_9_dialog_content = "¡Ese es mi pequeño novio Caelestite!",
  str_homestory_814801001_10_option_content = "Admitir",
  str_homestory_814801001_11_dialog_content = "... Sí. Soy yo.",
  str_homestory_814801001_12_dialog_content = "¡Guau! ¿Lo admites?",
  str_homestory_814801001_13_dialog_content = "Entonces será mejor que asumas la responsabilidad.",
  str_homestory_814801001_14_option_content = "Negar",
  str_homestory_814801001_15_dialog_content = "Azure, por favor no bromees así...",
  str_homestory_814801001_16_dialog_content = "Otras personas pueden malinterpretar...",
  str_homestory_814801001_17_dialog_content = "¿Vaya? ¿De qué estás tan asustado?",
  str_homestory_814801001_18_dialog_content = "¿No quieres que esa chica Illumina con cola de dragón escuche?",
  str_homestory_814801001_19_dialog_content = "¿O estás pensando en esa princesa distante de Lumopolis?",
  str_homestory_814801001_20_dialog_content = "...",
  str_homestory_814801001_21_dialog_content = "Aún más lindo cuando te sonrojas. Jajajaja",
  str_homestory_814801001_22_dialog_content = "Yo... tengo que irme...<sprite=emo_hanshui size=60 />",
  str_homestory_814801001_23_dialog_content = "Ahí ahí. Me detengo ahora.",
  str_homestory_814801001_24_dialog_content = "¿Me buscabas antes?",
  str_homestory_814801001_25_dialog_content = "Sólo quiero preguntarte cómo te va por aquí...",
  str_homestory_814801001_26_dialog_content = "Aww... Mi pequeña Caelestite es tan cariñosa. Estoy realmente conmovido.",
  str_homestory_814801001_27_dialog_content = "Gracias a ti, me lo estoy pasando genial aquí.",
  str_homestory_814801001_28_dialog_content = "Muy diferente de ese desierto abrasador y árido, este lugar es tan verde.",
  str_homestory_814801001_29_dialog_content = "No caliente. No esta seco. Incluso el viento es muy suave.",
  str_homestory_814801001_30_dialog_content = "Escoria mucho menos irritante.",
  str_homestory_814801001_31_dialog_content = "Un salón de belleza natural...",
  str_homestory_814801001_32_dialog_content = "¿No crees que soy más hermosa ahora?",
  str_homestory_814801001_33_option_content = "Confirmar",
  str_homestory_814801001_34_dialog_content = "Sí, tu belleza ha llegado al clímax...",
  str_homestory_814801001_35_option_content = "Negar",
  str_homestory_814801001_36_dialog_content = "No puedes volverte más hermosa porque ya eres perfecta.",
  str_homestory_814801001_37_dialog_content = "¿Dónde aprendiste todas estas dulces palabras?",
  str_homestory_814801001_38_dialog_content = "Supongo que debería quedarme más tiempo para disfrutar de su cálida hospitalidad.",
  str_homestory_814801001_39_dialog_content = "Pequeña Caelestite, ¿quieres que me quede?",
  str_homestory_814801001_40_option_content = "Confirmar",
  str_homestory_814801001_41_dialog_content = "Por supuesto... Puedes quedarte todo el tiempo que quieras.",
  str_homestory_814801001_42_dialog_content = "La puerta siempre está abierta para ti.",
  str_homestory_814801001_43_option_content = "Negar",
  str_homestory_814801001_44_dialog_content = "Yo... no tengo ninguna expectativa...",
  str_homestory_814801001_45_dialog_content = "Usted y todos los demás son libres de ir y venir...",
  str_homestory_814801001_46_dialog_content = "Bueno, entonces me sentiré como en casa.",
  str_homestory_814801001_47_dialog_content = "Dígale a su tienda que pida un vino decente.",
  str_homestory_814801001_48_dialog_content = "No puedo esperar más. ¿De acuerdo?",
  str_homestory_814801001_49_dialog_content = "Si...",
  str_homestory_814801001_50_dialog_content = "¿Que estas esperando?<sprite=emo_emo size=60 />",
  str_homestory_814801001_51_dialog_content = "¡Estoy en ello!",
  str_homestory_815001001_0_dialog_content = "Completamente quieto...",
  str_homestory_815001001_1_dialog_content = "Hola, PlayerName.<sprite=emo_heimao size=60 />",
  str_homestory_815001001_2_dialog_content = "LenoreEs muy feliz de verte.",
  str_homestory_815001001_3_dialog_content = "Lenore, ¿por qué estás parado aquí como una estatua?",
  str_homestory_815001001_4_dialog_content = "¿No quieres dar una vuelta?",
  str_homestory_815001001_5_dialog_content = "¿Dar un paseo?",
  str_homestory_815001001_6_dialog_content = "¿Es este un nuevo pedido de PlayerName?",
  str_homestory_815001001_7_dialog_content = "¿Dónde debo ir exactamente?",
  str_homestory_815001001_8_dialog_content = "Lenore, esto no es una orden. Si es necesario, tómalo como un consejo.",
  str_homestory_815001001_9_dialog_content = "¿Cuál es la diferencia entre una orden y un consejo?",
  str_homestory_815001001_10_dialog_content = "Hmm... Déjame pensar.",
  str_homestory_815001001_11_dialog_content = "Una orden es algo que debes hacer.",
  str_homestory_815001001_12_dialog_content = "Un consejo es solo una sugerencia que no tienes que tomar.",
  str_homestory_815001001_13_dialog_content = "Entendido.",
  str_homestory_815001001_14_dialog_content = "PlayerName aconsejado Lenore para dar un paseo. Es un consejo.",
  str_homestory_815001001_15_dialog_content = "Lenore puede elegir caminar o no.",
  str_homestory_815001001_16_dialog_content = "¡Muy inteligente! ¡Lo tienes completamente!",
  str_homestory_815001001_17_dialog_content = "Gracias por el cumplido, PlayerName.",
  str_homestory_815001001_18_dialog_content = "Eres muy bienvenido.",
  str_homestory_815001001_19_dialog_content = "...",
  str_homestory_815001001_20_dialog_content = ".",
  str_homestory_815001001_21_dialog_content = "...",
  str_homestory_815001001_22_dialog_content = "Errar... Lenore?",
  str_homestory_815001001_23_dialog_content = "¿Así que no quieres andar por ahí?",
  str_homestory_815001001_24_dialog_content = "¿No es solo un consejo?",
  str_homestory_815001001_25_dialog_content = "Lenore no tiene que hacerlo.",
  str_homestory_815001001_26_dialog_content = "Ahh...",
  str_homestory_815001001_27_dialog_content = "He plantado muchas flores y árboles hermosos. ¡Y se han instalado algunas instalaciones recreativas nuevas!",
  str_homestory_815001001_28_dialog_content = "¿No quieres verlos?",
  str_homestory_815001001_29_dialog_content = "Debería Lenore ¿querer verlos?",
  str_homestory_815001001_30_option_content = "Dominio",
  str_homestory_815001001_31_dialog_content = "Bueno... No hay otra manera. Bueno. Ordeno Lenore para echar un vistazo.",
  str_homestory_815001001_32_dialog_content = "Sí. Lenore completará la misión.",
  str_homestory_815001001_33_option_content = "Sugerir",
  str_homestory_815001001_34_dialog_content = "Sé que suena como fanfarronear, pero realmente creo que hice un buen trabajo.",
  str_homestory_815001001_35_dialog_content = "Así que... creo que deberías echarles un vistazo.",
  str_homestory_815001001_36_dialog_content = "Ya que PlayerName dijo eso, Lenore iré.",
  str_homestory_815001001_37_dialog_content = "Sí. Ve y disfruta.",
  str_homestory_815001001_38_dialog_content = "pero donde debe Lenore ¿Vamos?",
  str_homestory_815001001_39_dialog_content = "PlayerName, ¿tienes algún consejo para Lenore?",
  str_homestory_815001001_40_dialog_content = "¡Ah!",
  str_homestory_815001001_41_dialog_content = "¿Qué te pasa, PlayerName?",
  str_homestory_815001001_42_dialog_content = "Nada...",
  str_homestory_815001001_43_dialog_content = "Lenore realmente ha aprendido acerca de la palabra \"consejo\".",
  str_homestory_815001001_44_dialog_content = "estoy un poco conmovida...",
  str_homestory_801901001_0_dialog_content = "Victoria...",
  str_homestory_801901001_1_dialog_content = "Hola, PlayerName.",
  str_homestory_801901001_2_dialog_content = "Victoria, que bueno verte.",
  str_homestory_801901001_3_dialog_content = "Estoy admirando estas alegres corrientes. ¿Te gustaría unirte a mi?",
  str_homestory_801901001_4_dialog_content = "¿Admirando los arroyos?",
  str_homestory_801901001_5_dialog_content = "Disculpe... ¿Qué tiene de especial este arroyo que baja por la rocalla?",
  str_homestory_801901001_6_dialog_content = "El agua ha entrado en un ciclo sin fin sin saberlo.",
  str_homestory_801901001_7_dialog_content = "¿No crees que es bastante similar a nosotros los aurorianos?",
  str_homestory_801901001_8_option_content = "Asentir",
  str_homestory_801901001_9_dialog_content = "Si, es un poco...",
  str_homestory_801901001_10_dialog_content = "Aún así, no entendí completamente tus palabras...",
  str_homestory_801901001_11_option_content = "Sacudir la cabeza",
  str_homestory_801901001_12_dialog_content = "Lo siento, Victoria.",
  str_homestory_801901001_13_dialog_content = "Estoy un poco perdido.",
  str_homestory_801901001_14_dialog_content = "No te preocupes por eso. Sólo un comentario insignificante.",
  str_homestory_801901001_15_dialog_content = "Que es Victoria¿Qué piensas sobre esto?",
  str_homestory_801901001_16_dialog_content = "El agua no tiene idea de que está siguiendo un ciclo.",
  str_homestory_801901001_17_dialog_content = "Porque fluye sin rumbo fijo.",
  str_homestory_801901001_18_dialog_content = "No sabe por qué está fluyendo, cómo escapar de este ciclo o dónde está el final.",
  str_homestory_801901001_19_dialog_content = "La mayoría de nosotros vivimos nuestras vidas así, ¿no crees?",
  str_homestory_801901001_20_dialog_content = "No estoy criticando ni compadeciéndome de ninguna manera.",
  str_homestory_801901001_21_dialog_content = "Cómo uno vive su vida no hace una diferencia para mí.",
  str_homestory_801901001_22_dialog_content = "Sólo estoy tratando de pensar.",
  str_homestory_801901001_23_dialog_content = "... Tratando de pensar?",
  str_homestory_801901001_24_dialog_content = "Sí.",
  str_homestory_801901001_25_dialog_content = "Debemos respetar nuestros pensamientos. Cualquier cosa que te lleve a pensar está más allá de tu comprensión actual.",
  str_homestory_801901001_26_dialog_content = "... ¿Quieres decir... que debemos respetar lo desconocido?",
  str_homestory_801901001_27_dialog_content = "Más o menos, querido.",
  str_homestory_801901001_28_dialog_content = "Estas corrientes podrían estar pasando un buen rato. No necesitan nuestra voz en su flujo.",
  str_homestory_801901001_29_dialog_content = "Es bueno estar feliz y contento en este ciclo.",
  str_homestory_801901001_30_dialog_content = "Entonces... ¿No exclamarán sobre asuntos como este como lo hiciste tú?",
  str_homestory_801901001_31_dialog_content = "Jejeje ¿Quién sabe?",
  str_homestory_801901001_32_dialog_content = "Por cierto... El sol es muy fuerte aquí<sprite=emo_taiyang size=60 />.",
  str_homestory_801901001_33_dialog_content = "Err... Tenemos sombrillas allí. Victoria, te gustaría moverte?",
  str_homestory_801901001_34_dialog_content = "Gracias por su preocupación, PlayerName. Creo que me vendría bien un poco de descanso.",
  str_homestory_801901001_35_dialog_content = "¡Que la Verdad los bendiga!",
  str_homestory_800901001_0_dialog_content = "Señor. Faust?",
  str_homestory_800901001_1_dialog_content = "Querido navegante, me alegro de verte de nuevo.",
  str_homestory_800901001_2_dialog_content = "Igualmente.",
  str_homestory_800901001_3_dialog_content = "En realidad, no esperaba verte durante el día.",
  str_homestory_800901001_4_dialog_content = "Por favor, no me tomes a mal. Personalmente prefiero la noche, pero no estoy en contra de la energía del día.",
  str_homestory_800901001_5_dialog_content = "A Wispy parece gustarle este lugar.",
  str_homestory_800901001_6_dialog_content = "... Esperar. Wispy le gusta aquí?",
  str_homestory_800901001_7_dialog_content = "¿Tenemos mucha tristeza y desesperación aquí?",
  str_homestory_800901001_8_dialog_content = "Todavía recuerdo cómo este caso especial babeaba sobre mi impotencia...",
  str_homestory_800901001_9_dialog_content = "Wispy puede encontrar consuelo en muchas cosas.",
  str_homestory_800901001_10_dialog_content = "Recuerdos tristes, pesadillas, creencias desesperadas, o agua fría...",
  str_homestory_800901001_11_dialog_content = "¡¿Eh?!",
  str_homestory_800901001_12_dialog_content = "(Recordando el tiempo dedicado a cuidar a Wispy...<sprite=emo_sikao size=60 />)",
  str_homestory_800901001_13_dialog_content = "(¿Entonces la gente está triste y tiene pesadillas aquí?)",
  str_homestory_800901001_14_dialog_content = "Estimado Navegante, por favor no piense demasiado.",
  str_homestory_800901001_15_dialog_content = "El consuelo de Wispy...",
  str_homestory_800901001_16_dialog_content = "Podría provenir del pasado de los aurorianos, no de sus sentimientos actuales.",
  str_homestory_800901001_17_dialog_content = "Hasta donde yo sé, muchos de nosotros tuvimos un pasado amargo y doloroso.",
  str_homestory_800901001_18_dialog_content = "Si lo pones de esta manera...",
  str_homestory_800901001_19_dialog_content = "Sí, muy cierto.",
  str_homestory_800901001_20_dialog_content = "Espero que todos estén felices aquí.",
  str_homestory_800901001_21_dialog_content = "A veces, los recuerdos y las emociones están fuera de control, querido Navegante.",
  str_homestory_800901001_22_dialog_content = "Es un buen hábito no preocuparse excesivamente por los demás.",
  str_homestory_800901001_23_dialog_content = "Deja que la naturaleza siga su curso.",
  str_homestory_800901001_24_dialog_content = "... Está bien...",
  str_homestory_800901001_25_dialog_content = "Entonces, ¿por qué estás aquí?",
  str_homestory_800901001_26_option_content = "¿Difundir la verdad?",
  str_homestory_800901001_27_dialog_content = "No, mi querido Navegante.",
  str_homestory_800901001_28_option_content = "¿Alimentando a Wispy?",
  str_homestory_800901001_29_dialog_content = "Sí, mi querido Navegante.",
  str_homestory_800901001_30_dialog_content = "Este es el lugar perfecto para alimentar a Wispy...",
  str_homestory_800901001_31_dialog_content = "Wispy puede sentir libremente a los transeúntes.",
  str_homestory_800901001_32_dialog_content = "Deja que Wispy sienta libremente...",
  str_homestory_800901001_33_dialog_content = "Err... ¿Hay tanto dolor indescriptible en sus corazones?",
  str_homestory_800901001_34_dialog_content = "Tu conjetura es tan buena como la mía, querido Navegante.",
  str_homestory_800901001_35_dialog_content = "Sin embargo, aquí hay una cosa que sé con certeza.",
  str_homestory_800901001_36_dialog_content = "¿Si?",
  str_homestory_800901001_37_dialog_content = "Wispy bebió una tonelada de agua fría antes de salir de casa.",
  str_homestory_800901001_38_dialog_content = "?",
  str_homestory_800901001_39_dialog_content = "Entonces, ¿la comodidad de Wispy podría ser el resultado de toda el agua helada que acaba de beber?",
  str_homestory_800901001_40_dialog_content = "Eso significa que, después de todo, es posible que no haya mucha tristeza, dolor u otros sentimientos negativos.",
  str_homestory_800901001_41_dialog_content = "¡Me engañaste!",
  str_homestory_800901001_42_dialog_content = "Me temo que sí, mi querido Navegante.",
  str_homestory_800901001_43_dialog_content = "Pero lo hice para distraerte de todo el trabajo y el estrés.",
  str_homestory_800901001_44_dialog_content = "Las cosas no tienen que ser perfectas, ¿verdad?",
  str_homestory_800901001_45_dialog_content = "¡Que la Verdad los bendiga!",
  str_homestory_800901001_46_dialog_content = "Por qué tú...!<sprite=emo_shengqi size=60 />",
  str_homestory_815101001_0_dialog_content = "Esta canción de cuna...",
  str_homestory_815101001_1_dialog_content = "Hay un cordero negro llamado Isaac. ¡El vellón aterrador puede quemarte el brazo!",
  str_homestory_815101001_2_dialog_content = "Hola, Giles!",
  str_homestory_815101001_3_dialog_content = "ah Estimado Navegante.",
  str_homestory_815101001_4_dialog_content = "Casi lo olvido. Ya has escuchado esta canción de cuna.",
  str_homestory_815101001_5_dialog_content = "¿Es hora de algo nuevo?",
  str_homestory_815101001_6_dialog_content = "Una obra nueva, un tanto profética, centrada en la intrigante Caelestita...<sprite=emo_baimao size=60 />",
  str_homestory_815101001_7_dialog_content = "Err...",
  str_homestory_815101001_8_dialog_content = "¿Pareces reacio, Navegante?",
  str_homestory_815101001_9_dialog_content = "Eso me rompe el corazón...",
  str_homestory_815101001_10_dialog_content = "Dijiste que mis canciones infantiles eran tus favoritas...",
  str_homestory_815101001_11_dialog_content = "(... ¿De verdad?)",
  str_homestory_815101001_12_option_content = "¿Has terminado de crear la obra?",
  str_homestory_815101001_13_dialog_content = "No se tarda mucho cuando hay inspiración.",
  str_homestory_815101001_14_dialog_content = "Perfecto. La fuente de inspiración está justo frente a mí...",
  str_homestory_815101001_15_option_content = "¿Podrías esperar?",
  str_homestory_815101001_16_dialog_content = "Ni siquiera te molestaste en inventar alguna excusa.",
  str_homestory_815101001_17_dialog_content = "Esto es un claro rechazo para mí.",
  str_homestory_815101001_18_dialog_content = "Encantador y ágil, el Caelestita puede robarte fácilmente el corazón...",
  str_homestory_815101001_19_dialog_content = "... ¿Ya iniciado?",
  str_homestory_815101001_20_dialog_content = "¡La la la! ¡La la la! Una casa encantadora llena de flores.",
  str_homestory_815101001_21_dialog_content = "Los peces y los camarones también lo llaman hogar.",
  str_homestory_815101001_22_dialog_content = "Ella vive aquí con eso. Juntos abrazan a un intrépido Caelestite.",
  str_homestory_815101001_23_dialog_content = "Pitpat... Pitpat... La lluvia del tiempo llovizna.",
  str_homestory_815101001_24_dialog_content = "Construye torres altas. Reforzarlos con ladrillos y tejas. Busque formas de volverse más fuerte.",
  str_homestory_815101001_25_dialog_content = "¡La la la! ¡La la la! ¿Dónde está Caelestite ahora?",
  str_homestory_815101001_26_dialog_content = "El hogar ahora es grande y alto. Mira a Caelestite sobre las nubes, sin parpadear.",
  str_homestory_815101001_27_dialog_content = "¡La la la! ¡La la la! Una casa con encanto llena de flores...",
  str_homestory_815101001_28_dialog_content = "... ¿Esta es tu profecía?",
  str_homestory_815101001_29_dialog_content = "Solo una simple canción de cuna, Navigator.",
  str_homestory_815101001_30_dialog_content = "¿Tienes miedo? solo es un trabajo mio...",
  str_homestory_815101001_31_dialog_content = "Sí, lo sé.",
  str_homestory_815101001_32_dialog_content = "A menudo encuentro tus rimas infantiles simples pero oscuras.",
  str_homestory_815101001_33_dialog_content = "Una canción infantil no es más que una canción infantil.",
  str_homestory_815101001_34_dialog_content = "Navegante, por favor, no pienses demasiado en ello.",
  str_homestory_815101001_35_dialog_content = "Multa. Volvamos a la vida real...",
  str_homestory_815101001_36_dialog_content = "¿Cómo te sientes aquí?",
  str_homestory_815101001_37_dialog_content = "Isaac y yo lo amamos.",
  str_homestory_815101001_38_dialog_content = "Tengo un fuerte deseo de escribir más... ¡Hahah!",
  str_homestory_815101001_39_dialog_content = "Ya sean los transeúntes al azar o el Navegador, todos son fuentes de inspiración para mí.<sprite=emo_emo size=60 />",
  str_homestory_815101001_40_dialog_content = "bueno escuchar...",
  str_homestory_815101001_41_dialog_content = "BAA Baa...",
  str_homestory_815101001_42_dialog_content = "Necesito un momento a solas con Isaac. Discúlpenos, Navegante.",
  str_homestory_815101001_43_dialog_content = "¿Nos vemos la próxima vez?",
  str_homestory_815101001_44_dialog_content = "Muy bien... Nos vemos.",
  str_homestory_815301001_0_dialog_content = "¿El Gran Mariscal?",
  str_homestory_815301001_1_dialog_content = "Hiciste un gran trabajo con la infraestructura.<sprite=emo_dianzan size=60 />",
  str_homestory_815301001_2_dialog_content = "¡Gracias por sus amables palabras, Gran Mariscal!",
  str_homestory_815301001_3_dialog_content = "Estoy tan acostumbrado a los cuadrados limpios y uniformes en Illumina. Este es diferente y refrescante.",
  str_homestory_815301001_4_dialog_content = "La gente menosprecia a Illumina por nuestro mal gusto en el arte y nuestro bajo nivel de belleza.",
  str_homestory_815301001_5_dialog_content = "Lamentablemente, muchos de esos lugares que persiguen la perfección en el arte están luchando por alimentar a su gente.",
  str_homestory_815301001_6_dialog_content = "Las cosas bien estructuradas cuestan menos y funcionan de manera más eficiente. Esto es bastante simple de entender.",
  str_homestory_815301001_7_dialog_content = "Pero tengo que decir que es hermoso aquí.",
  str_homestory_815301001_8_dialog_content = "Bonito y marea. Vice y usted debe haber trabajado duro para esto.",
  str_homestory_815301001_9_option_content = "Asentir",
  str_homestory_815301001_10_dialog_content = "fue en su mayoría Vice... No sé mucho sobre esto en absoluto.",
  str_homestory_815301001_11_dialog_content = "Bueno, es un mérito reconocer tus defectos.",
  str_homestory_815301001_12_option_content = "Sacudir la cabeza",
  str_homestory_815301001_13_dialog_content = "No está mal. Las luciérnagas ayudaron mucho. Y nuestros amigos de Courier Union.",
  str_homestory_815301001_14_dialog_content = "Es un placer siempre y cuando todos se diviertan aquí.",
  str_homestory_815301001_15_dialog_content = "¿No es esta la cualidad más preciosa que tienen ustedes dos?",
  str_homestory_815301001_16_dialog_content = "En mi opinión, el placer de servir a los demás es un don especial.",
  str_homestory_815301001_17_dialog_content = "Como has arreglado cuidadosamente...",
  str_homestory_815301001_18_dialog_content = "Me quedo en una habitación como Vice's. Y comemos la misma comida todos los días.",
  str_homestory_815301001_19_dialog_content = "Me estás tratando mucho mejor que la mayoría de la gente.",
  str_homestory_815301001_20_dialog_content = "Es difícil tratar a todos por igual, independientemente de su estatus y posición.",
  str_homestory_815301001_21_dialog_content = "(No esperaba que el Gran Mariscal viera las cosas desde este ángulo...)",
  str_homestory_815301001_22_dialog_content = "(¿Debería decir la verdad?)",
  str_homestory_815301001_23_dialog_content = "(Vale... será mejor que sea honesto...)",
  str_homestory_815301001_24_dialog_content = "En realidad, Gran Mariscal...",
  str_homestory_815301001_25_dialog_content = "No podemos permitirnos mejores habitaciones...",
  str_homestory_815301001_26_dialog_content = "Eso lo sé.",
  str_homestory_815301001_27_dialog_content = "No se trata de qué tan grande es su presupuesto, sino cómo planea gastar el dinero en primer lugar.",
  str_homestory_815301001_28_dialog_content = "Creo que lo tengo...",
  str_homestory_815301001_29_dialog_content = "Eso es bueno.",
  str_homestory_815301001_30_dialog_content = "Voy a visitar a mis camaradas Illumina.",
  str_homestory_815301001_31_dialog_content = "Adiós, PlayerName.",
  str_homestory_815301001_32_dialog_content = "¡Fue un honor hablar con usted, Gran Mariscal!",
  str_homestory_803801001_0_dialog_content = "¿Jugando de nuevo?",
  str_homestory_803801001_1_dialog_content = "Hola, PlayerName!",
  str_homestory_803801001_2_dialog_content = "Jejeje... ¿Te apetece un juego?",
  str_homestory_803801001_3_dialog_content = "Ah, No.",
  str_homestory_803801001_4_dialog_content = "Sólo quiero preguntarte cómo te estás instalando aquí.",
  str_homestory_803801001_5_dialog_content = "Mmm...",
  str_homestory_803801001_6_dialog_content = "Nada mal. Podría usar algunas instalaciones recreativas más.",
  str_homestory_803801001_7_dialog_content = "Mmm. ¡Lo tengo! el super dulce PlayerName debe estar aquí para ayudar a aliviar el aburrimiento. ¿Tengo razón?",
  str_homestory_803801001_8_dialog_content = "Eh... yo...",
  str_homestory_803801001_9_dialog_content = "Jejeje Juguemos un juego simple...",
  str_homestory_803801001_10_dialog_content = "Es muy fácil. ¡No necesitamos ningún dispositivo!",
  str_homestory_803801001_11_dialog_content = "¿Te refieres a... piedra, papel o tijera?",
  str_homestory_803801001_12_dialog_content = "¡No! ¡Prueba!",
  str_homestory_803801001_13_dialog_content = "¿Listo? ¡El juego está a punto de comenzar!",
  str_homestory_803801001_14_dialog_content = "Bien... Solo porque estás muy interesado en esto.",
  str_homestory_803801001_15_dialog_content = "¡Pregunta 1! ¡Responda verdadero o falso!",
  str_homestory_803801001_16_dialog_content = "Divulgación del oficial técnico de Illumina GronruEl origen del misterio... ¡En realidad es un androide!",
  str_homestory_803801001_17_option_content = "Cierto",
  str_homestory_803801001_18_dialog_content = "¿Que demonios? ¡No soy un androide!",
  str_homestory_803801001_19_option_content = "Falso",
  str_homestory_803801001_20_dialog_content = "¡Bingo! ¡Correcto!<sprite=emo_dianzan size=60 />",
  str_homestory_803801001_21_dialog_content = "¡Pregunta 2!",
  str_homestory_803801001_22_dialog_content = "Raphael venció una vez Gronru en la Copa del Emperador!",
  str_homestory_803801001_23_option_content = "Cierto",
  str_homestory_803801001_24_dialog_content = "¡Oye! Nadie puede vencerme, ¿de acuerdo?",
  str_homestory_803801001_25_dialog_content = "Incluso la ayudé a mejorar esos aparatos.",
  str_homestory_803801001_26_option_content = "Falso",
  str_homestory_803801001_27_dialog_content = "¡Correcto! ¡Buen trabajo!",
  str_homestory_803801001_28_dialog_content = "¡Pregunta 3!",
  str_homestory_803801001_29_dialog_content = "PlayerName transferirá los permisos del sistema operativo a este lugar para Gronru!",
  str_homestory_803801001_30_dialog_content = "Verdadero...",
  str_homestory_803801001_31_dialog_content = "¡Esperar! ¡Esta pregunta no debería permitirse en ningún cuestionario!",
  str_homestory_803801001_32_dialog_content = "Ah, oh... ¿No?",
  str_homestory_803801001_33_dialog_content = "Err... Por supuesto que no, Gronru!",
  str_homestory_803801001_34_dialog_content = "¡Mmm! ¿Me rechazaste?",
  str_homestory_803801001_35_dialog_content = "¡Debes estar poseído por el jefe final!",
  str_homestory_803801001_36_dialog_content = "¿Poseído? ¿Que te hizo decir eso?",
  str_homestory_803801001_37_dialog_content = "¡Un verdadero caelestita nunca puede decirme que no!",
  str_homestory_803801001_38_dialog_content = "¡La súper amable Caelestite nunca rechazó una sola solicitud mía en el pasado!",
  str_homestory_803801001_39_dialog_content = "Pfft...",
  str_homestory_803801001_40_dialog_content = "Probablemente renunciaría a cualquier cosa por ti excepto a los permisos para el Coloso y este lugar. Gronru.",
  str_homestory_803801001_41_dialog_content = "Ahh... Eso es aburrido...",
  str_homestory_803801001_42_dialog_content = "Sin embargo...",
  str_homestory_803801001_43_dialog_content = "Ya que ha negado mi solicitud de investigación, ¡tendré que hacerlo en secreto!",
  str_homestory_803801001_44_dialog_content = "Un día... Jejeje. ¡Un día! ¡Averiguaré cómo funciona este sistema!",
  str_homestory_803801001_45_dialog_content = "Bien.",
  str_homestory_803801001_46_dialog_content = "La mejor de las suertes.",
  str_homestory_803801001_47_dialog_content = "¡Un nuevo juego está en marcha! Muy emocionante...<sprite=emo_yaosu size=60 />",
  str_homestory_802601001_0_dialog_content = "Uriel...",
  str_homestory_802601001_1_dialog_content = "...",
  str_homestory_802601001_2_dialog_content = "...",
  str_homestory_802601001_3_dialog_content = "¿Q-qué quieres?",
  str_homestory_802601001_4_dialog_content = "Ah nada. Solo quería verte.",
  str_homestory_802601001_5_dialog_content = "Me preocupa si estás bien aquí. Recuerdo que pasaste muchas noches sin dormir en el Coloso.",
  str_homestory_802601001_6_dialog_content = "No hay nada que no esté bien...",
  str_homestory_802601001_7_dialog_content = "Después de todo, las dos únicas cosas que realmente me importan son mi Anillo de Fuego y mi Abrigo de Fénix...",
  str_homestory_802601001_8_dialog_content = "Umm... ¿Hay algo que pueda conseguirte entonces?",
  str_homestory_802601001_9_dialog_content = "¿Comida, juguetes, cualquier cosa?",
  str_homestory_802601001_10_dialog_content = "¡Tú puedes decirme cualquier cosa!",
  str_homestory_802601001_11_dialog_content = "no quiero nada...",
  str_homestory_802601001_12_dialog_content = "voy a quemar<sprite=emo_nuhuo size=60 /> todos ellos al suelo...",
  str_homestory_802601001_13_dialog_content = "De ninguna manera, Uriel.",
  str_homestory_802601001_14_dialog_content = "He instalado instalaciones de prevención de incendios aquí. ¡No tienes que preocuparte por nada!",
  str_homestory_802601001_15_dialog_content = "Ok...",
  str_homestory_802601001_16_dialog_content = "¡Sí!",
  str_homestory_802601001_17_dialog_content = "¿Cualquier cosa?",
  str_homestory_802601001_18_dialog_content = "...",
  str_homestory_802601001_19_dialog_content = "... No.",
  str_homestory_802601001_20_dialog_content = "Los juguetes y las instalaciones recreativas no pueden proporcionar una alegría duradera...",
  str_homestory_802601001_21_dialog_content = "Es breve y barato...",
  str_homestory_802601001_22_dialog_content = "En realidad, tal alegría transitoria a menudo es seguida por un dolor interminable...",
  str_homestory_802601001_23_dialog_content = "Solo piensa en la tortura que sufrirás en llamas por esta felicidad momentánea...",
  str_homestory_802601001_24_dialog_content = "Prefiero no tener nada de esto...",
  str_homestory_802601001_25_dialog_content = "Además... No siempre hay alegría después del dolor...",
  str_homestory_802601001_26_dialog_content = "Todo lo contrario, la alegría momentánea puede ser engañosa, creando la ilusión de que tu sufrimiento siempre vale la pena...",
  str_homestory_802601001_27_dialog_content = "Pero eso no es cierto en absoluto, ya que el sufrimiento es infinito y el \"gozo\" es finito...<sprite=emo_xinsui size=60 />",
  str_homestory_802601001_28_dialog_content = "... ¿No estás de acuerdo, PlayerName?",
  str_homestory_802601001_29_dialog_content = "(Todo suena razonable pero no puedo seguir su lógica...)",
  str_homestory_802601001_30_option_content = "Si",
  str_homestory_802601001_31_dialog_content = "Probablemente tengas razón en algún sentido, Uriel.",
  str_homestory_802601001_32_option_content = "No",
  str_homestory_802601001_33_dialog_content = "Entiendo de dónde vienes, pero no puedo estar de acuerdo contigo...",
  str_homestory_802601001_34_dialog_content = "(Lo más importante ahora es calmarla...)",
  str_homestory_802601001_35_dialog_content = "Uriel cree que la alegría después del dolor es barata y momentánea...",
  str_homestory_802601001_36_dialog_content = "Pero mucha gente vive para este gozo pasajero.",
  str_homestory_802601001_37_dialog_content = "A veces, esta pequeña alegría después del sufrimiento es esperanza.",
  str_homestory_802601001_38_dialog_content = "Y esta esperanza nos mantiene en marcha para la próxima ronda de alegría...",
  str_homestory_802601001_39_dialog_content = "Por corta y diminuta que sea la alegría cada vez, es un momento de consuelo.",
  str_homestory_802601001_40_dialog_content = "La felicidad no es una recompensa por el dolor que has sufrido.",
  str_homestory_802601001_41_dialog_content = "Al contrario, es la nutrición que necesitamos desesperadamente para seguir soportando el dolor.",
  str_homestory_802601001_42_dialog_content = "...",
  str_homestory_802601001_43_dialog_content = "... Nutrición...",
  str_homestory_802601001_44_dialog_content = "... Quizás...",
  str_homestory_802601001_45_dialog_content = "(No creo que esté convencida...)",
  str_homestory_802601001_46_dialog_content = "Ahh... De todos modos, Uriel¡Por favor, no trates la felicidad como una carga!",
  str_homestory_802601001_47_dialog_content = "... De acuerdo...",
  str_homestory_802601001_48_dialog_content = "... Lo tengo, PlayerName...",
  str_homestory_802601001_49_dialog_content = "... Gracias por su preocupación...",
  str_homestory_802601001_50_dialog_content = "No lo menciones...",
  str_homestory_802601001_51_dialog_content = "Ahh... Hablando de felicidad...",
  str_homestory_802601001_52_dialog_content = "(Recuerdo que le gusta bastante leer, especialmente aquellas obras literarias populares en Umbraton...)",
  str_homestory_802601001_53_dialog_content = "Uriel, ¿qué tal si te presto algunos libros?",
  str_homestory_802601001_54_dialog_content = "Podrías leer si te aburres.",
  str_homestory_802601001_55_dialog_content = "No te preocupes. Muchos de nosotros estamos viviendo aquí ahora. Tengo algunos ejemplares de cada libro...",
  str_homestory_802601001_56_dialog_content = "... Libros...",
  str_homestory_802601001_57_dialog_content = "...",
  str_homestory_802601001_58_dialog_content = "... Suena bien...",
  str_homestory_802601001_59_dialog_content = "leeré...",
  str_homestory_802601001_60_dialog_content = "Uf... Eso es maravilloso.",
  str_homestory_804401001_0_dialog_content = "Vivian?",
  str_homestory_804401001_1_dialog_content = "El columpio es muy divertido, PlayerName!",
  str_homestory_804401001_2_dialog_content = "¡Sí! Estoy de acuerdo.",
  str_homestory_804401001_3_dialog_content = "El viento sopla suavemente en mi cara. No hay una preocupación en mi mente...<sprite=emo_pugongying size=60 />",
  str_homestory_804401001_4_dialog_content = "El columpio me empuja lentamente a los brazos del viento...",
  str_homestory_804401001_5_dialog_content = "Todo mi estrés se ha ido como un milagro.",
  str_homestory_804401001_6_dialog_content = "Me alegra que te sientas tan relajado en el columpio.",
  str_homestory_804401001_7_dialog_content = "Hmm... El único inconveniente de esta actividad recreativa es...",
  str_homestory_804401001_8_dialog_content = "Mi cabello está un poco desordenado después. jajaja",
  str_homestory_804401001_9_dialog_content = "¡Es Correcto!",
  str_homestory_804401001_10_dialog_content = "No es de extrañar Vice ¡Insiste en arreglarse el cabello cada vez que se baja del columpio!",
  str_homestory_804401001_11_dialog_content = "Entonces... ¿A quién se le ocurrió la idea de construir un columpio, a ti o Vice?",
  str_homestory_804401001_12_option_content = "Fui yo.",
  str_homestory_804401001_13_dialog_content = "Para ser honesto, realmente no jugué en un columpio mientras crecía...",
  str_homestory_804401001_14_dialog_content = "Pensé que sería bueno tener uno aquí.",
  str_homestory_804401001_15_option_content = "Fue Vice.",
  str_homestory_804401001_16_dialog_content = "Vice muy exigido uno aquí!",
  str_homestory_804401001_17_dialog_content = "No estaba seguro de esto al principio, pero siguió adelante con confianza con el dibujo de la construcción a pesar de mis dudas. Pensé...",
  str_homestory_804401001_18_dialog_content = "No fue gran cosa poner un columpio aquí. A algunos de ustedes les puede gustar.",
  str_homestory_804401001_19_dialog_content = "Ahh...",
  str_homestory_804401001_20_dialog_content = "¡Esta es una decisión fabulosa!",
  str_homestory_804401001_21_dialog_content = "Jejeje... Gracias por tus amables palabras, Vivian.",
  str_homestory_804401001_22_dialog_content = "Hablando de columpios...",
  str_homestory_804401001_23_dialog_content = "No hay muchos en Illumina.",
  str_homestory_804401001_24_dialog_content = "Hmm... ¿Es eso así?",
  str_homestory_804401001_25_dialog_content = "Esta es probablemente la razón por la que Vice y Vivian ambos aman tanto este columpio.",
  str_homestory_804401001_26_dialog_content = "Sí. Las cosas que rara vez se ven son más atractivas.",
  str_homestory_804401001_27_dialog_content = "Mmm... cierto...",
  str_homestory_804401001_28_dialog_content = "¿Ummm? ¿Qué tienes en mente?",
  str_homestory_804401001_29_dialog_content = "Ahh... Nada.",
  str_homestory_804401001_30_dialog_content = "Estaba calculando lo necesario que es este gasto <sprite=emo_baiyebi size=60 />es.",
  str_homestory_804401001_31_dialog_content = "¿Gastos?",
  str_homestory_804401001_32_dialog_content = "¿Qué gasto?",
  str_homestory_804401001_33_dialog_content = "Me pregunto cuánto costará construir un columpio...",
  str_homestory_804401001_34_dialog_content = "En todos los orfanatos, escuelas y bases de Illumina.",
  str_homestory_804401001_35_dialog_content = "Ah, ya veo.",
  str_homestory_804401001_36_dialog_content = "No creo que nuestro presupuesto pueda permitirse este proyecto...",
  str_homestory_804401001_37_dialog_content = "A menos que otros proyectos nuestros puedan reducir algunos costos.",
  str_homestory_804401001_38_dialog_content = "Hmm... Eso es complicado.",
  str_homestory_804401001_39_dialog_content = "¿Qué tal unos columpios menos?",
  str_homestory_804401001_40_dialog_content = "¿Menos columpios pero en mejores ubicaciones?",
  str_homestory_804401001_41_dialog_content = "Como...",
  str_homestory_804401001_42_dialog_content = "¡En algún lugar por donde pasaría todo el mundo!",
  str_homestory_804401001_43_dialog_content = "Como los cruces entre las ciudades subterráneas, y el medio de varios orfanatos o escuelas...",
  str_homestory_804401001_44_dialog_content = "Eres un genio, pequeño PlayerName!",
  str_homestory_804401001_45_dialog_content = "Feliz de ayudar.",
  str_homestory_804401001_46_dialog_content = "Sin embargo...",
  str_homestory_804401001_47_dialog_content = "¿Por qué estabas tan nervioso cuando mencioné el presupuesto antes?",
  str_homestory_804401001_48_dialog_content = "Ja... Ah, ja...",
  str_homestory_804401001_49_dialog_content = "Sonabas como Vice cuando revisa el libro de cuentas...",
  str_homestory_804401001_50_dialog_content = "¡Probablemente fue una respuesta condicionada!",
  str_homestory_804401001_51_dialog_content = "Oh... poco Vice y poco PlayerName están tan cerca...<sprite=emo_guilian size=60 />",
  str_homestory_808501001_0_dialog_content = "Jane?",
  str_homestory_808501001_1_dialog_content = "Hola, PlayerName.",
  str_homestory_808501001_2_dialog_content = "Ah, Jane!",
  str_homestory_808501001_3_dialog_content = "¿Estás... tomando notas de Cloud Gardens?",
  str_homestory_808501001_4_dialog_content = "Sí, voy a anotar todo lo que sucede aquí.",
  str_homestory_808501001_5_dialog_content = "Pero ahora mismo no estoy grabando. Este es un momento para dejarse llevar por completo.<sprite=emo_pugongying size=60 />",
  str_homestory_808501001_6_dialog_content = "¿Déjalo ir?",
  str_homestory_808501001_7_dialog_content = "¿Qué sucedió? ¿Algo te preocupa?",
  str_homestory_808501001_8_dialog_content = "¿O hay demasiada presión?",
  str_homestory_808501001_9_dialog_content = "Supongo que ambos.",
  str_homestory_808501001_10_dialog_content = "PlayerName, como Testigo profesional, no puedo intervenir en ciertas cosas.",
  str_homestory_808501001_11_dialog_content = "Sí, escuché sobre eso.",
  str_homestory_808501001_12_dialog_content = "Bueno.",
  str_homestory_808501001_13_dialog_content = "Si fuera Testigo, ¿ayudaría a una víctima de una pelea de pandillas?",
  str_homestory_808501001_14_option_content = "Por supuesto.",
  str_homestory_808501001_15_dialog_content = "Ser testigo es solo un trabajo...",
  str_homestory_808501001_16_option_content = "No.",
  str_homestory_808501001_17_dialog_content = "A mí no me importa tanto ser absolutamente objetivo...",
  str_homestory_808501001_18_dialog_content = "Podría llamar a alguien para que me ayude de inmediato.",
  str_homestory_808501001_19_dialog_content = "Entonces, ¿tratarías de ayudar pero no te involucrarías?",
  str_homestory_808501001_20_dialog_content = "Exactamente.",
  str_homestory_808501001_21_dialog_content = "que seria Jane ¿hacer?",
  str_homestory_808501001_22_dialog_content = "Era una pregunta muy específica la que acabas de hacer. ¿Te preocupa algo así en la vida real?",
  str_homestory_808501001_23_dialog_content = "Sí. Hace poco ayudé a una niña.",
  str_homestory_808501001_24_dialog_content = "Todavía estoy preocupado por la decisión que tomé en ese momento.",
  str_homestory_808501001_25_dialog_content = "¿Cuáles son tus preocupaciones?",
  str_homestory_808501001_26_dialog_content = "¿Qué pasaría si mi interferencia cambiara cómo se habrían desarrollado las cosas?",
  str_homestory_808501001_27_dialog_content = "Cuando un testigo vacila, su testimonio ya no es neutral.",
  str_homestory_808501001_28_dialog_content = "Podría ser el destino de esa niña desaparecer de este mundo. Y se suponía que esa era la consecuencia de esta pelea de pandillas.",
  str_homestory_808501001_29_dialog_content = "Ahora la salvé...",
  str_homestory_808501001_30_dialog_content = "... Mi testimonio sesgado no tiene sentido.",
  str_homestory_808501001_31_dialog_content = "En primer lugar, eres una persona real con sentimientos. Entonces, eres un testigo que hace todo lo posible por permanecer neutral.",
  str_homestory_808501001_32_dialog_content = "Esto lo entiendo.",
  str_homestory_808501001_33_dialog_content = "...",
  str_homestory_808501001_34_dialog_content = "...Ya veo.",
  str_homestory_808501001_35_dialog_content = "¿Qué tal si te incluyes a ti mismo en este testimonio?",
  str_homestory_808501001_36_dialog_content = "¿Incluyéndome a mi?",
  str_homestory_808501001_37_dialog_content = "Sí, escribe fielmente toda la historia.",
  str_homestory_808501001_38_dialog_content = "Un Testigo desencadenado por la escena intervino en el proceso después de esta pelea de pandillas... Podría tener un impacto.",
  str_homestory_808501001_39_dialog_content = "... Algo como eso.",
  str_homestory_808501001_40_dialog_content = "...",
  str_homestory_808501001_41_dialog_content = "Tienes un punto.",
  str_homestory_808501001_42_dialog_content = "Trataré de registrar el incidente de esta manera.",
  str_homestory_808501001_43_dialog_content = "Gracias.",
  str_homestory_808801001_0_dialog_content = "Maggie!",
  str_homestory_808801001_1_dialog_content = "Navegante... ¿También estás aquí por la historia?<sprite=emo_wuzui size=60 />",
  str_homestory_808801001_2_dialog_content = "¿Historia? ¿Que historia?",
  str_homestory_808801001_3_dialog_content = "Pensé que podríamos tener una charla. Ahora estoy muy interesado en esta historia.",
  str_homestory_808801001_4_dialog_content = "Ah oh... Se me escapó...",
  str_homestory_808801001_5_dialog_content = "¿Mmm? Maggie no quiere que yo sepa?",
  str_homestory_808801001_6_dialog_content = "Así no...",
  str_homestory_808801001_7_dialog_content = "Bien... Ya no es un secreto de todos modos...",
  str_homestory_808801001_8_dialog_content = "¿Qué es?",
  str_homestory_808801001_9_dialog_content = "Hmm... Hace unos días, estaba explorando en el desierto...",
  str_homestory_808801001_10_dialog_content = "Cuando me encontré con algunos niños.",
  str_homestory_808801001_11_dialog_content = "Obviamente se escaparon de casa y se perdieron en el vasto desierto...",
  str_homestory_808801001_12_dialog_content = "Los vi dando vueltas en círculos, así que me ofrecí a ayudar.",
  str_homestory_808801001_13_dialog_content = "Después de escoltarlos a un lugar seguro, me preguntaron mi nombre y querían venir a agradecerme algún día.",
  str_homestory_808801001_14_dialog_content = "Antes de que pudiera presentarme, vieron mi cola... Ellos...",
  str_homestory_808801001_15_option_content = "¿Se rieron de ti?",
  str_homestory_808801001_16_dialog_content = "No...",
  str_homestory_808801001_17_dialog_content = "¡Dijeron que mi cola era muy linda!",
  str_homestory_808801001_18_dialog_content = "Eso es bueno, ¿no?",
  str_homestory_808801001_19_option_content = "¿Te reconocieron?",
  str_homestory_808801001_20_dialog_content = "No...",
  str_homestory_808801001_21_dialog_content = "no soy popular como Fleur...",
  str_homestory_808801001_22_dialog_content = "Pero ellos...",
  str_homestory_808801001_23_dialog_content = "¡Me confundieron con un dragón!",
  str_homestory_808801001_24_dialog_content = "?",
  str_homestory_808801001_25_dialog_content = "yo estaba igual de sorprendida...",
  str_homestory_808801001_26_dialog_content = "¡Pensé que era escandaloso!",
  str_homestory_808801001_27_dialog_content = "Me dijeron que nunca antes habían visto un dragón con una cola esponjosa...",
  str_homestory_808801001_28_dialog_content = "Me preguntaron si podían tocarme la cola...",
  str_homestory_808801001_29_dialog_content = "¡Me enojé mucho!<sprite=emo_wuyun size=60 />",
  str_homestory_808801001_30_dialog_content = "¿Por qué? ¿No podrías simplemente explicarles la situación?",
  str_homestory_808801001_31_dialog_content = "No me importó que me confundieran con otra cosa, ¡pero su actitud era irritante!",
  str_homestory_808801001_32_dialog_content = "\"¿Podemos sentir tu cola?\"",
  str_homestory_808801001_33_dialog_content = "¿Qué tipo de solicitud es esta?",
  str_homestory_808801001_34_dialog_content = "¿A quién le dirías tal cosa además de a tu mascota?",
  str_homestory_808801001_35_dialog_content = "Yo... estoy tan enojado...",
  str_homestory_808801001_36_dialog_content = "quiero prenderle fuego a todo<sprite=emo_nuhuo size=60 />! ¡En este momento!",
  str_homestory_808801001_37_dialog_content = "(¡No otra vez!)",
  str_homestory_808801001_38_dialog_content = "Cálmate, Maggie!",
  str_homestory_808801001_39_dialog_content = "¿Qué pasaría si simplemente encontraran tu cola extremadamente linda?",
  str_homestory_808801001_40_dialog_content = "¡E-así es como me siento al respecto todo este tiempo!",
  str_homestory_808801001_41_dialog_content = "... Para ser honesto, no puedo imaginar cómo Maggie sería sin esta hermosa cola.",
  str_homestory_808801001_42_dialog_content = "...",
  str_homestory_808801001_43_dialog_content = "... ¿En serio?",
  str_homestory_808801001_44_dialog_content = "(Uf... Parece menos enfadada ahora...)",
  str_homestory_808801001_45_dialog_content = "Sí, Maggie! ¡Lo juro!",
  str_homestory_808801001_46_dialog_content = "... Bien entonces...",
  str_homestory_808801001_47_dialog_content = "¡Ay! De paso...",
  str_homestory_808801001_48_dialog_content = "¿Antes dijiste que ya no era un secreto?",
  str_homestory_808801001_49_dialog_content = "No creo que muchas personas estén al tanto de este incidente...",
  str_homestory_808801001_50_dialog_content = "Porque...",
  str_homestory_808801001_51_dialog_content = "Jomu incluyó esto en su última colección de cuentos...",
  str_homestory_808801001_52_dialog_content = "... Hmm... Debí haber pensado en esto yo mismo...",
  str_homestory_800801001_0_dialog_content = "Brock?",
  str_homestory_800801001_1_dialog_content = "¡Jajaja! Que bueno verte.<sprite=emo_yaosu size=60 />",
  str_homestory_800801001_2_dialog_content = "¿Lo viste? Bastante genial, ¿verdad?",
  str_homestory_800801001_3_dialog_content = "Err... ¿De qué estás hablando? Brock?",
  str_homestory_800801001_4_dialog_content = "¡Mis golpes! ¡Pulcro! ¡Guapo!",
  str_homestory_800801001_5_dialog_content = "Umm... No está mal...",
  str_homestory_800801001_6_dialog_content = "¿No está nada mal? ¿Eso es todo lo que tengo?",
  str_homestory_800801001_7_dialog_content = "No importa. No sabes nada de boxeo. Apuesto a que estás lleno de celos en este momento.",
  str_homestory_800801001_8_dialog_content = "?",
  str_homestory_800801001_9_dialog_content = "No te preocupes, PlayerName! ¡Aunque ahora soy la envidia tuya, seguiré siendo amable contigo!",
  str_homestory_800801001_10_dialog_content = "Pero no estoy celoso de ti...",
  str_homestory_800801001_11_dialog_content = "Calla... lo tengo.",
  str_homestory_800801001_12_dialog_content = "¡Cuando tenía más o menos tu edad, anhelaba convertirme en un hombre real como el que soy ahora!<sprite=emo_mojing size=60 />",
  str_homestory_800801001_13_dialog_content = "Escuchen, PlayerName! ¡Nada es imposible para un corazón dispuesto!",
  str_homestory_800801001_14_dialog_content = "... Multa. Brock.",
  str_homestory_800801001_15_dialog_content = "Eres muy bienvenido. Es mi responsabilidad ineludible alimentar Cloud Gardens.",
  str_homestory_800801001_16_dialog_content = "Cuando se trata de cuidar a los jóvenes, nadie lo hace mejor que yo.",
  str_homestory_800801001_17_dialog_content = "Espera un segundo... ¿Qué responsabilidad? ¿Qué combustible?",
  str_homestory_800801001_18_dialog_content = "¿No eres consciente de mi sacrificio por ti?",
  str_homestory_800801001_19_dialog_content = "... Iluminame.",
  str_homestory_800801001_20_dialog_content = "Bueno. visité Odi hace varios días para volver a pintar mi Brock con los colores del arcoiris.",
  str_homestory_800801001_21_dialog_content = "Parecía extremadamente preocupada y me rogó que te hiciera este favor.",
  str_homestory_800801001_22_dialog_content = "¿Que favor?",
  str_homestory_800801001_23_dialog_content = "Odi me dijo...",
  str_homestory_800801001_24_dialog_content = "Este maniquí tambaleante tuyo tiene un motor térmico instalado en su interior.",
  str_homestory_800801001_25_dialog_content = "?",
  str_homestory_800801001_26_dialog_content = "¡Este motor es la fuente de energía de todos los Jardines de Nubes!",
  str_homestory_800801001_27_dialog_content = "En resumen, son mis miles de golpes diarios los que hacen que los Jardines de las Nubes sigan funcionando.",
  str_homestory_800801001_28_dialog_content = "¡Jajaja! ¿Para qué es esa cara? ¡De nada!",
  str_homestory_800801001_29_dialog_content = "¡Estoy feliz de ayudar!",
  str_homestory_800801001_30_dialog_content = "... Eh... Brock... Pienso...",
  str_homestory_800801001_31_option_content = "Te han engañado.",
  str_homestory_800801001_32_dialog_content = "Este maniquí tambaleante no tiene nada más que algo de relleno dentro...",
  str_homestory_800801001_33_dialog_content = "Básicamente no tiene nada que ver con el funcionamiento de Cloud Gardens.",
  str_homestory_800801001_34_dialog_content = "¡Sin embargo!",
  str_homestory_800801001_35_dialog_content = "Tu práctica diaria de boxeo es excelente para tu salud física y mental.",
  str_homestory_800801001_36_option_content = "¡Yo aprecio!",
  str_homestory_800801001_37_dialog_content = "Sin embargo...",
  str_homestory_800801001_38_dialog_content = "no creo Odi está muy familiarizado con la estructura de Cloud Gardens.",
  str_homestory_800801001_39_dialog_content = "Es decir...",
  str_homestory_800801001_40_dialog_content = "Este maniquí tambaleante no tiene nada más que algo de relleno dentro...",
  str_homestory_800801001_41_dialog_content = "¡Vaya! ¿Es eso así?",
  str_homestory_800801001_42_dialog_content = "jajaja Supongo Odi no siempre tiene razón!",
  str_homestory_800801001_43_dialog_content = "Mmm... Brock...",
  str_homestory_800801001_44_dialog_content = "Es posible que te hayan engañado.",
  str_homestory_800801001_45_dialog_content = "Supongo que sí. No sería la primera vez.",
  str_homestory_800801001_46_dialog_content = "¿No estás molesto?",
  str_homestory_800801001_47_dialog_content = "¿Por qué lo sería?",
  str_homestory_800801001_48_dialog_content = "¡Les encanta jugar conmigo porque realmente les gusto!",
  str_homestory_800801001_49_dialog_content = "... Mmm... Probablemente tengas razón.",
  str_homestory_800801001_50_dialog_content = "Por lo menos...",
  str_homestory_800801001_51_dialog_content = "Bromear conmigo es una manera de mostrarme su admiración y confianza.",
  str_homestory_800801001_52_dialog_content = "... ¿Admiración? ¿Estas seguro acerca de esto?",
  str_homestory_800801001_53_dialog_content = "¿Por qué crees que nunca se burlan de Sinsa?",
  str_homestory_800801001_54_dialog_content = "¡Mi toque común es insuperable! ¡Jajajaja!<sprite=emo_dianzan size=60 />",
  str_homestory_806501001_0_dialog_content = "Tweety?",
  str_homestory_806501001_1_dialog_content = "¡Guau! ¡Navegador! Gusto por verte.",
  str_homestory_806501001_2_dialog_content = "Tweety, ¿Qué pasa? ¿Por qué estás tan nervioso de verme?",
  str_homestory_806501001_3_dialog_content = "Eh... ¿Yo?",
  str_homestory_806501001_4_dialog_content = "Mirar. Dejaste cosas por todas partes.",
  str_homestory_806501001_5_dialog_content = "¡Ay! ¿Dónde?",
  str_homestory_806501001_6_dialog_content = "Esa pelusa blanca junto a tus pies...",
  str_homestory_806501001_7_dialog_content = "Ahh... Déjame mirar...",
  str_homestory_806501001_8_dialog_content = "¡Guau! son plumas fwom Tweety!",
  str_homestory_806501001_9_dialog_content = "Boohoo... Nunca debería hacer cosas malas.",
  str_homestory_806501001_10_dialog_content = "¿Cosas malas?",
  str_homestory_806501001_11_dialog_content = "No es de extrañar que tu cola esté abajo hoy.",
  str_homestory_806501001_12_dialog_content = "Hmm...",
  str_homestory_806501001_13_dialog_content = "¿Qué sucedió? ¿Podría decirme?",
  str_homestory_806501001_14_dialog_content = "Mejor le digo a Navigator...",
  str_homestory_806501001_15_dialog_content = "Tweety vine a dewiver una carta hoy.",
  str_homestory_806501001_16_dialog_content = "Bueno. Ya esta en la publicación? Iré allí en breve!",
  str_homestory_806501001_17_dialog_content = "Pero... ¡Por favor espera!",
  str_homestory_806501001_18_dialog_content = "La carta... no la envié al correo.",
  str_homestory_806501001_19_dialog_content = "Tweety noté que Cloud Gardens ha cambiado un poco!",
  str_homestory_806501001_20_dialog_content = "Estuve aquí y allá y me olvidé de la carta...",
  str_homestory_806501001_21_dialog_content = "¿Es esto lo \"malo\" que hiciste?",
  str_homestory_806501001_22_option_content = "Enfadarse",
  str_homestory_806501001_23_dialog_content = "Descuidar tus deberes podría ser un gran problema.",
  str_homestory_806501001_24_dialog_content = "Como propietario de Cloud Gardens, ¿debería castigarte?",
  str_homestory_806501001_25_dialog_content = "¡Guau! ¿Castigame?",
  str_homestory_806501001_26_dialog_content = "Más plumas caerán de mi cola...",
  str_homestory_806501001_27_dialog_content = "Vale... te castigaré...",
  str_homestory_806501001_28_option_content = "Comodidad",
  str_homestory_806501001_29_dialog_content = "No te preocupes. No es urgente.",
  str_homestory_806501001_30_dialog_content = "Estoy muy contento de que te gusten los cambios que he hecho aquí.",
  str_homestory_806501001_31_dialog_content = "Gracias, Navegante. ¡Eres muy amable!",
  str_homestory_806501001_32_dialog_content = "Entonces, ¿quién envió la carta?",
  str_homestory_806501001_33_dialog_content = "Muéstrame.",
  str_homestory_806501001_34_dialog_content = "¡De acuerdo! ¡La Unión Couwier siempre dewivers!",
  str_homestory_806501001_35_dialog_content = "¡Guau! ¿Dónde está la carta?",
  str_homestory_806501001_36_dialog_content = "No en mi bolso...",
  str_homestory_806501001_37_dialog_content = "¡No en mi sombrero!",
  str_homestory_806501001_38_dialog_content = "Cálmate. ¿Lo dejaste caer en alguna parte?",
  str_homestory_806501001_39_dialog_content = "¿Adónde fuiste antes? Tweety?",
  str_homestory_806501001_40_dialog_content = "En todas partes... Fui por todo el lugar.",
  str_homestory_806501001_41_dialog_content = "... Será difícil buscar entonces.",
  str_homestory_806501001_42_dialog_content = "Tweety no quiere convertirse en el próximo Dove...",
  str_homestory_806501001_43_dialog_content = "¿Mmm? Algo acaba de caerse de tu cola...",
  str_homestory_806501001_44_dialog_content = "¿Se me cayeron más plumas de la cola? Tweety será calvo en poco tiempo!",
  str_homestory_806501001_45_dialog_content = "No, no parece una pluma...",
  str_homestory_806501001_46_dialog_content = "Eh...",
  str_homestory_806501001_47_dialog_content = "¡Ay! ¡Esta es la carta!",
  str_homestory_806501001_48_dialog_content = "¡Estaba escondido en mi cola!",
  str_homestory_805501001_0_dialog_content = "Eso es...",
  str_homestory_805501001_1_dialog_content = "Pittman?",
  str_homestory_805501001_2_dialog_content = "¡...!",
  str_homestory_805501001_3_dialog_content = "Pittman?",
  str_homestory_805501001_4_dialog_content = "Ejem... Debes estar equivocado.",
  str_homestory_805501001_5_dialog_content = "¿Eh? Pero este traje serio... ¡y las ojeras en tu rostro!",
  str_homestory_805501001_6_dialog_content = "definitivamente eres Pittman.",
  str_homestory_805501001_7_dialog_content = "Shh...",
  str_homestory_805501001_8_dialog_content = "Mantenerla baja. No dejes que otros te escuchen...",
  str_homestory_805501001_9_option_content = "Hacer una consulta",
  str_homestory_805501001_10_dialog_content = "¿Mmm? ¿El juez de Lumopolis tiene miedo de ser reconocido?",
  str_homestory_805501001_11_option_content = "Mostrar comprensión",
  str_homestory_805501001_12_dialog_content = "Está bien.",
  str_homestory_805501001_13_dialog_content = "¡No querrás revelar tu paradero!",
  str_homestory_805501001_14_dialog_content = "¿Eres buscado en Lumopolis?",
  str_homestory_805501001_15_dialog_content = "Soy justo y honorable, justo y íntegro, un devoto seguidor del Dios de la Luz y un leal servidor de Lumopolis.",
  str_homestory_805501001_16_dialog_content = "¿Por qué sería querido?",
  str_homestory_805501001_17_dialog_content = "Quizás...",
  str_homestory_805501001_18_dialog_content = "¡Montaste un caballito balancín para divertirte en secreto!",
  str_homestory_805501001_19_dialog_content = "Tú... ¿lo viste?<sprite=emo_daomei size=60 />",
  str_homestory_805501001_20_dialog_content = "¡Ajá! ¡Montaste el caballito balancín!",
  str_homestory_805501001_21_dialog_content = "Ejem. Quería asegurarme de que estaba en buenas condiciones.",
  str_homestory_805501001_22_dialog_content = "Demasiados falsos en el mercado en estos días.",
  str_homestory_805501001_23_dialog_content = "Los jueces debemos combatir a estos vendedores sin escrúpulos.",
  str_homestory_805501001_24_dialog_content = "Pero no te preocupes. Su caballito balancín es sólido y tiene una excelente mano de obra. Puede soportar al menos 84 kg.",
  str_homestory_805501001_25_dialog_content = "Puedes rockearlo con tranquilidad.",
  str_homestory_805501001_26_dialog_content = "Err... Gracias...",
  str_homestory_805501001_27_dialog_content = "He instalado este caballito balancín aquí para que todos puedan disfrutarlo.",
  str_homestory_805501001_28_dialog_content = "¡No hay necesidad de ser astuto al respecto!",
  str_homestory_805501001_29_dialog_content = "¿De dónde viene esto?",
  str_homestory_805501001_30_dialog_content = "Todo está escrito en tu cara.",
  str_homestory_805501001_31_dialog_content = "No eres un buen mentiroso. Jajajaja",
  str_homestory_805501001_32_dialog_content = "... Está bien...",
  str_homestory_805501001_33_dialog_content = "Por favor, mantén esto entre nosotros.",
  str_homestory_805501001_34_dialog_content = "¿Por qué? No tiene que ser un secreto...",
  str_homestory_805501001_35_dialog_content = "Me encanta montarlo yo mismo.",
  str_homestory_805501001_36_dialog_content = "Para defender la justicia, los jueces siempre quieren ser persuasivos y tranquilizadores.",
  str_homestory_805501001_37_dialog_content = "Si la gente descubre este lado infantil de mí...",
  str_homestory_805501001_38_dialog_content = "No podrán confiar en mi juicio en la corte.",
  str_homestory_805501001_39_dialog_content = "¿Está bien?",
  str_homestory_805501001_40_dialog_content = "Asi que PlayerName¿Mi secreto está a salvo contigo?",
  str_homestory_805501001_41_dialog_content = "Multa. Aunque sigo sin ver ninguna conexión entre montar un caballo balancín y juzgar un caso...",
  str_homestory_805501001_42_dialog_content = "¡Te prometo que no se lo diré a nadie!",
  str_homestory_805501001_43_dialog_content = "¡Gracias por su comprensión!",
  str_homestory_805501001_44_dialog_content = "Una cosa más...",
  str_homestory_805501001_45_dialog_content = "¡Si alguna vez eres víctima de productos falsos, defenderé la justicia por ti!<sprite=emo_qingsong size=60 />",
  str_homestory_815501001_0_dialog_content = "¿Suena como una espada recién envainada?",
  str_homestory_815501001_1_dialog_content = "Eraveil es verdaderamente maravilloso, PlayerName!",
  str_homestory_815501001_2_dialog_content = "No está mal... supongo...",
  str_homestory_815501001_3_dialog_content = "¿Cuántos secretos más nos oculta esta Caelestita?",
  str_homestory_815501001_4_dialog_content = "... No puedo esperar para averiguarlo.",
  str_homestory_815501001_5_dialog_content = "Hmm... Qué lugar tan encantador tienes, chico.",
  str_homestory_815501001_6_dialog_content = "Muy bien equipado, estratégicamente situado y de difícil acceso.",
  str_homestory_815501001_7_dialog_content = "¡En tiempos de guerra, esto podría ser una excelente base de combate sin ningún problema!",
  str_homestory_815501001_8_dialog_content = "Guau... Estás al menos diez pasos por delante de mí, Barton.",
  str_homestory_815501001_9_dialog_content = "¡Por supuesto!",
  str_homestory_815501001_10_dialog_content = "La búsqueda constante del poder y la planificación racional de lo que tienes son igual de importantes.",
  str_homestory_815501001_11_dialog_content = "(Barton suena diferente hoy...)",
  str_homestory_815501001_12_dialog_content = "Por desgracia... Ojalá me hubiera dado cuenta de esto antes...",
  str_homestory_815501001_13_dialog_content = "... Chico, ¿qué te parece?",
  str_homestory_815501001_14_dialog_content = "¿Qué es más importante en tu opinión, fortalecerte o planificar racionalmente tus recursos?<sprite=emo_sikao size=60 />",
  str_homestory_815501001_15_option_content = "Crecer más fuerte",
  str_homestory_815501001_16_dialog_content = "Si 10 Nightium fuera todo lo que tuviera, no tendría sentido planear...",
  str_homestory_815501001_17_dialog_content = "Debo volverme más fuerte primero. En otras palabras, primero necesito hacer crecer mi riqueza.",
  str_homestory_815501001_18_option_content = "planificar racionalmente",
  str_homestory_815501001_19_dialog_content = "Si 10 Nightium era todo lo que tenía, debía encontrar una forma de vivir antes de pensar en ganar más dinero...",
  str_homestory_815501001_20_dialog_content = "¿Eh? ¿No puedes hablar en serio?",
  str_homestory_815501001_21_dialog_content = "10 Nightium es todo lo que tienes?",
  str_homestory_815501001_22_dialog_content = "... ¡Era solo un ejemplo!",
  str_homestory_815501001_23_dialog_content = "Está bien.",
  str_homestory_815501001_24_dialog_content = "Estaba a punto de ofrecerte un préstamo si estabas tan arruinado.",
  str_homestory_815501001_25_dialog_content = "En este sentido, Illumina es bastante bueno. Al menos muchas cosas no cuestan un centavo.",
  str_homestory_815501001_26_dialog_content = "?",
  str_homestory_815501001_27_dialog_content = "Lo siento. estoy divagando...",
  str_homestory_815501001_28_dialog_content = "He llegado a un punto en el que creo que la búsqueda de poder y la planificación de recursos se pueden realizar simultáneamente.",
  str_homestory_815501001_29_dialog_content = "No tiene que ser una situación de uno u otro.",
  str_homestory_815501001_30_dialog_content = "Solía prestar toda mi atención al crecimiento de mi poder. Muchos asuntos importantes fueron descuidados en el camino.",
  str_homestory_815501001_31_dialog_content = "¡Planear lo que ya tienes te da una mejor idea del futuro!",
  str_homestory_815501001_32_dialog_content = "Una comprensión profunda de ti mismo te permite avanzar sin problemas en este viaje y volverte más fuerte.",
  str_homestory_815501001_33_dialog_content = "Más poder te da una mejor opinión.",
  str_homestory_815501001_34_dialog_content = "Hmm... Estoy de acuerdo contigo hasta cierto punto.",
  str_homestory_815501001_35_dialog_content = "¿Así que aceptas prestarme este lugar como mi base de combate?",
  str_homestory_815501001_36_dialog_content = "¡¿?!",
  str_homestory_815501001_37_dialog_content = "¡Yo nunca dije eso!",
  str_homestory_815501001_38_dialog_content = "¡El concepto de una base de combate simplemente no suena bien para los Jardines de las Nubes!",
  str_homestory_815501001_39_dialog_content = "jajaja ¿Quién sabe? ¡Nadie puede garantizarte una paz duradera!",
  str_homestory_815501001_40_dialog_content = "¡Oye! ¡Por favor, no digas eso!<sprite=emo_shengqi size=60 />",
  str_homestory_815501001_41_dialog_content = "No hace la diferencia. ¡Debemos estar preparados para los riesgos potenciales!",
  str_homestory_815501001_42_dialog_content = "Sí. Necesitamos algunas rondas más de juegos de guerra sin más.",
  str_homestory_815501001_43_dialog_content = "Y todas estas ideas en mi cabeza... las compartiré con Vivian mañana.",
  str_homestory_815501001_44_dialog_content = "Hmm... ¡No tengo tiempo para buscar documentos para un informe escrito!",
  str_homestory_815501001_45_dialog_content = "(Decido retirar lo que acabo de decir...)",
  str_homestory_815501001_46_dialog_content = "(Barton no ha cambiado nada).",
  str_homestory_801101001_0_dialog_content = "Sharona!",
  str_homestory_801101001_1_dialog_content = "Señor...",
  str_homestory_801101001_2_dialog_content = "¿Estás practicando nuevos movimientos?",
  str_homestory_801101001_3_dialog_content = "Sí.",
  str_homestory_801101001_4_dialog_content = "Muy diligente<sprite=emo_yaling size=60 />. No es de extrañar que la principal fuerza de combate de Illumina, la Primera Legión, esté bajo tu mando...",
  str_homestory_801101001_5_dialog_content = "Creo que hay un malentendido, PlayerName.",
  str_homestory_801101001_6_dialog_content = "No tengo intención de introducir este nuevo conjunto de movimientos en nuestro entrenamiento militar.",
  str_homestory_801101001_7_dialog_content = "Estas son en realidad habilidades que he adquirido recientemente de una novela.",
  str_homestory_801101001_8_dialog_content = "Tú... ¿Lees una novela?",
  str_homestory_801101001_9_dialog_content = "Espera... ¿Estás practicando movimientos de una novela?",
  str_homestory_801101001_10_dialog_content = "Esto... Esto no suena como el Oficial Sharona ¡Lo sé!",
  str_homestory_801101001_11_dialog_content = "¿Estás sorprendido?",
  str_homestory_801101001_12_option_content = "Asentir",
  str_homestory_801101001_13_dialog_content = "Pensé que siempre estabas ocupado con grandes negocios. Leyendo novelas...",
  str_homestory_801101001_14_dialog_content = "No me malinterpretes. ¡No tengo nada en contra de leer!",
  str_homestory_801101001_15_option_content = "Sacudir la cabeza",
  str_homestory_801101001_16_dialog_content = "Pensándolo bien, no deberíamos limitar nuestra comprensión de una persona a la primera impresión...",
  str_homestory_801101001_17_dialog_content = "A mí, oficial Sharona parece ocupado en todo momento. No pensé que tendrías el tiempo libre para leer una novela.",
  str_homestory_801101001_18_dialog_content = "Estás bien. No soy un gran lector en ninguna medida.",
  str_homestory_801101001_19_dialog_content = "Pero me llamó la atención el nombre del libro: El enredo milenario de dos dragones rebeldes.",
  str_homestory_801101001_20_dialog_content = "...",
  str_homestory_801101001_21_dialog_content = "¿Dónde te topaste con este libro?",
  str_homestory_801101001_22_dialog_content = "¡No me digas que se lo compraste a cierto auroriano!",
  str_homestory_801101001_23_dialog_content = "Sí, me lo vendió un comerciante de Umbraton.",
  str_homestory_801101001_24_dialog_content = "Pareces tranquilo...",
  str_homestory_801101001_25_dialog_content = "Supongo que la historia no está demasiado fuera de lugar.",
  str_homestory_801101001_26_dialog_content = "Me dijo que el truco de este libro era...",
  str_homestory_801101001_27_dialog_content = "Las habilidades secretas perdidas hace mucho tiempo de Dragon y una historia de amor de un antiguo linaje...",
  str_homestory_801101001_28_dialog_content = "¿Qué? ¿No estás loco?",
  str_homestory_801101001_29_dialog_content = "Realmente no.",
  str_homestory_801101001_30_dialog_content = "No hay mucho que pueda hacer de todos modos.",
  str_homestory_801101001_31_dialog_content = "La impresión y venta de este libro tiene lugar en Umbraton, fuera de mi jurisdicción.",
  str_homestory_801101001_32_dialog_content = "Para mí, el contenido de un libro importa poco.",
  str_homestory_801101001_33_dialog_content = "Pero para esos escritores, un libro podría ser lo único de lo que viven.",
  str_homestory_801101001_34_dialog_content = "... Sí, eso es muy cierto...",
  str_homestory_801101001_35_dialog_content = "Sharona... ¡Eres un excelente oficial!",
  str_homestory_801101001_36_dialog_content = "Bueno, las habilidades secretas de Dragon mencionadas en este libro son bastante ridículas...",
  str_homestory_801101001_37_dialog_content = "Pero puede animar un poco mi rutina de ejercicios.",
  str_homestory_801101001_38_dialog_content = "¿Quieres probar?",
  str_homestory_801101001_39_dialog_content = "Como está registrado en el libro, comenzaremos con 200 sentadillas fáciles antes de pasar a...",
  str_homestory_801101001_40_dialog_content = "No, no...",
  str_homestory_801101001_41_dialog_content = "Creo que realmente necesito concentrarme en las habilidades de Caelestite, oficial. Sharona.",
  str_homestory_801101001_42_dialog_content = "Los dejo con su ejercicio... ¡Adiós!",
  str_homestory_801101001_43_dialog_content = "Adiós.",
  str_homestory_810301001_0_dialog_content = "¿Ese es Eicy?",
  str_homestory_810301001_1_dialog_content = "Eicy, ¿quieres echar un vistazo al interior?",
  str_homestory_810301001_2_dialog_content = "Recuerdo que te encanta ir de compras.",
  str_homestory_810301001_3_dialog_content = "PlayerName, ya que conoces mi hobby...",
  str_homestory_810301001_4_dialog_content = "¿Cómo puedes ser tan tacaño construyendo una sola tienda?",
  str_homestory_810301001_5_dialog_content = "Err... tengo muchas razones...",
  str_homestory_810301001_6_dialog_content = "Seguir.",
  str_homestory_810301001_7_dialog_content = "Si te falla la memoria de repente, puedo quitarme el parche del ojo...",
  str_homestory_810301001_8_dialog_content = "Mi mirada hueca <sprite=emo_baimao size=60 />Te ayudará.",
  str_homestory_810301001_9_option_content = "Explique",
  str_homestory_810301001_10_dialog_content = "Bien. ¡Dame un minuto!",
  str_homestory_810301001_11_dialog_content = "La razón principal es nuestro presupuesto muy ajustado...",
  str_homestory_810301001_12_dialog_content = "Tenemos tantas cosas que construir. No es posible hacer todo perfecto desde el principio.",
  str_homestory_810301001_13_option_content = "responder vagamente",
  str_homestory_810301001_14_dialog_content = "El interrogatorio no puede marcar la diferencia aquí...",
  str_homestory_810301001_15_dialog_content = "Nuestro presupuesto es muy ajustado. Simplemente no podemos permitirnos otra tienda...",
  str_homestory_810301001_16_dialog_content = "Creo... Uno es mejor que ninguno!",
  str_homestory_810301001_17_dialog_content = "Eso es muy audaz y directo de tu parte.",
  str_homestory_810301001_18_dialog_content = "¡Sin embargo, nuestra única tienda cubre todas sus necesidades!",
  str_homestory_810301001_19_dialog_content = "He estado trabajando duro para cooperar con diferentes gremios en Umbraton...",
  str_homestory_810301001_20_dialog_content = "Los suministros llegan de forma irregular a través de Courier Union.",
  str_homestory_810301001_21_dialog_content = "¿Qué tal si entras y echas un vistazo primero? Avísame si hay algo que quieras que ordene.",
  str_homestory_810301001_22_dialog_content = "Eso no será necesario. Ya he estado allí.",
  str_homestory_810301001_23_dialog_content = "En realidad, he liquidado su stock para mostrar mi apoyo.",
  str_homestory_810301001_24_dialog_content = "¿Todo?",
  str_homestory_810301001_25_dialog_content = "Sí.",
  str_homestory_810301001_26_dialog_content = "¿Incluyendo el pez que pescamos hoy en el río?",
  str_homestory_810301001_27_dialog_content = "esos de colores? Sí, son adorables.",
  str_homestory_810301001_28_dialog_content = "No pude encontrar un tanque para mantenerlos, así que los liberé en un río cercano.",
  str_homestory_810301001_29_dialog_content = "¿Incluso ese zapato de cuero andrajoso no deseado?",
  str_homestory_810301001_30_dialog_content = "¿Zapato hecho jirones? Sí. ¿No es eso un macetero de última moda?",
  str_homestory_810301001_31_dialog_content = "Me he puesto en contacto con la Unión de Mensajeros para enviarlo de vuelta a la Orden Verdadera.",
  str_homestory_810301001_32_dialog_content = "¿Qué tal... mi mapa dibujado a mano de Eraveil?",
  str_homestory_810301001_33_dialog_content = "¿Te refieres a la imagen de un laberinto torcido?",
  str_homestory_810301001_34_dialog_content = "¿Lo dibujaste? Debo enmarcarlo y colgarlo en mi pared.",
  str_homestory_810301001_35_dialog_content = "Gracias, Eicy... ¡Eres el cliente más generoso que he visto en mi vida!",
  str_homestory_810301001_36_dialog_content = "No lo menciones. ¡Comprar se trata de salpicar!",
  str_homestory_810301001_37_dialog_content = "Me irrita que no haya más tienda para comprar más.",
  str_homestory_810301001_38_dialog_content = "Eicy, podrías dar un paseo.",
  str_homestory_810301001_39_dialog_content = "Tenemos un museo allá, y la Fuente de la Esperanza...",
  str_homestory_810301001_40_dialog_content = "Puedo darte mi palabra. ¡No podrás verlos en ningún otro lugar!",
  str_homestory_810301001_41_dialog_content = "Por supuesto. Suena interesante.",
  str_homestory_810301001_42_dialog_content = "Tengo una idea. me decido a comprar <sprite=emo_baiyebi size=60 />tú.",
  str_homestory_810301001_43_dialog_content = "¿Eh? ¿Cómprame?",
  str_homestory_810301001_44_dialog_content = "Sólo por un día. Puedes mostrarme los alrededores.",
  str_homestory_810301001_45_dialog_content = "Dime un precio justo por tu tiempo.",
  str_homestory_810301001_46_dialog_content = "¡Acuerdo! Estoy muy feliz de servirle!",
  str_homestory_802301001_0_dialog_content = "Connolly...",
  str_homestory_802301001_1_dialog_content = "La luz suave...",
  str_homestory_802301001_2_dialog_content = "Connolly, ¿qué dijiste?",
  str_homestory_802301001_3_dialog_content = "Na-navegante! <sprite=emo_wuzui size=60 />",
  str_homestory_802301001_4_dialog_content = "Solo estaba murmurando. Por favor, no me hagas caso...",
  str_homestory_802301001_5_dialog_content = "... ¡No, no es sólo eso!",
  str_homestory_802301001_6_dialog_content = "También puedes prestarme un poco de atención... Yo... Estoy en medio de un entrenamiento de desensibilización...",
  str_homestory_802301001_7_dialog_content = "¿Entrenamiento de desensibilización?",
  str_homestory_802301001_8_dialog_content = "Sí... Vice me hablo de esto...",
  str_homestory_802301001_9_dialog_content = "Me estaba costando mucho adaptarme a la luz aquí...",
  str_homestory_802301001_10_dialog_content = "Vice me encontró escondido en un rincón...",
  str_homestory_802301001_11_dialog_content = "¿Se dio cuenta de que necesitabas ayuda?",
  str_homestory_802301001_12_dialog_content = "Si...",
  str_homestory_802301001_13_dialog_content = "Ella me dijo que tratara de hacer cosas que me gustan e ignorar a otras personas...",
  str_homestory_802301001_14_dialog_content = "O imagina que este es el Holiday Cafe y todos ustedes son clientes...",
  str_homestory_802301001_15_dialog_content = "Realmente estoy tratando...",
  str_homestory_802301001_16_option_content = "¿Cómo te sientes?",
  str_homestory_802301001_17_dialog_content = "Ligeramente mejor...",
  str_homestory_802301001_18_dialog_content = "También había mucha gente en el Coloso...",
  str_homestory_802301001_19_option_content = "No te fuerces.",
  str_homestory_802301001_20_dialog_content = "No estás obligado a salir si te resulta más cómodo quedarte en tu habitación.",
  str_homestory_802301001_21_dialog_content = "En realidad, tengo algo que decirte, Navegante...",
  str_homestory_802301001_22_dialog_content = "¿Mmm? ¿Qué es?",
  str_homestory_802301001_23_dialog_content = "hice caso Vice's consejo y tocó una canción con Anton aquí<sprite=emo_yinfu size=60 />...",
  str_homestory_802301001_24_dialog_content = "Nunca esperé... una señora vestida con un traje de Lumopolis me elogió...",
  str_homestory_802301001_25_dialog_content = "Yo...",
  str_homestory_802301001_26_dialog_content = "Ah... De repente, este lugar brillante ya no parece tan malo, ¿verdad?",
  str_homestory_802301001_27_dialog_content = "A veces un cumplido es muy alentador.",
  str_homestory_802301001_28_dialog_content = "Connolly, creo que eres fenomenal!",
  str_homestory_802301001_29_dialog_content = "Haces el café más sabroso y eres un luchador dulce pero poderoso...",
  str_homestory_802301001_30_dialog_content = "Gracias por tus amables palabras, Navegante. Yo... no sé qué decir...",
  str_homestory_802301001_31_dialog_content = "¡Pero el cumplido de esa dama... se sintió diferente al tuyo!",
  str_homestory_802301001_32_dialog_content = "Navegador y Vice son buenos amigos de Connolly...",
  str_homestory_802301001_33_dialog_content = "Siempre me has apoyado, consolado y alabado...",
  str_homestory_802301001_34_dialog_content = "¡Pero esa dama era una total desconocida!",
  str_homestory_802301001_35_dialog_content = "Su aprobación fue pura y más tranquilizadora para Connolly.",
  str_homestory_802301001_36_dialog_content = "Sí... Así es exactamente como me siento...",
  str_homestory_802301001_37_dialog_content = "Navegador, ¿podría decir Vice Realmente aprecio su ayuda?",
  str_homestory_802301001_38_dialog_content = "Lo más probable es que estaría escondido en mi habitación en este momento si no fuera por ella...",
  str_homestory_802301001_39_dialog_content = "¡Considérelo hecho!",
  str_homestory_802301001_40_dialog_content = "¡Gracias, Navegador!",
  str_homestory_802301001_41_dialog_content = "Planeo practicar esa canción de nuevo con Anton...",
  str_homestory_802301001_42_dialog_content = "También puedes probar algo nuevo.",
  str_homestory_802301001_43_dialog_content = "Estoy seguro de que a esa dama misteriosa le encantaría escuchar.",
  str_homestory_802301001_44_dialog_content = "¡Ay! Estás bien...",
  str_homestory_802301001_45_dialog_content = "¡De acuerdo! ¡Navegante, voy a practicar!",
  str_homestory_802301001_46_dialog_content = "¡Lo tienes!",
  str_homestory_803001001_0_dialog_content = "Sinsa...",
  str_homestory_803001001_1_dialog_content = "Hola, Sinsa!",
  str_homestory_803001001_2_dialog_content = "UH Huh<sprite=emo_yaosu size=60 />! Que bueno verte, PlayerName, la última Caelestita!",
  str_homestory_803001001_3_dialog_content = "¿Como esta todo?",
  str_homestory_803001001_4_dialog_content = "Todo esta bien. ¿Y usted? ¿Te va bien aquí?",
  str_homestory_803001001_5_dialog_content = "No está mal.",
  str_homestory_803001001_6_dialog_content = "No te tomó mucho tiempo transformar completamente este agujero de mierda...",
  str_homestory_803001001_7_dialog_content = "estás a la altura Sinsalas expectativas. Ah jajajaja",
  str_homestory_803001001_8_dialog_content = "Entonces, ¿has decidido?",
  str_homestory_803001001_9_dialog_content = "¿Cuándo te unirás a Rediesel Wrench?",
  str_homestory_803001001_10_dialog_content = "Mmm... err...",
  str_homestory_803001001_11_dialog_content = "Según el estándar de Rediesel Wrench...",
  str_homestory_803001001_12_dialog_content = "¡Este lugar necesita desesperadamente un área para pelear y correr!",
  str_homestory_803001001_13_option_content = "Rechazar",
  str_homestory_803001001_14_dialog_content = "Prefiero no tener ningún conflicto aquí...",
  str_homestory_803001001_15_dialog_content = "No hay lugar para la violencia.",
  str_homestory_803001001_16_dialog_content = "Ay... he perdido la cuenta de tu frío rechazo.",
  str_homestory_803001001_17_dialog_content = "Sin embargo, PlayerName, tu idea suena bastante infantil allá atrás.",
  str_homestory_803001001_18_dialog_content = "Tome mi palabra para ello. Lo prohibido definitivamente va a suceder.",
  str_homestory_803001001_19_dialog_content = "No preguntes cómo lo sé...",
  str_homestory_803001001_20_dialog_content = "...",
  str_homestory_803001001_21_option_content = "Aceptar",
  str_homestory_803001001_22_dialog_content = "Hmm... No es parte de nuestro plan original...",
  str_homestory_803001001_23_dialog_content = "Pero las peleas aleatorias y las carreras de resistencia pueden dañar las casas por las que he trabajado duro.",
  str_homestory_803001001_24_dialog_content = "Es mejor tener una zona especial...",
  str_homestory_803001001_25_dialog_content = "Jajajaja Has crecido, chico.",
  str_homestory_803001001_26_dialog_content = "¡Ahora ya sabes cuándo escuchar!",
  str_homestory_803001001_27_dialog_content = "¿Podrías mostrarme los dormitorios de chicas de Cloud Gardens?",
  str_homestory_803001001_28_dialog_content = "¡¿Eh?!",
  str_homestory_803001001_29_dialog_content = "¿Por qué hay terror en tus ojos?",
  str_homestory_803001001_30_dialog_content = "¿Supongo que vas allí por una razón?",
  str_homestory_803001001_31_dialog_content = "Es hora de hacer una visita.",
  str_homestory_803001001_32_dialog_content = "¿Una visita?",
  str_homestory_803001001_33_dialog_content = "Sí<sprite=emo_qingsong size=60 />, necesito asegurarme de que sea lo suficientemente bueno para mi Eve.",
  str_homestory_803001001_34_dialog_content = "Uf... Ya veo.",
  str_homestory_803001001_35_dialog_content = "Necesito comprobar si el colchón es lo suficientemente suave...",
  str_homestory_803001001_36_dialog_content = "Si la lámpara de noche es buena para la vista...",
  str_homestory_803001001_37_dialog_content = "Si la hoja tiene EveEl patrón favorito de...",
  str_homestory_803001001_38_dialog_content = "Si hay un armario adecuado para Eve's vestidos bonitos...",
  str_homestory_803001001_39_dialog_content = "¡Ay! ¡Y lo mas importante! ¡Si hay un termo en la habitación!",
  str_homestory_803001001_40_option_content = "Aceptar",
  str_homestory_803001001_41_dialog_content = "enviare Vice para revisar todo...",
  str_homestory_803001001_42_dialog_content = "¡Jajaja! ¡Ese es mi hermano!",
  str_homestory_803001001_43_option_content = "No Aceptar",
  str_homestory_803001001_44_dialog_content = "Sinsa, creo que es hora de que aprendas a respetar Eveel espacio de",
  str_homestory_803001001_45_dialog_content = "¿Qué dijiste?",
  str_homestory_803001001_46_dialog_content = "¡No importa! enviare Vice para revisar todo...",
  str_homestory_811601001_0_dialog_content = "¡Estos zumbidos y haws!",
  str_homestory_811601001_1_dialog_content = "Navegante, ¿tiene algo que reparar?",
  str_homestory_811601001_2_dialog_content = "¡Tiempo perfecto! ¡No he recibido ninguna tarea hoy!",
  str_homestory_811601001_3_dialog_content = "¿Reparar?",
  str_homestory_811601001_4_dialog_content = "¿Está tomando pedidos... en el depósito de carga?",
  str_homestory_811601001_5_dialog_content = "Sí, tengo clientes aquí. Luego arreglo sus cosas en mi habitación.",
  str_homestory_811601001_6_dialog_content = "No te preocupes. No hay dinero involucrado.",
  str_homestory_811601001_7_dialog_content = "Entonces por qué tu...",
  str_homestory_811601001_8_dialog_content = "¿Por qué ofrezco servicio de reparación gratuito?",
  str_homestory_811601001_9_dialog_content = "Sí. Normalmente te mantienes ocupado con tus propios pasatiempos...",
  str_homestory_811601001_10_dialog_content = "Investigación de piezas y componentes y tal.",
  str_homestory_811601001_11_dialog_content = "Porque la gente aquí es de todas partes.<sprite=emo_sikao size=60 />",
  str_homestory_811601001_12_dialog_content = "Las cosas que quieren arreglar son tan diferentes y fascinantes.",
  str_homestory_811601001_13_dialog_content = "Más temprano Charon me pidió que hiciera su fonógrafo<sprite=emo_yinfu size=60 /> mas fuerte...",
  str_homestory_811601001_14_dialog_content = "Pensé que era solo un fonógrafo de Illumina y no le presté mucha atención.",
  str_homestory_811601001_15_dialog_content = "¿Sabes que? ¡Resultó ser un modelo vintage de origen desconocido!",
  str_homestory_811601001_16_dialog_content = "jajaja ¡Estudié el fonógrafo dentro y fuera una y otra vez!",
  str_homestory_811601001_17_dialog_content = "Err... ¿realmente ayudaste? Charon hacerlo más fuerte?",
  str_homestory_811601001_18_dialog_content = "Bueno, solo un poco. Fue mi pago por esta rara oportunidad de estudiar un nuevo dispositivo...",
  str_homestory_811601001_19_dialog_content = "¡Pero! También soy víctima de su música a todo volumen. ¡Juro que solo lo hice un poco más fuerte!",
  str_homestory_811601001_20_dialog_content = "Muy bien... Pareces divertirte aquí.",
  str_homestory_811601001_21_dialog_content = "¡Mucho!",
  str_homestory_811601001_22_dialog_content = "Tantas tecnologías diferentes, piezas nuevas y dispositivos para estudiar... ¡Esto es el cielo!<sprite=emo_aixin size=60 />",
  str_homestory_811601001_23_dialog_content = "Está bien, mientras te sientas cómodo aquí.",
  str_homestory_811601001_24_dialog_content = "Bastante bien. ¡Pronto podré hacer un nuevo mecha!",
  str_homestory_811601001_25_dialog_content = "... ¡Aquí vamos de nuevo!",
  str_homestory_811601001_26_dialog_content = "¡No seas así! ¡Me preocupo mucho por ti! Inspeccioné la estructura de este depósito de carga para usted hace un momento.",
  str_homestory_811601001_27_dialog_content = "Mi llave y destornillador han demostrado que este pabellón es muy estable y no necesita mi servicio.",
  str_homestory_811601001_28_dialog_content = "Fue construido con materiales de Eraveil.",
  str_homestory_811601001_29_dialog_content = "¿Ver? Aquí incluso tengo acceso a materiales de Eraveil. ¡Fabuloso!",
  str_homestory_811601001_30_dialog_content = "Muy bien, supongo que te dejaré aquí... ¿para recibir órdenes?",
  str_homestory_811601001_31_dialog_content = "No me estás molestando en absoluto. De hecho, eres bienvenido a quedarte y tomar órdenes conmigo.",
  str_homestory_811601001_32_option_content = "Aceptar",
  str_homestory_811601001_33_dialog_content = "Bien... Tengo curiosidad por las necesidades de reparación que hay por ahí.",
  str_homestory_811601001_34_dialog_content = "¡Excelente!",
  str_homestory_811601001_35_dialog_content = "... Estoy teniendo un día muy lento hoy.",
  str_homestory_811601001_36_dialog_content = "... ¿Qué pasa si nadie viene a usted para las reparaciones?",
  str_homestory_811601001_37_option_content = "Rechazar",
  str_homestory_811601001_38_dialog_content = "Hoy no. Tengo cosas que hacer...",
  str_homestory_811601001_39_dialog_content = "¡Ay! De paso...",
  str_homestory_811601001_40_dialog_content = "¿Qué pasa si nadie viene a usted para la reparación?",
  str_homestory_811601001_41_dialog_content = "¿Seguirás dando vueltas por aquí?",
  str_homestory_811601001_42_dialog_content = "Eso es correcto.",
  str_homestory_811601001_43_dialog_content = "Sin embargo, Navegante, aquí hay una cosa que debo corregirte.",
  str_homestory_811601001_44_dialog_content = "No estoy dando vueltas por aquí. Una intensa guerra de mechas está peleando constantemente en mi cabeza.",
  str_homestory_811601001_45_dialog_content = "Antes de que vinieras, estaba pensando en quién ganaría si Mecha PlayerName y mecha Odi tuve una pelea.",
  str_homestory_811601001_46_dialog_content = "mecha PlayerName es conocido por sus golpes rápidos y ligeros, mientras que Mecha Odi esta mucho mejor equipado...",
  str_homestory_811601001_47_dialog_content = "¡Fue una pelea feroz!",
  str_homestory_811601001_48_dialog_content = "Bien... He terminado aquí...",
  str_homestory_811701001_0_dialog_content = "Gram?",
  str_homestory_811701001_1_dialog_content = "Gram, ¿qué estás haciendo en la tienda?",
  str_homestory_811701001_2_dialog_content = "Err... ¿Estás pensando?",
  str_homestory_811701001_3_dialog_content = "¿O hay algo que no puedes encontrar aquí?",
  str_homestory_811701001_4_dialog_content = "chico",
  str_homestory_811701001_5_dialog_content = "Necesito algunos ingredientes para hacer brochetas con carne racionada a punto de caducar.",
  str_homestory_811701001_6_dialog_content = "carne caducada<sprite=emo_rou size=60 />...",
  str_homestory_811701001_7_dialog_content = "Caducando, no caducado. Está perfectamente bien.",
  str_homestory_811701001_8_dialog_content = "Además, la calidad del plato depende únicamente de las habilidades del chef y no tiene nada que ver con la calidad de los ingredientes.",
  str_homestory_811701001_9_dialog_content = "Gram, ¡Estás en lo correcto!",
  str_homestory_811701001_10_dialog_content = "De hecho, nunca he probado tus brochetas...",
  str_homestory_811701001_11_dialog_content = "Lo harás.",
  str_homestory_811701001_12_dialog_content = "Las brochetas son muy fáciles de hacer.",
  str_homestory_811701001_13_dialog_content = "... ¿Fácil?",
  str_homestory_811701001_14_dialog_content = "Lo sabía. Gram, eres verdaderamente dotado...",
  str_homestory_811701001_15_dialog_content = "¿Un cocinero dotado? No hay tal cosa.",
  str_homestory_811701001_16_dialog_content = "¡Mmm! ¡La generación joven tiene que ver con las dotaciones!",
  str_homestory_811701001_17_dialog_content = "Muchos logros se alcanzan a través del trabajo duro y el estudio diligente. ¡El talento por sí solo no te lleva a ninguna parte!",
  str_homestory_811701001_18_dialog_content = "Cocino bien porque trabajé muchos años en la cocina.",
  str_homestory_811701001_19_dialog_content = "Cocinar como habilidad tiene muy poco que ver con el talento.",
  str_homestory_811701001_20_option_content = "no entiendo muy bien",
  str_homestory_811701001_21_dialog_content = "Traté de cocinar y seguí de cerca una receta...",
  str_homestory_811701001_22_dialog_content = "No salió bien.",
  str_homestory_811701001_23_option_content = "Está empezando a tener sentido",
  str_homestory_811701001_24_dialog_content = "¿Se pueden mejorar las habilidades culinarias con la práctica?",
  str_homestory_811701001_25_dialog_content = "Cualquier cosa se puede mejorar con suficiente práctica.",
  str_homestory_811701001_26_dialog_content = "Para cocinar una comida sabrosa, debes sentirlo en tu corazón.",
  str_homestory_811701001_27_dialog_content = "¿Sentirlo?",
  str_homestory_811701001_28_dialog_content = "Asi que Vicelos platos...",
  str_homestory_811701001_29_dialog_content = "¿No tenías sentimientos o demasiados sentimientos?",
  str_homestory_811701001_30_dialog_content = "Obviamente, perdió sus sentimientos ante las instrucciones.",
  str_homestory_811701001_31_dialog_content = "Digamos que se ve obstaculizada por sus ganancias y pérdidas personales.",
  str_homestory_811701001_32_dialog_content = "Hmm... Probablemente también puedas decir eso de mí.",
  str_homestory_811701001_33_dialog_content = "Tengo miedo de estropear las cosas, pero también tengo muchas ganas de hacer algo increíble. Esto me deja confundido y estresado...",
  str_homestory_811701001_34_dialog_content = "Te daré un ejemplo muy simple.",
  str_homestory_811701001_35_dialog_content = "Cuando estaba en la unidad de logística, deseaba ir al frente, pero aun así lograba entregar comida sabrosa todos los días. Solo había una razón.",
  str_homestory_811701001_36_dialog_content = "Quería que todos mis hermanos de armas comieran bien para que tuvieran fuerzas para luchar.",
  str_homestory_811701001_37_dialog_content = "Ahora estoy cocinando aquí por la misma razón.",
  str_homestory_811701001_38_dialog_content = "¡Quiero que ustedes jóvenes coman bien para que tengan la energía para luchar!",
  str_homestory_811701001_39_dialog_content = "Cocinar una comida sabrosa es muy fácil.",
  str_homestory_811701001_40_dialog_content = "Siga las instrucciones y deje de lado todos sus pensamientos aleatorios.",
  str_homestory_811701001_41_dialog_content = "Cuanto más pienses, más errores cometerás. ¿Comprendido?",
  str_homestory_811701001_42_dialog_content = "¡Sí! ¡Esta vez lo conseguí!",
  str_homestory_811701001_43_dialog_content = "Estás absolutamente en lo correcto, Gram!",
  str_homestory_811701001_44_dialog_content = "Para ser honesto, creo que deberías escribir un libro sobre técnicas de cocina.",
  str_homestory_811701001_45_dialog_content = "Incluso miembros del Desierto Rediesel están publicando libros... ¡Tú puedes hacerlo!",
  str_homestory_811701001_46_dialog_content = "Puedo presentarte a la prensa en Umbraton.",
  str_homestory_811701001_47_dialog_content = "No ahora. Lo pensare.",
  str_homestory_811701001_48_dialog_content = "¿Vienes por mis brochetas cuando estén listas, chico?",
  str_homestory_811701001_49_dialog_content = "¡Definitivamente!",
  str_homestory_807701001_0_dialog_content = "¿Su Majestad?",
  str_homestory_807701001_1_dialog_content = "Su Majestad...",
  str_homestory_807701001_2_dialog_content = "Hola, el que sostiene el futuro.",
  str_homestory_807701001_3_option_content = "Bienvenidos.",
  str_homestory_807701001_4_dialog_content = "Es un honor tenerte aquí.",
  str_homestory_807701001_5_dialog_content = "PlayerName, no te pares en la ceremonia.",
  str_homestory_807701001_6_dialog_content = "He estado mirando esta Torre Jacinto.",
  str_homestory_807701001_7_option_content = "¿Estoy molestando?",
  str_homestory_807701001_8_dialog_content = "Te ves muy concentrado...",
  str_homestory_807701001_9_dialog_content = "Sí, estoy viendo esta Torre Jacinto.",
  str_homestory_807701001_10_dialog_content = "¿La Torre Jacinto? ¿Qué pasa con eso?",
  str_homestory_807701001_11_dialog_content = "Hmm... Esta Torre Jacinto significa mucho para Caelestites.",
  str_homestory_807701001_12_dialog_content = "¡Sí! Esta es una estructura masiva.",
  str_homestory_807701001_13_dialog_content = "Es posible que no puedas verlo claramente desde aquí, pero en realidad es muy grande. ¡Bastante espacioso por dentro también!",
  str_homestory_807701001_14_dialog_content = "Puede producir y reparar el Coloso.",
  str_homestory_807701001_15_dialog_content = "Según la información disponible, aquí se entrenaron muchos caelestitas.",
  str_homestory_807701001_16_dialog_content = "Es más o menos una cuna para Navigators.",
  str_homestory_807701001_17_dialog_content = "¿una cuna?",
  str_homestory_807701001_18_dialog_content = "Vea cuán excepcionalmente brillante y radiante es bajo el cielo.",
  str_homestory_807701001_19_dialog_content = "Es más como... un tótem espiritual de Caelestites.",
  str_homestory_807701001_20_dialog_content = "PlayerName, ¿sabes cómo se unen las personas?",
  str_homestory_807701001_21_dialog_content = "Ah, me tienes...",
  str_homestory_807701001_22_dialog_content = "Nunca he pensado en esto. Lo siento.",
  str_homestory_807701001_23_dialog_content = "No te preocupes. Esta pregunta no te importaba antes.",
  str_homestory_807701001_24_dialog_content = "Pero las cosas son diferentes ahora. Necesitas ver este continente desde una nueva perspectiva.",
  str_homestory_807701001_25_dialog_content = "Todos aquí, altos o bajos, fuertes o débiles, ancianos o jóvenes...",
  str_homestory_807701001_26_dialog_content = "Mientras compartan una fe y una creencia comunes...",
  str_homestory_807701001_27_dialog_content = "Ellos están juntos.",
  str_homestory_807701001_28_dialog_content = "No podemos conquistar la naturaleza solos.",
  str_homestory_807701001_29_dialog_content = "No tenemos garras afiladas ni colmillos. Nuestras pieles no son duras como rocas y nuestros brazos no pueden llevarnos al cielo.",
  str_homestory_807701001_30_dialog_content = "Pero si luchamos juntos como uno solo, nuestro poder está más allá de la imaginación...",
  str_homestory_807701001_31_dialog_content = "Si lo pones de esta manera...",
  str_homestory_807701001_32_dialog_content = "Su Majestad, usted es el tótem espiritual de nosotros.",
  str_homestory_807701001_33_dialog_content = "...",
  str_homestory_807701001_34_dialog_content = "Mmm... Así es.",
  str_homestory_807701001_35_dialog_content = "La confianza, la admiración o la búsqueda de protección me las traen.",
  str_homestory_807701001_36_dialog_content = "Esto no es algo malo...",
  str_homestory_807701001_37_dialog_content = "Un grupo unido siempre es más fuerte que un montón de arena suelta.",
  str_homestory_807701001_38_dialog_content = "Tanto Illumina como Lumopolis mantienen esta unidad a su manera.",
  str_homestory_807701001_39_dialog_content = "Sí... He aprendido sobre esto.",
  str_homestory_807701001_40_dialog_content = "Has crecido, el Caelestite que sostiene el futuro.",
  str_homestory_807701001_41_dialog_content = "Esta Torre Blanca, el tótem de Caelestites, es como tú...",
  str_homestory_807701001_42_dialog_content = "Ambos tienen el poder de la unidad.",
  str_homestory_807701001_43_dialog_content = "¿Tengo el poder de unir a la gente y defender a Eraveil...? Oh, Su Majestad, ¿puedo hacerle una pregunta?",
  str_homestory_807701001_44_dialog_content = "Adelante.",
  str_homestory_807701001_45_dialog_content = "¿Viste el Eraveil de hoy en el futuro que preveías?",
  str_homestory_807701001_46_dialog_content = "... Por supuesto. Y hay más",
  str_homestory_804201001_0_dialog_content = "Barton!",
  str_homestory_804201001_1_dialog_content = "¡Hola, Navegador!",
  str_homestory_804201001_2_dialog_content = "Barton...",
  str_homestory_804201001_3_dialog_content = "Shh... Mira conmigo.<sprite=emo_mojing size=60 />",
  str_homestory_804201001_4_dialog_content = "... ¿Ah?",
  str_homestory_804201001_5_dialog_content = "¿Qué estás viendo?",
  str_homestory_804201001_6_dialog_content = "¡Tienes bastantes hombres dotados aquí! ¡Navegador!",
  str_homestory_804201001_7_dialog_content = "¿Cómo los extrañé a todos en el Coloso?",
  str_homestory_804201001_8_dialog_content = "Hmm... ¡Supongo que no tenían suficiente espacio para desplegar completamente sus alas en el Coloso!",
  str_homestory_804201001_9_dialog_content = "... ¿Hombres superdotados?",
  str_homestory_804201001_10_dialog_content = "¿Estás reclutando para Illumina?",
  str_homestory_804201001_11_dialog_content = "¿Recluta? No, no tienen que unirse.",
  str_homestory_804201001_12_dialog_content = "PlayerName, ¿sabes qué legión mando?",
  str_homestory_804201001_13_option_content = "la segunda legión",
  str_homestory_804201001_14_dialog_content = "¡Es Correcto!",
  str_homestory_804201001_15_option_content = "La 4ta Legión",
  str_homestory_804201001_16_dialog_content = "¿En serio? <sprite=emo_shengqi size=60 />¡Mocoso, mis tropas son mucho más grandes que las de esa chica!",
  str_homestory_804201001_17_dialog_content = "¡Mmm! Wrath¡Las reservas de élite de 's no pueden resistir un solo golpe de nosotros!",
  str_homestory_804201001_18_dialog_content = "Estoy al mando de la 2ª Legión más grande. Recuerda esto.",
  str_homestory_804201001_19_dialog_content = "Si...",
  str_homestory_804201001_20_dialog_content = "¿¡Conoces mi responsabilidad especialmente asignada por el Gran Mariscal!?",
  str_homestory_804201001_21_option_content = "¿Apoyo rápido?",
  str_homestory_804201001_22_dialog_content = "... Eso es para Hiiro y Vice.",
  str_homestory_804201001_23_dialog_content = "¡Oye! ¿Olvidaste tu cerebro en casa?",
  str_homestory_804201001_24_dialog_content = "¡Yo dirijo las tropas de la guarnición!",
  str_homestory_804201001_25_dialog_content = "... ¿Ahora lo ves?",
  str_homestory_804201001_26_dialog_content = "Si...",
  str_homestory_804201001_27_option_content = "Defensa y seguridad.",
  str_homestory_804201001_28_dialog_content = "¡Correcto! ¡Has estado aprendiendo!",
  str_homestory_804201001_29_dialog_content = "Con este conocimiento, deberías entender lo que estoy haciendo aquí.",
  str_homestory_804201001_30_dialog_content = "Has reunido a tantos talentosos con habilidades únicas aquí...",
  str_homestory_804201001_31_dialog_content = "De vez en cuando estallaba una pelea entre ellos...",
  str_homestory_804201001_32_dialog_content = "¡Ataques furtivos! ¡Armas ocultas! ¡Taijutsu ataca!",
  str_homestory_804201001_33_dialog_content = "Tsk... Espléndido.",
  str_homestory_804201001_34_dialog_content = "No los necesito para unirse a Illumina. ¿Lo entiendes?",
  str_homestory_804201001_35_dialog_content = "Ver su ataque y defensa es suficiente.",
  str_homestory_804201001_36_dialog_content = "Estoy aprendiendo diferentes técnicas de diferentes personas. ¡Después, les pasaré todo esto a mis soldados!",
  str_homestory_804201001_37_dialog_content = "¡Esta es una lección valiosa!",
  str_homestory_804201001_38_dialog_content = "Ok...",
  str_homestory_804201001_39_dialog_content = "Esperar. ¿Por qué están peleando?",
  str_homestory_804201001_40_dialog_content = "¿No es bastante común que los aurorianos no se gusten entre sí?",
  str_homestory_804201001_41_dialog_content = "Pensé que ya estabas acostumbrado a esto en el Coloso.",
  str_homestory_804201001_42_dialog_content = "Pero...",
  str_homestory_804201001_43_dialog_content = "¡Solo finge que están entrenando entre ellos!",
  str_homestory_804201001_44_dialog_content = "Ahora necesito trabajar en el movimiento que vi ayer...",
  str_homestory_804201001_45_dialog_content = "¿Cómo tomó esa patada de ella?",
  str_homestory_804201001_46_dialog_content = "Hmm... Una vez que domine esto, atrévete Wrath para provocarme de nuevo!",
  str_homestory_804201001_47_dialog_content = "¡Oye! ¡Eh!<sprite=emo_nuhuo size=60 />",
  str_homestory_804201001_48_dialog_content = "... Bien. Buena suerte, Barton...",
  str_homestory_807601001_0_dialog_content = "Kleken...",
  str_homestory_807601001_1_dialog_content = "¡Ay! El héroe viajero finalmente ha aterrizado.",
  str_homestory_807601001_2_dialog_content = "Hola, Kleken.",
  str_homestory_807601001_3_dialog_content = "¿Realmente te gusta esta roca de la cascada? A menudo te veo por aquí dando vueltas...",
  str_homestory_807601001_4_dialog_content = "¡Qué preciosa es esta corriente!",
  str_homestory_807601001_5_dialog_content = "Todos estos ríos y manantiales me están conmoviendo hasta las lágrimas<sprite=emo_hanshui size=60 />.",
  str_homestory_807601001_6_dialog_content = "¿Estas siendo sarcastico?",
  str_homestory_807601001_7_dialog_content = "Todo lo que tenemos aquí son algunos arroyos ornamentales...",
  str_homestory_807601001_8_dialog_content = "No es nada comparado con el \"océano\" y el \"ahogamiento\" que te gusta decir.",
  str_homestory_807601001_9_dialog_content = "Quiero agradecerte.",
  str_homestory_807601001_10_dialog_content = "... ¿Para qué?",
  str_homestory_807601001_11_dialog_content = "Pronto serás testigo de cómo mi Técnica de la Mirada alcanza la perfección.",
  str_homestory_807601001_12_dialog_content = "Podré decir en qué ha estado ocupada últimamente tu cabecita...",
  str_homestory_807601001_13_dialog_content = "Una mirada a tus hermosos ojos es todo lo que se necesita para encontrar la respuesta.",
  str_homestory_807601001_14_dialog_content = "Gracias por ser mi primer testigo.",
  str_homestory_807601001_15_dialog_content = "Err...",
  str_homestory_807601001_16_option_content = "¿Técnica de la mirada?",
  str_homestory_807601001_17_dialog_content = "Eres curioso, pequeño...",
  str_homestory_807601001_18_option_content = "¿Puedo decir no?",
  str_homestory_807601001_19_dialog_content = "Claro.",
  str_homestory_807601001_20_dialog_content = "Pero esas pequeñas criaturas rápidas detrás de mí no te dejarán.",
  str_homestory_807601001_21_dialog_content = "Les encanta verte dormir, PlayerName...",
  str_homestory_807601001_22_dialog_content = "(... ¿Que demonios?)",
  str_homestory_807601001_23_dialog_content = "Bien... No tardes demasiado. Tengo cosas que hacer.",
  str_homestory_807601001_24_dialog_content = "Entonces, ¿qué es esta técnica de la mirada?",
  str_homestory_807601001_25_dialog_content = "Déjame explicarte, guerrero.",
  str_homestory_807601001_26_dialog_content = "Creo que visitaste Umbraton recientemente...",
  str_homestory_807601001_27_dialog_content = "Caminabas tranquilamente por la calle cuando viste a una niña lamentable.",
  str_homestory_807601001_28_dialog_content = "Ella te pidió ayuda para averiguar los precios de esos restaurantes en esa calle...",
  str_homestory_807601001_29_dialog_content = "Tenía muy poco para caminar en un restaurante al azar.",
  str_homestory_807601001_30_dialog_content = "No podía soportar la idea de que los camareros la miraran mal si pedía solo una rebanada de pan...",
  str_homestory_807601001_31_dialog_content = "Fuiste con ella a un restaurante tras otro y averiguaste los precios para ella.",
  str_homestory_807601001_32_dialog_content = "Cada vez, ella sacudía la cabeza.",
  str_homestory_807601001_33_dialog_content = "Al final, decidiste comprarle una buena comida...",
  str_homestory_807601001_34_dialog_content = "Después de la comida, se fue después de un rápido agradecimiento, dejando suficiente dinero en la mesa para cubrir la cuenta.",
  str_homestory_807601001_35_dialog_content = "... ¿Cómo lo sabes?",
  str_homestory_807601001_36_dialog_content = "(¿Cómo podría esta técnica de la mirada ser tan mágica?)",
  str_homestory_807601001_37_dialog_content = "... De todos modos, fue difícil para mí procesarlo.",
  str_homestory_807601001_38_dialog_content = "Si ella tuvo el dinero todo el tiempo, ¿por qué no entró en un restaurante y disfrutó de la comida?",
  str_homestory_807601001_39_dialog_content = "Como dijiste... ¡comprobó el precio de cada plato en todos los restaurantes de Umbraton!",
  str_homestory_807601001_40_dialog_content = "Jajaja... Jajajaja<sprite=emo_guilian size=60 />.",
  str_homestory_807601001_41_dialog_content = "Porque yo le pedí que lo hiciera.",
  str_homestory_807601001_42_dialog_content = "Era una tarea asignada por el Señor Istvan...",
  str_homestory_807601001_43_dialog_content = "Para estudiar los precios de los alimentos en Umbraton.",
  str_homestory_807601001_44_dialog_content = "He estado ayudando a esta chica. Darle esta oportunidad de hacerme un pequeño favor podría hacerla sentir útil...",
  str_homestory_807601001_45_dialog_content = "De todos modos, Caelestite no tenía mejores cosas que hacer entonces. Entonces, ¿por qué no seguir adelante con eso?",
  str_homestory_807601001_46_dialog_content = "Caminar es demasiado exigente físicamente para mí en estos días.",
  str_homestory_807601001_47_dialog_content = "...",
  str_homestory_807601001_48_dialog_content = "Verás. Esta es la verdad de la Técnica de la Mirada, PlayerName.",
  str_homestory_807601001_49_dialog_content = "Pareces decepcionado... ¡Qué interesante!",
  str_homestory_804601001_0_dialog_content = "Es él.",
  str_homestory_804601001_1_dialog_content = "Navegador viene y Navegador se va ♪",
  str_homestory_804601001_2_dialog_content = "Navigator le sonríe a Pierre, pero Pierre solo quiere causar problemas.",
  str_homestory_804601001_3_dialog_content = "¿Estás de compras?",
  str_homestory_804601001_4_dialog_content = "Compras. Navigator cree que estoy comprando<sprite=emo_yinfu size=60 />",
  str_homestory_804601001_5_dialog_content = "Dian diría que no y Kara diría: \"¡Así es!\" Niel diría: \"Algo así...\", pero Pierre solo se reiría.<sprite=emo_muji size=60 />",
  str_homestory_804601001_6_dialog_content = "Entonces, ¿qué crees que estoy tratando de decir?",
  str_homestory_804601001_7_dialog_content = "...%^&",
  str_homestory_804601001_8_dialog_content = "Olvídalo. No estoy de humor para un acertijo.",
  str_homestory_804601001_9_dialog_content = "Quería preguntarte cómo te trata la vida aquí...",
  str_homestory_804601001_10_dialog_content = "Es un alivio verte inteligente y travieso como siempre.",
  str_homestory_804601001_11_dialog_content = "Navegador se preocupa por Keating. Pierre es honrado ♪",
  str_homestory_804601001_12_dialog_content = "Navegante, ¿no tienes curiosidad por saber a quién he conocido recientemente?",
  str_homestory_804601001_13_dialog_content = "... Tengo un mal presentimiento ...<sprite=emo_tanqi size=60 />",
  str_homestory_804601001_14_dialog_content = "Entonces, ¿a quién has conocido?",
  str_homestory_804601001_15_dialog_content = "Tus pequeños deben tener más cuidado aquí. No es bueno burlarse de los demás...",
  str_homestory_804601001_16_dialog_content = "No estás en Lumópolis. ¡Algunos aurorianos tienen mal genio!",
  str_homestory_804601001_17_dialog_content = "También hay Aurorianos muy sensibles. Tus malas palabras probablemente los harían llorar...",
  str_homestory_804601001_18_dialog_content = "Navigator está preocupado por nosotros. Navigator se preocupa por sus amigos ♪",
  str_homestory_804601001_19_dialog_content = "Conocimos a un reparador de cola larga y nos hizo un brazo robótico para atrapar pollos.",
  str_homestory_804601001_20_dialog_content = "Conocimos a un pájaro gordito y nos regaló muchas bolas de nieve.",
  str_homestory_804601001_21_dialog_content = "Conocimos a un perro con traje, molesto porque nadie estaba interesado en sus pinturas falsas.",
  str_homestory_804601001_22_dialog_content = "Pierre conoció a un Navegante bajo y fornido, parado frente a mí preocupado por sus amigos.",
  str_homestory_804601001_23_dialog_content = "... Uf... Mejor de lo que pensaba.",
  str_homestory_804601001_24_dialog_content = "Para ser honesto, estas son posiblemente las palabras más amables que jamás hayas dicho.",
  str_homestory_804601001_25_dialog_content = "La gente se vuelve gentil por una razón.",
  str_homestory_804601001_26_dialog_content = "En la librería hay libros que le gustan a Dian.",
  str_homestory_804601001_27_dialog_content = "En la habitación, hay un paño para lentes que Niel necesita.",
  str_homestory_804601001_28_dialog_content = "En el comedor, hay un perchero para Kara.",
  str_homestory_804601001_29_dialog_content = "En el césped, están los bocadillos favoritos de Gege y Pierre♪",
  str_homestory_804601001_30_dialog_content = "El navegante pensativo es nuestro amigo del alma.",
  str_homestory_804601001_31_dialog_content = "El Navigator es la estrella del mañana.",
  str_homestory_804601001_32_dialog_content = "La estrella que crecerá más alta ♪",
  str_homestory_804601001_33_dialog_content = "... Todo estuvo bien hasta la última línea.",
  str_homestory_804601001_34_dialog_content = "Navegante, ¿cuál es tu plan?",
  str_homestory_804601001_35_option_content = "Vuelve a descansar",
  str_homestory_804601001_36_dialog_content = "Tomaré una siesta.",
  str_homestory_804601001_37_option_content = "Deambular",
  str_homestory_804601001_38_dialog_content = "Voy a ver qué están haciendo otras personas.",
  str_homestory_804601001_39_dialog_content = "Entiendo. Pedro lo entendió.",
  str_homestory_804601001_40_dialog_content = "Aunque a Pierre realmente no le importa. Aquí hay una línea para el maestro.",
  str_homestory_804601001_41_dialog_content = "Gege está fertilizando cerca del jardín. Fertilizando ♪",
  str_homestory_804601001_42_dialog_content = "¡¿?!",
  str_homestory_804601001_43_dialog_content = "¿Fertilizando?",
  str_homestory_804601001_44_dialog_content = "Pierre es muy amable. Compruébalo cuando puedas ♪",
  str_homestory_804601001_45_dialog_content = "... ¡Gracias por su preocupación!",
  str_homestory_805701001_0_dialog_content = "Esto es... ¿pelo de gato?",
  str_homestory_805701001_1_dialog_content = "Bostezo-",
  str_homestory_805701001_2_dialog_content = "¿Mmm? Philyshy?",
  str_homestory_805701001_3_dialog_content = "Ajá...<sprite=emo_kun size=60 />",
  str_homestory_805701001_4_dialog_content = "... Philyshy?",
  str_homestory_805701001_5_dialog_content = "¡Uf... Miau!",
  str_homestory_805701001_6_dialog_content = "¡Que demonios! Es PlayerName, maullar.",
  str_homestory_805701001_7_dialog_content = "¿No ves que estoy durmiendo, miau?",
  str_homestory_805701001_8_dialog_content = "Vuelve después de mi siesta, miau.",
  str_homestory_805701001_9_dialog_content = "Tendré un dulce sueño en este cómodo pajar, miau...",
  str_homestory_805701001_10_dialog_content = "Esperar, Philyshy! ¡Tengo algo que decirte!",
  str_homestory_805701001_11_dialog_content = "Eh... Eh... ¡Miau!",
  str_homestory_805701001_12_dialog_content = "Hmm... ¿Qué tienes que decirme, miau?",
  str_homestory_805701001_13_dialog_content = "Más vale que sea muy importante, ¡miau!",
  str_homestory_805701001_14_dialog_content = "Umm... Algunos Aurorianos vinieron a mí...",
  str_homestory_805701001_15_dialog_content = "Philyshy, Has estado...",
  str_homestory_805701001_16_option_content = "¿Sentirse mal?",
  str_homestory_805701001_17_dialog_content = "¿Alguna picazón?",
  str_homestory_805701001_18_dialog_content = "¿Pérdida de apetito?",
  str_homestory_805701001_19_dialog_content = "¿De qué estás hablando, miau?",
  str_homestory_805701001_20_dialog_content = "Philyshy no entiende",
  str_homestory_805701001_21_option_content = "¿Temporada de muda?",
  str_homestory_805701001_22_dialog_content = "¿Despojarse de qué... miau?",
  str_homestory_805701001_23_dialog_content = "¿Qué es eso?",
  str_homestory_805701001_24_dialog_content = "(¡Qué mala actuación!)",
  str_homestory_805701001_25_dialog_content = "De todos modos, Philyshy no siente nada!",
  str_homestory_805701001_26_dialog_content = "(Acariciando Philyshyla cola)",
  str_homestory_805701001_27_dialog_content = "¡Miau!",
  str_homestory_805701001_28_dialog_content = "PlayerName, ¿cómo pudiste tocar la cola de una dama?",
  str_homestory_805701001_29_dialog_content = "Se sintió un poco agradable. ¡No, miau!",
  str_homestory_805701001_30_dialog_content = "Philyshy, ¡cuánto pelo se te cayó cuando lo sacudiste!",
  str_homestory_805701001_31_dialog_content = "¡E-Eso no es cierto...!",
  str_homestory_805701001_32_dialog_content = "Boohoo... Miau. ¡No puedo detenerlo!",
  str_homestory_805701001_33_dialog_content = "Es la temporada de muda... ¡No, miau!",
  str_homestory_805701001_34_dialog_content = "Mi cabello está absorbiendo suficiente luz solar para una evolución, ¡miau!",
  str_homestory_805701001_35_dialog_content = "Una vez que esté hecho... me convertiré en Super Philyshy, ¡maullar!",
  str_homestory_805701001_36_dialog_content = "Pero... Si tu pelo vuela por todos lados...",
  str_homestory_805701001_37_dialog_content = "Algunos aurorianos pueden sufrir alergias.",
  str_homestory_805701001_38_dialog_content = "Hmm... ¿Qué debo hacer entonces?",
  str_homestory_805701001_39_dialog_content = "No es Philyshyelección de .<sprite=emo_tanqi size=60 />",
  str_homestory_805701001_40_dialog_content = "Tienes razón... Déjame pensar...",
  str_homestory_805701001_41_dialog_content = "¿Qué tal... déjame arreglarte?",
  str_homestory_805701001_42_dialog_content = "Tu cabello será más suave y sedoso. No más vuelos.",
  str_homestory_805701001_43_dialog_content = "Istvan me enseñó esto.",
  str_homestory_805701001_44_dialog_content = "De acuerdo... Solo porque preparaste este cómodo pajar en Eraveil.",
  str_homestory_805701001_45_dialog_content = "Petición de preparación concedida, ¡miau!",
  str_homestory_803601001_0_dialog_content = "Hydrad?",
  str_homestory_803601001_1_dialog_content = "¿Qué estás haciendo?",
  str_homestory_803601001_2_dialog_content = "¿No puedes ver?",
  str_homestory_803601001_3_dialog_content = "Estoy de pie.",
  str_homestory_803601001_4_dialog_content = "... Eso lo sé.",
  str_homestory_803601001_5_dialog_content = "...",
  str_homestory_803601001_6_dialog_content = "...",
  str_homestory_803601001_7_dialog_content = "Hola.",
  str_homestory_803601001_8_dialog_content = "¿Si?",
  str_homestory_803601001_9_dialog_content = "Me lesioné ayer.",
  str_homestory_803601001_10_dialog_content = "¡¿?!",
  str_homestory_803601001_11_option_content = "¿Estás bien?",
  str_homestory_803601001_12_dialog_content = "Aún pateando.",
  str_homestory_803601001_13_option_content = "¿Dónde fuiste?",
  str_homestory_803601001_14_dialog_content = "Sé lo que te preocupa.",
  str_homestory_803601001_15_dialog_content = "No sucedió aquí.",
  str_homestory_803601001_16_dialog_content = "Yo... sólo me preocupa tu salud.",
  str_homestory_803601001_17_dialog_content = "¿Cómo te sientes? ¿Algo mejor?",
  str_homestory_803601001_18_dialog_content = "Más o menos.",
  str_homestory_803601001_19_dialog_content = "Mi pronta recuperación es todo gracias a Shadow Wolves.",
  str_homestory_803601001_20_dialog_content = "Multa. ¿Podrías decirme qué pasó?",
  str_homestory_803601001_21_dialog_content = "No me digas que disfrutas esto.",
  str_homestory_803601001_22_dialog_content = "Estaba luchando por algo.",
  str_homestory_803601001_23_dialog_content = "En el Mercado Negro de Umbraton.",
  str_homestory_803601001_24_dialog_content = "¿Qué era tan importante?",
  str_homestory_803601001_25_dialog_content = "Supuestamente un producto de la civilización antigua.",
  str_homestory_803601001_26_dialog_content = "¿Presuntamente?",
  str_homestory_803601001_27_dialog_content = "¿No estás seguro de esto?",
  str_homestory_803601001_28_dialog_content = "Nunca lo sabrás hasta que lo intentes.",
  str_homestory_803601001_29_dialog_content = "... ¿Qué era?",
  str_homestory_803601001_30_dialog_content = "Una especie de consola que puede hacer realidad la ilusión o la magia de las Sombras.",
  str_homestory_803601001_31_dialog_content = "Err... Pero tus Lobos Sombríos siempre han estado a tu lado.",
  str_homestory_803601001_32_dialog_content = "Tararear. Pero quiero acariciar su pelaje esponjoso todos los días.",
  str_homestory_803601001_33_dialog_content = "El pelaje real crece de su piel, no de los pelos dispersos que se caen durante el período de muda.",
  str_homestory_803601001_34_dialog_content = "Ok...",
  str_homestory_803601001_35_dialog_content = "(Hydrad... es probablemente bastante solitario?)",
  str_homestory_803601001_36_dialog_content = "Creo que es falso.",
  str_homestory_803601001_37_dialog_content = "¿El dispositivo?",
  str_homestory_803601001_38_dialog_content = "Sí.",
  str_homestory_803601001_39_dialog_content = "Nunca he oído hablar de algo así.",
  str_homestory_803601001_40_dialog_content = "(¿Se sentiría mejor si fuera falso?)",
  str_homestory_803601001_41_dialog_content = "Estoy de acuerdo con usted.",
  str_homestory_803601001_42_dialog_content = "Algo así sería una reliquia de valor incalculable...",
  str_homestory_803601001_43_dialog_content = "No terminará en el mercado negro.",
  str_homestory_803601001_44_dialog_content = "... Eso es cierto.",
  str_homestory_803601001_45_dialog_content = "Ya que tú también lo piensas.",
  str_homestory_803601001_46_dialog_content = "Me tengo que ir.",
  str_homestory_803601001_47_dialog_content = "¡Nos vemos!",
  str_homestory_803601001_48_dialog_content = "(Si fuera real, ¿qué haría con él?)",
  str_homestory_811401001_0_dialog_content = "este caballo...",
  str_homestory_811401001_1_dialog_content = "Ah, querido Navegante.",
  str_homestory_811401001_2_dialog_content = "¿Anna se interpone en tu camino?",
  str_homestory_811401001_3_dialog_content = "¿O estás aquí para verme?",
  str_homestory_811401001_4_dialog_content = "Perdón por quedarme aquí por tanto tiempo. Estas flores son tan fragantes...",
  str_homestory_811401001_5_dialog_content = "No te preocupes por eso. Disfruta de las flores.",
  str_homestory_811401001_6_dialog_content = "Eso fue rápido. Estas flores...",
  str_homestory_811401001_7_dialog_content = "Muchas más flores de las que imaginaba.",
  str_homestory_811401001_8_dialog_content = "¿Mmm? ¿Qué fue eso, Navegante?",
  str_homestory_811401001_9_dialog_content = "Ah... Estaba murmurando sobre estas flores.",
  str_homestory_811401001_10_dialog_content = "Acabo de pedir a través de Courier Union<sprite=emo_gezitou size=60 /> hace unos días.",
  str_homestory_811401001_11_dialog_content = "Algunas personas sugirieron que deberíamos agregar algunas flores a todas las rocas y árboles.",
  str_homestory_811401001_12_dialog_content = "¿Vaya? ¡Pensé en lo mismo!",
  str_homestory_811401001_13_dialog_content = "Le dije a Anna el otro día que necesitábamos más flores aquí.",
  str_homestory_811401001_14_dialog_content = "Sí. Por eso me puse en contacto con el Courier Union.",
  str_homestory_811401001_15_dialog_content = "Sin embargo, es un poco más de lo que esperaba...",
  str_homestory_811401001_16_dialog_content = "También acabo de comprar algunos después de mi última misión.",
  str_homestory_811401001_17_dialog_content = "Eso lo explica todo...",
  str_homestory_811401001_18_dialog_content = "Navigator, tienes un lindo lugar.",
  str_homestory_811401001_19_dialog_content = "Revisé la tienda y encontré mi ginebra favorita...",
  str_homestory_811401001_20_dialog_content = "También esas hierbas, jarabes y especias esenciales para un delicioso cóctel.",
  str_homestory_811401001_21_dialog_content = "jajaja ¡Estoy gratamente sorprendido!",
  str_homestory_811401001_22_dialog_content = "Te has vuelto más pensativo.",
  str_homestory_811401001_23_dialog_content = "Reflexivo...",
  str_homestory_811401001_24_dialog_content = "¿Qué experiencias volvieron a ese niño ignorante tan dulce y considerable?",
  str_homestory_811401001_25_dialog_content = "Genevieve ¿Sigue hablando de almacenar ginebra en la tienda?",
  str_homestory_811401001_26_dialog_content = "No solo eso. También has pedido flores para las damas.",
  str_homestory_811401001_27_dialog_content = "Bueno en realidad...",
  str_homestory_811401001_28_dialog_content = "La persona que me dijo que comprara ginebra y ordenara flores es...",
  str_homestory_811401001_29_dialog_content = "... Smokey.",
  str_homestory_811401001_30_dialog_content = "... ¿Vaya?",
  str_homestory_811401001_31_dialog_content = "Tenía muchas más solicitudes, así que no creo que lo haya hecho por ti...",
  str_homestory_811401001_32_dialog_content = "Ahora lo mencionaste... Ese día cuando estaba hablando con Anna, sentí algo de aire caliente a mi alrededor.",
  str_homestory_811401001_33_dialog_content = "Ni siquiera pensé en ella, considerando la gran cantidad de personas aquí que usan fuego.<sprite=emo_nuhuo size=60 />.",
  str_homestory_811401001_34_dialog_content = "... Este chico...",
  str_homestory_811401001_35_dialog_content = "Probablemente no quiera que me entere de esto.",
  str_homestory_811401001_36_dialog_content = "Mmm... creo...",
  str_homestory_811401001_37_option_content = "Ella espera que sí.",
  str_homestory_811401001_38_dialog_content = "De lo contrario, fácilmente podría conseguir un poco de ginebra y flores ella misma...",
  str_homestory_811401001_39_dialog_content = "Quiero decir... Realmente no me necesitaba para conseguir esto.",
  str_homestory_811401001_40_option_content = "Ella espera que no.",
  str_homestory_811401001_41_dialog_content = "De hecho, pregunté si la ginebra era para ti. Y ella negó...",
  str_homestory_811401001_42_dialog_content = "¿En serio?",
  str_homestory_811401001_43_dialog_content = "Eso es un poco incómodo.",
  str_homestory_811401001_44_dialog_content = "De todos modos, Navegante, por favor mantenga la conversación de hoy entre nosotros.",
  str_homestory_811401001_45_dialog_content = "Aunque he aprendido acerca de su amabilidad, nadie quiere esto expuesto en su cara...",
  str_homestory_811401001_46_dialog_content = "Para ocultar su vergüenza, prendía fuego o montaba una escena.",
  str_homestory_811401001_47_dialog_content = "Entendido...",
  str_homestory_811401001_48_dialog_content = "¡La conoces bien!",
  str_homestory_811401001_49_dialog_content = "¿Crees que sí? No sé sobre eso.",
  str_homestory_801801001_0_dialog_content = "Esta aura salvaje...",
  str_homestory_801801001_1_dialog_content = "¡No te preocupes!",
  str_homestory_801801001_2_dialog_content = "Y... ¡sin desperdicio de aliento!",
  str_homestory_801801001_3_dialog_content = "¡Demasiados tontos en este mundo! ¡Fuego! ¡Quemar!<sprite=emo_nuhuo size=60 />",
  str_homestory_801801001_4_dialog_content = "(¡Está completamente fuera de sí!)",
  str_homestory_801801001_5_dialog_content = "Oye, Regina!",
  str_homestory_801801001_6_dialog_content = "Navigator, ¿qué opinas de mi nueva demostración?",
  str_homestory_801801001_7_dialog_content = "Pensé que estabas maldiciendo...",
  str_homestory_801801001_8_dialog_content = "¿Lo escuchaste?",
  str_homestory_801801001_9_dialog_content = "¡Sí!",
  str_homestory_801801001_10_dialog_content = "Oh... ¡He intentado ser implícito!",
  str_homestory_801801001_11_dialog_content = "¿Pero aún podías escucharlo?",
  str_homestory_801801001_12_dialog_content = "¡Has aprendido de los niños malos!",
  str_homestory_801801001_13_dialog_content = "?",
  str_homestory_801801001_14_dialog_content = "ejem... nunca...",
  str_homestory_801801001_15_dialog_content = "Lo que sea. ¡A quien le importa!",
  str_homestory_801801001_16_dialog_content = "Mi nueva canción aún no está completa. ¿Cualquier pensamiento? ¡Pégame!",
  str_homestory_801801001_17_dialog_content = "¿Tema? ¿Letra? ¿Melodía?",
  str_homestory_801801001_18_dialog_content = "Apesto en la música.",
  str_homestory_801801001_19_dialog_content = "¿Y qué? ¡No odio a nadie más que a esos viejos que insisten en establecer umbrales para la música!",
  str_homestory_801801001_20_dialog_content = "¡Solo di algo, lo que sea!",
  str_homestory_801801001_21_dialog_content = "...",
  str_homestory_801801001_22_option_content = "Barbara es la mejor",
  str_homestory_801801001_23_dialog_content = "¿Eh? ¿Qué diablos dijiste?",
  str_homestory_801801001_24_dialog_content = "Lo tengo. Sarcasmo.",
  str_homestory_801801001_25_option_content = "¡Metal para siempre!",
  str_homestory_801801001_26_dialog_content = "¡Es Correcto!",
  str_homestory_801801001_27_dialog_content = "¡Lo escribiré!",
  str_homestory_801801001_28_dialog_content = "¡Ja! ¡Una nueva canción compuesta con la ayuda de Caelestite será increíble!",
  str_homestory_801801001_29_dialog_content = "ah estás compitiendo con Barbara en todos los campos, así como con sus compañeros de metal?",
  str_homestory_801801001_30_dialog_content = "Vamos. ¿Qué músico respeta genuinamente a otro?<sprite=emo_shengqi size=60 />",
  str_homestory_801801001_31_dialog_content = "Especialmente los de mi género. ¡La mayoría de ellos son ignorantes y falsos!",
  str_homestory_801801001_32_dialog_content = "Sintiéndose los últimos que entienden el rock y tienen una antigüedad considerable... En realidad, ¡probablemente nunca escriban una canción por su cuenta!",
  str_homestory_801801001_33_dialog_content = "¡Mmm! Si por mí fuera, les prendería fuego a todos...",
  str_homestory_801801001_34_dialog_content = "Hablar con ellos de metal es peor que escuchar Barbara¡El nuevo sencillo de!",
  str_homestory_801801001_35_dialog_content = "... Pensé que te desagradaba mucho Barbara?",
  str_homestory_801801001_36_dialog_content = "Dos segundos.",
  str_homestory_801801001_37_dialog_content = "?",
  str_homestory_801801001_38_dialog_content = "puedo soportar BarbaraLa nueva canción de 2 segundos.",
  str_homestory_801801001_39_dialog_content = "Ahh...",
  str_homestory_809201001_0_dialog_content = "Eso es...",
  str_homestory_809201001_1_dialog_content = "Oye, Pact.",
  str_homestory_809201001_2_dialog_content = "¿Quién más podría ser?<sprite=emo_baiyan size=60 />",
  str_homestory_809201001_3_dialog_content = "Ejem. Este columpio es bastante popular...",
  str_homestory_809201001_4_dialog_content = "Entonces... ¿Te gusta jugar en el columpio?",
  str_homestory_809201001_5_dialog_content = "Tu pregunta no está muy bien estructurada.",
  str_homestory_809201001_6_dialog_content = "Primero, ¿cuál es tu definición de \"me gusta\"?",
  str_homestory_809201001_7_option_content = "Definir",
  str_homestory_809201001_8_dialog_content = "Creo que si te gusta algo, querrás hacerlo a menudo.",
  str_homestory_809201001_9_dialog_content = "Entonces, ¿cuál es la medida de \"a menudo\"? Esto no está claro.",
  str_homestory_809201001_10_dialog_content = "¿Como constantemente?",
  str_homestory_809201001_11_dialog_content = "O solo cuando tengo tiempo?",
  str_homestory_809201001_12_dialog_content = "¿O tal vez no pienso en ello con frecuencia, pero cuando lo haga, seguiré adelante y tomaré medidas?",
  str_homestory_809201001_13_dialog_content = "(¡Dios mío! Sólo estoy tratando de tener una conversación informal con Pact...)",
  str_homestory_809201001_14_dialog_content = "Supongo que la medida de \"a menudo\" es hacerlo cuando tengas tiempo.",
  str_homestory_809201001_15_option_content = "Negarse a definir",
  str_homestory_809201001_16_dialog_content = "¿Quién necesita una definición de \"me gusta\"?",
  str_homestory_809201001_17_dialog_content = "Cuando tengo tiempo, me gusta caminar.",
  str_homestory_809201001_18_dialog_content = "¿Algo que quiero hacer cuando tenga tiempo?",
  str_homestory_809201001_19_dialog_content = "Entendido.",
  str_homestory_809201001_20_dialog_content = "En este caso, me gusta sentarme en este columpio.",
  str_homestory_809201001_21_dialog_content = "Este tipo de silla colgante ofrece una sensación muy sutil de gravedad cero...",
  str_homestory_809201001_22_dialog_content = "Me da una alegría que no se puede expresar con palabras.",
  str_homestory_809201001_23_dialog_content = "¿De veras? ¡Estupendo!",
  str_homestory_809201001_24_dialog_content = "Al principio, no estaba seguro de si un columpio era una buena idea.",
  str_homestory_809201001_25_dialog_content = "¡Me alegro mucho de que lo estés disfrutando!",
  str_homestory_809201001_26_dialog_content = "Sin embargo, también hay problemas.",
  str_homestory_809201001_27_dialog_content = "Hunting Stone tiene dificultades para encontrar la cantidad adecuada de fuerza para empujarme.",
  str_homestory_809201001_28_dialog_content = "De hecho, ¡me caí una vez!",
  str_homestory_809201001_29_dialog_content = "Jajaja...",
  str_homestory_809201001_30_dialog_content = "¿Acabas de reírte de mí?<sprite=emo_shengqi size=60 />",
  str_homestory_809201001_31_option_content = "Negar",
  str_homestory_809201001_32_dialog_content = "Nunca...",
  str_homestory_809201001_33_dialog_content = "¿Está seguro? ¿Por qué las comisuras de tus labios subieron entonces?",
  str_homestory_809201001_34_option_content = "Admitir",
  str_homestory_809201001_35_dialog_content = "Lo siento...",
  str_homestory_809201001_36_dialog_content = "Casi podía verlo en mi cabeza...",
  str_homestory_809201001_37_dialog_content = "Ejem... ¿Estabas herido?",
  str_homestory_809201001_38_dialog_content = "¿Crees que soy tan vulnerable?",
  str_homestory_809201001_39_dialog_content = "¡Eso es un alivio! Ya que te gusta tanto el columpio...",
  str_homestory_809201001_40_dialog_content = "¿Puedo darte un empujón?",
  str_homestory_809201001_41_dialog_content = "¿Mmm? ¿Te importa?",
  str_homestory_809201001_42_dialog_content = "Bueno, si no te importa. Mi fuerza no es nada comparada con la de Hunting Stone.",
  str_homestory_809201001_43_dialog_content = "Eso depende de cómo definas \"mente\".",
  str_homestory_809201001_44_dialog_content = "Err...",
  str_homestory_809201001_45_dialog_content = "Vamos. ¡Es hora de balancearse!",
  str_homestory_809201001_46_dialog_content = "Está bien... Ya que eres así de sincero... Vamos.",
  str_homestory_809901001_0_dialog_content = "Areia...",
  str_homestory_809901001_1_dialog_content = "Ah, PlayerName...",
  str_homestory_809901001_2_dialog_content = "Gracias por invitarme aquí. ¡Estoy muy feliz!",
  str_homestory_809901001_3_dialog_content = "¡De nada!",
  str_homestory_809901001_4_dialog_content = "Supongo que aún no estás familiarizado con esta área. ¿Necesitas un guía turístico?",
  str_homestory_809901001_5_dialog_content = "PlayerName, ¿realmente tienes tiempo para esto?",
  str_homestory_809901001_6_dialog_content = "Por supuesto. Nadie conoce este lugar mejor que yo.",
  str_homestory_809901001_7_dialog_content = "Pero...",
  str_homestory_809901001_8_dialog_content = "Yo... prefiero volver a mi habitación.",
  str_homestory_809901001_9_dialog_content = "¿Eh? Areia, no te gusta el paisaje exterior?",
  str_homestory_809901001_10_dialog_content = "Todo lo contrario. Me encanta el paisaje aquí!",
  str_homestory_809901001_11_dialog_content = "Nunca antes había estado en un lugar aislado y cómodo como este.",
  str_homestory_809901001_12_option_content = "Muestra gratitud",
  str_homestory_809901001_13_dialog_content = "¡Estoy muy contento de que te guste aquí!",
  str_homestory_809901001_14_dialog_content = "Aquí tenemos paz y aislamiento, así como hilaridad y júbilo.",
  str_homestory_809901001_15_dialog_content = "Te mostraré los alrededores.",
  str_homestory_809901001_16_dialog_content = "Pero estoy asustado...",
  str_homestory_809901001_17_option_content = "Hacer una consulta",
  str_homestory_809901001_18_dialog_content = "¿Cuál es la prisa por volver a la habitación?",
  str_homestory_809901001_19_dialog_content = "Tengo miedo...",
  str_homestory_809901001_20_dialog_content = "¿Qué pasa si la maldición y las espinas oscuras sobre mí arruinaron la belleza?",
  str_homestory_809901001_21_dialog_content = "Causaría tantos problemas para PlayerName...",
  str_homestory_809901001_22_dialog_content = "Areia, eso es muy considerado de tu parte.",
  str_homestory_809901001_23_dialog_content = "Pero no creo que arruines la belleza aquí.",
  str_homestory_809901001_24_dialog_content = "¿Mmm?",
  str_homestory_809901001_25_dialog_content = "Nos conocemos desde hace algún tiempo. Tu maldición no me afecta en absoluto.",
  str_homestory_809901001_26_dialog_content = "Pero mis espinas oscuras...",
  str_homestory_809901001_27_dialog_content = "¿No son tus amigos los que protegen tu cuerpo de la maldición?",
  str_homestory_809901001_28_dialog_content = "Si...",
  str_homestory_809901001_29_dialog_content = "Areia¡Los amigos de son mis amigos!",
  str_homestory_809901001_30_dialog_content = "Además...",
  str_homestory_809901001_31_dialog_content = "Recuerdo que has estado buscando maneras de eliminar la maldición.",
  str_homestory_809901001_32_dialog_content = "Date una vuelta y tal vez encuentres algo.",
  str_homestory_809901001_33_dialog_content = "Huh... Lo encuentro muy difícil de creer incluso si salió de PlayerName.",
  str_homestory_809901001_34_dialog_content = "Han pasado tantos años. ¿Cuál es la posibilidad de encontrar una solución aquí?",
  str_homestory_809901001_35_dialog_content = "¿Supongo que no sales mucho más que por trabajo?",
  str_homestory_809901001_36_dialog_content = "Si...",
  str_homestory_809901001_37_dialog_content = "Cuando pasas tiempo en la naturaleza, tu estado de ánimo mejorará.",
  str_homestory_809901001_38_dialog_content = "Nunca sabes. ¡Un buen humor podría debilitar la maldición!",
  str_homestory_809901001_39_dialog_content = "...",
  str_homestory_809901001_40_dialog_content = "Jajaja...",
  str_homestory_809901001_41_dialog_content = "Gracias. Me siento bastante bien ahora.<sprite=emo_aixin size=60 />",
  str_homestory_809901001_42_dialog_content = "Bueno, entonces... ¿puedo visitar la mina?",
  str_homestory_809901001_43_dialog_content = "¿Mmm?",
  str_homestory_801601001_0_dialog_content = "Kafka?",
  str_homestory_801601001_1_dialog_content = "Esperar, Kafka... ¿Qué es esta mancha de agua?<sprite=emo_hanshui size=60 /> ¿en el piso?",
  str_homestory_801601001_2_dialog_content = "Ah... lo siento mucho. Franz<sprite=emo_goutou size=60 /> babeado Acabo de limpiarlo.",
  str_homestory_801601001_3_dialog_content = "Parece babear mucho cuando se siente feliz. He trabajado duro para abordar este nuevo problema.",
  str_homestory_801601001_4_dialog_content = "Err... Al menos no moja mi cama con tanta frecuencia.",
  str_homestory_801601001_5_dialog_content = "Vale la pena un regalo... Franz siempre ha sido un buen chico, ¿verdad?",
  str_homestory_801601001_6_dialog_content = "Tu cumplido lo hará enloquecer de alegría.",
  str_homestory_801601001_7_dialog_content = "Sé que es muy feliz aquí.",
  str_homestory_801601001_8_dialog_content = "¿Mmm? ¿Porque tiene más espacio aquí que en el Coloso?",
  str_homestory_801601001_9_dialog_content = "O porque sigue encontrándose con gente extraña...",
  str_homestory_801601001_10_dialog_content = "Como sabes, le encantan las cosas extrañas.",
  str_homestory_801601001_11_dialog_content = "¿Cómo qué?",
  str_homestory_801601001_12_dialog_content = "Debería decir \"criaturas extrañas\".",
  str_homestory_801601001_13_dialog_content = "extrañas criaturas...",
  str_homestory_801601001_14_dialog_content = "¡Entiendo! Debes estar hablando de... Él...",
  str_homestory_801601001_15_option_content = "Tourdog?",
  str_homestory_801601001_16_dialog_content = "Hmm... Eso suena bien. Nunca hablé mucho con él.",
  str_homestory_801601001_17_dialog_content = "Pero la cola de Franz se mueve como un loco cuando ve Tourdog. Incluso trató de morder Tourdogla oreja de una vez.",
  str_homestory_801601001_18_dialog_content = "¿Ah? Que hizo Tourdog ¿hacer?",
  str_homestory_801601001_19_dialog_content = "No mucho. Miró a Franz durante un rato, sosteniendo una sartén en la mano. Sentí que tenía algo que decir.",
  str_homestory_801601001_20_dialog_content = "(... ¡Podría pedirle a Franz que le dibuje algunos dibujos!)",
  str_homestory_801601001_21_dialog_content = "Por fin, miró las patas de Franz y se alejó sacudiendo la cabeza.",
  str_homestory_801601001_22_dialog_content = "Uf... Eso es un alivio...",
  str_homestory_801601001_23_dialog_content = "Por cierto, sus orejas se ven muy suaves.",
  str_homestory_801601001_24_dialog_content = "Debería tocarlos la próxima vez...",
  str_homestory_801601001_25_option_content = "¿Hachi y ginebra?",
  str_homestory_801601001_26_dialog_content = "Dos mocosos peludos que intentan parecer maduros.",
  str_homestory_801601001_27_dialog_content = "Cada vez que ven a Franz, gritan: \"¡Guau! ¡Un perrito de verdad!\".",
  str_homestory_801601001_28_dialog_content = "A Franz también parece gustarles y sigue corriendo tras ellos.",
  str_homestory_801601001_29_dialog_content = "Eso suena raro...",
  str_homestory_801601001_30_dialog_content = "No sé por qué, pero tengo muchas ganas de verlo por mí mismo...",
  str_homestory_801601001_31_dialog_content = "Con todo, Franz está viviendo una buena vida aquí.",
  str_homestory_801601001_32_dialog_content = "Sin embargo... ¿has estado pasando mucho tiempo con Franz últimamente?",
  str_homestory_801601001_33_dialog_content = "¿Mmm? No puedo recordar eso.",
  str_homestory_801601001_34_dialog_content = "¡Pero puedo olerte en Franz!",
  str_homestory_801601001_35_dialog_content = "Podría haberse colado en tu habitación.",
  str_homestory_801601001_36_dialog_content = "Hmm... No es del todo imposible.",
  str_homestory_801601001_37_dialog_content = "Espera...",
  str_homestory_801601001_38_dialog_content = "¿Qué fué lo que me dijiste?",
  str_homestory_801601001_39_dialog_content = "Franz no moja tu cama<sprite=emo_hanshui size=60 /> ¿tan amenudo?",
  str_homestory_801601001_40_dialog_content = "Err... No me digas...",
  str_homestory_801601001_41_dialog_content = "... ¡Con razón mis sábanas han estado húmedas recientemente!",
  str_homestory_801601001_42_dialog_content = "Eso explica mucho...",
  str_homestory_801601001_43_dialog_content = "Supongo que le gustas mucho a Franz.",
  str_homestory_801601001_44_dialog_content = "... ¿Debería sentirme feliz en este momento?",
  str_homestory_801601001_45_dialog_content = "¿Estás buscando mi consejo?",
  str_homestory_801601001_46_dialog_content = "Bueno... Si yo fuera tú, iría corriendo a casa a lavar las sábanas ahora mismo.",
  str_homestory_804501001_0_dialog_content = "¿Qué es ese sonido?",
  str_homestory_804501001_1_dialog_content = "Nails?",
  str_homestory_804501001_2_dialog_content = "Cállate... Por favor, espera...",
  str_homestory_804501001_3_dialog_content = "¡Ay! Tu rostro es brillante y limpio como un plato de porcelana, reflejando mi sucio cuerpo...",
  str_homestory_804501001_4_dialog_content = "Tus ojos son profundos como el cielo nocturno, perforando la parte insoportable de mi corazón...",
  str_homestory_804501001_5_dialog_content = "Por favor perdóname por mi pecado...",
  str_homestory_804501001_6_dialog_content = "¿O perdonarme sería tu desgracia?",
  str_homestory_804501001_7_dialog_content = "...",
  str_homestory_804501001_8_dialog_content = "Perdón por la espera, PlayerName!",
  str_homestory_804501001_9_dialog_content = "¿Te molesté?",
  str_homestory_804501001_10_dialog_content = "¡Mis más sinceras disculpas! Mi voz es intolerable a cualquier oído, llena de pecados...",
  str_homestory_804501001_11_dialog_content = "Por favor, no seas tan duro contigo mismo. ¡No estoy molesto en absoluto!",
  str_homestory_804501001_12_dialog_content = "Pero tengo mucha curiosidad... ¿Con quién estabas hablando?",
  str_homestory_804501001_13_dialog_content = "Debe haber algún malentendido... No había nadie. Estaba confesando mis pecados.",
  str_homestory_804501001_14_dialog_content = "¡Todo es gracias a ti!",
  str_homestory_804501001_15_dialog_content = "Gracias por proporcionar este lugar perfecto para mi confesión.",
  str_homestory_804501001_16_dialog_content = "Finalmente, puedo confesarme sin molestar a Lady. Victoria.",
  str_homestory_804501001_17_option_content = "Negar",
  str_homestory_804501001_18_dialog_content = "No recuerdo haber construido un lugar para la confesión...",
  str_homestory_804501001_19_dialog_content = "Muy humilde. Estoy seguro de que esta magnífica fuente te tomó mucho tiempo y esfuerzo.",
  str_homestory_804501001_20_dialog_content = "Pero esta es la Fuente de la Esperanza.",
  str_homestory_804501001_21_option_content = "Admitir",
  str_homestory_804501001_22_dialog_content = "Eres bienvenido. Me alegra que te guste...",
  str_homestory_804501001_23_dialog_content = "Espera... ¿Dijiste confesión?",
  str_homestory_804501001_24_dialog_content = "No estarás hablando de esta Fuente de Esperanza, ¿verdad?",
  str_homestory_804501001_25_dialog_content = "La Fuente de la Esperanza. ¡Qué gentil nombre!",
  str_homestory_804501001_26_dialog_content = "Vi gente aquí juntando las palmas de las manos con devoción y confesándose. ¡Ahora sé su nombre!",
  str_homestory_804501001_27_dialog_content = "Soy culpable. Debo confesar...",
  str_homestory_804501001_28_dialog_content = "Supongo que esa es una forma de verlo... Creo que la gente está aquí orando.",
  str_homestory_804501001_29_dialog_content = "También debo confesar en nombre de PlayerName...",
  str_homestory_804501001_30_dialog_content = "¡¿Eh?!",
  str_homestory_804501001_31_dialog_content = "Una confesión nunca debe ser interrumpida...",
  str_homestory_804501001_32_dialog_content = "PlayerName, por favor perdóname por no explicar esto antes.",
  str_homestory_804501001_33_dialog_content = "Oh Verdad que moras en la Fuente de la Esperanza...",
  str_homestory_804501001_34_dialog_content = "Por favor perdona Nails por molestarte una vez más!",
  str_homestory_804501001_35_dialog_content = "Soy culpable. Estoy aquí para confesarte. por favor castigame...",
  str_homestory_804501001_36_option_content = "Castigar",
  str_homestory_804501001_37_dialog_content = "¡Dios mio! ¡Sentí la respuesta de la Fuente de la Esperanza!",
  str_homestory_804501001_38_dialog_content = "¿Respuesta? ¡La verdad finalmente está aquí!",
  str_homestory_804501001_39_dialog_content = "Ejem, la Fuente de la Esperanza declaró...",
  str_homestory_804501001_40_option_content = "Comodidad",
  str_homestory_804501001_41_dialog_content = "Nails, Realmente no creo que necesites confesar tales asuntos.",
  str_homestory_804501001_42_dialog_content = "En lugar de confesarte aquí, ¿por qué no hacer planes para el futuro?",
  str_homestory_804501001_43_dialog_content = "!",
  str_homestory_804501001_44_dialog_content = "¿Cómo no pude pensar en esto hasta ahora?",
  str_homestory_804501001_45_dialog_content = "Lo sabía... Soy un hombre pecador...",
  str_homestory_804501001_46_dialog_content = "Err...",
  str_homestory_808601001_0_dialog_content = "Esta familiar flor blanca...",
  str_homestory_808601001_1_dialog_content = "Navegador PlayerName.",
  str_homestory_808601001_2_dialog_content = "No esperaba que Eraveil fuera tan hermosa.",
  str_homestory_808601001_3_dialog_content = "Esta pradera sin fin... No la encontrarás en Lumopolis.",
  str_homestory_808601001_4_dialog_content = "Incluso estas flores blancas<sprite=emo_huaduo size=60 /> como Eraveil...",
  str_homestory_808601001_5_dialog_content = "Sí. Estoy igual de asombrado.",
  str_homestory_808601001_6_dialog_content = "¿Mmm? ¿No eres uno de ellos en Eraveil?",
  str_homestory_808601001_7_dialog_content = "Ah bien...",
  str_homestory_808601001_8_dialog_content = "Ahora lo recuerdo... Te obligaron a dejar Eraveil a una edad temprana.",
  str_homestory_808601001_9_dialog_content = "Eso es correcto. Aprendí sobre Eraveil de Soroz...",
  str_homestory_808601001_10_dialog_content = "Pero me sorprendió su belleza cuando llegué por primera vez a Eraveil.<sprite=emo_pugongying size=60 />",
  str_homestory_808601001_11_dialog_content = "Y este asombro no se desvanece con el tiempo.",
  str_homestory_808601001_12_dialog_content = "Esta es probablemente la sensación de estar en casa. Sé que Eraveil está conectado conmigo.",
  str_homestory_808601001_13_dialog_content = "Sí... Todo aquí está lleno de inteligencia espiritual. La arquitectura de Caelestite convive perfectamente con la naturaleza.",
  str_homestory_808601001_14_dialog_content = "A menudo trato con el pasado. Puedo sentirlo...",
  str_homestory_808601001_15_dialog_content = "Este lugar tiene la belleza de la fuente de la vida.",
  str_homestory_808601001_16_dialog_content = "Cualquier cosa viva y cualquiera que cante las alabanzas de la vida se enamorará de Eraveil.",
  str_homestory_808601001_17_dialog_content = "La casa de PlayerName es realmente hermosa.",
  str_homestory_808601001_18_dialog_content = "Me alegro mucho de que hayas elegido establecerte aquí.",
  str_homestory_808601001_19_dialog_content = "Gracias, Uriah.",
  str_homestory_808601001_20_dialog_content = "Estoy encantado con tu alta valoración de Eraveil.",
  str_homestory_808601001_21_option_content = "Pide un favor",
  str_homestory_808601001_22_dialog_content = "En realidad... tengo un favor que pedirle a la señorita Uriah.",
  str_homestory_808601001_23_dialog_content = "Jejeje... PlayerName, no seas un extraño.",
  str_homestory_808601001_24_dialog_content = "Se siente bastante serio pero un poco ambiguo...",
  str_homestory_808601001_25_dialog_content = "¿Es más que una cita? ¿Estás proponiendo?",
  str_homestory_808601001_26_dialog_content = "¿Perdóname?",
  str_homestory_808601001_27_dialog_content = "¡Eso no!",
  str_homestory_808601001_28_dialog_content = "Jejeje... ¡Adorable!",
  str_homestory_808601001_29_dialog_content = "¡Por favor, no te burles de mí!",
  str_homestory_808601001_30_option_content = "Extiende tu bienvenida",
  str_homestory_808601001_31_dialog_content = "Eres bienvenida a Eraveil cuando quieras, señorita. Uriah. Espero verte más a menudo.",
  str_homestory_808601001_32_dialog_content = "Claro.",
  str_homestory_808601001_33_dialog_content = "El hermoso paisaje aquí es fascinante. Además, esta es tu casa.",
  str_homestory_808601001_34_dialog_content = "PlayerName, espero con ansias su brillante futuro bajo su liderazgo.",
  str_homestory_808601001_35_dialog_content = "Gracias... Uriah, eres una monja encargada de la oración por los difuntos para que descansen en paz, ¿no?",
  str_homestory_808601001_36_dialog_content = "Sí, esa es mi responsabilidad en Lumopolis.",
  str_homestory_808601001_37_dialog_content = "... Creo que sé lo que necesitas.",
  str_homestory_808601001_38_dialog_content = "Sí. Quiero orar por los miembros de mi clan fallecidos para que puedan descansar tranquilos.",
  str_homestory_808601001_39_dialog_content = "Lo supuse...",
  str_homestory_808601001_40_dialog_content = "Estoy impresionado por lo maduro que te has vuelto. Ahora eres capaz de aceptar tanto la vida como la muerte.",
  str_homestory_808601001_41_dialog_content = "Yo, oración fúnebre, Uriah la monja, rezará por los espíritus de Eraveil.",
  str_homestory_808601001_42_dialog_content = "¡Que sus almas descancen en paz! Alfombra de flores blancas de mayo Eraveil.",
  str_homestory_808601001_43_dialog_content = "Gracias.",
  str_homestory_810201001_0_dialog_content = "Esta corriente eléctrica...",
  str_homestory_810201001_1_dialog_content = "Tessa?",
  str_homestory_810201001_2_dialog_content = "Si estás cansado, descansa un poco en los dormitorios de Cloud Gardens.",
  str_homestory_810201001_3_dialog_content = "*Bostezo*<sprite=emo_kun size=60 />",
  str_homestory_810201001_4_dialog_content = "¿Que qué? ¡Eh, tú!",
  str_homestory_810201001_5_dialog_content = "¿Qué dijiste?",
  str_homestory_810201001_6_dialog_content = "Suspiro... ¿Tengo que sacar esta piruleta para que lo entiendas?",
  str_homestory_810201001_7_dialog_content = "Hmm... No quiero que te resfríes durmiendo afuera.",
  str_homestory_810201001_8_dialog_content = "¿Es una regla aquí dormir adentro?",
  str_homestory_810201001_9_dialog_content = "No es obligatorio...",
  str_homestory_810201001_10_dialog_content = "Realmente no me importa incluso si lo es.",
  str_homestory_810201001_11_dialog_content = "Duermo donde quiero.",
  str_homestory_810201001_12_option_content = "Aceptar",
  str_homestory_810201001_13_dialog_content = "¡Por supuesto!",
  str_homestory_810201001_14_dialog_content = "Estoy celoso de tu estilo de vida.",
  str_homestory_810201001_15_dialog_content = "Solo necesito un poco de paz. No hay nada de qué estar celoso.",
  str_homestory_810201001_16_option_content = "incapaz de estar de acuerdo",
  str_homestory_810201001_17_dialog_content = "entiendo donde Tessa es de pero...",
  str_homestory_810201001_18_dialog_content = "Solo necesito un poco de paz. No se necesita comprensión.",
  str_homestory_810201001_19_dialog_content = "Multa...",
  str_homestory_810201001_20_dialog_content = "Hay sombrillas y carpas en la tienda. Avísame cuando necesites uno.",
  str_homestory_810201001_21_dialog_content = "Soy bastante bueno en la sombra.",
  str_homestory_810201001_22_dialog_content = "Por cierto, ¿esta tienda vende piruletas?",
  str_homestory_810201001_23_dialog_content = "me estoy quedando sin",
  str_homestory_810201001_24_dialog_content = "Lo hacemos, pero...",
  str_homestory_810201001_25_dialog_content = "¿Has estado dentro de un dormitorio de Cloud Gardens?",
  str_homestory_810201001_26_dialog_content = "Como dije, no estoy interesado en quedarme adentro.",
  str_homestory_810201001_27_dialog_content = "¿Qué tiene esto que ver con las piruletas?",
  str_homestory_810201001_28_dialog_content = "dar la bienvenida Tessa...",
  str_homestory_810201001_29_dialog_content = "He preparado muchas piruletas en el dormitorio...",
  str_homestory_810201001_30_dialog_content = "¿Piruletas?",
  str_homestory_810201001_31_dialog_content = "Acabo de verificar. No queda nada.",
  str_homestory_810201001_32_dialog_content = "Pensé que era Tessa... Supongo que alguien lo consiguió antes que tú.",
  str_homestory_810201001_33_dialog_content = "¿En serio? ¿Por qué no me dijiste antes?",
  str_homestory_810201001_34_dialog_content = "Pensé que todos irían primero a los dormitorios de Cloud Gardens a descansar...",
  str_homestory_810201001_35_dialog_content = "¡Hmph! Lo que sea.",
  str_homestory_810201001_36_dialog_content = "Compraré algunos más.",
  str_homestory_810201001_37_dialog_content = "(Tessaes sorprendentemente razonable...)",
  str_homestory_810201001_38_dialog_content = "¿Hay algún trabajo remunerado disponible aquí?",
  str_homestory_810201001_39_dialog_content = "¿Mmm? Pensé que estabas en un descanso... ¿Cómo es que estás buscando trabajo ahora?",
  str_homestory_810201001_40_dialog_content = "Quería ir de compras pero no me queda dinero.",
  str_homestory_810201001_41_dialog_content = "Tendré que comprar a crédito si no hay nada disponible.",
  str_homestory_810201001_42_dialog_content = "...",
  str_homestory_810201001_43_dialog_content = "¿Podría inspeccionar el circuito eléctrico de los dormitorios de Cloud Gardens?",
  str_homestory_810201001_44_dialog_content = "¡Estoy en ello!",
  str_homestory_801501001_0_dialog_content = "Esa es la primera...",
  str_homestory_801501001_1_dialog_content = "Nunca te había visto sin Gin antes.",
  str_homestory_801501001_2_dialog_content = "¡Ay! PlayerName, ¿Puede usted olerlo?",
  str_homestory_801501001_3_dialog_content = "La fragancia de Nightium<sprite=emo_baiyebi size=60 />! ¡Está en todas partes!",
  str_homestory_801501001_4_option_content = "Expresa tus dudas",
  str_homestory_801501001_5_dialog_content = "¿Cómo es que no puedo olerlo?",
  str_homestory_801501001_6_dialog_content = "¿Cuál es la fragancia de Nightium de todos modos?",
  str_homestory_801501001_7_dialog_content = "PlayerName, esto es un arte de hablar. La cuestión es...",
  str_homestory_801501001_8_dialog_content = "Tengo algunos proyectos para discutir contigo. ¡Cualquiera de estos vale más de 9 dígitos!",
  str_homestory_801501001_9_dialog_content = "9 dígitos?",
  str_homestory_801501001_10_option_content = "Pregunta por el olor",
  str_homestory_801501001_11_dialog_content = "¿Cómo huele Nightium?",
  str_homestory_801501001_12_dialog_content = "30% dulzura oxidada mezclada con 40% sudor salado...",
  str_homestory_801501001_13_dialog_content = "Más el 50%... *Olfatea*",
  str_homestory_801501001_14_dialog_content = "¡Fragancia 50% pura de árboles frutales!",
  str_homestory_801501001_15_dialog_content = "Eso es 120%.",
  str_homestory_801501001_16_dialog_content = "Tanto como mi sinceridad para hacer negocios con PlayerName.",
  str_homestory_801501001_17_dialog_content = "Para ser claro. Es 120% no 12%.",
  str_homestory_801501001_18_dialog_content = "¿Qué tienes esta vez?",
  str_homestory_801501001_19_dialog_content = "Escuchar. Mis dibujos no están a la venta. Y no puedes pedir prestado para hacer una copia...",
  str_homestory_801501001_20_dialog_content = "PlayerName, adopte una perspectiva más amplia.",
  str_homestory_801501001_21_dialog_content = "Ahora tienes una sala de exposiciones natural. No te apegues demasiado a unos pocos dibujos.",
  str_homestory_801501001_22_dialog_content = "¿Sala de exhibición?",
  str_homestory_801501001_23_dialog_content = "Un ejemplo perfecto de combinar un espacio natural abierto con la ecología cultural.",
  str_homestory_801501001_24_dialog_content = "Esta es una excelente Sala de Exposiciones natural.",
  str_homestory_801501001_25_dialog_content = "PlayerName, nos encanta<sprite=emo_aixin size=60 /> este lugar tanto.",
  str_homestory_801501001_26_dialog_content = "¡Acabo de tomar una decisión difícil!",
  str_homestory_801501001_27_dialog_content = "Yo decido...",
  str_homestory_801501001_28_dialog_content = "¡Me convertiré en planificador de exposiciones!",
  str_homestory_801501001_29_dialog_content = "¿Qué hace exactamente un planificador de exposiciones?",
  str_homestory_801501001_30_dialog_content = "Tos... En fin, me encargo de evaluar, estudiar, conservar y exhibir todo tipo de obras de arte...",
  str_homestory_801501001_31_dialog_content = "Seré un gerente profesional que planifica y organiza exhibiciones de arte en lugares específicos.",
  str_homestory_801501001_32_dialog_content = "Estoy perdido, pero suena legítimo.",
  str_homestory_801501001_33_dialog_content = "¿Entonces estas de acuerdo?",
  str_homestory_801501001_34_dialog_content = "No necesitas mi permiso para cambiar de carrera.",
  str_homestory_801501001_35_dialog_content = "Mientras no destruyas nuestro medio ambiente... He trabajado duro para construir esto.",
  str_homestory_801501001_36_dialog_content = "Entendido.",
  str_homestory_801501001_37_dialog_content = "PlayerName no quiere que cambie la arquitectura y las plantas aquí.",
  str_homestory_801501001_38_dialog_content = "Eso es correcto.",
  str_homestory_801501001_39_dialog_content = "PlayerName no quiere que diseñe u organice exposiciones y festivales artísticos.",
  str_homestory_801501001_40_dialog_content = "Correcto.",
  str_homestory_801501001_41_dialog_content = "PlayerName tampoco quiere que mis exhibiciones y festivales de arte atraigan turistas.",
  str_homestory_801501001_42_dialog_content = "Si...",
  str_homestory_801501001_43_dialog_content = "Tampoco es PlayerName interesado en los importantes ingresos resultantes.",
  str_homestory_801501001_44_dialog_content = "Hmm...",
  str_homestory_801501001_45_dialog_content = "PlayerName no tiene ningún deseo de mejorar su terrible situación financiera.",
  str_homestory_801501001_46_dialog_content = "Ejem... Espera un minuto.",
  str_homestory_801501001_47_dialog_content = "Necesito pensar más en esto.",
  str_homestory_801501001_48_dialog_content = "jajaja PlayerName ¡Finalmente olía la fragancia de Nightium!",
  str_homestory_815401001_0_dialog_content = "¿De nuevo?",
  str_homestory_815401001_1_dialog_content = "Vice, has estado pasando mucho tiempo en el museo últimamente.",
  str_homestory_815401001_2_dialog_content = "¿Hay alguna manera de ganar dinero allí?",
  str_homestory_815401001_3_dialog_content = "Pobre de mí...",
  str_homestory_815401001_4_dialog_content = "Nuestra posición financiera no es buena, pero pensé que habíamos llegado a un acuerdo.",
  str_homestory_815401001_5_dialog_content = "Este museo es un sitio de servicio público dedicado a mostrar la historia de Eraveil y la tecnología de Caelestites.",
  str_homestory_815401001_6_dialog_content = "Entrada gratuita y sin ánimo de lucro...",
  str_homestory_815401001_7_option_content = "Disculparse",
  str_homestory_815401001_8_dialog_content = "Lo siento, Vice.",
  str_homestory_815401001_9_dialog_content = "Lo he estado pensando estos días. Supongo que ahora estoy obsesionado.",
  str_homestory_815401001_10_dialog_content = "Jajajaja ¡Está bien! Yo mismo estuve allí una vez.",
  str_homestory_815401001_11_dialog_content = "¡Creo que necesitas un descanso!",
  str_homestory_815401001_12_dialog_content = "Vice, díselo a ti mismo.",
  str_homestory_815401001_13_dialog_content = "Casi te has mudado al museo estos días. Te ves ansioso y preocupado...",
  str_homestory_815401001_14_dialog_content = "¿Hace cuánto que no descansas bien?",
  str_homestory_815401001_15_option_content = "Inquietud",
  str_homestory_815401001_16_dialog_content = "No te preocupes. ¡Nunca cambiaré mi posición en esto!",
  str_homestory_815401001_17_dialog_content = "Como último Caelestita, no puedo permitir que nuestra civilización termine en mis manos.",
  str_homestory_815401001_18_dialog_content = "Pero...",
  str_homestory_815401001_19_dialog_content = "¿Qué haces tan pensativo en el museo?",
  str_homestory_815401001_20_dialog_content = "Ay... no puedo esconder nada de PlayerName.<sprite=emo_wuzui size=60 />",
  str_homestory_815401001_21_dialog_content = "Recientemente, he estado investigando los elementos que se exhiben en el museo.",
  str_homestory_815401001_22_dialog_content = "¿Investigar? ¿Una nueva misión asignada por Illumina?",
  str_homestory_815401001_23_dialog_content = "No, es para mí.",
  str_homestory_815401001_24_dialog_content = "Tal vez no debería llamarlo una investigación.",
  str_homestory_815401001_25_dialog_content = "Estoy buscando inspiración.",
  str_homestory_815401001_26_dialog_content = "Ya sabes... Después de lo que le pasó a mi cuerpo...",
  str_homestory_815401001_27_dialog_content = "He recordado muchos fragmentos de memoria.",
  str_homestory_815401001_28_dialog_content = "Pero está completamente en blanco cuando se trata de mi origen...",
  str_homestory_815401001_29_dialog_content = "Entonces... ¿Estás buscando contactos con tus antecedentes?",
  str_homestory_815401001_30_dialog_content = "Jejeje. Extraño, ¿verdad?",
  str_homestory_815401001_31_dialog_content = "Lo sé. ¿Cómo podría encontrar algo en un museo Caelestite?",
  str_homestory_815401001_32_dialog_content = "Nunca sabes.",
  str_homestory_815401001_33_dialog_content = "El mundo es grande pero las coincidencias ocurren todos los días.",
  str_homestory_815401001_34_dialog_content = "Jajajaja. Eres mucho más optimista ahora.",
  str_homestory_815401001_35_dialog_content = "¿Hacemos otro recorrido por el museo?",
  str_homestory_815401001_36_dialog_content = "¿Podríamos encontrar algo esta vez, como una carta familiar o algo así?",
  str_homestory_815401001_37_dialog_content = "¡Seguro!",
  str_homestory_815401001_38_dialog_content = "Pero y si soy tu hermana mayor...<sprite=emo_sikao size=60 />",
  str_homestory_815401001_39_dialog_content = "¿Qué harías?",
  str_homestory_815401001_40_dialog_content = "¿Mi hermana mayor? ¡De ninguna manera!",
  str_homestory_815401001_41_dialog_content = "¡Aunque es posible que sea tu hermano mayor!",
  str_homestory_815401001_42_dialog_content = "PlayerName.",
  str_homestory_815401001_43_dialog_content = "Hmm... Realmente no puedo ver eso.",
  str_homestory_815401001_44_dialog_content = "Ejem... ¡Espero que este no sea el caso!",
  str_homestory_805702001_0_dialog_content = "¿Esta lloviendo?",
  str_homestory_805702001_1_dialog_content = "Miau...",
  str_homestory_805702001_2_dialog_content = "Está lloviendo, Philyshy. Deberíamos salir de la lluvia.",
  str_homestory_805702001_3_dialog_content = "No, en realidad fui yo sacudiéndome el agua.",
  str_homestory_805702001_4_dialog_content = "Lo siento por ponerlo en ti, PlayerName...",
  str_homestory_805702001_5_dialog_content = "Ya veo. No es de extrañar que estuvieras sacudiendo la cabeza en todas direcciones...",
  str_homestory_805702001_6_dialog_content = "Deja de burlarte de mi, PlayerName...",
  str_homestory_805702001_7_dialog_content = "Pero si no llovió, ¿cómo te mojaste?",
  str_homestory_805702001_8_dialog_content = "Miau... ¡Le echo la culpa al brillante pescado seco del río!<sprite=emo_shengqi size=60 />",
  str_homestory_805702001_9_option_content = "¿Brillante?",
  str_homestory_805702001_10_dialog_content = "¿Cómo es eso posible?",
  str_homestory_805702001_11_dialog_content = "Yo también quiero saber. Por eso traté de atraparlo, miau.",
  str_homestory_805702001_12_option_content = "¿Pescado seco brillante?",
  str_homestory_805702001_13_dialog_content = "Espera, ¿cómo puede haber pescado seco en el río?",
  str_homestory_805702001_14_dialog_content = "¡Será después de que lo atrape y lo seque al sol!",
  str_homestory_805702001_15_dialog_content = "Por más que lo intenté, no pude atraparlo y caí al río.",
  str_homestory_805702001_16_dialog_content = "¡Achu! El río está muy frío, miau...",
  str_homestory_805702001_17_dialog_content = "Deberías volver a la casa y calentarte antes de que te resfríes.",
  str_homestory_805702001_18_dialog_content = "Pero...",
  str_homestory_805702001_19_dialog_content = "Oye, ya que eres el dueño aquí, PlayerName...",
  str_homestory_805702001_20_dialog_content = "¡Atrapa ese pescado seco brillante para mí!",
  str_homestory_805702001_21_dialog_content = "¿Eh?",
  str_homestory_805702001_22_dialog_content = "Y recuerda... Sécalo al sol... Zzz...<sprite=emo_kun size=60 />",
  str_homestory_805702001_23_dialog_content = "Te vas a resfriar durmiendo aquí... Philyshy?",
  str_homestory_805702001_24_dialog_content = "Zzz... Zzz... <sprite=emo_kun size=60 />Pescado seco...",
  str_homestory_814101001_0_dialog_content = "Que interesante...",
  str_homestory_814101001_1_dialog_content = "Hola, PlayerName, ¿explorando también?",
  str_homestory_814101001_2_option_content = "Lo eres.",
  str_homestory_814101001_3_dialog_content = "Hay muchos lugares para explorar en mis jardines de nubes seleccionados.",
  str_homestory_814101001_4_option_content = "No.",
  str_homestory_814101001_5_dialog_content = "Sólo estoy tomando un poco de aire fresco.",
  str_homestory_814101001_6_dialog_content = "Con un esfuerzo, Cloud Gardens se convierte en lo que es hoy, así que me gustaría pasar el rato aquí cuando pueda.",
  str_homestory_814101001_7_dialog_content = "¡Estás absolutamente en lo correcto!",
  str_homestory_814101001_8_dialog_content = "Esta isla que construiste es tan emocionante. ¡Me encanta!",
  str_homestory_814101001_9_dialog_content = "Estaba hurgando en ese río hace un rato.",
  str_homestory_814101001_10_dialog_content = "¿Sí? ¿Encontraste algo emocionante?",
  str_homestory_814101001_11_dialog_content = "¡Je, sabía que me preguntarías eso!",
  str_homestory_814101001_12_dialog_content = "¡Tan pronto como vi el río, salté dentro!",
  str_homestory_814101001_13_dialog_content = "Aparté las cañas y encontré una moneda que nunca antes había visto en el fondo<sprite=emo_baiyebi size=60 />...",
  str_homestory_814101001_14_dialog_content = "Luego atrapé un gran pez Betta...",
  str_homestory_814101001_15_dialog_content = "¡Unos golpes después, vi una extraña reliquia!",
  str_homestory_814101001_16_dialog_content = "Así que simplemente lo agarré y lo llevé a la orilla. Adivina que es.",
  str_homestory_814101001_17_dialog_content = "¿Q-qué es?",
  str_homestory_814101001_18_dialog_content = "¡Un viejo zapato andrajoso lleno de juncos!",
  str_homestory_814101001_19_dialog_content = "Intenté vendérselo a la tienda, ¡pero ni siquiera consiguió un Nightium! ¡Muy divertido!",
  str_homestory_814101001_20_dialog_content = "¿Qué pasa con el pez y la moneda?",
  str_homestory_814101001_21_dialog_content = "Oh sí... Sé que los puse en mi bolsillo...",
  str_homestory_814101001_22_dialog_content = "Hmm, probablemente se cayeron cuando alcancé el zapato.",
  str_homestory_814101001_23_dialog_content = "¡Podemos ir a buscarlo si estás interesado!",
  str_homestory_814101001_24_dialog_content = "Aunque el pez ya se ha ido nadando, seguro.",
  str_homestory_814101001_25_dialog_content = "Ruby, un eterno optimista.",
  str_homestory_814101001_26_dialog_content = "¡Oh, no se lo digas a Blossom!",
  str_homestory_814101001_27_dialog_content = "¡O me obligará a tragar un medicamento amargo para la fiebre!",
  str_homestory_801001001_0_dialog_content = "¿Aún dormida?",
  str_homestory_801001001_1_dialog_content = "Estás bien, Louise? Te ves cansado.",
  str_homestory_801001001_2_dialog_content = "Oh, eres tú, PlayerName.",
  str_homestory_801001001_3_dialog_content = "Pensé que mi espera finalmente había terminado...",
  str_homestory_801001001_4_dialog_content = "¿Estas esperando a alguien?",
  str_homestory_801001001_5_dialog_content = "Estoy esperando a las hadas en el río.",
  str_homestory_801001001_6_dialog_content = "Fae?",
  str_homestory_801001001_7_dialog_content = "¿No has oído hablar de ese cuento de hadas muy famoso, PlayerName?",
  str_homestory_801001001_8_dialog_content = "En un río remoto vivía un hada muy hermosa.",
  str_homestory_801001001_9_dialog_content = "Las hadas saldrían volando cuando alguien accidentalmente dejara caer algo en el agua.",
  str_homestory_801001001_10_dialog_content = "¡Aquellos que respondieron honestamente a la pregunta de las hadas serían recompensados!",
  str_homestory_801001001_11_option_content = "Río...",
  str_homestory_801001001_12_dialog_content = "¿Crees que hay un hada en este río? Louise?",
  str_homestory_801001001_13_dialog_content = "Uh, ¿no todos los ríos tienen un hada?",
  str_homestory_801001001_14_dialog_content = "En el río de Northland vivía un hada de Northland, así que en el río de Eraveil viviría un hada de Eraveil...",
  str_homestory_801001001_15_option_content = "Cuento de hadas, dijiste...",
  str_homestory_801001001_16_dialog_content = "Sabes, creo que he escuchado algo similar.",
  str_homestory_801001001_17_dialog_content = "Alguien perdió un hacha de acero pero se volvió codicioso y afirmó que era un hacha de oro.",
  str_homestory_801001001_18_dialog_content = "Pero el punto aquí es...",
  str_homestory_801001001_19_dialog_content = "¿Perdiste algo en el río?",
  str_homestory_801001001_20_dialog_content = "¡Sí! Pero no es mío.",
  str_homestory_801001001_21_dialog_content = "Es una moneda que recogí en el banco con patrones muy intrincados.",
  str_homestory_801001001_22_dialog_content = "Pero se había metido en el agua antes de que pudiera verlo bien.",
  str_homestory_801001001_23_dialog_content = "Esperé tanto tiempo pero todavía no hay fae.",
  str_homestory_801001001_24_dialog_content = "Supongo que tu río no tiene hadas, PlayerName...<sprite=emo_sikao size=60 />",
  str_homestory_801001001_25_dialog_content = "Déjame ver si puedo sacarlo.",
  str_homestory_801001001_26_dialog_content = "Así que eres el fae, PlayerName?!",
  str_homestory_804102001_0_dialog_content = "no puedes hablar en serio...",
  str_homestory_804102001_1_dialog_content = "Hola, Sra. Blanc.",
  str_homestory_804102001_2_dialog_content = "Hola, cariño PlayerName.",
  str_homestory_804102001_3_dialog_content = "¿Sigues inspeccionando las carreteras y los edificios en Cloud Gardens?",
  str_homestory_804102001_4_dialog_content = "Me alegra que aún recuerdes mis rutinas.",
  str_homestory_804102001_5_option_content = "Creo que es muy profesional.",
  str_homestory_804102001_6_dialog_content = "Pero...",
  str_homestory_804102001_7_option_content = "¡Disculpas!",
  str_homestory_804102001_8_dialog_content = "¿Por qué dices eso?",
  str_homestory_804102001_9_dialog_content = "He estado expandiendo Cloud Gardens, agregando estructuras y caminos.",
  str_homestory_804102001_10_dialog_content = "Eso no facilitará su trabajo, ¿verdad?",
  str_homestory_804102001_11_dialog_content = "Nunca subestimes las habilidades de una mujer profesional, PlayerName.",
  str_homestory_804102001_12_dialog_content = "Mientras consiga las coordenadas y ubicaciones de los principales edificios y carreteras en mi cabeza...",
  str_homestory_804102001_13_dialog_content = "No tendré problema en memorizar más.",
  str_homestory_804102001_14_dialog_content = "¡Qué recuerdo tan increíble!",
  str_homestory_804102001_15_dialog_content = "Pero te vi frunciendo el ceño. ¿Hay algún problema?",
  str_homestory_804102001_16_dialog_content = "Uy, ya viste eso, PlayerName?",
  str_homestory_804102001_17_dialog_content = "Bueno, algo me está molestando. Supongo que está bien decírtelo.",
  str_homestory_804102001_18_dialog_content = "Estaba escribiendo la guía de Cloud Gardens...",
  str_homestory_804102001_19_dialog_content = "Cuando llegué al río aquí.",
  str_homestory_804102001_20_dialog_content = "Encima de una variedad de peces, hay algo brillante.",
  str_homestory_804102001_21_dialog_content = "Para garantizar la precisión de la descripción, me gustaría mucho saber qué es eso...",
  str_homestory_804102001_22_dialog_content = "Objeto brillante, dijiste...",
  str_homestory_804102001_23_dialog_content = "Ya que eres el propietario de Cloud Gardens, ¿te importaría investigarlo?",
  str_homestory_804102001_24_dialog_content = "¡Claro, no hay problema!",
  str_homestory_801502001_0_dialog_content = "¿Husmeando de nuevo?",
  str_homestory_801502001_1_dialog_content = "Ejem, ¿qué estás haciendo ahora mismo, Hachi?",
  str_homestory_801502001_2_dialog_content = "Oye, ¿no es nuestro querido PlayerName!<sprite=emo_yaosu size=60 />",
  str_homestory_801502001_3_dialog_content = "Así que, ¿has tomado tu decisión?",
  str_homestory_801502001_4_dialog_content = "¿Qué decisión?",
  str_homestory_801502001_5_dialog_content = "Ah, entiendo. ¡Tienes muchas cosas en tu plato!",
  str_homestory_801502001_6_dialog_content = "Quise decir... remodelar Cloud Gardens en una exhibición natural.",
  str_homestory_801502001_7_option_content = "Está bajo consideración.",
  str_homestory_801502001_8_dialog_content = "Bueno, eh, todavía estoy pensando en eso...",
  str_homestory_801502001_9_option_content = "Olvídalo...",
  str_homestory_801502001_10_dialog_content = "Un objetivo admirable, pero me gusta Cloud Gardens tal como está ahora, limpio y tranquilo.",
  str_homestory_801502001_11_dialog_content = "Oh. Está bien.",
  str_homestory_801502001_12_dialog_content = "Pero deberías reconsiderarlo. ¡Las oportunidades no esperan a nadie!",
  str_homestory_801502001_13_dialog_content = "Hmm...",
  str_homestory_801502001_14_dialog_content = "*Sniff sniff*",
  str_homestory_801502001_15_dialog_content = "¿Qué estás olfateando?",
  str_homestory_801502001_16_dialog_content = "¿No puedes olerlo? Huele a moneda.",
  str_homestory_801502001_17_dialog_content = "nocheio <sprite=emo_baiyebi size=60 />¿otra vez?",
  str_homestory_801502001_18_dialog_content = "¡No, totalmente diferente!",
  str_homestory_801502001_19_dialog_content = "Es completamente nuevo e indescriptiblemente único... *Sniff*",
  str_homestory_801502001_20_dialog_content = "Es más jugoso y húmedo que Nightium, más antiguo también...",
  str_homestory_801502001_21_dialog_content = "Y los patrones son más intrincados.",
  str_homestory_801502001_22_dialog_content = "¿También puedes oler los patrones?",
  str_homestory_801502001_23_dialog_content = "Nunca subestimes la nariz canina.",
  str_homestory_801502001_24_dialog_content = "Ya sea una tendencia comercial o el olor de una moneda, puedo orientarlo en la dirección correcta.",
  str_homestory_801502001_25_dialog_content = "Esta vez, te daré la oportunidad de encontrar la moneda, querida. PlayerName.",
  str_homestory_801502001_26_dialog_content = "¿Eh?",
  str_homestory_801502001_27_dialog_content = "¡Espero que pienses en nuestra colaboración!",
  str_homestory_805602001_0_dialog_content = "Constantine?",
  str_homestory_805602001_1_dialog_content = "Hola, PlayerName.",
  str_homestory_805602001_2_dialog_content = "¿Adónde fuiste esta vez? Constantine?",
  str_homestory_805602001_3_dialog_content = "Acabo de volver de pescar.",
  str_homestory_805602001_4_dialog_content = "Ah, veo que has estado haciendo eso los últimos días.",
  str_homestory_805602001_5_dialog_content = "Eres un profesional, así que probablemente pescaste mucho, ¿verdad?",
  str_homestory_805602001_6_dialog_content = "Ni siquiera uno.",
  str_homestory_805602001_7_dialog_content = "¿Qué? ¡Pero eres un cazador experto!",
  str_homestory_805602001_8_dialog_content = "Puede considerar pescar lo mismo que cazar, pero hay una gran diferencia entre los dos.<sprite=emo_sikao size=60 />",
  str_homestory_805602001_9_dialog_content = "Sometes activamente a la presa cuando cazas.",
  str_homestory_805602001_10_dialog_content = "Mientras que minimizas la iniciativa y haces que acudan a ti cuando pescas.",
  str_homestory_805602001_11_option_content = "Entiendo.",
  str_homestory_805602001_12_dialog_content = "Al pescar, nadie tiene idea de lo que atrapará.",
  str_homestory_805602001_13_dialog_content = "Pero cuando cazan, primero encuentran el objetivo y luego actúan.",
  str_homestory_805602001_14_option_content = "No.",
  str_homestory_805602001_15_dialog_content = "Pero dijiste que cazar requería paciencia. Eso también es necesario para la pesca.",
  str_homestory_805602001_16_dialog_content = "Nadie tiene idea de cuándo picará un pez.",
  str_homestory_805602001_17_dialog_content = "Sí, estás en lo correcto.",
  str_homestory_805602001_18_dialog_content = "Francamente, estaba en contra de las reglas al principio...",
  str_homestory_805602001_19_dialog_content = "Siempre fijaba primero un objetivo y luego intentaba atraparlo, pero eso nunca funcionaba.",
  str_homestory_805602001_20_dialog_content = "Para recordarme la lección aprendida, aplané el anzuelo.",
  str_homestory_805602001_21_dialog_content = "¿Qué? ¿Puedes pescar peces así?",
  str_homestory_805602001_22_dialog_content = "No sé, no me importa. Solo quiero afinar mi paciencia.",
  str_homestory_805602001_23_dialog_content = "¿Continuará?",
  str_homestory_805602001_24_dialog_content = "Me he fijado una fecha límite.",
  str_homestory_805602001_25_dialog_content = "Cuando la moneda junto al banco se empantana en el lodo o se la lleva... o alguien la recoge.",
  str_homestory_805602001_26_dialog_content = "Hasta entonces, me quedo con el anzuelo recto.",
  str_homestory_805602001_27_dialog_content = "(Moneda...?)",
  str_homestory_805602001_28_dialog_content = "(Debería ver si puedo pescar eso).",
  str_homestory_808502001_0_dialog_content = "Vaya, tan rápido...",
  str_homestory_808502001_1_dialog_content = "¿Estás escribiendo un diario, Jane?",
  str_homestory_808502001_2_dialog_content = "Sí, estoy grabando todo lo que veo en Cloud Gardens.",
  str_homestory_808502001_3_dialog_content = "Si no hubiera sabido tu ocupación, habría pensado que estabas dibujando.",
  str_homestory_808502001_4_dialog_content = "Pero estaba dibujando.",
  str_homestory_808502001_5_dialog_content = "Eh...?<sprite=emo_wuzui size=60 />",
  str_homestory_808502001_6_dialog_content = "Necesita más que texto para la descripción. Las ilustraciones también son necesarias.",
  str_homestory_808502001_7_dialog_content = "¿Cuándo son necesarias las ilustraciones?",
  str_homestory_808502001_8_dialog_content = "Es bastante sencillo. Cuando las palabras no son suficientes para describir algo, usas ilustraciones.",
  str_homestory_808502001_9_dialog_content = "Por ejemplo, estaba describiendo todo lo que vi en el río.",
  str_homestory_808502001_10_dialog_content = "Podría usar palabras para describir Redfin Fish, pero los lectores solo imaginarían una imagen vaga en sus mentes.",
  str_homestory_808502001_11_dialog_content = "Pero si realmente dibujo la forma y el color...",
  str_homestory_808502001_12_dialog_content = "Inmediatamente obtendrán el aspecto del pez.",
  str_homestory_808502001_13_dialog_content = "Entonces eso es...",
  str_homestory_808502001_14_dialog_content = "Otro ejemplo, cuando estaba escribiendo sobre \"Una moneda todavía está en el fondo del río\"...",
  str_homestory_808502001_15_dialog_content = "Solo podían imaginar la moneda que usaron antes.",
  str_homestory_808502001_16_dialog_content = "Así que tendría que dibujar los patrones de esa moneda que nadie ha visto antes.",
  str_homestory_808502001_17_dialog_content = "Les permite saber claramente qué tipo de moneda yacía en el fondo del río en Cloud Gardens.",
  str_homestory_808502001_18_dialog_content = "Entonces, ¿dónde está la moneda ahora?",
  str_homestory_808502001_19_dialog_content = "Todavía en el río.",
  str_homestory_808502001_20_dialog_content = "¿Qué? ¿Por qué no lo sacaste?",
  str_homestory_808502001_21_dialog_content = "Solo grabo. Yo no interfiero.",
  str_homestory_808502001_22_dialog_content = "Eso también significa que no evitaré que consigas la moneda tú mismo.",
  str_homestory_808502001_23_dialog_content = "Pero lo registraré como sucede.",
  str_homestory_805502001_0_dialog_content = "¿De mal humor?",
  str_homestory_805502001_1_dialog_content = "Qué sucedió, Pittman? Pareces enojado.",
  str_homestory_805502001_2_dialog_content = "Justo a tiempo, PlayerName. ¡Iba a buscarte!",
  str_homestory_805502001_3_dialog_content = "¿Tiene algo que ver conmigo?",
  str_homestory_805502001_4_dialog_content = "Aún no estoy seguro, pero...",
  str_homestory_805502001_5_dialog_content = "¡Noche Blanca en lo alto! Como juez de Lumopolis, por la presente abro una investigación...",
  str_homestory_805502001_6_dialog_content = "¿Estás acuñando Nightium aquí en Cloud Gardens?",
  str_homestory_805502001_7_option_content = "¡No!",
  str_homestory_805502001_8_dialog_content = "Es cierto que necesito Nightium, ¡pero no estoy tan desesperado!",
  str_homestory_805502001_9_option_content = "Me gustaría.",
  str_homestory_805502001_10_dialog_content = "Pero es caro acuñar Nightium. Necesitaría un montón de dinero para ganar dinero.",
  str_homestory_805502001_11_dialog_content = "¡Sabes que no tengo tanto!",
  str_homestory_805502001_12_dialog_content = "¿Lo juras?",
  str_homestory_805502001_13_dialog_content = "YO, PlayerName, nunca he acuñado Nightium, nunca.",
  str_homestory_805502001_14_dialog_content = "O... ¡puedes hacer conmigo lo que quieras!",
  str_homestory_805502001_15_dialog_content = "Entonces, ¿has notado algún sospechoso o señal relacionada con eso en Cloud Gardens?",
  str_homestory_805502001_16_dialog_content = "¿Especialmente los de Umbraton y el desierto?",
  str_homestory_805502001_17_dialog_content = "Todos son mis amigos, así que realmente no quiero dudar de ellos...",
  str_homestory_805502001_18_dialog_content = "Todos son iguales ante la ley, sin importar quién.",
  str_homestory_805502001_19_dialog_content = "Pero, ¿por qué sospechas de ellos?",
  str_homestory_805502001_20_dialog_content = "Ya que hiciste tu juramento, puedo divulgar mi secreto.",
  str_homestory_805502001_21_dialog_content = "¡Encontré una moneda junto al río que se parecía a Nightium!",
  str_homestory_805502001_22_dialog_content = "¿Te importa si lo veo?",
  str_homestory_805502001_23_dialog_content = "Me enfadé demasiado, perdí el agarre y se cayó al río.",
  str_homestory_805502001_24_dialog_content = "Es solo una suposición... pero creo que probablemente nos perteneció a nosotros, los Caelestites.",
  str_homestory_805502001_25_dialog_content = "Ah... ¿E-en serio?",
  str_homestory_805502001_26_dialog_content = "Bueno, no lo vi bien, después de todo...",
  str_homestory_805502001_27_dialog_content = "Si esa es la verdad, debo disculparme por mi mala educación.",
  str_homestory_805502001_28_dialog_content = "¡Lo siento!",
  str_homestory_805502001_29_dialog_content = "Está bien, tampoco estoy seguro de cuál es exactamente la historia con eso.",
  str_homestory_805502001_30_dialog_content = "Te lo mostraré cuando lo encuentre.",
  str_homestory_805502001_31_dialog_content = "Muchísimas gracias, PlayerName!",
  str_homestory_815701001_0_dialog_content = "Sanae...",
  str_homestory_815701001_1_dialog_content = "¡Ahhhhhhhhhhh! Sr. Navegante...",
  str_homestory_815701001_2_dialog_content = "solo estaba admirando las flores<sprite=emo_huaduo size=60 />!",
  str_homestory_815701001_3_dialog_content = "Definitivamente no me caí cerca y terminé descansando aquí...",
  str_homestory_815701001_4_dialog_content = "¿Caíste? ¿Estás herido?",
  str_homestory_815701001_5_dialog_content = "Estoy acostumbrado... Ah, ¿me delaté?",
  str_homestory_815701001_6_dialog_content = "Sanae... Eres muy fácil de leer.",
  str_homestory_815701001_7_dialog_content = "Por favor, no me despidan por mi torpeza...",
  str_homestory_815701001_8_dialog_content = "Eso no sucederá, pero... ¿qué tenías en mente?",
  str_homestory_815701001_9_dialog_content = "Si tiene alguna idea sobre el desarrollo de Cloud Gardens, ¡hágamelo saber!",
  str_homestory_815701001_10_dialog_content = "Yo no... realmente...",
  str_homestory_815701001_11_dialog_content = "¡No me preguntaba en absoluto por qué decidiste cultivar flores en este lugar preciso!",
  str_homestory_815701001_12_dialog_content = "Bueno, eso no es nada sospechoso...",
  str_homestory_815701001_13_dialog_content = "¿Eh?",
  str_homestory_815701001_14_dialog_content = "Enterrando aquí tu añoranza en forma de flores en memoria de tu amado...",
  str_homestory_815701001_15_dialog_content = "Oh, yo no sabría nada al respecto...",
  str_homestory_815701001_16_option_content = "¿Amado?",
  str_homestory_815701001_17_dialog_content = "¡Sí! Alguien que te conoció por casualidad...",
  str_homestory_815701001_18_dialog_content = "Alguien que rompió todas las restricciones mundanas y vino a tu lado...",
  str_homestory_815701001_19_dialog_content = "Alguien que le ofreció consejos sobre su viaje en Astra...",
  str_homestory_815701001_20_dialog_content = "¡Oh, debe haber sido una chica muy buena!",
  str_homestory_815701001_21_dialog_content = "Las flores de este jardín deben ser sus favoritas, ¿verdad?",
  str_homestory_815701001_22_option_content = "¿Enterrando mi anhelo?",
  str_homestory_815701001_23_dialog_content = "Alguien que dejó todo atrás para venir a ti...",
  str_homestory_815701001_24_dialog_content = "Alguien que miró por encima de tus hombros en el viaje...",
  str_homestory_815701001_25_dialog_content = "Pero ahora es imposible que ustedes dos se reúnan debido a algunas limitaciones mundanas.",
  str_homestory_815701001_26_dialog_content = "Entonces, para mostrar cuánto la extrañas...",
  str_homestory_815701001_27_dialog_content = "¡Plantaste sus flores favoritas en el jardín!",
  str_homestory_815701001_28_dialog_content = "No tengo ni idea de lo que estás hablando ...",
  str_homestory_815701001_29_dialog_content = "Es eso así...<sprite=emo_sikao size=60 />!",
  str_homestory_815701001_30_dialog_content = "Yo debería haber sabido. Esta información no se puede divulgar fácilmente a un extraño como yo...",
  str_homestory_815701001_31_dialog_content = "Si te preguntas por qué hay macizos de flores aquí...",
  str_homestory_815701001_32_dialog_content = "Mi respuesta sería que están ahí como parte del diseño del paisaje.",
  str_homestory_815701001_33_dialog_content = "¿Diseño de exteriores? Que termino mas complicado...",
  str_homestory_815701001_34_dialog_content = "Vice tiene muchos conocimientos sobre dibujo de ingeniería, por lo que me dio muchos consejos cuando diseñamos los jardines de nubes.",
  str_homestory_815701001_35_dialog_content = "Gabriel, Nikinis y Jola saben mucho de plantas...",
  str_homestory_815701001_36_dialog_content = "Les he pedido consejo sobre qué plantas quedan bien en los jardines.",
  str_homestory_815701001_37_dialog_content = "Es un esfuerzo conjunto que Cloud Gardens luzca como es hoy.",
  str_homestory_815701001_38_dialog_content = "Esfuerzo conjunto...",
  str_homestory_815701001_39_dialog_content = "¡Exactamente! Además, no te consideres un \"forastero\", Sanae.",
  str_homestory_815701001_40_dialog_content = "¡Te has convertido en uno de nosotros desde el momento en que llegaste aquí!",
  str_homestory_815701001_41_dialog_content = "Aww... Aww...",
  str_homestory_815701001_42_dialog_content = "Ah, por favor, no llores. No quise culparte...",
  str_homestory_815701001_43_dialog_content = "Eres realmente una buena persona, Sr. Navegante...",
  str_homestory_815701001_44_dialog_content = "Yo también... haré mis contribuciones.",
  str_homestory_815701001_45_dialog_content = "¡Tiene una idea! Déjame cuidar este \"Macizo de Flores del Amor\"<sprite=emo_aixin size=60 />\" ¡de aquí en adelante!",
  str_homestory_815601001_0_dialog_content = "¡No puedo creer lo que veo!",
  str_homestory_815601001_1_dialog_content = "¿Nina acaba de montar un caballito balancín?",
  str_homestory_815601001_2_dialog_content = "¿Un caballito balancín?",
  str_homestory_815601001_3_dialog_content = "Pensé que odiabas esos juguetes.",
  str_homestory_815601001_4_dialog_content = "Yo tampoco dije que me gustara...",
  str_homestory_815601001_5_dialog_content = "Estaba cansado de caminar y necesitaba un lugar para descansar.",
  str_homestory_815601001_6_dialog_content = "Nunca me interesaría algo así.",
  str_homestory_815601001_7_dialog_content = "Buen punto...",
  str_homestory_815601001_8_dialog_content = "¿No se supone que el punto es \"Estaba cansado de caminar y no tenía lugar para descansar\"?",
  str_homestory_815601001_9_option_content = "Disculparse",
  str_homestory_815601001_10_dialog_content = "Oh... ¡Lo siento mucho!",
  str_homestory_815601001_11_dialog_content = "¿Debería poner algunos bancos de piedra más cerca?",
  str_homestory_815601001_12_dialog_content = "¿Banco de piedra? Jajaja, debes estar bromeando, ¿verdad?",
  str_homestory_815601001_13_dialog_content = "Nadie realmente se sentará en algo tan duro, ¿verdad?",
  str_homestory_815601001_14_dialog_content = "Si te gusta...",
  str_homestory_815601001_15_dialog_content = "Atentamente, podemos diseñar algunos asientos para visitantes hermosos y cómodos para usted.",
  str_homestory_815601001_16_dialog_content = "Mientras me digas qué tiene de divertido eso de madera...",
  str_homestory_815601001_17_option_content = "Preguntar por su estado de ánimo",
  str_homestory_815601001_18_dialog_content = "Parece que has estado en muchos lugares hoy, Nina.",
  str_homestory_815601001_19_dialog_content = "Me pregunto si mi lugar le sirve bien, señorita.",
  str_homestory_815601001_20_dialog_content = "Ahora que preguntaste, no me culpes por ser duro.",
  str_homestory_815601001_21_dialog_content = "¡Este lugar está en el medio de la nada!",
  str_homestory_815601001_22_dialog_content = "No puedo discutir con eso...",
  str_homestory_815601001_23_dialog_content = "Pero el paisaje aquí es realmente agradable. Puedo agregarlo a mi lista de deseos de vacaciones.",
  str_homestory_815601001_24_dialog_content = "Debes saber que mis comentarios pueden influir en mucha gente si alguna vez se publican en el periódico Umbraton.",
  str_homestory_815601001_25_dialog_content = "Siempre que... me expliques qué tiene de interesante esa cosa de madera...",
  str_homestory_815601001_26_dialog_content = "Pensé que no te interesaban los caballos mecedores.",
  str_homestory_815601001_27_dialog_content = "... Cambié de opinión.",
  str_homestory_815601001_28_dialog_content = "Saber en qué está cada uno es parte de mi trabajo.",
  str_homestory_815601001_29_dialog_content = "Estos bloques de madera inestables obviamente se tambalearán cuando intentes sentarte sobre ellos.",
  str_homestory_815601001_30_dialog_content = "Entonces, ¿nunca has montado un caballito balancín?",
  str_homestory_815601001_31_dialog_content = "¿Cómo es eso posible?",
  str_homestory_815601001_32_dialog_content = "Pero... toda la experiencia de montar un caballito balancín es esta sensación de balanceo.",
  str_homestory_815601001_33_dialog_content = "Oh, ya veo... ¡No lo malinterpretes! ¡Ya sabia eso!",
  str_homestory_815601001_34_dialog_content = "Era sólo, sólo una prueba para ti.",
  str_homestory_815601001_35_option_content = "creele",
  str_homestory_815601001_36_dialog_content = "Entonces debo haberlo pasado...",
  str_homestory_815601001_37_dialog_content = "¡Sí! Eres más inteligente de lo que pareces, PlayerName. Ja ja.",
  str_homestory_815601001_38_option_content = "no le creas",
  str_homestory_815601001_39_dialog_content = "no lo compro",
  str_homestory_815601001_40_dialog_content = "PlayerName es tan tonto! Humph.",
  str_homestory_815601001_41_dialog_content = "...",
  str_homestory_815601001_42_dialog_content = "Pero...",
  str_homestory_815601001_43_dialog_content = "¿Por qué alguien montaría caballos de madera en lugar de reales?",
  str_homestory_815601001_44_dialog_content = "no lo se con seguridad...",
  str_homestory_815601001_45_dialog_content = "Pero los caballitos mecedores ofrecen su propia diversión y son mucho más seguros...",
  str_homestory_815601001_46_dialog_content = "Y supongo que no todo el mundo llega a montar caballos de verdad.",
  str_homestory_815601001_47_dialog_content = "¿Quiere decir... que no pueden permitirse los de verdad?<sprite=emo_wuzui size=60 />",
  str_homestory_815601001_48_dialog_content = "Me temo que algunas personas ni siquiera pueden permitirse un caballito balancín.",
  str_homestory_815601001_49_dialog_content = "...",
  str_homestory_815601001_50_dialog_content = "... ¡He tomado mi decisión!",
  str_homestory_815601001_51_dialog_content = "¿En qué?",
  str_homestory_815601001_52_dialog_content = "Quiero aprender diseño de carpintería y hacer caballitos balancines más interesantes...",
  str_homestory_815601001_53_dialog_content = "¡Y enviarlos a los niños que los necesitan!",
  str_homestory_810401001_0_dialog_content = "¿Amanecer?",
  str_homestory_810401001_1_dialog_content = "Estos pasos...",
  str_homestory_810401001_2_dialog_content = "Podría ser PlayerName?",
  str_homestory_810401001_3_dialog_content = "¡Ay! ¿Puedes reconocer mis pasos?",
  str_homestory_810401001_4_dialog_content = "¡Sí!<sprite=emo_yaosu size=60 />",
  str_homestory_810401001_5_dialog_content = "Hay muchos más sonidos diferentes aquí que en el Colossus...",
  str_homestory_810401001_6_dialog_content = "Pero todavía puedo elegir los hechos por personas conocidas.",
  str_homestory_810401001_7_dialog_content = "Me gusta PlayerName y Eva Ustedes tienen una forma especial de caminar.",
  str_homestory_810401001_8_dialog_content = "Una forma especial de caminar...",
  str_homestory_810401001_9_option_content = "pregunta por el mio",
  str_homestory_810401001_10_dialog_content = "Siempre estás apurado, pero luego te vuelves cauteloso cuando te acercas a mí.",
  str_homestory_810401001_11_dialog_content = "Puede que no te lo aclare...",
  str_homestory_810401001_12_dialog_content = "De todos modos, ¡solo sé que eres tú!",
  str_homestory_810401001_13_dialog_content = "¡Ay! Una cosa más...",
  str_homestory_810401001_14_dialog_content = "Cuando te acercas, me siento feliz.",
  str_homestory_810401001_15_dialog_content = "Este sentimiento feliz también me dice que PlayerName está viniendo.",
  str_homestory_810401001_16_option_content = "Pregunta por Eva",
  str_homestory_810401001_17_dialog_content = "Eva tiene unos pasos muy lindos!",
  str_homestory_810401001_18_dialog_content = "... Lindos... ¿pasos?",
  str_homestory_810401001_19_dialog_content = "¡Sí! Todo sobre Eva es lindo.<sprite=emo_aixin size=60 />.",
  str_homestory_810401001_20_dialog_content = "Err...",
  str_homestory_810401001_21_dialog_content = "Bueno, déjame ponerlo de esta manera. El físico de Eve es bastante especial...",
  str_homestory_810401001_22_dialog_content = "Apenas hace ruido cuando camina.",
  str_homestory_810401001_23_dialog_content = "Pero cuando Eve se acerca, me siento feliz.",
  str_homestory_810401001_24_dialog_content = "Este sentimiento feliz me dice que Eva está llegando.",
  str_homestory_810401001_25_dialog_content = "Entonces eso es...",
  str_homestory_810401001_26_dialog_content = "¡Eres increíble!",
  str_homestory_810401001_27_dialog_content = "Supongo que debido a que no puedo ver, mi oído se ha vuelto muy agudo.",
  str_homestory_810401001_28_dialog_content = "¡Ay! De paso...",
  str_homestory_810401001_29_dialog_content = "¿Qué tal Sinsa?",
  str_homestory_810401001_30_dialog_content = "Creo que estás familiarizado con él. ¿Cómo suenan los pasos de Sinsa?",
  str_homestory_810401001_31_dialog_content = "Bueno, tengo una manera más fácil de reconocerlo.",
  str_homestory_810401001_32_dialog_content = "¿Qué es?",
  str_homestory_810401001_33_dialog_content = "Él es apestoso.",
  str_homestory_810401001_34_dialog_content = "¿.?",
  str_homestory_810401001_35_dialog_content = "Está en constante movimiento... Creo que suda mucho.",
  str_homestory_810401001_36_dialog_content = "Ok...",
  str_homestory_810401001_37_dialog_content = "Definitivamente no es el hombre más apestoso de Rediesel Wrench...",
  str_homestory_810401001_38_dialog_content = "Pero ciertamente apesta más que tú y Eve.",
  str_homestory_810401001_39_dialog_content = "Me alegro de que no huelas como él, Navegante.",
  str_homestory_810401001_40_dialog_content = "Err... Gracias...",
  str_homestory_810401001_41_dialog_content = "Pero por qué... ¿Por qué no puedo notar el olor de Sinsa?",
  str_homestory_810401001_42_dialog_content = "¿No puedes?",
  str_homestory_810401001_43_dialog_content = "¿Estoy tan molesto porque Eve pasa demasiado tiempo con él...?<sprite=emo_sikao size=60 />",
  str_homestory_810401001_44_dialog_content = "... que he inventado ese olor?",
  str_homestory_810401001_45_dialog_content = "... Eso debe ser!",
  str_homestory_810401001_46_dialog_content = "... ¡Lo que sea! Estoy seguro de que es muy apestoso.",
  str_homestory_810401001_47_dialog_content = "Apestoso, apestoso Sinsa<sprite=emo_kulou size=60 />!",
  str_homestory_809001001_0_dialog_content = "¿Bárbara?",
  str_homestory_809001001_1_dialog_content = "¿Es el amor solo una hermosa mentira? ♪",
  str_homestory_809001001_2_dialog_content = "<sprite=emo_aixin size=60 />El verdadero amor solo emerge cuando el combustible se quema. ♪",
  str_homestory_809001001_3_dialog_content = "Whoa Whoa. El único amor. ♪",
  str_homestory_809001001_4_dialog_content = "¿Estás practicando tu nuevo sencillo?",
  str_homestory_809001001_5_dialog_content = "Jejeje, nuevo single? ¡No!",
  str_homestory_809001001_6_dialog_content = "Me estoy preparando para un nuevo álbum!",
  str_homestory_809001001_7_option_content = "¿Un álbum?",
  str_homestory_809001001_8_dialog_content = "¿Es un álbum un disco con muchas canciones incluidas?",
  str_homestory_809001001_9_dialog_content = "Eso es correcto.",
  str_homestory_809001001_10_option_content = "¿Mejor que el de Regina?",
  str_homestory_809001001_11_dialog_content = "¡UH Huh! ¡Por supuesto!",
  str_homestory_809001001_12_dialog_content = "¡Tengo que dar lo mejor de mí para las ventas de este álbum!",
  str_homestory_809001001_13_dialog_content = "Eres muy trabajador.",
  str_homestory_809001001_14_dialog_content = "Seguramente. Después de todo, nuevos géneros musicales están apareciendo por todas partes...",
  str_homestory_809001001_15_dialog_content = "¡No puedo quedarme atrás!",
  str_homestory_809001001_16_dialog_content = "¿Te preocupa perder popularidad y apoyo?",
  str_homestory_809001001_17_dialog_content = "¿Perder popularidad y apoyo? ¡Nunca!",
  str_homestory_809001001_18_dialog_content = "Me encanta ver diferentes tipos de música y músicos florecer juntos.",
  str_homestory_809001001_19_dialog_content = "Entonces, ¿qué quiere decir con \"no puede quedarse atrás\"?",
  str_homestory_809001001_20_dialog_content = "Eso solo significa que debo trabajar más duro.<sprite=emo_yinfu size=60 />.",
  str_homestory_809001001_21_dialog_content = "¡Necesito progresar junto con nuevos artistas y traer más música increíble para todos!",
  str_homestory_809001001_22_dialog_content = "¡Odio quedarme atrás!",
  str_homestory_809001001_23_dialog_content = "¡Eso es inspirador!",
  str_homestory_809001001_24_dialog_content = "Hmm... No estoy demasiado preocupado por mi popularidad.",
  str_homestory_809001001_25_dialog_content = "Pero si los fans que conozco bien me dejaron por otros cantantes...",
  str_homestory_809001001_26_dialog_content = "¡Todavía me sentiría un poco frustrado!",
  str_homestory_809001001_27_dialog_content = "Otros cantantes... ¿Estás hablando de Regina?",
  str_homestory_809001001_28_dialog_content = "PlayerName... ¡Eso es muy directo de tu parte!",
  str_homestory_809001001_29_dialog_content = "Te importa la música de Regina, ¿no?",
  str_homestory_809001001_30_dialog_content = "¿Cómo debo ponerlo?",
  str_homestory_809001001_31_dialog_content = "Mentiría si digo que no me importa nada<sprite=emo_tanqi size=60 />...",
  str_homestory_809001001_32_dialog_content = "Er... Es seguro decir que...",
  str_homestory_809001001_33_dialog_content = "Estoy escuchando su música para promover la diversidad.",
  str_homestory_809001001_34_dialog_content = "Hmm... Puede que no tenga tantos fans como yo, pero sus seguidores son muy leales.",
  str_homestory_809001001_35_dialog_content = "Los músicos hablan de la calidad de sus canciones, pero yo tengo bastante curiosidad...",
  str_homestory_809001001_36_dialog_content = "¿Cómo mantiene a sus fans cerca?",
  str_homestory_809001001_37_dialog_content = "¿Por qué no le preguntas a Regina si realmente quieres saberlo?",
  str_homestory_809001001_38_dialog_content = "Hmm...",
  str_homestory_809001001_39_dialog_content = "Supongo que prestaré atención a tu consejo, PlayerName...",
  str_homestory_809001001_40_dialog_content = "¡Hacerle una pregunta no es gran cosa!",
  str_homestory_809001001_41_dialog_content = "Hmm... En al menos 20 años<sprite=emo_emo size=60 />!",
  str_homestory_809001001_42_dialog_content = "... ¡Mejor dile que nunca le vas a preguntar!",
  str_homestory_807001001_0_dialog_content = "leona...",
  str_homestory_807001001_1_dialog_content = "Oye, chico.",
  str_homestory_807001001_2_dialog_content = "¿Qué tal?",
  str_homestory_807001001_3_dialog_content = "Lo siento, realmente no tengo tiempo ahora.",
  str_homestory_807001001_4_dialog_content = "Como puedes ver, estoy ocupado aliviando mis emociones negativas.",
  str_homestory_807001001_5_dialog_content = "¡Ay! No sabía que golpear sacos de arena es algo que puede ayudar.",
  str_homestory_807001001_6_dialog_content = "Muy efectivamente<sprite=emo_baiyan size=60 />.",
  str_homestory_807001001_7_dialog_content = "¿Nunca escuchaste?",
  str_homestory_807001001_8_dialog_content = "Hacer ejercicio es una buena manera de combatir las emociones negativas.",
  str_homestory_807001001_9_dialog_content = "Escuché eso antes.",
  str_homestory_807001001_10_dialog_content = "Hablando de tus emociones negativas...",
  str_homestory_807001001_11_option_content = "¿Cual es la causa?",
  str_homestory_807001001_12_dialog_content = "Sin causa específica.",
  str_homestory_807001001_13_option_content = "¿Te sientes mejor ahora?",
  str_homestory_807001001_14_dialog_content = "Sí, más o menos.",
  str_homestory_807001001_15_dialog_content = "Puedes ver las emociones negativas como un nudo dentro de tu cuerpo.",
  str_homestory_807001001_16_dialog_content = "¿Un nudo? ¿Como un nudo en una cuerda?",
  str_homestory_807001001_17_dialog_content = "Mas o menos.",
  str_homestory_807001001_18_dialog_content = "Una vez que notas que estás de mal humor...",
  str_homestory_807001001_19_dialog_content = "Necesitas hacer algo que te guste para salir de eso.",
  str_homestory_807001001_20_dialog_content = "Cualquier cosa que te relaje harías.",
  str_homestory_807001001_21_dialog_content = "Para mí, esta es la mejor manera de relajarse. Me hace sentir como si estuviera en una batalla.",
  str_homestory_807001001_22_dialog_content = "Cuando los sentimientos negativos arraigan en tu corazón, este nudo se vuelve cada vez más difícil de desatar.",
  str_homestory_807001001_23_dialog_content = "Incluso puede convertirse en una amenaza para su salud.",
  str_homestory_807001001_24_dialog_content = "Me tomó mucho tiempo aprender esto.",
  str_homestory_807001001_25_dialog_content = "Cuando tu corazón está cegado por el odio...",
  str_homestory_807001001_26_dialog_content = "... Lo siento. estoy divagando...",
  str_homestory_807001001_27_dialog_content = "Eh... tienes toda la razón.",
  str_homestory_807001001_28_dialog_content = "Pruébalo la próxima vez.",
  str_homestory_807001001_29_dialog_content = "¡No hay problema!",
  str_homestory_807001001_30_dialog_content = "Tal vez Sharona estuvo aquí golpeando sacos de arena por la misma razón la última vez.",
  str_homestory_807001001_31_dialog_content = "¿Te refieres a Sharona?",
  str_homestory_807001001_32_dialog_content = "¿Sharona había golpeado este saco de arena?",
  str_homestory_807001001_33_dialog_content = "¿Ah? ¡Es una broma!",
  str_homestory_807001001_34_dialog_content = "(Ah oh... probablemente no debería haber dicho eso...)",
  str_homestory_807001001_35_dialog_content = "...",
  str_homestory_807001001_36_dialog_content = "Leona, ¿qué pasa?",
  str_homestory_807001001_37_dialog_content = "Jejeje. Estoy haciendo lo mismo que mi querida hermana otra vez.",
  str_homestory_807001001_38_dialog_content = "Para no quemar este lugar <sprite=emo_nuhuo size=60 />abajo...",
  str_homestory_807001001_39_dialog_content = "Probablemente debería irme a Umbraton ahora mismo.",
  str_homestory_807001001_40_dialog_content = "Adiós, chico.",
  str_homestory_807001001_41_dialog_content = "U-Um...",
  str_homestory_807001001_42_dialog_content = "Te veo pronto...",
  str_homestory_811501001_0_dialog_content = "¡Naroxel!",
  str_homestory_811501001_1_dialog_content = "Estimado PlayerName.",
  str_homestory_811501001_2_dialog_content = "Debe ser la fuerza de la naturaleza la que nos ha guiado hasta aquí una vez más.",
  str_homestory_811501001_3_dialog_content = "¿Estás teniendo una conversación con Olive y Palm?",
  str_homestory_811501001_4_dialog_content = "¡Sí!",
  str_homestory_811501001_5_dialog_content = "Me sorprende que aún recuerdes sus nombres.",
  str_homestory_811501001_6_dialog_content = "Están muy felices.",
  str_homestory_811501001_7_dialog_content = "No es nada...",
  str_homestory_811501001_8_dialog_content = "Estoy lleno de emociones viendo el Eraveil levantarse de nuevo<sprite=emo_pugongying size=60 />.",
  str_homestory_811501001_9_dialog_content = "Cloud Gardens es realmente próspero y hermoso ahora.",
  str_homestory_811501001_10_dialog_content = "Gracias a la bendición de la naturaleza y a su arduo trabajo, PlayerName.",
  str_homestory_811501001_11_dialog_content = "Sin embargo... estoy un poco preocupado por ti.",
  str_homestory_811501001_12_dialog_content = "¿Estás bien después de lo que ha pasado últimamente?",
  str_homestory_811501001_13_option_content = "Asentir",
  str_homestory_811501001_14_dialog_content = "Estoy feliz de compartir este lugar con todos ustedes.",
  str_homestory_811501001_15_dialog_content = "Pero a veces me siento estresado por las altas expectativas.",
  str_homestory_811501001_16_option_content = "Sacudir la cabeza",
  str_homestory_811501001_17_dialog_content = "no estoy de mal humor...",
  str_homestory_811501001_18_dialog_content = "Pero me siento ansioso y estresado.",
  str_homestory_811501001_19_dialog_content = "Entendido.",
  str_homestory_811501001_20_dialog_content = "¿Te gustaría relajarte un poco conmigo?",
  str_homestory_811501001_21_dialog_content = "Está bien.",
  str_homestory_811501001_22_dialog_content = "Probemos este ejercicio de respiración.",
  str_homestory_811501001_23_dialog_content = "¿Ejercicio de respiración?",
  str_homestory_811501001_24_dialog_content = "Sí.",
  str_homestory_811501001_25_dialog_content = "Esto te ayudará a equilibrar la energía dentro de tu cuerpo.",
  str_homestory_811501001_26_dialog_content = "Para ponerlo simple...",
  str_homestory_811501001_27_dialog_content = "Mantiene nuestra energía interna fluyendo.",
  str_homestory_811501001_28_dialog_content = "¡Comprendido! ¿Deberíamos empezar?",
  str_homestory_811501001_29_dialog_content = "Claro.",
  str_homestory_811501001_30_dialog_content = "Relaja tus hombros. Tomar una respiración profunda.",
  str_homestory_811501001_31_dialog_content = "Muy bueno. Ahora... tápate la nariz.",
  str_homestory_811501001_32_dialog_content = "(Sostenga la nariz... Hmm...)",
  str_homestory_811501001_33_dialog_content = "Presione el ala derecha de la nariz e inhale por la fosa nasal izquierda.",
  str_homestory_811501001_34_dialog_content = "Luego presione el ala izquierda de la nariz y exhale por la fosa nasal derecha...",
  str_homestory_811501001_35_dialog_content = "(Inhala exhala...)",
  str_homestory_811501001_36_dialog_content = "Así. Ajuste lentamente su respiración.",
  str_homestory_811501001_37_dialog_content = "Inhala y exhala en equilibrio...",
  str_homestory_811501001_38_dialog_content = "Pronto sentiremos nuestro cuerpo y mente relajados a través de este ejercicio de respiración.",
  str_homestory_811501001_39_dialog_content = "Sí... Me siento muy tranquilo ahora.",
  str_homestory_811501001_40_dialog_content = "en realidad tengo un poco de sueño<sprite=emo_kun size=60 />...",
  str_homestory_811501001_41_dialog_content = "Jeje.",
  str_homestory_811501001_42_dialog_content = "Este ejercicio de respiración nos puede traer una liberación y un buen sueño.",
  str_homestory_811501001_43_dialog_content = "Siéntase libre de intentarlo de nuevo antes de acostarse.",
  str_homestory_811501001_44_dialog_content = "Es posible que se sienta aún mejor si sus ojos están cerrados durante este ejercicio.",
  str_homestory_811501001_45_dialog_content = "Mmm. Intentaré recordar eso.",
  str_homestory_811501001_46_dialog_content = "¡Gracias, Naroxel!",
  str_homestory_803302001_0_dialog_content = "Hola Vice.",
  str_homestory_803302001_1_dialog_content = "PlayerName! ¿Estás libre en este momento?",
  str_homestory_803302001_2_dialog_content = "Por supuesto. ¿Que necesitas?",
  str_homestory_803302001_3_dialog_content = "Mientras caminaba por la orilla del río, noté algo en el agua.",
  str_homestory_803302001_4_dialog_content = "Intenté agarrarlo, pero fallé. Parecía una especie de plano.",
  str_homestory_803302001_5_dialog_content = "Si quieres, puedes ir a comprobarlo.",
  str_homestory_803302001_6_dialog_content = "No hay problema.",
  str_homestory_803303001_0_dialog_content = "¿Qué estás haciendo?",
  str_homestory_803303001_1_dialog_content = "Estoy pensando en cómo puedo sacar esa cosa de ahí...",
  str_homestory_803303001_2_dialog_content = "¿Qué es?",
  str_homestory_803303001_3_dialog_content = "Hay algo peculiar en el río que despertó mi curiosidad.<sprite=emo_sikao size=60 />.",
  str_homestory_803303001_4_dialog_content = "Pero no puedo conseguirlo, no importa cuánto lo intente... y ahora me duelen las manos.",
  str_homestory_803303001_5_dialog_content = "¿Me puede ayudar? Es por allá.",
  str_homestory_803303001_6_dialog_content = "Está bien, lo intentaré.",
  str_homestory_803304001_0_dialog_content = "¿Buscándome?",
  str_homestory_803304001_1_dialog_content = "Oye, ¿cómo supiste que te estaba buscando?",
  str_homestory_803304001_2_dialog_content = "¡Encontré algo interesante!<sprite=emo_yaosu size=60 />",
  str_homestory_803304001_3_dialog_content = "No otra araña gigante o grillo bailarín, ¿verdad?",
  str_homestory_803304001_4_dialog_content = "¡No, es un plano para muebles nuevos!",
  str_homestory_803304001_5_dialog_content = "Pero está bajo el agua y es difícil de sacar.",
  str_homestory_803304001_6_dialog_content = "Bueno, déjamelo a mí. Soy bueno en cosas como esa.",
  str_homestory_803304001_7_dialog_content = "¡Es por allá! ¡Deja que te enseñe!",
  str_homestory_809301001_0_dialog_content = "Esa mirada en tus ojos...",
  str_homestory_809301001_1_dialog_content = "¿Puedo, eh, ayudarte?",
  str_homestory_809301001_2_dialog_content = "Has crecido desde la última vez que nos vimos. Sabías que quería algo de ti.",
  str_homestory_809301001_3_dialog_content = "Sentí que se me erizaba el pelo de la espalda como si me estuvieran observando...",
  str_homestory_809301001_4_dialog_content = "Miré hacia arriba y te encontré mirándome.",
  str_homestory_809301001_5_dialog_content = "\"Miró hacia arriba\"? Supongo que no has crecido tanto como pensaba.",
  str_homestory_809301001_6_option_content = "¡Soy más alto!",
  str_homestory_809301001_7_dialog_content = "¿Sí? ¿Cómo es que no podía decir? ¿Quieres ir a mi laboratorio?",
  str_homestory_809301001_8_dialog_content = "Puedo abrirte para ver si te crecieron los huesos.",
  str_homestory_809301001_9_option_content = "Correcto...",
  str_homestory_809301001_10_dialog_content = "¿Renunciar ya? debería ayudarte ¿Quieres ir a mi laboratorio?",
  str_homestory_809301001_11_dialog_content = "Puedo abrirte y ver si tus huesos aún pueden crecer.",
  str_homestory_809301001_12_dialog_content = "U-Um, eso no será necesario...",
  str_homestory_809301001_13_dialog_content = "No te preocupes. Después de mi disección, te haré un plan para crecer más alto.",
  str_homestory_809301001_14_dialog_content = "Está bien. Dejémoslo a la naturaleza por ahora.",
  str_homestory_809301001_15_dialog_content = "¿Naturaleza? ¿Estás bromeando?",
  str_homestory_809301001_16_dialog_content = "Puedo decir que muchos de los árboles en Cloud Gardens han sido modificados genéticamente.",
  str_homestory_809301001_17_dialog_content = "Y esto fue logrado por...",
  str_homestory_809301001_18_dialog_content = "Empalmar las semillas de diferentes plantas en variedades nuevas y únicas.",
  str_homestory_809301001_19_dialog_content = "¿Podrías decir eso con solo mirar?",
  str_homestory_809301001_20_dialog_content = "¿Ha olvidado que soy un oficial técnico de Illumina que se especializa en biotecnología?",
  str_homestory_809301001_21_dialog_content = "He hecho más experimentos de bioingeniería como este de los que puedo contar.",
  str_homestory_809301001_22_dialog_content = "Pero no esperaba que tuvieras un don para este tipo de tecnología.",
  str_homestory_809301001_23_dialog_content = "Solo estaba bromeando, así que no es nada especial.",
  str_homestory_809301001_24_dialog_content = "Sí, puedo decirlo.",
  str_homestory_809301001_25_dialog_content = "...",
  str_homestory_809301001_26_dialog_content = "No puedes tener ese éxito sin fallar noventa y nueve veces antes.",
  str_homestory_809301001_27_dialog_content = "Eso es lo que me di cuenta de todo mi esfuerzo. En cuanto a ti...",
  str_homestory_809301001_28_dialog_content = "Para obtener esa semilla ultra rara, debes hacer esto y aquello.",
  str_homestory_809301001_29_dialog_content = "\"Esto y aquello\"? ¿Qué quieres decir?",
  str_homestory_809301001_30_dialog_content = "Es difícil para ti conseguirlo sin una formación científica. Hablaremos más tarde.",
  str_homestory_809301001_31_dialog_content = "Bueno, podemos hacerlo ahora.",
  str_homestory_809301001_32_dialog_content = "¿Ahora? Déjame dormir un poco primero.",
  str_homestory_809301001_33_dialog_content = "...",
  str_homestory_809301001_34_dialog_content = "Oh, espera, casi olvido lo que quería preguntarte.",
  str_homestory_809301001_35_dialog_content = "¿Puedes cambiar mi habitación a un dormitorio con muchas chicas bonitas?",
  str_homestory_809301001_36_option_content = "Aceptar",
  str_homestory_809301001_37_dialog_content = "Puedo, pero deberías discutirlo con todos primero.",
  str_homestory_809301001_38_option_content = "Rechazar",
  str_homestory_809301001_39_dialog_content = "No infrinjo el derecho de nadie a vivir donde quiera.",
  str_homestory_809301001_40_dialog_content = "Pero está bien si pudieras resolverlo con ellos.",
  str_homestory_809301001_41_dialog_content = "Eso suena como un problema.",
  str_homestory_809301001_42_dialog_content = "Aunque vale la pena intentarlo. Si no, 100 intentos.",
  str_homestory_809301001_43_dialog_content = "(¿Mantener esa misma actitud para esto también?)",
  str_homestory_815702001_0_dialog_content = "¿Qué estás mirando?",
  str_homestory_815702001_1_dialog_content = "¡Ahhhhhhhhhhh!",
  str_homestory_815702001_2_dialog_content = "Lo siento, ¿te asusté de nuevo?",
  str_homestory_815702001_3_dialog_content = "(¿Pero por qué dije \"otra vez\"?)",
  str_homestory_815702001_4_dialog_content = "No, solo estaba sumido en mis pensamientos.",
  str_homestory_815702001_5_dialog_content = "Así que no te vi aquí.",
  str_homestory_815702001_6_dialog_content = "Debería ser yo quien se disculpe.",
  str_homestory_815702001_7_dialog_content = "Todo está bien, así que no te preocupes.",
  str_homestory_815702001_8_dialog_content = "Acabas de venir del río, ¿verdad? No me digas que estabas pensando en...",
  str_homestory_815702001_9_option_content = "¿Pescar?",
  str_homestory_815702001_10_dialog_content = "Pesca... ¿Eso no requiere artes caros?",
  str_homestory_815702001_11_dialog_content = "Ese pensamiento, eh, nunca pasó por mi mente...",
  str_homestory_815702001_12_option_content = "¿Natación?",
  str_homestory_815702001_13_dialog_content = "Nadar... ¿No tienes que usar un traje ceñido para eso?",
  str_homestory_815702001_14_dialog_content = "Me sentiría un poco avergonzado.",
  str_homestory_815702001_15_dialog_content = "En realidad, estaba pensando...",
  str_homestory_815702001_16_dialog_content = "¿Los granjeros de Eraveil trabajaron tan duro como los de la Isla de las Nubes?",
  str_homestory_815702001_17_dialog_content = "Tampoco estoy seguro, pero creo que si es Eraveil o Cloud Island...",
  str_homestory_815702001_18_dialog_content = "Todos están extasiados cuando se trata de una cosecha abundante.",
  str_homestory_815702001_19_dialog_content = "Entonces, ¿qué trajo eso?",
  str_homestory_815702001_20_dialog_content = "Bueno, acabo de encontrar un objeto brillante en la orilla del río que parecía una moneda.<sprite=emo_baiyebi size=60 />.",
  str_homestory_815702001_21_dialog_content = "Las monedas significan comercio, el comercio significa comida y la comida significa... ¡granjero!",
  str_homestory_815702001_22_dialog_content = "¿Lo pones todo junto así?",
  str_homestory_815702001_23_dialog_content = "¡Oh, por favor, no te enfades!",
  str_homestory_815702001_24_dialog_content = "Nunca tuve la intención de quedarme con la moneda.",
  str_homestory_815702001_25_dialog_content = "Te doy la moneda ahora mismo...",
  str_homestory_815702001_26_dialog_content = "Está bien, tómalo con calma.",
  str_homestory_815702001_27_dialog_content = "A ver donde lo pongo...",
  str_homestory_815702001_28_dialog_content = "Se fue...",
  str_homestory_815702001_29_dialog_content = "¡Ah!",
  str_homestory_815702001_30_dialog_content = "¿Qué tal?",
  str_homestory_815702001_31_dialog_content = "Recuerdo haber escuchado un chapoteo cuando salí de la orilla del río antes.",
  str_homestory_815702001_32_dialog_content = "¡Debo haberlo dejado caer accidentalmente al agua!",
  str_homestory_815702001_33_dialog_content = "Todo está bien. Lo pescaré.",
  str_homestory_815702001_34_dialog_content = "¿Lo harás? R-¿En serio? ¡Gracias!",
  str_homestory_815602001_0_dialog_content = "¿Qué estás buscando?",
  str_homestory_815602001_1_dialog_content = "¡Oye, ven aquí!",
  str_homestory_815602001_2_dialog_content = "Nina?",
  str_homestory_815602001_3_dialog_content = "Si no me equivoco, estabas buscando algo.",
  str_homestory_815602001_4_dialog_content = "Sí.",
  str_homestory_815602001_5_dialog_content = "¿Has visto una cosita redonda?",
  str_homestory_815602001_6_dialog_content = "puedes ser mas preciso?",
  str_homestory_815602001_7_dialog_content = "Bueno... Aquí está la cosa.",
  str_homestory_815602001_8_dialog_content = "Nunca había visto algo con un patrón como ese...",
  str_homestory_815602001_9_dialog_content = "¡Por eso lo apreté con fuerza en mi mano!",
  str_homestory_815602001_10_dialog_content = "Pero... se me escapó de la mano y cayó al agua cuando aflojé mi agarre...",
  str_homestory_815602001_11_dialog_content = "Espera, ¿por qué siento que estás hablando de...?",
  str_homestory_815602001_12_dialog_content = "Espera, déjame terminar.",
  str_homestory_815602001_13_dialog_content = "¡Entonces descubrí un patrón extraño en la palma de mi mano!",
  str_homestory_815602001_14_option_content = "¡¿Lúmina mutada?!",
  str_homestory_815602001_15_dialog_content = "¿Has estado leyendo demasiadas novelas de fantasía?",
  str_homestory_815602001_16_option_content = "¡¿Te vas a transformar?!",
  str_homestory_815602001_17_dialog_content = "¿De qué demonios estás hablando?",
  str_homestory_815602001_18_dialog_content = "¡Es porque ese objeto tenía una forma y patrón únicos!",
  str_homestory_815602001_19_dialog_content = "Cuando lo sostuve en mi palma, quedó impreso en mi piel.",
  str_homestory_815602001_20_dialog_content = "Este patrón es algo estéticamente agradable...",
  str_homestory_815602001_21_dialog_content = "Piénsalo, si tuviera que diseñar una prenda basada en este patrón...",
  str_homestory_815602001_22_dialog_content = "¡Necesito encontrar esa moneda!",
  str_homestory_815602001_23_dialog_content = "¡Sabía que era una moneda!",
  str_homestory_815602001_24_dialog_content = "Ayudaré.",
  str_homestory_815602001_25_dialog_content = "G-Gracias—¡Oye, espera!<sprite=emo_wuzui size=60 />",
  str_homestory_815602001_26_dialog_content = "Desde que encontré la moneda en Cloud Gardens... técnicamente te pertenece, ¿verdad?",
  str_homestory_815602001_27_dialog_content = "Entonces, si te lo pidiera prestado y lo estudiara...",
  str_homestory_815602001_28_dialog_content = "No es un problema. Pero tendremos que encontrarlo primero.",
  str_homestory_815602001_29_dialog_content = "Me sorprende que lo aceptaras tan rápido.",
  str_homestory_815602001_30_dialog_content = "Ejem... No es que realmente QUIERA estudiarlo...",
  str_homestory_815602001_31_dialog_content = "¡Es solo una inspiración para el diseño de ropa, ya sabes!",
  str_homestory_815602001_32_dialog_content = "¿Sabes, verdad?",
  str_homestory_815602001_33_dialog_content = "Lo sé.",
  str_homestory_815602001_34_dialog_content = "Tsk, eso es bueno.",
  str_homestory_812601001_0_dialog_content = "Qué estás pensando?",
  str_homestory_812601001_1_dialog_content = "Bethel?",
  str_homestory_812601001_2_dialog_content = "Parece que estás pensando mucho en algo...",
  str_homestory_812601001_3_dialog_content = "Cállate...<sprite=emo_chidai size=60 />",
  str_homestory_812601001_4_dialog_content = "Acabo de lidiar con todas esas declaraciones del Gremio. Estoy en medio de hacer algunas reflexiones.",
  str_homestory_812601001_5_dialog_content = "¿Acerca de?",
  str_homestory_812601001_6_dialog_content = "¡Mi última obra de ficción!",
  str_homestory_812601001_7_dialog_content = "Tal vez debería analizarlo contigo.",
  str_homestory_812601001_8_dialog_content = "Claro, si puedo ser de ayuda.",
  str_homestory_812601001_9_dialog_content = "Muy bien... Escucha. Así va la historia...",
  str_homestory_812601001_10_dialog_content = "Los protagonistas masculino y femenino llegan a un río...",
  str_homestory_812601001_11_dialog_content = "¡Y de repente, el pañuelo de la protagonista femenina cae al agua!",
  str_homestory_812601001_12_dialog_content = "Así que aquí está la pregunta: ¿Debería la protagonista femenina recuperarlo, o debería el protagonista masculino?",
  str_homestory_812601001_13_option_content = "la protagonista femenina",
  str_homestory_812601001_14_dialog_content = "Hmm...",
  str_homestory_812601001_15_dialog_content = "Claro, eso le demostrará que es una mujer muy independiente y capaz.",
  str_homestory_812601001_16_option_content = "El protagonista masculino",
  str_homestory_812601001_17_dialog_content = "Hmm...",
  str_homestory_812601001_18_dialog_content = "¡Eso realmente impulsará la historia y podrán comenzar a hablar sobre el pañuelo!",
  str_homestory_812601001_19_dialog_content = "Bien. ¡Lo tengo!",
  str_homestory_812601001_20_dialog_content = "¡Así es como lo voy a escribir!<sprite=emo_yaosu size=60 />",
  str_homestory_812601001_21_dialog_content = "¿Qué te hizo concebir una trama así?",
  str_homestory_812601001_22_dialog_content = "Porque vi algo caer al agua hace un momento.",
  str_homestory_812601001_23_dialog_content = "Me hizo pensar que sería una buena premisa...",
  str_homestory_812601001_24_dialog_content = "¿Esperar lo? ¿Qué cayó al agua?",
  str_homestory_812601001_25_dialog_content = "No cogí una buena mirada. Era algo pequeño y redondo.<sprite=emo_sikao size=60 />",
  str_homestory_812601001_26_dialog_content = "Pequeño y redondo...",
  str_homestory_812601001_27_dialog_content = "Sé lo que es.",
  str_homestory_816401001_0_dialog_content = "¿Carleen?",
  str_homestory_816401001_1_dialog_content = "¿PlayerName?",
  str_homestory_816401001_2_dialog_content = "Qué estás haciendo, Carleen?",
  str_homestory_816401001_3_dialog_content = "Estoy pensando.",
  str_homestory_816401001_4_dialog_content = "¿Está todo bien? Te ves un poco... decaído.",
  str_homestory_816401001_5_dialog_content = "¿Abajo? Bien...",
  str_homestory_816401001_6_dialog_content = "Porque Lumopolis fue golpeada por varios desastres naturales recientemente.",
  str_homestory_816401001_7_dialog_content = "Siento escuchar eso...",
  str_homestory_816401001_8_dialog_content = "¿Cómo está la ciudad ahora? ¿Hay algo que pueda hacer para ayudar?",
  str_homestory_816401001_9_dialog_content = "Gracias por preguntar, PlayerName.",
  str_homestory_816401001_10_dialog_content = "El recuento de bajas y las pérdidas de activos se están manejando oficialmente.",
  str_homestory_816401001_11_dialog_content = "Además de devolver los cuerpos de los muertos a sus familias...",
  str_homestory_816401001_12_dialog_content = "Realmente no sé qué más podemos hacer para aliviar su dolor.",
  str_homestory_816401001_13_dialog_content = "Sé cómo debes sentirte, Carleen.",
  str_homestory_816401001_14_dialog_content = "Uf... <sprite=emo_tanqi size=60 />",
  str_homestory_816401001_15_dialog_content = "Mi mente se siente mucho más clara ahora que te he dicho lo que me estaba molestando.",
  str_homestory_816401001_16_dialog_content = "¿Estás pensando en cómo evitar estos desastres en el futuro?",
  str_homestory_816401001_17_dialog_content = "No.",
  str_homestory_816401001_18_dialog_content = "Ante los desastres naturales, no somos más que hormigas.",
  str_homestory_816401001_19_dialog_content = "Solo estoy orando por mi cuenta, y para reafirmarme algo...",
  str_homestory_816401001_20_option_content = "¿Tu fe?",
  str_homestory_816401001_21_dialog_content = "Bueno...",
  str_homestory_816401001_22_option_content = "¿La eficacia de las oraciones?",
  str_homestory_816401001_23_dialog_content = "¿Cómo debo poner esto?",
  str_homestory_816401001_24_dialog_content = "Solo quiero confirmar que las oraciones aún pueden brindarme el consuelo que necesito desesperadamente.",
  str_homestory_816401001_25_dialog_content = "Entiendo...",
  str_homestory_816401001_26_dialog_content = "A menudo tememos las cosas impredecibles que no podemos controlar.",
  str_homestory_816401001_27_dialog_content = "Pero no hay nada que podamos hacer más que observar cómo se desarrollan.",
  str_homestory_816401001_28_dialog_content = "Y por eso te sientes impotente, ¿verdad?",
  str_homestory_816401001_29_dialog_content = "Correcto.",
  str_homestory_816401001_30_dialog_content = "Rezo cada vez que me siento derrotado.",
  str_homestory_816401001_31_dialog_content = "Y también me pregunto qué es lo que realmente me dan las oraciones.",
  str_homestory_816401001_32_dialog_content = "Y después de mucho pensar, llegué a la conclusión de que es apoyo espiritual, y...",
  str_homestory_816401001_33_dialog_content = "La motivación para seguir adelante.",
  str_homestory_816401001_34_dialog_content = "Así es.",
  str_homestory_816401001_35_dialog_content = "Estoy seguro de que sus oraciones lo ayudarán en estos tiempos difíciles.",
  str_homestory_816401001_36_dialog_content = "Y finalmente entendí algo.",
  str_homestory_816401001_37_dialog_content = "¿Por qué tenemos una tendencia a hacer deidades a partir de tantos elementos de la naturaleza?",
  str_homestory_816401001_38_dialog_content = "Porque tenemos demasiadas preguntas sobre este mundo y muy pocas respuestas.",
  str_homestory_816401001_39_dialog_content = "Las oraciones son en realidad un compromiso. <sprite=emo_sikao size=60 />",
  str_homestory_816401001_40_dialog_content = "No resuelven ningún problema ni proporcionan ninguna respuesta.",
  str_homestory_816401001_41_dialog_content = "Pero te traen paz interior y te ayudan a recuperarte.",
  str_homestory_816401001_42_dialog_content = "Cierto... proporcionan mucho apoyo.",
  str_homestory_816401001_43_dialog_content = "Tal vez debería intentar esto de la oración la próxima vez.",
  str_homestory_816401001_44_dialog_content = "Espero poder hablar con usted al respecto.",
  str_homestory_811101001_0_dialog_content = "Beryl...",
  str_homestory_811101001_1_dialog_content = "...",
  str_homestory_811101001_2_dialog_content = "Beryl!",
  str_homestory_811101001_3_dialog_content = "¿Hmm? ¿Que pasa?",
  str_homestory_811101001_4_dialog_content = "Estás distraído, mirando el río. ¿Hay algo mal?",
  str_homestory_811101001_5_dialog_content = "Oh, ¿estabas preocupado por mí?",
  str_homestory_811101001_6_option_content = "Sip.",
  str_homestory_811101001_7_dialog_content = "¿Entonces crees que soy infeliz porque he estado parado junto al río? <sprite=emo_wuzui size=60 />",
  str_homestory_811101001_8_dialog_content = "Um, bueno, eso no es realmente...",
  str_homestory_811101001_9_dialog_content = "Estaba dando un paseo por el río. Quiero decir, el clima es agradable hoy, ¿verdad?",
  str_homestory_811101001_10_dialog_content = "La expresión de tu rostro es extraña.",
  str_homestory_811101001_11_option_content = "Realmente no.",
  str_homestory_811101001_12_dialog_content = "Simplemente no sabía lo que estabas haciendo, porque has estado parado aquí por mucho tiempo.",
  str_homestory_811101001_13_dialog_content = "Cuando bajo al río, suelo caminar o pescar, pero no me quedo quieto.",
  str_homestory_811101001_14_dialog_content = "Entonces... ¿qué estabas haciendo?",
  str_homestory_811101001_15_dialog_content = "Estaba pensando en mis cristales y Cloud Gardens.",
  str_homestory_811101001_16_dialog_content = "tus cristales...",
  str_homestory_811101001_17_dialog_content = "Sí, Vice Dijo que ha estado estresado por el desarrollo de Cloud Gardens.",
  str_homestory_811101001_18_dialog_content = "Y sobre cómo no tienes mucho dinero <sprite=emo_baiyebi size=60 />, así que estaba pensando en cómo hacerte rico.",
  str_homestory_811101001_19_dialog_content = "Y comencé a pensar en mi poder, los cristales.",
  str_homestory_811101001_20_dialog_content = "Si convierto las piedras de Cloud Gardens en cristales, luego se las vendo a los joyeros de Umbration...",
  str_homestory_811101001_21_dialog_content = "¿Usted puede hacer eso?",
  str_homestory_811101001_22_dialog_content = "Sí, escuché que puedes romperlos y vender los fragmentos de cristal por una buena suma.",
  str_homestory_811101001_23_dialog_content = "¿D-De veras?",
  str_homestory_811101001_24_dialog_content = "No en realidad no.",
  str_homestory_811101001_25_dialog_content = "¡Guau! ¡Veo que has aprendido a hacer bromas!",
  str_homestory_811101001_26_dialog_content = "Tal vez cambié después de venir aquí. Después de todo, es un lugar muy relajante.",
  str_homestory_811101001_27_dialog_content = "Especialmente cuando miro a los peces en el río.",
  str_homestory_811101001_28_dialog_content = "Si quieres ver peces, ¿por qué no vas a la Fuente de la Esperanza?",
  str_homestory_811101001_29_dialog_content = "Debería haber muchos allí, y algunos también son realmente bonitos.",
  str_homestory_811101001_30_dialog_content = "Aquí... Solo puedo ver los muy pequeños.",
  str_homestory_811101001_31_dialog_content = "Esos son los que he estado mirando.",
  str_homestory_811101001_32_dialog_content = "Especialmente la forma en que deambulan entre las algas o la forma en que descansan junto a las rocas.",
  str_homestory_811101001_33_dialog_content = "Es muy relajante cómo se mimetizan con el entorno.",
  str_homestory_811101001_34_dialog_content = "Su atención al detalle es realmente algo...",
  str_homestory_811101001_35_dialog_content = "No puedo creer que tus ojos puedan seguirlos mientras se lanzan a través del agua.",
  str_homestory_811101001_36_dialog_content = "No están nadando todo el tiempo. De hecho, pasan mucho tiempo descansando en el fondo del río.",
  str_homestory_811101001_37_dialog_content = "Algunos incluso se meten en los huecos entre las rocas y solo asoman la cabeza.",
  str_homestory_811101001_38_dialog_content = "Algunos siguen a las algas cuando se balancean en el agua. Se siente tan... liberador.",
  str_homestory_811101001_39_dialog_content = "Ya veo. No estás mirando al pez, Beryl. Realmente estás viendo cómo viven.",
  str_homestory_811101001_40_dialog_content = "¿Cómo viven?",
  str_homestory_811101001_41_dialog_content = "Cómo no están atados por nada y viven vidas sin preocupaciones.",
  str_homestory_811101001_42_dialog_content = "Sí, nunca he sentido esto en ningún otro lugar.",
  str_homestory_811101001_43_dialog_content = "Solo se me ocurrió después de que llegué a Cloud Gardens y los vi en el río.",
  str_homestory_811101001_44_dialog_content = "¿Es por el encanto de este lugar?",
  str_homestory_811101001_45_dialog_content = "No el encanto, sino la forma en que te relaja.",
  str_homestory_811101001_46_dialog_content = "si, relajado <sprite=emo_pugongying size=60 />...",
  str_homestory_816501001_0_dialog_content = "Ciel...",
  str_homestory_816501001_1_dialog_content = "¡Hola! ¿Tienes algún trabajo para mí?",
  str_homestory_816501001_2_option_content = "Si.",
  str_homestory_816501001_3_dialog_content = "¿Qué son? ¿Cómo es el pago?",
  str_homestory_816501001_4_dialog_content = "No estoy seguro de si son adecuados para ti... Son tareas de decoración de edificios...",
  str_homestory_816501001_5_dialog_content = "Lo cual sería un desperdicio de sus talentos.",
  str_homestory_816501001_6_option_content = "No.",
  str_homestory_816501001_7_dialog_content = "¿De verdad no tienes nada?",
  str_homestory_816501001_8_dialog_content = "Para empezar, Cloud Gardens no tiene muchos trabajos, y los Chubb hacen la mayoría de ellos.",
  str_homestory_816501001_9_dialog_content = "¿Algo a mayor escala entonces? Como hacer túneles o cavar a través de las montañas.",
  str_homestory_816501001_10_dialog_content = "Mi mecha está hecho para esas cosas, ya sabes. <sprite=emo_dianzan size=60 />",
  str_homestory_816501001_11_dialog_content = "No creas que tengo nada ahora mismo. Por cierto, ¿por qué de repente estás buscando trabajo? ¿No quieres disfrutar al máximo de tu descanso?",
  str_homestory_816501001_12_dialog_content = "No puedo tomar ningún descanso porque necesito dinero.",
  str_homestory_816501001_13_dialog_content = "¿Dinero? Escuché que Illumina lo raciona. ¿Hay algo que quieras comprar?",
  str_homestory_816501001_14_dialog_content = "Yo... quiero una calculadora mecánica. Vi uno una vez en el laboratorio de investigación.",
  str_homestory_816501001_15_dialog_content = "¿Por qué no construyes uno? Tienes tiempo para mientras estás aquí.",
  str_homestory_816501001_16_dialog_content = "No, porque tienen muchas piezas no estándar y es demasiado complicado.",
  str_homestory_816501001_17_dialog_content = "Tomaría mucho tiempo si tuviera que hacer las piezas yo mismo.",
  str_homestory_816501001_18_dialog_content = "Y costaría mucho dinero fabricarlos.",
  str_homestory_816501001_19_dialog_content = "Pero realmente quiero uno, así que estoy buscando cualquier trabajo secundario que pueda asumir.",
  str_homestory_816501001_20_dialog_content = "Hablando de eso, ¿qué te llevó de repente a querer conseguir uno?",
  str_homestory_816501001_21_dialog_content = "Porque creo que hay algo mal con el plano. Hay un lugar donde los cálculos no coinciden, incluso después de varios intentos.",
  str_homestory_816501001_22_dialog_content = "El cálculo es realmente complicado y lo he hecho lo mejor que he podido, pero una máquina nunca se equivocaría.",
  str_homestory_816501001_23_dialog_content = "Así que quieres verificar los números.",
  str_homestory_816501001_24_dialog_content = "¡Sí! Recientemente construí un mecha dinámico de acuerdo con este plano...",
  str_homestory_816501001_25_dialog_content = "Pero debido a un error, el mecanismo se averió y casi quema el plano.",
  str_homestory_816501001_26_dialog_content = "Lo salvé del edificio en llamas, pero...",
  str_homestory_816501001_27_dialog_content = "Esto simplemente no está funcionando, y creo que es porque me falta una parte del plano. <sprite=emo_daomei size=60 />",
  str_homestory_816501001_28_dialog_content = "Algunas partes del mecanismo dinámico construido de acuerdo con los planes actuales no funcionan según lo previsto.",
  str_homestory_816501001_29_dialog_content = "Lógicamente, si al plano le falta una parte, no deberías poder construir el mecha en absoluto, ¿verdad?",
  str_homestory_816501001_30_dialog_content = "En términos generales, sí.",
  str_homestory_816501001_31_dialog_content = "Entonces, ¿podría ser un problema de perspectiva?",
  str_homestory_816501001_32_dialog_content = "Por ejemplo, pensé que una de las conexiones en Colossus no se veía bien, pero no pude arreglarlo incluso después de intentarlo durante mucho tiempo.",
  str_homestory_816501001_33_dialog_content = "Luego vino una luciérnaga e inmediatamente vio el problema.",
  str_homestory_816501001_34_dialog_content = "Perspectiva...",
  str_homestory_816501001_35_dialog_content = "¡Lo tengo! es como el <sprite=emo_baiyebi size=60 /> ¡moneda!",
  str_homestory_816501001_36_dialog_content = "¿Qué moneda?",
  str_homestory_816501001_37_dialog_content = "Ayer vi una moneda junto al río. Bueno, podría haber sido una tapa de botella o simplemente una pieza de metal.",
  str_homestory_816501001_38_dialog_content = "De todos modos, eso no es importante. ¡Lo importante era que estaba rebotando en el río por su cuenta!",
  str_homestory_816501001_39_dialog_content = "Ahora que lo pienso, la superficie estaba en calma, pero tal vez había una corriente de agua debajo...",
  str_homestory_816501001_40_dialog_content = "Ah, ya veo. Tal vez las fórmulas solo estaban sugiriendo la dirección que debería tomar el diseño.",
  str_homestory_816501001_41_dialog_content = "Espera, ¿dijiste que viste una moneda junto al río?",
  str_homestory_816501001_42_dialog_content = "¿Hmm? Correcto, sí. De todos modos, me voy a diseñar el mecha de nuevo. ¡Nos vemos!",
  str_homestory_816501001_43_dialog_content = "Bien...",
  str_homestory_810001001_0_dialog_content = "¿Qué tienes en mente?",
  str_homestory_810001001_1_dialog_content = "Sikare?",
  str_homestory_810001001_2_dialog_content = "Oh, hola bola de nieve. Justo a quien estaba buscando.",
  str_homestory_810001001_3_dialog_content = "¿Qué tal?",
  str_homestory_810001001_4_dialog_content = "¿Qué opinas sobre Jardines de Nubes?",
  str_homestory_810001001_5_dialog_content = "¿Eh? Esa es mi linea. Ahora que me preguntas, necesito un momento...",
  str_homestory_810001001_6_option_content = "Una casa.",
  str_homestory_810001001_7_dialog_content = "Esta es, por supuesto, mi casa.",
  str_homestory_810001001_8_option_content = "Un lugar para descansar.",
  str_homestory_810001001_9_dialog_content = "Un gran lugar para tomar un descanso.",
  str_homestory_810001001_10_dialog_content = "Entiendo...",
  str_homestory_810001001_11_dialog_content = "¿No crees que también es como una prisión?",
  str_homestory_810001001_12_dialog_content = "Como la Cripta Estrellada que guardo.",
  str_homestory_810001001_13_dialog_content = "Yo no te entiendo.",
  str_homestory_810001001_14_dialog_content = "Es demasiado cómodo aquí. Es tan cómodo que hace que no quieras pensar en otras cosas.",
  str_homestory_810001001_15_dialog_content = "Siento que otros también me han dicho esto.",
  str_homestory_810001001_16_dialog_content = "Es una especie de consuelo que se relaciona con el dicho Astra que todo el mundo sabe:",
  str_homestory_810001001_17_dialog_content = "La espada más amenazante es una cama cómoda, donde muchos héroes se han desvanecido.",
  str_homestory_810001001_18_dialog_content = "Las personas olvidan sus deberes cuando se sienten cómodas, especialmente los tontos que solo ven lo que tienen enfrente. <sprite=emo_wuyu size=60 />.",
  str_homestory_810001001_19_dialog_content = "¿Qué te hizo pensar en esto de todos modos?",
  str_homestory_810001001_20_dialog_content = "Ayer estaba junto al río y vi algunas malas hierbas flotando en el agua.",
  str_homestory_810001001_21_dialog_content = "Y podría haber habido una pieza de metal que estaba rebotando en la superficie del agua con las malas hierbas.",
  str_homestory_810001001_22_dialog_content = "Creo que veo tu punto ahora.",
  str_homestory_810001001_23_dialog_content = "Si puedes pensar en una analogía como esta, entonces es muy obvio que no eres esa pieza de metal.",
  str_homestory_810001001_24_dialog_content = "Después de todo, controlamos qué acciones tomamos individualmente, ¿no es así?",
  str_homestory_810001001_25_dialog_content = "Sabía que no me había equivocado contigo, Snowball. Eres diferente de esos otros tontos.",
  str_homestory_816601001_0_dialog_content = "Nada mal...",
  str_homestory_816601001_1_dialog_content = "Parece que estás de buen humor hoy.",
  str_homestory_816601001_2_dialog_content = "¿Supongo que finalmente te has establecido aquí?",
  str_homestory_816601001_3_dialog_content = "¡No intentes adivinar lo que está pensando un extrozoólogo!",
  str_homestory_816601001_4_dialog_content = "Ni siquiera he dicho nada... <sprite=emo_shengqi size=60 />",
  str_homestory_816601001_5_dialog_content = "Pero tus acciones han demostrado que estás de buen humor.",
  str_homestory_816601001_6_dialog_content = "¿Ah?",
  str_homestory_816601001_7_dialog_content = "No me parece.",
  str_homestory_816601001_8_dialog_content = "Bien de acuerdo. Tengo algunas preguntas para ti.",
  str_homestory_816601001_9_dialog_content = "¿Preguntas?",
  str_homestory_816601001_10_dialog_content = "Pregunte y veré si puedo responder.",
  str_homestory_816601001_11_dialog_content = "que hacen los perros <sprite=emo_goutou size=60 /> hacer cuando están felices?",
  str_homestory_816601001_12_dialog_content = "¿Ni siquiera sabes eso?",
  str_homestory_816601001_13_dialog_content = "Cuando están felices, que es muy a menudo, mueven la cola. Es obvio, también.",
  str_homestory_816601001_14_dialog_content = "¿Qué hay de los gatos? <sprite=emo_baimao size=60 />?",
  str_homestory_816601001_15_dialog_content = "Eso es fácil, también.",
  str_homestory_816601001_16_dialog_content = "Son muy cautelosos, pero si puedes hacerlos felices...",
  str_homestory_816601001_17_dialog_content = "Se acercarán a ti y comenzarán a ronronear.",
  str_homestory_816601001_18_dialog_content = "¿Qué tal una bestia maravillosa como Kyllo?",
  str_homestory_816601001_19_dialog_content = "De hecho, es muy obvio cuando Kyllo está feliz.",
  str_homestory_816601001_20_dialog_content = "¡Puedo decir cómo se siente Kyllo con los ojos cerrados, en realidad!",
  str_homestory_816601001_21_dialog_content = "Bueno, bestias maravillosas o no...",
  str_homestory_816601001_22_dialog_content = "Supongo que los animales lo demuestran cuando están felices.",
  str_homestory_816601001_23_dialog_content = "... ¿Por qué tengo la sensación de que tienes otras intenciones con estas preguntas?",
  str_homestory_816601001_24_dialog_content = "¡Para nada!",
  str_homestory_816601001_25_dialog_content = "Solo quería ver si mis observaciones sobre ti eran correctas.",
  str_homestory_816601001_26_dialog_content = "¿De mí?",
  str_homestory_816601001_27_dialog_content = "Soy extrozoólogo, y normalmente soy yo el que observa...",
  str_homestory_816601001_28_dialog_content = "Entonces, ¿por qué me estás observando?",
  str_homestory_816601001_29_dialog_content = "Quizás...",
  str_homestory_816601001_30_option_content = "Por curiosidad.",
  str_homestory_816601001_31_dialog_content = "Muestras muchas más emociones que yo, así que estoy muy intrigado.",
  str_homestory_816601001_32_option_content = "Boredom",
  str_homestory_816601001_33_dialog_content = "Eres un niño muy interesante, así que tuve ganas de observar tu comportamiento.",
  str_homestory_816601001_34_dialog_content = "Y según lo que he visto...",
  str_homestory_816601001_35_dialog_content = "Tus orejas de conejo se animan cuando estás feliz.",
  str_homestory_816601001_36_dialog_content = "¡Ahhhhh! <sprite=emo_hanshui size=60 /> N-No, por favor no mires mis orejas...",
  str_homestory_816601001_37_dialog_content = "...",
  str_homestory_816601001_38_dialog_content = "¡Espera!",
  str_homestory_816601001_39_dialog_content = "¡Mis oídos siempre están de pie!",
  str_homestory_816601001_40_dialog_content = "Al cubrirlos ahora, ha admitido que está de buen humor.",
  str_homestory_816601001_41_dialog_content = "Así que me engañaste, PlayerName!",
  str_homestory_816601001_42_dialog_content = "Lo siento.",
  str_homestory_816601001_43_dialog_content = "Para demostrar que me disculpo, bajaré por los toboganes contigo.",
  str_homestory_816601001_44_dialog_content = "Eso suena bien.",
  str_homestory_816701001_0_dialog_content = "¿Estás dormido?",
  str_homestory_816701001_1_dialog_content = "una buena pregunta",
  str_homestory_816701001_2_dialog_content = "Si el viento es como respira el mundo...",
  str_homestory_816701001_3_dialog_content = "Entonces el mundo probablemente se esté desplazando hacia la tierra de los sueños en este momento. <sprite=emo_kun size=60 />.",
  str_homestory_816701001_4_dialog_content = "Ah, entonces estás despierto.",
  str_homestory_816701001_5_dialog_content = "Pensé que te habías quedado dormido en el sillón.",
  str_homestory_816701001_6_dialog_content = "El océano es como un tirano que nunca se despierta.",
  str_homestory_816701001_7_dialog_content = "Si tienes el placer de sentir las ráfagas, como cuchillas, rozando tu rostro en el océano...",
  str_homestory_816701001_8_dialog_content = "Jeno?",
  str_homestory_816701001_9_dialog_content = "¿Sí, buscador de adivinación?",
  str_homestory_816701001_10_dialog_content = "No estoy seguro de entender lo que acabas de decir.",
  str_homestory_816701001_11_dialog_content = "En realidad, sé que no entendí nada.",
  str_homestory_816701001_12_dialog_content = "Las palabras ya no pertenecen a la garganta que las formó una vez que salen de la boca.",
  str_homestory_816701001_13_dialog_content = "Y luego son interpretados por el cerebro que los recibe tan pronto como entran en los oídos de otra persona.",
  str_homestory_816701001_14_dialog_content = "Este mundo es un gran festival de fantasías.",
  str_homestory_816701001_15_dialog_content = "Al menos eso es lo que siempre he pensado.",
  str_homestory_816701001_16_option_content = "(Sin entender esto en absoluto)",
  str_homestory_816701001_17_dialog_content = "Eso es profundo. Realmente no sé de lo que estás hablando.",
  str_homestory_816701001_18_option_content = "(Comprendido)",
  str_homestory_816701001_19_dialog_content = "Piensas que las personas nunca se entenderán realmente entre sí.",
  str_homestory_816701001_20_dialog_content = "Mi querido oyente.",
  str_homestory_816701001_21_dialog_content = "No importa, solo nos falta disfrutar.",
  str_homestory_816701001_22_dialog_content = "Ejem. De alguna manera pienso...",
  str_homestory_816701001_23_dialog_content = "Que a veces ni sabes de lo que hablas.",
  str_homestory_816701001_24_dialog_content = "Quizás a veces no tengo las palabras adecuadas.",
  str_homestory_816701001_25_dialog_content = "Pero mi magia nunca defraudará a nadie. <sprite=emo_mojing size=60 />.",
  str_homestory_816701001_26_dialog_content = "Eso es cierto.",
  str_homestory_816701001_27_dialog_content = "¿Hmm? ¡Esperar!",
  str_homestory_816701001_28_dialog_content = "No creaste una ilusión para engañarme, ¿verdad?",
  str_homestory_816701001_29_dialog_content = "De hecho, ¡has estado durmiendo en la tumbona todo el tiempo!",
  str_homestory_816701001_30_dialog_content = "Ah, ¿me has pillado?",
  str_homestory_816701001_31_dialog_content = "¡Lo sabía!",
  str_homestory_816701001_32_dialog_content = "Espera, no he terminado.",
  str_homestory_816701001_33_dialog_content = "Tienes razón en una cosa: hay alguien durmiendo en la tumbona.",
  str_homestory_816701001_34_dialog_content = "Pero...",
  str_homestory_816701001_35_dialog_content = "¿Cómo sabes que no eres... tú?",
  str_homestory_816701001_36_dialog_content = "¡No puede ser!",
  str_homestory_816701001_37_dialog_content = "¡Porque te vi durmiendo en él desde lejos!",
  str_homestory_816701001_38_dialog_content = "¿Recuerdas lo que estaba pasando antes de eso, entonces?",
  str_homestory_816701001_39_dialog_content = "Era...",
  str_homestory_816701001_40_dialog_content = "Espera, ¿qué estaba haciendo?",
  str_homestory_816701001_41_dialog_content = "Jajajaja",
  str_homestory_816701001_42_dialog_content = "¿Me hipnotizaste sin que yo lo supiera?",
  str_homestory_816701001_43_dialog_content = "por favor despiértame... <sprite=emo_tanqi size=60 />",
  str_homestory_816701001_44_dialog_content = "Eso es fácil. Solo toma una siesta en la tumbona.",
  str_homestory_816701001_45_dialog_content = "Bien...",
  str_homestory_816801001_0_dialog_content = "¿Qué estás haciendo?",
  str_homestory_816801001_1_dialog_content = "Aquí estás, PlayerName.",
  str_homestory_816801001_2_dialog_content = "¡Este lugar se ve muy bien! Especialmente esa cosa de ahí...",
  str_homestory_816801001_3_dialog_content = "Reproduce música cuando lo tocas. <sprite=emo_yinfu size=60 />!",
  str_homestory_816801001_4_dialog_content = "¿Oh sí? Me alegra escucharlo.",
  str_homestory_816801001_5_dialog_content = "Pensé que podría ocupar demasiado espacio...",
  str_homestory_816801001_6_dialog_content = "Y que a nadie le gustaría.",
  str_homestory_816801001_7_dialog_content = "¡Me gusta!",
  str_homestory_816801001_8_dialog_content = "¡No lo amo!",
  str_homestory_816801001_9_dialog_content = "¿Me mostrarás cómo usarlo?",
  str_homestory_816801001_10_dialog_content = "Yo tampoco estoy muy familiarizado con eso.",
  str_homestory_816801001_11_dialog_content = "hay manual o algo?",
  str_homestory_816801001_12_dialog_content = "Realmente no...",
  str_homestory_816801001_13_dialog_content = "Entonces, ¿tendremos que resolverlo por nuestra cuenta?",
  str_homestory_816801001_14_dialog_content = "Sin embargo, se siente más divertido de esa manera.",
  str_homestory_816801001_15_dialog_content = "No sabía que te gustaba tanto la música.",
  str_homestory_816801001_16_dialog_content = "Me encantan las cosas hermosas. Y...",
  str_homestory_816801001_17_dialog_content = "Si pudiera aprender a usarlo, entonces implementarlo en mis actuaciones...",
  str_homestory_816801001_18_dialog_content = "¡Haría que nuestro acto de apertura fuera más agradable!",
  str_homestory_816801001_19_dialog_content = "Siempre estás pensando en el circo.",
  str_homestory_816801001_20_dialog_content = "Realmente debes amar lo que haces.",
  str_homestory_816801001_21_dialog_content = "Honestamente, nunca lo he pensado mucho <sprite=emo_wuzui size=60 />.",
  str_homestory_816801001_22_dialog_content = "Siempre creí que nací para proteger la Esmeralda.",
  str_homestory_816801001_23_dialog_content = "Lo hago reparándolo y manteniéndolo cuando está acoplado...",
  str_homestory_816801001_24_dialog_content = "Y dispararle a cualquiera a bordo con malas intenciones con mi Aqua Blaster.",
  str_homestory_816801001_25_dialog_content = "Actuando con el circo para que más sepan de la Esmeralda...",
  str_homestory_816801001_26_dialog_content = "es otra forma de protegerlo.",
  str_homestory_816801001_27_dialog_content = "Entonces eso es...",
  str_homestory_816801001_28_dialog_content = "La protección viene en muchas formas y formas.",
  str_homestory_816801001_29_dialog_content = "Por ejemplo, haces un gran trabajo protegiendo Cloud Gardens.",
  str_homestory_816801001_30_dialog_content = "Pero es posible que desee limpiar el fondo del río pronto.",
  str_homestory_816801001_31_dialog_content = "Cuando estaba llenando el blaster con agua hace un momento...",
  str_homestory_816801001_32_dialog_content = "Encontré algo brillante en el fondo del río.",
  str_homestory_816801001_33_dialog_content = "¿Algo brillante...?",
  str_homestory_816801001_34_dialog_content = "Hablando del río, ¿quieres refrescarte?",
  str_homestory_816801001_35_option_content = "¡Mucho!",
  str_homestory_816801001_36_dialog_content = "Estaba trabajando y hacía mucho calor.",
  str_homestory_816801001_37_dialog_content = "Eso es fácil.",
  str_homestory_816801001_38_dialog_content = "¡Toma esto!",
  str_homestory_816801001_39_dialog_content = "¡¿Qué?!",
  str_homestory_816801001_40_option_content = "Realmente no...",
  str_homestory_816801001_41_dialog_content = "No me vas a disparar con la pistola de agua, ¿verdad?",
  str_homestory_816801001_42_dialog_content = "¿Qué otra cosa?",
  str_homestory_816801001_43_dialog_content = "Estoy bien, de verdad.",
  str_homestory_816801001_44_dialog_content = "solo estaré junto al río <sprite=emo_pugongying size=60 />!",
  str_homestory_801602001_0_dialog_content = "Kafka?",
  str_homestory_801602001_1_dialog_content = "¡Ah!",
  str_homestory_801602001_2_dialog_content = "Me asustaste, PlayerName.",
  str_homestory_801602001_3_dialog_content = "Lo lamento.",
  str_homestory_801602001_4_dialog_content = "¿Qué tal?",
  str_homestory_801602001_5_option_content = "Bueno...",
  str_homestory_801602001_6_dialog_content = "Me acabo de dar cuenta de que has estado parado aquí por un tiempo.",
  str_homestory_801602001_7_dialog_content = "Y tenía miedo de que te diera un golpe de calor.",
  str_homestory_801602001_8_dialog_content = "No te preocupes, solo estoy protegiendo algo.",
  str_homestory_801602001_9_option_content = "Estoy bien.",
  str_homestory_801602001_10_dialog_content = "Me acabo de dar cuenta de que has estado parado aquí por un tiempo.",
  str_homestory_801602001_11_dialog_content = "Así que tenía curiosidad por lo que estás haciendo.",
  str_homestory_801602001_12_dialog_content = "Claramente, estoy protegiendo algo.",
  str_homestory_801602001_13_dialog_content = "¿Cuidando algo?",
  str_homestory_801602001_14_dialog_content = "Gracias, pero Cloud Gardens es muy seguro...",
  str_homestory_801602001_15_dialog_content = "No tienes que alarmarte tanto.",
  str_homestory_801602001_16_dialog_content = "No estoy haciendo esto por Cloud Gardens. Es para...",
  str_homestory_801602001_17_dialog_content = "Un grupo de conejitos.",
  str_homestory_801602001_18_dialog_content = "¿Conejitos? ¿Dónde están?",
  str_homestory_801602001_19_dialog_content = "Están de vuelta en sus madrigueras",
  str_homestory_801602001_20_dialog_content = "No te preocupes, nunca los encontrarás.",
  str_homestory_801602001_21_dialog_content = "no soy su enemigo...",
  str_homestory_801602001_22_dialog_content = "Te gustan mucho los bichos, ¿verdad?",
  str_homestory_801602001_23_dialog_content = "¿Yo?",
  str_homestory_801602001_24_dialog_content = "Simplemente no quiero que vayan a un lugar al que no deben ir.",
  str_homestory_801602001_25_dialog_content = "Eres casi como un... pastor.",
  str_homestory_801602001_26_dialog_content = "Con tu gran perro <sprite=emo_goutou size=60 />, llevando a los animales a un lugar seguro...",
  str_homestory_801602001_27_dialog_content = "¿Pastor? No, definitivamente no.",
  str_homestory_801602001_28_dialog_content = "Por cierto, vi algo brillante en el fondo del río.",
  str_homestory_801602001_29_dialog_content = "¿Descubrirás qué es?",
  str_homestory_801602001_30_dialog_content = "No dejes que asuste a los bichos de la zona.",
  str_homestory_801602001_31_dialog_content = "¡De acuerdo!",
  str_homestory_817001001_0_dialog_content = "Que rara ocasión...",
  str_homestory_817001001_1_dialog_content = "¡¿Quién está ahí?!",
  str_homestory_817001001_2_dialog_content = "Soy yo, PlayerName...",
  str_homestory_817001001_3_dialog_content = "Disculpas, me pongo nervioso cuando escucho pasos que se detienen repentinamente.",
  str_homestory_817001001_4_dialog_content = "Relájate, es muy seguro en Cloud Gardens.",
  str_homestory_817001001_5_dialog_content = "Sí, había oído hace un tiempo",
  str_homestory_817001001_6_dialog_content = "que el Caelestite que apareció de la nada construyó un escondite exquisito en Eraveil.",
  str_homestory_817001001_7_dialog_content = "No lo habría creído si no lo hubiera visto por mí mismo.",
  str_homestory_817001001_8_dialog_content = "No esperaba tales habilidades de gestión de alguien tan joven como tú.",
  str_homestory_817001001_9_option_content = "Reconocer",
  str_homestory_817001001_10_dialog_content = "Gracias por el cumplido.",
  str_homestory_817001001_11_dialog_content = "No es humilde, por lo que veo.",
  str_homestory_817001001_12_dialog_content = "Aún así, me gusta el coraje en ti.",
  str_homestory_817001001_13_option_content = "Negar",
  str_homestory_817001001_14_dialog_content = "En realidad, mis amigos me ayudaron mucho.",
  str_homestory_817001001_15_dialog_content = "¿En serio?",
  str_homestory_817001001_16_dialog_content = "Es raro ver jóvenes con tanta humildad.",
  str_homestory_817001001_17_dialog_content = "No es de extrañar que Cloud Gardens pueda mantener su serenidad y paz.",
  str_homestory_817001001_18_dialog_content = "Sin acoso de Eclipsites, sin guerras de pandillas.",
  str_homestory_817001001_19_dialog_content = "Cuando pienso en ello, no he tenido la oportunidad de disfrutar el cálido sol en mi piel.",
  str_homestory_817001001_20_dialog_content = "en lo que parece toda una vida.",
  str_homestory_817001001_21_dialog_content = "Por eso debes tratar de relajarte.",
  str_homestory_817001001_22_dialog_content = "¿Relax?",
  str_homestory_817001001_23_dialog_content = "Sabes, recién ahora me doy cuenta de que",
  str_homestory_817001001_24_dialog_content = "permanecer alerta se ha convertido en una segunda naturaleza para mí.",
  str_homestory_817001001_25_dialog_content = "Aunque he dejado Euphoria...",
  str_homestory_817001001_26_dialog_content = "mis viejos hábitos se han quedado conmigo.",
  str_homestory_817001001_27_dialog_content = "Es mirar hacia abajo a todos los que están cerca desde un punto de vista...",
  str_homestory_817001001_28_dialog_content = "¿Un hábito que también has conservado de tu tiempo en Euphoria?",
  str_homestory_817001001_29_dialog_content = "Ya veo, vigilar a tus invitados debe ser uno de tus deberes como líder de este lugar.",
  str_homestory_817001001_30_dialog_content = "Supongo que no puedo subestimarte en absoluto.",
  str_homestory_817001001_31_dialog_content = "No, eso no es lo que quise decir.",
  str_homestory_817001001_32_dialog_content = "Acabo de verte en la torre de vigilancia.",
  str_homestory_817001001_33_dialog_content = "Relájate, no estoy tratando de empezar nada.",
  str_homestory_817001001_34_dialog_content = "Solía disfrutar de estar de pie en lo alto, viendo todos los acontecimientos de Euphoria desarrollarse ante mí.",
  str_homestory_817001001_35_dialog_content = "Normalmente, verías...",
  str_homestory_817001001_36_dialog_content = "una miríada de codicia y deseo acumulándose bajo las densas nubes de lluvia.",
  str_homestory_817001001_37_dialog_content = "Pero no aquí.",
  str_homestory_817001001_38_dialog_content = "Es tranquilo hasta donde mis ojos pueden ver.",
  str_homestory_817001001_39_dialog_content = "tengo una peticion, PlayerName.",
  str_homestory_817001001_40_dialog_content = "Solo hazme saber que necesitas.",
  str_homestory_817001001_41_dialog_content = "¿Puedo traer a los niños de la iglesia conmigo la próxima vez?",
  str_homestory_817001001_42_dialog_content = "¡Seguro!",
  str_homestory_817001001_43_dialog_content = "Ah, y otra cosa...",
  str_homestory_817001001_44_dialog_content = "Vi algo junto al río que podría interesarte.",
  str_homestory_817001001_45_dialog_content = "Todavía debería estar allí si vas ahora.",
  str_homestory_817001001_46_dialog_content = "¿En serio? ¡Le daré un vistazo!",
  str_homestory_817101001_0_dialog_content = "¿Casta?",
  str_homestory_817101001_1_dialog_content = "Oye, eres tú.",
  str_homestory_817101001_2_dialog_content = "¿Cómo te estás instalando en Cloud Gardens?",
  str_homestory_817101001_3_dialog_content = "Mal.",
  str_homestory_817101001_4_dialog_content = "¿Vaya? ¿Cuál parece ser el problema?",
  str_homestory_817101001_5_dialog_content = "¡Lo rectificaré!",
  str_homestory_817101001_6_dialog_content = "Por un lado, la niebla aquí...",
  str_homestory_817101001_7_dialog_content = "siempre parece disiparse.",
  str_homestory_817101001_8_dialog_content = "La incesante luz del sol hace que mis ojos se sientan secos.",
  str_homestory_817101001_9_dialog_content = "Y no hay matones ni hooligans buscando problemas.",
  str_homestory_817101001_10_dialog_content = "No estoy haciendo ningún ejercicio decente en este lugar pacífico.",
  str_homestory_817101001_11_dialog_content = "Si esto continúa, mi precisión se deteriorará<sprite=emo_daomei size=60 />.",
  str_homestory_817101001_12_option_content = "Disculparse",
  str_homestory_817101001_13_dialog_content = "¡Lo lamento!",
  str_homestory_817101001_14_dialog_content = "La vida debe ser aburrida para ti aquí.",
  str_homestory_817101001_15_option_content = "Suspiro de resignación",
  str_homestory_817101001_16_dialog_content = "Pero...",
  str_homestory_817101001_17_dialog_content = "No puedo hacer nada al respecto...",
  str_homestory_817101001_18_dialog_content = "¿No puedes decir que estoy tratando de felicitarte?",
  str_homestory_817101001_19_dialog_content = "¿Ah?",
  str_homestory_817101001_20_dialog_content = "Me he acostumbrado tanto a la vida en los barrios bajos...",
  str_homestory_817101001_21_dialog_content = "que no sé qué hacer en un lugar que es realmente seguro y cómodo.",
  str_homestory_817101001_22_dialog_content = "Lo cual es un poco divertido, sinceramente.",
  str_homestory_817101001_23_dialog_content = "¡Bueno, en realidad hay muchas cosas interesantes que hacer aquí!",
  str_homestory_817101001_24_dialog_content = "Sí, lo he estado descubriendo últimamente.",
  str_homestory_817101001_25_dialog_content = "Este cartel es intrigante por la forma en que los colores y las imágenes se unen...",
  str_homestory_817101001_26_dialog_content = "Debe ser un anuncio de casino, ¿verdad?",
  str_homestory_817101001_27_dialog_content = "...",
  str_homestory_817101001_28_dialog_content = "¿Qué pasa con tu expresión <sprite=emo_baiyan size=60 />?",
  str_homestory_817101001_29_dialog_content = "Solo quiero ganar algunos recuerdos para los niños de la iglesia.",
  str_homestory_817101001_30_dialog_content = "No voy a romper tu banco ni nada.",
  str_homestory_817101001_31_dialog_content = "Uh, esto es sólo para mostrar.",
  str_homestory_817101001_32_dialog_content = "Aquí no tenemos casinos...",
  str_homestory_817101001_33_dialog_content = "¿Qué?",
  str_homestory_817101001_34_dialog_content = "¿Qué tal pescar en su lugar?",
  str_homestory_817101001_35_dialog_content = "¿Pescar?",
  str_homestory_817101001_36_dialog_content = "Ya sabes, lanzar el cebo y esperar a que los peces muerdan.",
  str_homestory_817101001_37_dialog_content = "¡Es una buena prueba de suerte!",
  str_homestory_817101001_38_dialog_content = "Bueno, ¡cualquier prueba de suerte es algo que no puedo dejar pasar!",
  str_homestory_817101001_39_dialog_content = "Ah, casi se me olvida...",
  str_homestory_817101001_40_dialog_content = "¡Eres bendecido por Lady Luck<sprite=emo_dianzan size=60 />!",
  str_homestory_817101001_41_dialog_content = "Veo que hoy es un mal día para los peces...",
  str_homestory_813001001_0_dialog_content = "Se ve bien, ¿no?",
  str_homestory_813001001_1_dialog_content = "¿Ah?",
  str_homestory_813001001_2_dialog_content = "Ejem...",
  str_homestory_813001001_3_dialog_content = "Oh, es tú.",
  str_homestory_813001001_4_dialog_content = "No seas tan ruidoso la próxima vez. ¿Estás tratando de asustarme hasta la muerte?",
  str_homestory_813001001_5_dialog_content = "¡No digas que nunca te lo advertí!",
  str_homestory_813001001_6_dialog_content = "Si le das a alguien un infarto...",
  str_homestory_813001001_7_dialog_content = "¡Eso podría ser una cadena perpetua!",
  str_homestory_813001001_8_dialog_content = "Gracias por la advertencia...",
  str_homestory_813001001_9_dialog_content = "Ahora que lo sabes, ¿me necesitabas para algo?",
  str_homestory_813001001_10_dialog_content = "¿Cloud Gardens necesita mis habilidades de juez?",
  str_homestory_813001001_11_dialog_content = "No, en absoluto.",
  str_homestory_813001001_12_dialog_content = "Te vi reflexionar y gesticular ante esta estatua...",
  str_homestory_813001001_13_dialog_content = "Así que solo tenía curiosidad.",
  str_homestory_813001001_14_dialog_content = "Gesticular? ¿Quién estaba gesticulando?",
  str_homestory_813001001_15_dialog_content = "La rumorología es contra la ley.",
  str_homestory_813001001_16_dialog_content = "De acuerdo con el Código de Reputación de Lumopolis, aquellos que calumnian a otros...",
  str_homestory_813001001_17_dialog_content = "será condenado a 100 días de cárcel o multado con un millón de Nightium.",
  str_homestory_813001001_18_dialog_content = "¿Qué?",
  str_homestory_813001001_19_option_content = "Refutar",
  str_homestory_813001001_20_dialog_content = "¡Pero estamos en Cloud Gardens, no en Lumopolis!",
  str_homestory_813001001_21_dialog_content = "PP-¡Absurdo!",
  str_homestory_813001001_22_dialog_content = "¿Cómo puedes tolerar no tener ningún tipo de leyes en Cloud Gardens?",
  str_homestory_813001001_23_option_content = "Cumplir",
  str_homestory_813001001_24_dialog_content = "Supongo que me equivoqué entonces...",
  str_homestory_813001001_25_dialog_content = "Tienes que tener más cuidado, PlayerName.",
  str_homestory_813001001_26_dialog_content = "O estarás rodeado de sordidez.",
  str_homestory_813001001_27_dialog_content = "¡Esa sería la caída de tu dominio!",
  str_homestory_813001001_28_dialog_content = "Cierto...",
  str_homestory_813001001_29_dialog_content = "Decir...",
  str_homestory_813001001_30_dialog_content = "¿Qué tal si me das la estatua?",
  str_homestory_813001001_31_dialog_content = "Y nos olvidaremos de todo el asunto.",
  str_homestory_813001001_32_dialog_content = "¿Qué? Pero...",
  str_homestory_813001001_33_dialog_content = "La estatua es muy importante para mí.",
  str_homestory_813001001_34_dialog_content = "Representa a cierto antepasado Caelestita.",
  str_homestory_813001001_35_dialog_content = "Las tierras sin ley son verdaderamente incomprensibles.",
  str_homestory_813001001_36_dialog_content = "Si realmente te gusta la estatua...",
  str_homestory_813001001_37_dialog_content = "Puedo hacerte una réplica con barro.",
  str_homestory_813001001_38_dialog_content = "Bueno...",
  str_homestory_813001001_39_dialog_content = "Esa es una solución<sprite=emo_woshou size=60 />.",
  str_homestory_813001001_40_dialog_content = "No me hagas esperar.",
  str_homestory_812101001_0_dialog_content = "¿Paloma?",
  str_homestory_812101001_1_dialog_content = "Oh, es tú.",
  str_homestory_812101001_2_dialog_content = "Perdóname...",
  str_homestory_812101001_3_dialog_content = "¿Te desperte?",
  str_homestory_812101001_4_dialog_content = "Sabes mejor que fingir que te importa cuando hablas conmigo.",
  str_homestory_812101001_5_dialog_content = "Solo escúpelo.",
  str_homestory_812101001_6_dialog_content = "Quieres saber cómo me gusta Cloud Gardens hasta ahora, ¿verdad?",
  str_homestory_812101001_7_option_content = "Negar",
  str_homestory_812101001_8_dialog_content = "Realmente no...",
  str_homestory_812101001_9_dialog_content = "Sólo quería decir hola.",
  str_homestory_812101001_10_option_content = "Admitir",
  str_homestory_812101001_11_dialog_content = "Estás bien...",
  str_homestory_812101001_12_dialog_content = "Me importa tu opinión.",
  str_homestory_812101001_13_dialog_content = "Ya sea que lo admitas o no, diré esto...",
  str_homestory_812101001_14_dialog_content = "...",
  str_homestory_812101001_15_dialog_content = "No odio el lugar.",
  str_homestory_812101001_16_dialog_content = "¡Eso es genial!",
  str_homestory_812101001_17_dialog_content = "Pensé que lo ibas a desarmar...",
  str_homestory_812101001_18_dialog_content = "¿Qué dijiste?",
  str_homestory_812101001_19_dialog_content = "Ah, quiero decir...",
  str_homestory_812101001_20_dialog_content = "¡Esperaba una crítica constructiva tuya!",
  str_homestory_812101001_21_dialog_content = "No es que no tenga nada que decir.",
  str_homestory_812101001_22_dialog_content = "Pero como eres bueno con el desarrollo, la construcción y la gestión...",
  str_homestory_812101001_23_dialog_content = "¿Estás interesado en expulsar a los nobles de Lumopolis y apoderarte de Azurite?",
  str_homestory_812101001_24_dialog_content = "¡¿Qué?!",
  str_homestory_812101001_25_dialog_content = "Ni siquiera he considerado algo así.",
  str_homestory_812101001_26_dialog_content = "He conocido a muchos que dijeron una cosa e hicieron lo contrario...",
  str_homestory_812101001_27_dialog_content = "Una demasiadas veces.",
  str_homestory_812101001_28_dialog_content = "Yo... solo trato de proteger mi propia casa.",
  str_homestory_812101001_29_dialog_content = "Supongo que los de Lumopolis también sienten lo mismo por su hogar.",
  str_homestory_812101001_30_dialog_content = "¿Hogar?",
  str_homestory_812101001_31_dialog_content = "Soy alguien a quien echaron de su casa.",
  str_homestory_812101001_32_dialog_content = "\"Hogar\" se ha convertido durante mucho tiempo en una palabra sin sentido para mí.",
  str_homestory_812101001_33_dialog_content = "Recuerda Paloma, todavía tienes Cloud Gardens.",
  str_homestory_812101001_34_dialog_content = "Si te gustaria...",
  str_homestory_812101001_35_dialog_content = "¡puedes tratar a Cloud Gardens como tu hogar!",
  str_homestory_812101001_36_dialog_content = "¿Así que no crees que nadie más va a intentar quitártelo?",
  str_homestory_812101001_37_dialog_content = "Sólo llegó a donde está hoy gracias a todos mis amigos.",
  str_homestory_812101001_38_dialog_content = "Por eso quiero que Cloud Gardens sea un refugio seguro para todos.",
  str_homestory_812101001_39_dialog_content = "Oh, Caelestite, seguro que eres increíblemente ingenuo. <sprite=emo_baiyan size=60 />",
  str_homestory_812101001_40_dialog_content = "Quizás...",
  str_homestory_812101001_41_dialog_content = "Puedo agregar una definición a \"casa\" en mi diccionario.",
  str_homestory_812101001_42_dialog_content = "Cuál podría ser...",
  str_homestory_812101001_43_dialog_content = "Jardines de nubes.",
  str_homestory_812001001_0_dialog_content = "Ahí estás, Hedy.",
  str_homestory_812001001_1_dialog_content = "Argh...",
  str_homestory_812001001_2_dialog_content = "¿Qué pasa, Hedy?",
  str_homestory_812001001_3_dialog_content = "Noche Blanca en lo alto...",
  str_homestory_812001001_4_dialog_content = "¡Esa máquina sigue gruñéndome malvadamente!",
  str_homestory_812001001_5_dialog_content = "Dime, ¿es una reliquia maligna de la Era Antigua, PlayerName?",
  str_homestory_812001001_6_dialog_content = "Si esto sigue...",
  str_homestory_812001001_7_dialog_content = "Tendré que convocar al Caballero de la Luz para destruirlo<sprite=emo_shengqi size=60 />.",
  str_homestory_812001001_8_option_content = "Consola",
  str_homestory_812001001_9_dialog_content = "No te preocupes, Hedy.",
  str_homestory_812001001_10_dialog_content = "Es solo una máquina de helados.",
  str_homestory_812001001_11_option_content = "Disculparse",
  str_homestory_812001001_12_dialog_content = "Lo siento, olvidé decírtelo.",
  str_homestory_812001001_13_dialog_content = "¡Esta es una máquina de helados!",
  str_homestory_812001001_14_dialog_content = "¿Una... máquina de helados?<sprite=emo_wuzui size=60 />",
  str_homestory_812001001_15_dialog_content = "Sí. Simplemente coloque una taza encima y presione el botón.",
  str_homestory_812001001_16_dialog_content = "Entonces la máquina te hará un delicioso helado.",
  str_homestory_812001001_17_dialog_content = "En realidad, ya supuse que era una máquina de helados por los copos de nieve que tenía.",
  str_homestory_812001001_18_dialog_content = "Pero no salió ningún helado...",
  str_homestory_812001001_19_dialog_content = "Así que pensé que podría ser una creación diabólica disfrazada de máquina de helados.",
  str_homestory_812001001_20_dialog_content = "¿Se quedó sin helado otra vez?",
  str_homestory_812001001_21_dialog_content = "\"Otra vez\"?",
  str_homestory_812001001_22_dialog_content = "Bueno, el helado que hace es tan bueno...",
  str_homestory_812001001_23_dialog_content = "Si no llega lo suficientemente temprano, no obtendrá ninguno.",
  str_homestory_812001001_24_dialog_content = "Ha estado mucho más fresco en los últimos días, pensé que menos gente lo usaría.",
  str_homestory_812001001_25_dialog_content = "Pero supongo que sigue siendo muy popular.",
  str_homestory_812001001_26_dialog_content = "¿Qué sabor te gusta, Hedy?",
  str_homestory_812001001_27_dialog_content = "Iré a buscar los ingredientes para ello.",
  str_homestory_812001001_28_dialog_content = "Mi sabor de helado favorito...",
  str_homestory_812001001_29_dialog_content = "Sí, ¿qué te gusta?",
  str_homestory_812001001_30_dialog_content = "Vainilla, chocolate, matcha, naranja, frijol rojo...",
  str_homestory_812001001_31_dialog_content = "¡Los amo a todos!",
  str_homestory_812001001_32_dialog_content = "Tantos sabores, ya veo...",
  str_homestory_812001001_33_dialog_content = "¿Nunca has comido helado antes? Estos son todos los sabores básicos...",
  str_homestory_812001001_34_dialog_content = "¿Q-Qué quieres decir?",
  str_homestory_812001001_35_dialog_content = "¡Por supuesto que he tenido helado antes!",
  str_homestory_812001001_36_dialog_content = "Creo que todos los sabores que mencionaste eran demasiado simples.",
  str_homestory_812001001_37_dialog_content = "Solo he probado helado con sabor a \"antiguo tomo\" antes.",
  str_homestory_812001001_38_dialog_content = "Pero no creo que la máquina pueda hacer eso.<sprite=emo_emo size=60 />",
  str_homestory_812001001_39_dialog_content = "¿Sabor a \"tomos antiguos\"?",
  str_homestory_812001001_40_dialog_content = "No puedo decir que haya tenido eso, nunca.",
  str_homestory_812001001_41_dialog_content = "Pero voy a tratar de encontrar la receta!",
  str_homestory_812001001_42_dialog_content = "Oh, eso está muy bien...",
  str_homestory_812001001_43_dialog_content = "¿Cómo?",
  str_homestory_812001001_44_dialog_content = "me gustaria saber como...",
  str_homestory_812001001_45_dialog_content = "Sabor a helado de vainilla, chocolate, matcha, naranja y frijol rojo.",
  str_homestory_806801001_0_dialog_content = "¿Wendy?",
  str_homestory_806801001_1_dialog_content = "¿Qué estás haciendo?",
  str_homestory_806801001_2_dialog_content = "Oh, eres tú, PlayerName.",
  str_homestory_806801001_3_dialog_content = "Busco un lugar para practicar vuelo vertical.",
  str_homestory_806801001_4_dialog_content = "Vuelo vertical?",
  str_homestory_806801001_5_dialog_content = "Sí, volando hacia arriba y hacia abajo.",
  str_homestory_806801001_6_dialog_content = "Es la última prueba de habilidades de vuelo.",
  str_homestory_806801001_7_dialog_content = "Sabes, siempre tengo miedo de que te caigas por volar tan alto.",
  str_homestory_806801001_8_dialog_content = "¿En serio?",
  str_homestory_806801001_9_dialog_content = "Relájate, es pan comido para mí.",
  str_homestory_806801001_10_dialog_content = "¿O has olvidado que soy el misil del huracán del desierto<sprite=emo_mojing size=60 />?",
  str_homestory_806801001_11_option_content = "Olvidó",
  str_homestory_806801001_12_dialog_content = "Entonces voy a reiterar!",
  str_homestory_806801001_13_option_content = "no se olvidó",
  str_homestory_806801001_14_dialog_content = "¿Cómo podría olvidar un apodo tan impresionante?",
  str_homestory_806801001_15_dialog_content = "Reitero todo, por si acaso!",
  str_homestory_806801001_16_dialog_content = "¡Soy Wendy, el misil del huracán del desierto!",
  str_homestory_806801001_17_dialog_content = "¡La velocidad es mi marca registrada y la audacia es mi segundo nombre!",
  str_homestory_806801001_18_dialog_content = "Está bien, está bien, lo tengo.",
  str_homestory_806801001_19_dialog_content = "Dicho esto, ¿por qué practicar el vuelo vertical?",
  str_homestory_806801001_20_dialog_content = "Por motivos de entrega, por supuesto!",
  str_homestory_806801001_21_dialog_content = "¿Entregar una carta?",
  str_homestory_806801001_22_dialog_content = "¿Has visto la cosa con los largos tentáculos, PlayerName?",
  str_homestory_806801001_23_dialog_content = "¿Te refieres al globo de medusa?",
  str_homestory_806801001_24_dialog_content = "No me importa lo que sea.",
  str_homestory_806801001_25_dialog_content = "Si un cliente quiere que le entreguen una carta, la recibirá 100% garantizada.",
  str_homestory_806801001_26_dialog_content = "Así que conoces el globo, PlayerName?",
  str_homestory_806801001_27_dialog_content = "Quiero decir que conozco el mobiliario... ¿así que supongo?",
  str_homestory_806801001_28_dialog_content = "¿El globo se llama Kleken?",
  str_homestory_806801001_29_dialog_content = "Bueno, si el correo está dirigido a Kleken...",
  str_homestory_806801001_30_dialog_content = "Debe haber una confusión, porque Kleken no es un globo.",
  str_homestory_806801001_31_dialog_content = "¡¿Qué?! ¿En serio?",
  str_homestory_806801001_32_dialog_content = "El remitente dijo que Kleken tiene muchos tentáculos largos y suaves.",
  str_homestory_806801001_33_dialog_content = "Y a menudo usa un sombrero de copa negro.",
  str_homestory_806801001_34_dialog_content = "¿Hay un sombrero en el globo?",
  str_homestory_806801001_35_dialog_content = "Bueno, en cualquier caso, los globos de medusa no son el destinatario que estás buscando.",
  str_homestory_806801001_36_dialog_content = "Oh no, voy a establecer un nuevo récord personal por el tiempo de entrega más largo.",
  str_homestory_806801001_37_dialog_content = "tengo que correr",
  str_homestory_806801001_38_dialog_content = "Aunque vi algo brillante junto al río y quería comprobarlo...",
  str_homestory_806801001_39_dialog_content = "¡Tengo que hacer una entrega!<sprite=emo_dianzan size=60 />",
  str_homestory_817201001_0_dialog_content = "Hola, Lilica...",
  str_homestory_817201001_1_dialog_content = "Ven a comprobarlo, PlayerName!",
  str_homestory_817201001_2_dialog_content = "¿Qué tal?",
  str_homestory_817201001_3_dialog_content = "¡Mira, este juguete es muy divertido!",
  str_homestory_817201001_4_dialog_content = "¡Entonces, todo lo que tienes que hacer es golpearlo con un bate hasta que explote con una explosión de confeti!<sprite=emo_caitiao size=60 />",
  str_homestory_817201001_5_dialog_content = "¡A veces, también pueden aparecer dulces!",
  str_homestory_817201001_6_dialog_content = "Creo que nunca antes había visto un juguete como este.",
  str_homestory_817201001_7_dialog_content = "Bueno, eso tiene sentido ya que Windelion Dolls son adornos tradicionales exclusivos de Eraveil.",
  str_homestory_817201001_8_dialog_content = "Definitivamente no los encontrarás en ningún otro lado.",
  str_homestory_817201001_9_dialog_content = "¿Muñecas Windelion? Adornos tradicionales de Eraveil...",
  str_homestory_817201001_10_dialog_content = "¡Ahora que lo mencionas, creo que lo recuerdo vagamente!",
  str_homestory_817201001_11_dialog_content = "¿No tienen un festival en el que llenaban una olla de barro con semillas de antemano...",
  str_homestory_817201001_12_dialog_content = "y romperlo en el mismo día?",
  str_homestory_817201001_13_dialog_content = "¡Solo entonces pueden recibir la bendición de la naturaleza para una cosecha abundante ese año!",
  str_homestory_817201001_14_dialog_content = "¿Verdad?",
  str_homestory_817201001_15_dialog_content = "¡Vaya, Lilica! ¡No tengo idea de que conozcas tan bien las tradiciones de Eraveil!",
  str_homestory_817201001_16_dialog_content = "Jeje, yo no iría TAN lejos, ¿sabes?",
  str_homestory_817201001_17_dialog_content = "Una vez hice el papel de un profesor de historia en una película.",
  str_homestory_817201001_18_dialog_content = "No era un papel especial ni nada, ¡ni siquiera obtuve un primer plano! Pero necesitaba seguir dando conferencias en segundo plano.",
  str_homestory_817201001_19_dialog_content = "¡Recuerdo que el guión que me dieron hablaba de Eraveil y sus tradiciones!",
  str_homestory_817201001_20_dialog_content = "¡Oh, vaya! ¿Resulta que hay películas así por ahí?",
  str_homestory_817201001_21_dialog_content = "¿Cuál es el nombre de la película?",
  str_homestory_817201001_22_dialog_content = "*Se aclara la garganta* De todos modos, mis líneas eran solo parte del ruido de fondo, nada más.",
  str_homestory_817201001_23_dialog_content = "Dudo que puedas entender lo que estaba diciendo en la película...",
  str_homestory_817201001_24_option_content = "(Sentirse decepcionado)",
  str_homestory_817201001_25_dialog_content = "Bien entonces...",
  str_homestory_817201001_26_dialog_content = "Por un segundo, pensé que podría ver una película sobre Eraveil.",
  str_homestory_817201001_27_dialog_content = "Vamos, no te veas tan derrotado, PlayerName! ¿Ya has olvidado quién soy?",
  str_homestory_817201001_28_option_content = "(Sentirse emocionado)",
  str_homestory_817201001_29_dialog_content = "Incluso si solo fuera el ruido de fondo, que se mencionara a Eraveil en una película...",
  str_homestory_817201001_30_dialog_content = "¡Solo saber eso me hace increíblemente feliz!",
  str_homestory_817201001_31_dialog_content = "Realmente no es gran cosa, PlayerName... Además, ¿ya has olvidado quién soy?",
  str_homestory_817201001_32_dialog_content = "¡Soy el director de cine prometedor más brillante de nuestro tiempo! ¿Recuerda?",
  str_homestory_817201001_33_dialog_content = "¿Por qué no...",
  str_homestory_817201001_34_dialog_content = "rodar una película dedicada íntegramente a Eraveil?",
  str_homestory_817201001_35_dialog_content = "¿eh? ¿Está bien?",
  str_homestory_817201001_36_dialog_content = "¡Claro que puedes contar conmigo!",
  str_homestory_817201001_37_dialog_content = "¡Eso sería increíble! ¿Ya tienes algo en mente, Lilica?",
  str_homestory_817201001_38_dialog_content = "Mmm... a ver...<sprite=emo_sikao size=60 />",
  str_homestory_817201001_39_dialog_content = "¡Ajá! ¡Lo tengo!",
  str_homestory_817201001_40_dialog_content = "¿Qué tal una película de baile que tiene lugar en Eraveil... conmigo como protagonista!",
  str_homestory_817201001_41_dialog_content = "¿Ah?",
  str_homestory_817201001_42_dialog_content = "¿Seguirá siendo una película sobre Eraveil?",
  str_homestory_817201001_43_dialog_content = "¿Por qué no?",
  str_homestory_817201001_44_dialog_content = "Ugh, esto seguro es un dolor de cabeza...",
  str_homestory_817201001_45_dialog_content = "Muy bien, ¿y si en lugar de mí... TÚ protagonizas la película de baile que tiene lugar en Eraveil? ¿eh? eh??",
  str_homestory_817201001_46_dialog_content = "Yo... no creo que nadie quiera ver eso...",
  str_homestory_817301001_0_dialog_content = "Minos...",
  str_homestory_817301001_1_dialog_content = "Buenos dias navegante<sprite=emo_mojing size=60 />.",
  str_homestory_817301001_2_dialog_content = "Hola Minos.",
  str_homestory_817301001_3_dialog_content = "¿Hay algo que pueda hacer por ti hoy, Navegante?",
  str_homestory_817301001_4_option_content = "(Confirmar)",
  str_homestory_817301001_5_dialog_content = "Er... Bueno, en realidad hay algo que quería preguntarte, Minos.",
  str_homestory_817301001_6_dialog_content = "Por todos los medios, señor.",
  str_homestory_817301001_7_dialog_content = "Espero que puedas relajarte un poco cuando estés aquí en Cloud Gardens...",
  str_homestory_817301001_8_dialog_content = "No hay necesidad de que seas tan cortés y reverente, ¿sabes?",
  str_homestory_817301001_9_option_content = "(Negar)",
  str_homestory_817301001_10_dialog_content = "N-No realmente, no...",
  str_homestory_817301001_11_dialog_content = "Siempre me siento tan a gusto cuando estás aquí en Cloud Gardens, Minos.",
  str_homestory_817301001_12_dialog_content = "Pero realmente espero que puedas relajarte un poco mientras estás aquí...",
  str_homestory_817301001_13_dialog_content = "Después de todo, te invité a ser mi huésped en Cloud Gardens.",
  str_homestory_817301001_14_dialog_content = "Tienes razon, si.",
  str_homestory_817301001_15_dialog_content = "Como su invitado, ciertamente es grosero de mi parte privarlo del placer de recibir invitados.",
  str_homestory_817301001_16_dialog_content = "He tomado nota de su petición, señor.",
  str_homestory_817301001_17_dialog_content = "Ahora bien, permítanme unos momentos para convertirme en el invitado perfecto.",
  str_homestory_817301001_18_dialog_content = "No tienes que esforzarte para ser perfecto, ¿sabes?",
  str_homestory_817301001_19_dialog_content = "¿Un invitado imperfecto, entonces?",
  str_homestory_817301001_20_dialog_content = "Eso suena como un desafio.",
  str_homestory_817301001_21_dialog_content = "Jejeje... Lo estás pensando demasiado, Minos. De todos modos...",
  str_homestory_817301001_22_dialog_content = "Acabo de ver estas velas encendidas tan pronto como levantas la mano.",
  str_homestory_817301001_23_dialog_content = "¡Eso es simplemente increíble! ¿Cómo hiciste eso, Minos?",
  str_homestory_817301001_24_dialog_content = "Tiene una gran capacidad de observación, señor.",
  str_homestory_817301001_25_dialog_content = "Estaba terminando su entrenamiento cuando llegaste.",
  str_homestory_817301001_26_dialog_content = "¿Estabas... entrenando velas?",
  str_homestory_817301001_27_dialog_content = "Por cierto. Es una técnica que solo conocen los mayordomos veteranos que han dedicado años a brindar servicio...",
  str_homestory_817301001_28_dialog_content = "No importa lo caro que sea un mueble o lo delicado que parezca un adorno...",
  str_homestory_817301001_29_dialog_content = "Con la técnica adecuada, todos pueden ser entrenados para servir mejor a los demás dentro de sus respectivos espacios.",
  str_homestory_817301001_30_dialog_content = "Tome estas velas, por ejemplo.",
  str_homestory_817301001_31_dialog_content = "Disponen de un mecanismo que les permite encenderse y apagarse automáticamente.",
  str_homestory_817301001_32_dialog_content = "Si no se controlan, estas velas simplemente se activarán y desactivarán al azar, sin la menor apariencia de orden.",
  str_homestory_817301001_33_dialog_content = "Pero no te preocupes. Al acercarse a ellos en el orden correcto...",
  str_homestory_817301001_34_dialog_content = "Ahora se iluminarán felizmente en tu presencia.",
  str_homestory_817301001_35_dialog_content = "E-Eso es asombroso...",
  str_homestory_817301001_36_dialog_content = "¡Ay! Mis disculpas...",
  str_homestory_817301001_37_dialog_content = "Como tu invitado, no debería estar haciendo cosas como entrenar tus muebles...",
  str_homestory_817301001_38_dialog_content = "Sin preocupaciones.",
  str_homestory_817301001_39_dialog_content = "¡Si no fuera por ti, nunca hubiera sabido que podía hacer esto con estas velas!",
  str_homestory_817301001_40_dialog_content = "Gracias por pasar por alto mi delito menor.",
  str_homestory_817301001_41_dialog_content = "Aunque no puedo evitar sentirme agradecido por mi error...",
  str_homestory_817301001_42_dialog_content = "Por eso he asumido perfectamente el papel de invitado imperfecto.",
  str_homestory_817301001_43_dialog_content = "Pero solo espero mi rendimiento<sprite=emo_baimao size=60 /> ha sido de su agrado, Navegante.",
  str_homestory_815901001_0_dialog_content = "¡Hola, Sadie!",
  str_homestory_815901001_1_dialog_content = "Oh, eres tú. ¿No me digas que alguien te tuvo para buscarme?",
  str_homestory_815901001_2_dialog_content = "No, me atrajo la música.<sprite=emo_yinfu size=60 /> más temprano.",
  str_homestory_815901001_3_dialog_content = "Ese ritmo pegadizo y ritmos estimulantes...",
  str_homestory_815901001_4_dialog_content = "¡No puedo evitar bailar con la música!",
  str_homestory_815901001_5_dialog_content = "¡Parece que te has enamorado del encanto irresistible del hip-hop!",
  str_homestory_815901001_6_dialog_content = "Pero es perfectamente normal ya que ¿a quién no le gusta el hip-hop?",
  str_homestory_815901001_7_dialog_content = "¿Así que esto es hip-hop...?",
  str_homestory_815901001_8_dialog_content = "No me digas que nunca has oído hablar de él antes, PlayerName?",
  str_homestory_815901001_9_option_content = "(Confirmar)",
  str_homestory_815901001_10_dialog_content = "Realmente no escucho mucho hip-hop, así que no puedo decir que lo entienda muy bien.",
  str_homestory_815901001_11_option_content = "(Negar)",
  str_homestory_815901001_12_dialog_content = "De ninguna manera, me encanta todo tipo de música!",
  str_homestory_815901001_13_dialog_content = "Pero las únicas canciones de hip-hop que he escuchado son tus rapeos...",
  str_homestory_815901001_14_dialog_content = "Por eso no entiendo mucho del género.",
  str_homestory_815901001_15_dialog_content = "También es por eso que no pude decir que era hip-hop de inmediato.",
  str_homestory_815901001_16_dialog_content = "Eso es una verdadera vergüenza. Con razón pensé que faltaba algo cuando llegué aquí por primera vez.",
  str_homestory_815901001_17_dialog_content = "¡Tan pronto como vi este tambor antes, me di cuenta de repente de que este lugar necesita algo de hip-hop!",
  str_homestory_815901001_18_dialog_content = "Nunca supe que un solo tambor puede hacer ritmos tan conmovedores...",
  str_homestory_815901001_19_dialog_content = "Parece que estás completamente hipnotizado por eso, PlayerName.",
  str_homestory_815901001_20_dialog_content = "Supongo que un espadachín como yo no tiene más remedio que echarte una mano.",
  str_homestory_815901001_21_dialog_content = "¿Ayúdame?",
  str_homestory_815901001_22_dialog_content = "¡Así es! ¡Te voy a enseñar a tocar este tambor de la manera correcta!",
  str_homestory_815901001_23_dialog_content = "¡De esa manera, puedes escuchar dulces ritmos de hip-hop cuando quieras!",
  str_homestory_815901001_24_dialog_content = "¿eh? Espera, si te enseño a hacer eso...",
  str_homestory_815901001_25_dialog_content = "¿No significará eso que todos en Cloud Gardens podrán escuchar los ritmos de hip-hop que haces?",
  str_homestory_815901001_26_dialog_content = "¡No puedo creer que empezaré la tendencia hip-hop en Astra!",
  str_homestory_815901001_27_dialog_content = "S-Perdón por interrumpir, Sadie...",
  str_homestory_815901001_28_dialog_content = "Pero solo soy un principiante cuando se trata de hip-hop o batería.",
  str_homestory_815901001_29_dialog_content = "No creo que enseñarme sea una tarea fácil.",
  str_homestory_815901001_30_dialog_content = "¡Ay, no te preocupes por eso! Después de todo, el mejor estudiante es aquel que está ansioso por aprender.<sprite=emo_dianzan size=60 />!",
  str_homestory_815901001_31_dialog_content = "Ahora, los dos aspectos más importantes del hip-hop son el ritmo y el compás.",
  str_homestory_815901001_32_dialog_content = "El ritmo vendrá de forma natural siempre y cuando estés tocando al compás.",
  str_homestory_815901001_33_dialog_content = "Ahora, imagínate a ti mismo como la baqueta y saca el ritmo dentro de tu corazón.",
  str_homestory_815901001_34_dialog_content = "Después de todo, ¡el mejor hip-hop siempre viene directamente del corazón!",
  str_homestory_815901001_35_dialog_content = "¿Estás diciendo que seré capaz de actuar como tú si sigo mi corazón?",
  str_homestory_815901001_36_dialog_content = "¡Absolutamente! ¿Por qué no lo intentas?",
  str_homestory_815901001_37_dialog_content = "Solo sigue el ritmo y sigue tocando la batería. ¡La música fluirá por sí sola!",
  str_homestory_815901001_38_dialog_content = "S-Solo sigue tocando la batería, eh...",
  str_homestory_815901001_39_dialog_content = "¿No quieres ayudar a más personas a darse cuenta de lo increíble que es el hip-hop?",
  str_homestory_815901001_40_dialog_content = "Por supuesto que sí, pero estoy muy agotado ahora.",
  str_homestory_815901001_41_dialog_content = "Supongo que todavía tienes un largo camino por recorrer antes de convertirte en una superestrella del hip-hop, PlayerName.",
  str_homestory_815901001_42_dialog_content = "Vamos a llamarlo por hoy, ¿sí?",
  str_homestory_815901001_43_dialog_content = "G-Gracias...",
  str_homestory_807901001_0_dialog_content = "Michenny...",
  str_homestory_807901001_1_dialog_content = "¿Michenny?",
  str_homestory_807901001_2_dialog_content = "Hola, PlayerName.",
  str_homestory_807901001_3_dialog_content = "Jejeje... ¿Estás aquí para apreciar la decoración también?",
  str_homestory_807901001_4_dialog_content = "Como recaudador de impuestos de mente lógica, la palabra \"apreciar\" es demasiado sentimental.",
  str_homestory_807901001_5_dialog_content = "Simplemente estoy aquí para evaluar el valor de este artículo, nada más.",
  str_homestory_807901001_6_dialog_content = "Ah... Esto no es Lumopolis, ¿sabes? Creo que incluso tú puedes permitirte relajarte de vez en cuando, Michenny.<sprite=emo_sikao size=60 />.",
  str_homestory_807901001_7_dialog_content = "Ejercer el pensamiento racional no es un asunto trivial.",
  str_homestory_807901001_8_dialog_content = "Especialmente cuando el objetivo de uno es convertirse en un erudito superior en el campo de las leyes fiscales.",
  str_homestory_807901001_9_dialog_content = "No tengo intención de desperdiciar años de experiencia académica solo para holgazanear, ni siquiera por un momento.",
  str_homestory_807901001_10_dialog_content = "Sin embargo, eso no quiere decir que no tenga tiempo libre. Si lo necesita, puedo ayudarlo con los impuestos de Cloud Gardens en mi tiempo libre.",
  str_homestory_807901001_11_dialog_content = "No creo que tengamos problemas fiscales en Cloud Gardens por ahora...",
  str_homestory_807901001_12_dialog_content = "Tu tono es suave y suenas inseguro. Eso es aproximadamente un impuesto de 10 Nightium<sprite=emo_baiyebi size=60 /> lejos de lo determinado.",
  str_homestory_807901001_13_dialog_content = "Parece que ha rechazado mi servicio por completo.",
  str_homestory_807901001_14_option_content = "Aceptar",
  str_homestory_807901001_15_dialog_content = "No es que quiera rechazarte, Michenny. Es solo que... Cloud Gardens no puede permitirse un recaudador de impuestos como tú.",
  str_homestory_807901001_16_dialog_content = "Ah, menos Nightium como siempre, por lo que veo.",
  str_homestory_807901001_17_dialog_content = "No tienes que preocuparte por eso. Puedo proporcionarle asesoramiento fiscal experto, sin cargo.",
  str_homestory_807901001_18_dialog_content = "Después de todo, evaluar adecuadamente el valor de Cloud Gardens también me proporcionará una medida de valor emocional.",
  str_homestory_807901001_19_option_content = "Negar",
  str_homestory_807901001_20_dialog_content = "¡N-En absoluto!",
  str_homestory_807901001_21_dialog_content = "Si Cloud Gardens alguna vez necesita un recaudador de impuestos, ¡serás la primera persona a la que llame, Michenny!",
  str_homestory_807901001_22_dialog_content = "Los impuestos deben existir dondequiera que se administre la tierra y se realicen transacciones.",
  str_homestory_807901001_23_dialog_content = "Ya que ha depositado tanta confianza en mí, continuaré evaluando el valor de Cloud Gardens.",
  str_homestory_807901001_24_dialog_content = "S-Claro...",
  str_homestory_807901001_25_dialog_content = "Volviendo al tema que nos ocupa, cuéntame... ¿Cuánto sabes de esta pieza de decoración?",
  str_homestory_807901001_26_dialog_content = "Necesito más información para hacer una evaluación justa de la misma.",
  str_homestory_807901001_27_dialog_content = "Se llama Nido de Windelion.",
  str_homestory_807901001_28_dialog_content = "Aunque estas cáscaras de huevo gigantes son solo decoraciones para nosotros, muchos animales<sprite=emo_gezitou size=60 /> les gusta usarlos para poner huevos.",
  str_homestory_807901001_29_dialog_content = "Mmm. No generan ningún valor económico directo y ocupan espacio.",
  str_homestory_807901001_30_dialog_content = "Además, las criaturas que crían eventualmente comenzarán a consumir los recursos alimenticios de Cloud Gardens.",
  str_homestory_807901001_31_dialog_content = "Mi conclusión es que este objeto y las pequeñas criaturas que residen en él no tienen valor alguno.",
  str_homestory_807901001_32_dialog_content = "Por el contrario, son una carga económica para Cloud Gardens.",
  str_homestory_807901001_33_dialog_content = "¡P-Pero dentro de los huevos hay criaturas vivas!",
  str_homestory_807901001_34_dialog_content = "¿Cómo podrías evaluar el valor de sus vidas usando la lógica?",
  str_homestory_807901001_35_dialog_content = "Si me preguntas, sus vidas no tienen precio.",
  str_homestory_807901001_36_dialog_content = "¿No tiene precio, dices?",
  str_homestory_807901001_37_dialog_content = "Espera... ¡Lo tengo!",
  str_homestory_807901001_38_dialog_content = "¿Cómo te gustaría cuidar de este Windelion Nest, Michenny?",
  str_homestory_807901001_39_dialog_content = "Muy bien. ¿Que necesito hacer?",
  str_homestory_807901001_40_dialog_content = "¡Solo espera aquí hasta que estos pequeños salgan del cascarón y cuídalos hasta que crezcan!",
  str_homestory_807901001_41_dialog_content = "Puedo prestarte un libro que te enseñe todo sobre el cuidado de los animales.",
  str_homestory_807901001_42_dialog_content = "Un libro de texto sería de gran ayuda, sí.",
  str_homestory_807901001_43_dialog_content = "Déjamelo a mí. Te prometo que no te decepcionaré.",
  str_homestory_817601001_0_dialog_content = "¡Beretta!",
  str_homestory_817601001_1_dialog_content = "¿Qué estás haciendo, Beretta?",
  str_homestory_817601001_2_dialog_content = "Oh hola PlayerName!",
  str_homestory_817601001_3_dialog_content = "Estoy haciendo ejercicio.",
  str_homestory_817601001_4_dialog_content = "Cuando pasé corriendo por aquí, creí ver a Lady Raphael.",
  str_homestory_817601001_5_dialog_content = "Así que me detuve para echar otro vistazo...",
  str_homestory_817601001_6_dialog_content = "¡y noté su foto en esta tarjeta!",
  str_homestory_817601001_7_dialog_content = "¡Ah, esa es la postal que todos me enviaron antes!",
  str_homestory_817601001_8_dialog_content = "Algunos de los otros son recuerdos que traje de lugares nuevos.",
  str_homestory_817601001_9_dialog_content = "Creo que esta fue tomada cuando Raphael arrastró a Michael en un largo viaje.",
  str_homestory_817601001_10_dialog_content = "¡Me preguntaba por qué Michael parecía tan desanimado!<sprite=emo_wuzui size=60 />",
  str_homestory_817601001_11_dialog_content = "Pareces bastante popular.",
  str_homestory_817601001_12_dialog_content = "Tienes mucho aquí... Incluso vi uno con la firma de Lady Hedy.",
  str_homestory_817601001_13_dialog_content = "Oye, ¿es esta una foto de paisaje del desierto de Rediesel?",
  str_homestory_817601001_14_dialog_content = "Está.",
  str_homestory_817601001_15_dialog_content = "Este es un recuerdo de visitar la Llave Rediesel.",
  str_homestory_817601001_16_option_content = "Y este es de Northland...",
  str_homestory_817601001_17_dialog_content = "Wow, desierto y nieve... ¡Espectacular!",
  str_homestory_817601001_18_option_content = "Y este es de la playa...",
  str_homestory_817601001_19_dialog_content = "Wow, desierto y playa... ¡Espectacular!",
  str_homestory_817601001_20_dialog_content = "Estoy tan celoso de que hayas estado en tantos lugares, PlayerName!",
  str_homestory_817601001_21_dialog_content = "¿No viajas, Beretta?",
  str_homestory_817601001_22_dialog_content = "No, debido a mi trabajo, nunca puedo relajarme por completo, incluso cuando estoy fuera del trabajo.",
  str_homestory_817601001_23_dialog_content = "Después de todo, los pacientes no dejan de enfermarse o lastimarse solo porque está de vacaciones.",
  str_homestory_817601001_24_dialog_content = "Incluso cuando viajo, es para brindar asistencia médica.",
  str_homestory_817601001_25_dialog_content = "Realmente es difícil ser médico...",
  str_homestory_817601001_26_dialog_content = "Es difícil.",
  str_homestory_817601001_27_dialog_content = "Pero cuando pienso en cómo puedo aliviar el dolor de alguien o incluso salvar una vida...",
  str_homestory_817601001_28_dialog_content = "¡Ya no es difícil!",
  str_homestory_817601001_29_dialog_content = "Sin mencionar que tengo que esforzarme más para mejorar.",
  str_homestory_817601001_30_dialog_content = "De esa manera, puedo crear mi propio equipo médico itinerante para tratar pacientes en todo el continente.",
  str_homestory_817601001_31_dialog_content = "Entonces, no solo podré ayudar a más personas, ¡sino que también podré ver paisajes que nunca antes había visto!",
  str_homestory_817601001_32_dialog_content = "¡Dos pájaros con una piedra!<sprite=emo_guilian size=60 />",
  str_homestory_817601001_33_dialog_content = "¡Estoy impresionado, Beretta!",
  str_homestory_817601001_34_dialog_content = "¡Tienes cierto brillo en ti cuando hablas de tu trabajo!",
  str_homestory_817601001_35_dialog_content = "Jajaja, pero todavía tengo un largo camino por recorrer!",
  str_homestory_817601001_36_dialog_content = "Mi objetivo es ser un gran médico como Lady Raphael o Mr. John.",
  str_homestory_817601001_37_dialog_content = "Pero todavía tengo mucho que aprender.",
  str_homestory_817601001_38_dialog_content = "No solo en medicina, sino también en resistencia física y mental.",
  str_homestory_817601001_39_dialog_content = "Cuando el Dr. John me operó, estuvo junto a la mesa de operaciones durante tres días completos.",
  str_homestory_817601001_40_dialog_content = "Eso es imposible para mí ahora mismo.",
  str_homestory_817601001_41_dialog_content = "¡Ah, mejor dejo de hablar y retomo mi entrenamiento!",
  str_homestory_817601001_42_dialog_content = "Adiós, PlayerName.",
  str_homestory_817601001_43_dialog_content = "¡Te enviaré postales cuando empiece a tratar a la gente!",
  str_homestory_817601001_44_dialog_content = "Heh, todavía tengo prisa como siempre.",
  str_homestory_817601001_45_dialog_content = "Espero ese día. Tú puedes hacerlo, Beretta.",
  str_homestory_817501001_0_dialog_content = "¿Axelia?",
  str_homestory_817501001_1_dialog_content = "Hola Axelia.",
  str_homestory_817501001_2_dialog_content = "Hola, PlayerName.",
  str_homestory_817501001_3_dialog_content = "¿Te sientes mejor últimamente?",
  str_homestory_817501001_4_dialog_content = "Te veo bastante a menudo en Cloud Gardens.",
  str_homestory_817501001_5_dialog_content = "Sí<sprite=emo_chidai size=60 />Sin embargo, una vez que termine de explorar Cloud Gardens, debo regresar a la cámara de estasis.",
  str_homestory_817501001_6_dialog_content = "Pero hay muchas cosas aquí que encuentro fascinantes.",
  str_homestory_817501001_7_dialog_content = "¿Como este tambor que visitas con frecuencia?",
  str_homestory_817501001_8_dialog_content = "*Tose*",
  str_homestory_817501001_9_dialog_content = "¿Me has estado observando? PlayerName?",
  str_homestory_817501001_10_option_content = "¡Claro!",
  str_homestory_817501001_11_dialog_content = "Los Cubos siempre están contigo, por lo que nunca deberían ocurrir contratiempos.",
  str_homestory_817501001_12_dialog_content = "Pero siento que debo ser consciente de su condición.",
  str_homestory_817501001_13_dialog_content = "Gracias por preocuparte.",
  str_homestory_817501001_14_option_content = "Nop",
  str_homestory_817501001_15_dialog_content = "Es solo que cada vez que te veo, siempre estás dando vueltas alrededor del tambor.",
  str_homestory_817501001_16_dialog_content = "Mmm...",
  str_homestory_817501001_17_dialog_content = "Tengo cierta curiosidad por esos tambores.",
  str_homestory_817501001_18_dialog_content = "Cierto, recuerdo que te interesaba la música.",
  str_homestory_817501001_19_dialog_content = "¿Pero hay alguna razón por la que te gusta el techno?",
  str_homestory_817501001_20_dialog_content = "Razón...",
  str_homestory_817501001_21_dialog_content = "Tal vez sea porque esa música no tiene letra. <sprite=emo_sikao size=60 />",
  str_homestory_817501001_22_dialog_content = "¿Letra?",
  str_homestory_817501001_23_dialog_content = "Sí.",
  str_homestory_817501001_24_dialog_content = "Sin letra, los oyentes tienen más espacio para la imaginación.",
  str_homestory_817501001_25_dialog_content = "Simplemente pueden dejarse llevar por el ritmo de la música sin necesidad de invertir demasiado de sus emociones en algún tipo de historia.",
  str_homestory_817501001_26_dialog_content = "De hecho, esa es una respuesta muy parecida a Axelia.",
  str_homestory_817501001_27_dialog_content = "Aunque mi padre se burlaría de la idea, creo que en comparación con otra música...",
  str_homestory_817501001_28_dialog_content = "Techno personifica la fusión racional de la creatividad y las notas musicales sencillas.",
  str_homestory_817501001_29_dialog_content = "Sabes, tiene sentido cuando lo pones de esa manera.",
  str_homestory_817501001_30_dialog_content = "Este tipo de música no parece evocar emociones fuertes en mí...",
  str_homestory_817501001_31_dialog_content = "Sí.",
  str_homestory_817501001_32_dialog_content = "Así que...",
  str_homestory_817501001_33_dialog_content = "¿Te quedas con la batería porque la música tecno suele tener ritmos de batería?",
  str_homestory_817501001_34_dialog_content = "¿O estás tratando de incorporar sonidos de batería en el ritmo?",
  str_homestory_817501001_35_dialog_content = "Solo quiero escuchar más sus sonidos.",
  str_homestory_817501001_36_dialog_content = "Pero me has dado una idea.",
  str_homestory_817501001_37_dialog_content = "Seguiré visitando en el futuro.",
  str_homestory_817501001_38_dialog_content = "¡Por supuesto! Avísame si hay algo más que necesites.",
  str_homestory_817501001_39_dialog_content = "Gracias, PlayerName.",
  str_homestory_805401001_0_dialog_content = "¿Nadine?",
  str_homestory_805401001_1_dialog_content = "¡PlayerName!",
  str_homestory_805401001_2_dialog_content = "¿Por qué estás parado aquí solo?",
  str_homestory_805401001_3_dialog_content = "¿Por qué no estás dentro de los dormitorios con los demás, o pescando en algún lugar cercano?",
  str_homestory_805401001_4_dialog_content = "¡Porque tengo que terminar mi trabajo!",
  str_homestory_805401001_5_dialog_content = "¿Tu trabajo?",
  str_homestory_805401001_6_dialog_content = "Así es. Como el primer Nightwatch de Cloud Gardens...",
  str_homestory_805401001_7_dialog_content = "¡Es mi deber estar atento durante cada turno!",
  str_homestory_805401001_8_dialog_content = "Oye, espera un minuto—",
  str_homestory_805401001_9_dialog_content = "No recuerdo haberte pedido que fueras la Guardia Nocturna de Cloud Gardens. <sprite=emo_yueliang size=60 />.",
  str_homestory_805401001_10_dialog_content = "Me invitaste a pasar el rato en Cloud Gardens.",
  str_homestory_805401001_11_dialog_content = "Usted proporcionó alojamiento, comida y tantas cosas divertidas...",
  str_homestory_805401001_12_dialog_content = "¡Estoy increíblemente feliz!",
  str_homestory_805401001_13_dialog_content = "Nunca pensé que llegaría a ser amigo cercano de una celebridad como tú.",
  str_homestory_805401001_14_dialog_content = "Mucho menos dejar Lumopolis por un lugar tan remoto como Cloud Gardens.",
  str_homestory_805401001_15_dialog_content = "Pero no tengo dinero ni habilidades especiales... No sé cómo pagarte.",
  str_homestory_805401001_16_dialog_content = "Parece que todo lo que sé es ser un Nightwatch.",
  str_homestory_805401001_17_dialog_content = "Así que decidí que así es como te mostraré mi gratitud, PlayerName!",
  str_homestory_805401001_18_option_content = "Gracias a ella",
  str_homestory_805401001_19_dialog_content = "Gracias, Nadina. Me conmueve oírte decir eso.",
  str_homestory_805401001_20_dialog_content = "Pero no puedo tener a mis invitados trabajando aquí para mí.",
  str_homestory_805401001_21_option_content = "Consuelala",
  str_homestory_805401001_22_dialog_content = "¡Tu felicidad es la mejor recompensa para mí!",
  str_homestory_805401001_23_dialog_content = "Realmente no tienes que esforzarte tanto.",
  str_homestory_805401001_24_dialog_content = "No te preocupes, estoy acostumbrado. No es difícil para mí.",
  str_homestory_805401001_25_dialog_content = "Además...",
  str_homestory_805401001_26_dialog_content = "Cloud Gardens es precioso!",
  str_homestory_805401001_27_dialog_content = "Y siempre obtienes muebles que se adaptan a nuestras preferencias…",
  str_homestory_805401001_28_dialog_content = "Poco a poco he llegado a sentirme como en casa aquí.",
  str_homestory_805401001_29_dialog_content = "Ya que este es mi hogar, no necesitas ser tan formal conmigo.",
  str_homestory_805401001_30_dialog_content = "No se obsesione con sus deudas impagas.",
  str_homestory_805401001_31_dialog_content = "Bueno, siento un sentido del deber aquí porque lo considero un hogar.",
  str_homestory_805401001_32_dialog_content = "¡Quiero proteger Cloud Gardens, nuestro hogar, de todo daño!",
  str_homestory_805401001_33_dialog_content = "Para mí, esto no es sólo un trabajo.",
  str_homestory_805401001_34_dialog_content = "¡Es un instinto y un deber!",
  str_homestory_805401001_35_dialog_content = "Oh, Nadina...",
  str_homestory_805401001_36_dialog_content = "Gracias, supongo.",
  str_homestory_805401001_37_dialog_content = "Trataré de compensarte por esto de alguna manera.",
  str_homestory_805401001_38_dialog_content = "¡¿Qué?!",
  str_homestory_817801001_0_dialog_content = "Hola, Vic.",
  str_homestory_817801001_1_dialog_content = "¡No todos los días podemos verte aventurándote al aire libre!",
  str_homestory_817801001_2_dialog_content = "¿No estás de humor para estar acostado en la cama bebiendo hoy?<sprite=emo_kun size=60 />",
  str_homestory_817801001_3_dialog_content = "Wow, ¿eso es realmente lo que piensas de mí?",
  str_homestory_817801001_4_dialog_content = "Eso duele... Soy un maestro extrozoólogo, sabes...",
  str_homestory_817801001_5_dialog_content = "Cada vez que estoy en mi habitación, por lo general estoy clasificando materiales o trabajando en mi nuevo libro.",
  str_homestory_817801001_6_dialog_content = "Siempre tengo mi mente en asuntos importantes, ¡solo que beber ayuda a expandir mi mente!",
  str_homestory_817801001_7_dialog_content = "¿Oh sí? Entonces, ¿cómo va tu nuevo libro?",
  str_homestory_817801001_8_dialog_content = "Ejem... Digo, el ambiente aquí realmente está mejorando día a día.",
  str_homestory_817801001_9_dialog_content = "Bueno, esa es una forma de cambiar de tema.",
  str_homestory_817801001_10_dialog_content = "No, no, ¿sabes lo que he estado haciendo aquí?",
  str_homestory_817801001_11_dialog_content = "Hmm... ¿Aparte de caminar aturdido?",
  str_homestory_817801001_12_dialog_content = "...",
  str_homestory_817801001_13_dialog_content = "Estoy investigando las especies y cantidades de formas de vida en tu bosque.",
  str_homestory_817801001_14_dialog_content = "¿Para qué estás haciendo eso?",
  str_homestory_817801001_15_dialog_content = "¡No subestimes la importancia de esta información!",
  str_homestory_817801001_16_dialog_content = "Puede revelar fenómenos de gran importancia.",
  str_homestory_817801001_17_dialog_content = "Por ejemplo, nos dirá qué tipos de formas de vida se adaptan al medio ambiente aquí,",
  str_homestory_817801001_18_dialog_content = "las interacciones simbióticas entre los animales y las plantas aquí, y así sucesivamente.",
  str_homestory_817801001_19_dialog_content = "sabes que se me acaba de ocurrir<sprite=emo_wuzui size=60 />—",
  str_homestory_817801001_20_dialog_content = "¡Este lugar es perfecto para la investigación y la investigación!",
  str_homestory_817801001_21_dialog_content = "Planeo presentar algunas bestias maravillosas aquí.",
  str_homestory_817801001_22_dialog_content = "De esa manera, mi libro tendrá más...",
  str_homestory_817801001_23_dialog_content = "Espera... ¿Quieres hacer qué?",
  str_homestory_817801001_24_dialog_content = "¿Eh? ¿Reunir información y escribirla en mi libro...?",
  str_homestory_817801001_25_dialog_content = "No, me refiero a la otra cosa.",
  str_homestory_817801001_26_dialog_content = "¿Quieres criar bestias maravillosas en el bosque?",
  str_homestory_817801001_27_dialog_content = "Ya te di tantas habitaciones para ti, ¿¡eso no es suficiente!?",
  str_homestory_817801001_28_dialog_content = "¿Cómo es eso en cualquier lugar remotamente cerca de lo mismo?",
  str_homestory_817801001_29_dialog_content = "El paisaje interior artificial no se puede comparar con los entornos reales del mundo exterior.",
  str_homestory_817801001_30_dialog_content = "El comportamiento animal solo se puede observar en su estado más real cuando el sujeto se encuentra en su hábitat natural.",
  str_homestory_817801001_31_dialog_content = "¡Ese no es mi punto!",
  str_homestory_817801001_32_dialog_content = "Ya trajiste tantas bestias maravillosas al Coloso; He recibido muchas quejas de los demás, ¿sabes?",
  str_homestory_817801001_33_dialog_content = "Sin mencionar que no me has encontrado una solución para los constantes gritos de bestias maravillosas que despiertan a todos temprano en la mañana.",
  str_homestory_817801001_34_dialog_content = "Y nunca llegas a limpiar todo el excremento y el pelo que dejan por todas partes.",
  str_homestory_817801001_35_dialog_content = "¿¡Ahora quieres causarme aún más problemas!?",
  str_homestory_817801001_36_dialog_content = "eres tan frio, PlayerName.",
  str_homestory_817801001_37_dialog_content = "¿Cómo puedes pensar que esto es problemático?",
  str_homestory_817801001_38_dialog_content = "¡Piensa en la contribución que esto hará a las organizaciones de bestias maravillosas en todo el continente!",
  str_homestory_817801001_39_dialog_content = "¡Estas siendo ridiculo!<sprite=emo_shengqi size=60 />",
  str_homestory_817801001_40_dialog_content = "No tienes permitido traer tus estragos extrazoológicos a este bosque, y ese es el final.",
  str_homestory_817801001_41_dialog_content = "¡Las praderas, los valles y los ríos también están fuera de los límites!",
  str_homestory_817801001_42_dialog_content = "Suspiro... Bien.",
  str_homestory_817801001_43_dialog_content = "Realmente, los jóvenes de hoy en día no tienen paciencia con sus mayores.",
  str_homestory_817701001_0_dialog_content = "Goldie!",
  str_homestory_817701001_1_dialog_content = "¡Ah, finalmente te encontré, Goldie! <sprite=emo_yaosu size=60 />",
  str_homestory_817701001_2_dialog_content = "PlayerName, Acabo de cantar mi nueva canción en el escenario.",
  str_homestory_817701001_3_dialog_content = "Oh, estoy tan nerviosa. Me pregunto si a todos les gustó...",
  str_homestory_817701001_4_dialog_content = "¿Que piensas de eso?",
  str_homestory_817701001_5_dialog_content = "¡Sonaba increíble!",
  str_homestory_817701001_6_dialog_content = "¡Estoy seguro de que a todos les encantó!",
  str_homestory_817701001_7_dialog_content = "Jejeje... Gracias. Supongo que puedo descansar tranquilo ahora.",
  str_homestory_817701001_8_dialog_content = "Para ser honesto, hay algo en mi mente en este momento.",
  str_homestory_817701001_9_dialog_content = "Esperaba que pudieras darme un consejo.",
  str_homestory_817701001_10_dialog_content = "¿Que pasa? Rara vez te veo en conflicto.",
  str_homestory_817701001_11_dialog_content = "Se trata del sencillo principal de mi nuevo álbum...",
  str_homestory_817701001_12_dialog_content = "Hay una canción escrita en mi estilo habitual, llena de sol <sprite=emo_taiyang size=60 /> y positividad.",
  str_homestory_817701001_13_dialog_content = "Luego está este otro sonido más fresco <sprite=emo_mojing size=60 /> canción con la que estoy pensando en reemplazarla, en un intento de probar algo nuevo.",
  str_homestory_817701001_14_dialog_content = "¿Crees que necesito reemplazarlo, PlayerName?",
  str_homestory_817701001_15_option_content = "Deberías hacerlo.",
  str_homestory_817701001_16_dialog_content = "¡Es bueno probar un nuevo estilo de vez en cuando!",
  str_homestory_817701001_17_option_content = "No hay necesidad de reemplazarlo.",
  str_homestory_817701001_18_dialog_content = "Correcto, ¡puedo manejar mi estilo familiar con mucha más confianza!",
  str_homestory_817701001_19_dialog_content = "Sin embargo, todo depende del tema del álbum en su conjunto, ¿verdad?",
  str_homestory_817701001_20_dialog_content = "¡Derecha! El tema del nuevo álbum es \"Growing Pains\".",
  str_homestory_817701001_21_dialog_content = "¡La compañía gastó una fortuna para publicar este álbum!",
  str_homestory_817701001_22_dialog_content = "¿Qué opina tu agente?",
  str_homestory_817701001_23_dialog_content = "Mi agente dice que no necesito cambiar nada.",
  str_homestory_817701001_24_dialog_content = "Porque algunos de mis fans pueden no ser receptivos a un nuevo estilo...",
  str_homestory_817701001_25_dialog_content = "Es una sugerencia algo conservadora.",
  str_homestory_817701001_26_dialog_content = "Pero creo que tus fans prefieren que seas fiel a ti mismo.",
  str_homestory_817701001_27_dialog_content = "Ya sea que cambies o no, ¡tus fans te apoyarán como siempre lo han hecho!",
  str_homestory_817701001_28_dialog_content = "Entonces, también podrías seguir tu corazón.",
  str_homestory_817701001_29_dialog_content = "Elige un estilo que realmente te guste.",
  str_homestory_817701001_30_dialog_content = "¡Está bien!",
  str_homestory_817701001_31_dialog_content = "¡Eso lo resuelve! elegiré—",
  str_homestory_817701001_32_dialog_content = "Vas a elegir—",
  str_homestory_817701001_33_dialog_content = "¡Mi canción de sol positiva!",
  str_homestory_817701001_34_dialog_content = "¿Eh?",
  str_homestory_817701001_35_dialog_content = "¡Porque eso es lo que realmente soy!",
  str_homestory_817701001_36_dialog_content = "¡Eso es lo que más me conviene!",
  str_homestory_817701001_37_dialog_content = "Supongo que tu agente te conoce, después de todo...",
  str_homestory_818001001_0_dialog_content = "¿Brandy?",
  str_homestory_818001001_1_dialog_content = "Mmm...? ¿Debo poner este palo de luz aquí? ¿Es extraño?",
  str_homestory_818001001_2_dialog_content = "¿Qué estás haciendo?",
  str_homestory_818001001_3_dialog_content = "¡Oye! ¡Llegas justo a tiempo!",
  str_homestory_818001001_4_dialog_content = "Ayúdame a echar un vistazo. ¿Debo poner este palo de luz a la izquierda o a la derecha?",
  str_homestory_818001001_5_option_content = "La izquierda.",
  str_homestory_818001001_6_dialog_content = "Se vería mejor a la derecha.",
  str_homestory_818001001_7_option_content = "Todo es lo mismo.",
  str_homestory_818001001_8_dialog_content = "Estás bien. Lo pondré a la derecha.",
  str_homestory_818001001_9_dialog_content = "...",
  str_homestory_818001001_10_dialog_content = "¿Para qué estás haciendo esto?",
  str_homestory_818001001_11_dialog_content = "Estoy tomando fotos para mi artículo \"Goldie Takes Cloud Gardens By Storm\".",
  str_homestory_818001001_12_dialog_content = "En este momento, estoy tomando fotos de la mercancía de los fanáticos de Goldie.",
  str_homestory_818001001_13_dialog_content = "Hay palos de luz, letreros de neón, pegatinas, mini tarjetas de retrato...",
  str_homestory_818001001_14_dialog_content = "Incluso hay una camiseta con la cara de Goldie. ¡Es tan lindo!",
  str_homestory_818001001_15_dialog_content = "Ahora que lo pienso. Siento que todavía me falta un soporte Goldie de tamaño real.",
  str_homestory_818001001_16_dialog_content = "Solo necesito poner mis manos en uno y llevarlo a escondidas a mi habitación... <sprite=emo_sikao size=60 />",
  str_homestory_818001001_17_dialog_content = "¡Oh, no! ¿¡No debería haber una estatua de Goldie de tamaño natural por aquí en alguna parte!?",
  str_homestory_818001001_18_dialog_content = "¿Podría haber sido arrebatado por algún fanático de mente sucia?",
  str_homestory_818001001_19_dialog_content = "¡Maldita sea! ¿Cómo podría alguien hacer tal cosa?",
  str_homestory_818001001_20_dialog_content = "Acabas de decir que eso era exactamente lo que querías hacer...",
  str_homestory_818001001_21_dialog_content = "Olvídalo. Tomaré estas fotos primero.",
  str_homestory_818001001_22_dialog_content = "Ella está de pie junto a ti, ¿por qué necesitas tomar fotos de la mercancía?",
  str_homestory_818001001_23_dialog_content = "No creo que estés abordando esto de la manera correcta.",
  str_homestory_818001001_24_dialog_content = "No entiendes, esta es una forma de agregar un grado de contraste. Puede expresar completamente...",
  str_homestory_818001001_25_dialog_content = "¿eh? ¡Espera un segundo!",
  str_homestory_818001001_26_dialog_content = "¿Qué ocurre?",
  str_homestory_818001001_27_dialog_content = "Ese grupo de sombras de los árboles está golpeando el letrero de neón en el lugar correcto.",
  str_homestory_818001001_28_dialog_content = "Luces y sombras bailando por el tablero, animando la escena con la silueta de los árboles.",
  str_homestory_818001001_29_dialog_content = "¡Este es el momento perfecto para tomar algunas fotos!",
  str_homestory_818001001_30_dialog_content = "¡Qué disparo! ¡Nunca antes había visto una foto tan perfecta!",
  str_homestory_818001001_31_dialog_content = "¡Esta es justo la foto que necesita mi artículo de noticias!",
  str_homestory_818001001_32_dialog_content = "Creo que su artículo de noticias necesita una foto de Goldie real...",
  str_homestory_818001001_33_dialog_content = "¡He terminado! Voy a regresar y revelar estas fotos.",
  str_homestory_818001001_34_dialog_content = "Por cierto, recuerdo haber visto algo en el agua de camino aquí. Deberías ir a echar un vistazo.",
  str_homestory_818001001_35_dialog_content = "No me estás escuchando en absoluto, ¿verdad?",
  str_homestory_818101001_0_dialog_content = "Zhong Xu?",
  str_homestory_818101001_1_dialog_content = "¿Qué estás mirando?",
  str_homestory_818101001_2_dialog_content = "Mira el estante.",
  str_homestory_818101001_3_dialog_content = "¿Qué tiene de especial? <sprite=emo_sikao size=60 />",
  str_homestory_818101001_4_dialog_content = "¡Espera, veo a Yixin!",
  str_homestory_818101001_5_dialog_content = "Se arrastró hasta el estante mientras yo no estaba prestando atención.",
  str_homestory_818101001_6_dialog_content = "¡Qué gato más travieso!",
  str_homestory_818101001_7_dialog_content = "Yimeng y Yinuo también están allí.",
  str_homestory_818101001_8_dialog_content = "¿Tanto les gusta el estante?",
  str_homestory_818101001_9_dialog_content = "Probablemente porque les gustan los lugares oscuros y angostos.",
  str_homestory_818101001_10_dialog_content = "Eso tiene sentido. El estante está en capas y muy oscuro por dentro.",
  str_homestory_818101001_11_dialog_content = "¿Esto podría servir como un nuevo tipo de torre para gatos, tal vez?",
  str_homestory_818101001_12_dialog_content = "Suena lógico.",
  str_homestory_818101001_13_dialog_content = "Conseguiré que un artesano modele uno después de este.",
  str_homestory_818101001_14_dialog_content = "¡Absolutamente, eres bienvenido en cualquier momento!",
  str_homestory_818101001_15_dialog_content = "Nunca pensé que el estante podría usarse de esta manera.",
  str_homestory_818101001_16_dialog_content = "Gracias.",
  str_homestory_818101001_17_dialog_content = "¿Esto te molestará?",
  str_homestory_818101001_18_option_content = "¡Para nada!",
  str_homestory_818101001_19_option_content = "Un poco.",
  str_homestory_818101001_20_dialog_content = "Lo siento, me aseguraré de hablar con ellos al respecto.",
  str_homestory_818101001_21_dialog_content = "Ahora la pregunta es... ¿cómo los sacamos?",
  str_homestory_818101001_22_dialog_content = "Están durmiendo tan profundamente.",
  str_homestory_818101001_23_dialog_content = "Por lo general, vienen cuando los llamo por su nombre, pero hoy no responden muy bien.",
  str_homestory_818101001_24_dialog_content = "Tal vez sea porque te conocen demasiado bien.",
  str_homestory_818101001_25_dialog_content = "¿Qué quieres decir? <sprite=emo_wuzui size=60 />",
  str_homestory_818101001_26_dialog_content = "Por lo general, los llamas por su nombre cuando los necesitas para hacer algo.",
  str_homestory_818101001_27_dialog_content = "Hoy, solo estás tratando de sacarlos del estante.",
  str_homestory_818101001_28_dialog_content = "Así que optaron por ignorarte.",
  str_homestory_818101001_29_dialog_content = "¡Estos gatos son muy inteligentes!",
  str_homestory_818101001_30_dialog_content = "... Este estante parece tener un poder mucho más potente de lo que imaginaba.",
  str_homestory_818101001_31_dialog_content = "Debo preparar una réplica para ellos.",
  str_homestory_818101001_32_dialog_content = "¿Qué vas a hacer con los gatos?",
  str_homestory_818101001_33_dialog_content = "Esperaré a que se despierten, supongo.",
  str_homestory_818101001_34_dialog_content = "¡Una victoria rotunda para los gatos!",
  str_homestory_818101001_35_dialog_content = "Sin embargo, qué maravillosa vista.",
  str_homestory_818101001_36_dialog_content = "Aquellos que no saben lo que está pasando probablemente piensen que Zhong Xu está reflexionando sobre algo filosófico otra vez...",
  str_homestory_818301001_0_dialog_content = "liqing?",
  str_homestory_818301001_1_dialog_content = "A donde se fué...?",
  str_homestory_818301001_2_dialog_content = "¿Qué estás haciendo?",
  str_homestory_818301001_3_dialog_content = "H-Hola, PlayerName.",
  str_homestory_818301001_4_dialog_content = "Estoy buscando a Tinytail. ¿Lo has visto?",
  str_homestory_818301001_5_dialog_content = "No, ¿qué está pasando?",
  str_homestory_818301001_6_dialog_content = "Está holgazaneando de nuevo, ¡eso es lo que está pasando! <sprite=emo_shengqi size=60 />",
  str_homestory_818301001_7_dialog_content = "Lo llevé al jardín a recoger algunas hierbas.",
  str_homestory_818301001_8_dialog_content = "¡Y luego se fue, así como así!",
  str_homestory_818301001_9_dialog_content = "¿Hay hierbas en Cloud Gardens?",
  str_homestory_818301001_10_dialog_content = "Por supuesto.",
  str_homestory_818301001_11_dialog_content = "Las buenas hierbas generalmente se encuentran donde menos las esperas.",
  str_homestory_818301001_12_dialog_content = "Sólo necesitas un par de buenos ojos. <sprite=emo_mojing size=60 />",
  str_homestory_818301001_13_dialog_content = "Eso suena totalmente como algo que dirías.",
  str_homestory_818301001_14_dialog_content = "Por cierto...",
  str_homestory_818301001_15_option_content = "¿Cuánto tiempo llevas buscándolo?",
  str_homestory_818301001_16_dialog_content = "Um, bueno, unos treinta minutos...",
  str_homestory_818301001_17_dialog_content = "Eso es un largo tiempo.",
  str_homestory_818301001_18_dialog_content = "En realidad, tal vez... ¿solo diez minutos?",
  str_homestory_818301001_19_option_content = "¿Qué hierbas estabas recogiendo?",
  str_homestory_818301001_20_dialog_content = "Um, j-solo... ¿hierbas?",
  str_homestory_818301001_21_dialog_content = "¿Por qué sigues tartamudeando?",
  str_homestory_818301001_22_dialog_content = "¡No estoy!",
  str_homestory_818301001_23_dialog_content = "Será que...",
  str_homestory_818301001_24_dialog_content = "¿También estabas holgazaneando?",
  str_homestory_818301001_25_dialog_content = "NN-No. Imposible. De ninguna manera.",
  str_homestory_818301001_26_dialog_content = "¡Vine con Tinytail a recoger hierbas!",
  str_homestory_818301001_27_dialog_content = "Pero...",
  str_homestory_818301001_28_dialog_content = "Pero...?",
  str_homestory_818301001_29_dialog_content = "Es demasiado cómodo aquí...",
  str_homestory_818301001_30_dialog_content = "Puede que tenga <sprite=emo_kun size=60 /> tomó una siesta. ¡Solo por un momento!",
  str_homestory_818301001_31_dialog_content = "Y Tinytail se había ido cuando me desperté.",
  str_homestory_818301001_32_dialog_content = "Jaja, así que ambos sois holgazanes, ya veo.",
  str_homestory_818301001_33_dialog_content = "¡No no soy!",
  str_homestory_818201001_0_dialog_content = "¿Qué estás haciendo?",
  str_homestory_818201001_1_dialog_content = "Me deleito con la sensación de la respiración del agua.",
  str_homestory_818201001_2_dialog_content = "Realmente no lo entiendo, pero... suena genial.",
  str_homestory_818201001_3_dialog_content = "¿Has sentido el agua respirar antes?",
  str_homestory_818201001_4_option_content = "Sí.",
  str_homestory_818201001_5_dialog_content = "¿En realidad? ¿Cómo se siente?",
  str_homestory_818201001_6_dialog_content = "Frío, refrescante, que apaga la sed.",
  str_homestory_818201001_7_dialog_content = "Ese es el sabor, no su aliento.",
  str_homestory_818201001_8_option_content = "No.",
  str_homestory_818201001_9_dialog_content = "Si quieres aprender, puedo enseñarte.",
  str_homestory_818201001_10_dialog_content = "Está bien...",
  str_homestory_818201001_11_dialog_content = "Comencemos ahora.",
  str_homestory_818201001_12_dialog_content = "¿Ahora? No tengo mi bañador...",
  str_homestory_818201001_13_dialog_content = "Podemos practicar los movimientos básicos en tierra primero.",
  str_homestory_818201001_14_dialog_content = "Párate derecho, respira hondo y siente el agua fluir.",
  str_homestory_818201001_15_dialog_content = "Eso no es demasiado difícil. Creo que puedo hacer eso.",
  str_homestory_818201001_16_dialog_content = "*Inhalar*",
  str_homestory_818201001_17_dialog_content = "*Exhalar*",
  str_homestory_818201001_18_dialog_content = "¿Cuánto tiempo tengo que estar así?",
  str_homestory_818201001_19_dialog_content = "10.000 horas.",
  str_homestory_818201001_20_dialog_content = "10.000 horas?!",
  str_homestory_818201001_21_dialog_content = "Se necesitan 10.000 horas para volverse extraordinario en algo.",
  str_homestory_818201001_22_dialog_content = "Lo sé, pero esto es un poco monótono... <sprite=emo_xinsui size=60 />",
  str_homestory_818201001_23_dialog_content = "Puedes rendirte ahora si quieres.",
  str_homestory_818201001_24_dialog_content = "Hay muchas cosas divertidas, pero el camino hacia el éxito generalmente no lo es.",
  str_homestory_818201001_25_dialog_content = "Lo siento, trabajaré más duro.",
  str_homestory_818201001_26_dialog_content = "¿Se sometió a un entrenamiento similar para llegar a ser tan bueno en el agua?",
  str_homestory_818201001_27_dialog_content = "No, nací con la habilidad.",
  str_homestory_818201001_28_dialog_content = "¿¿¿???",
  str_homestory_818201001_29_dialog_content = "¿Estás tratando de engañarme para que me quede aquí durante 10.000 horas?",
  str_homestory_818201001_30_dialog_content = "No, un anciano de Lin me enseñó esto cuando estaba aprendiendo a nadar.",
  str_homestory_818201001_31_dialog_content = "Pero nací con la capacidad de resonar con el agua, así que no tuve que practicar.",
  str_homestory_818201001_32_dialog_content = "Bueno, si un anciano de Lin lo dijo, probablemente sea cierto.",
  str_homestory_818201001_33_dialog_content = "Solo mantente de pie...",
  str_homestory_818201001_34_dialog_content = "Me duelen las piernas, déjame tomar un descanso. <sprite=emo_tanqi size=60 />",
  str_homestory_818201001_35_dialog_content = "Entonces podemos parar aquí.",
  str_homestory_818201001_36_dialog_content = "¿Eh? Pero el anciano Lin dijo...",
  str_homestory_818201001_37_dialog_content = "El anciano no sabía nadar, así que probablemente se lo inventó.",
  str_homestory_818201001_38_dialog_content = "!!!",
  str_homestory_818201001_39_dialog_content = "Lo consideré por un minuto. No creo que puedas resonar con el agua incluso si permaneces de pie durante 10.000 horas.",
  str_homestory_818201001_40_dialog_content = "Algunas cosas con las que solo necesitas nacer. No puedes obligarlos.",
  str_homestory_818201001_41_dialog_content = "¡Deberías haberlo dicho antes!",
  str_homestory_818201001_42_dialog_content = "Estabas tan concentrado que no quería interrumpir.",
  str_homestory_818201001_43_dialog_content = "Tú...",
  str_homestory_818201001_44_dialog_content = "Ah... mis piernas están acalambradas...",
  str_homestory_818201001_45_dialog_content = "Te llevaré en mi espalda.",
  str_homestory_818201001_46_dialog_content = "No, esta bien...",
  str_homestory_818201001_47_dialog_content = "Te veo más tarde entonces.",
  str_homestory_818201001_48_dialog_content = "Um, espera, ¿puedes bajar por favor?",
  str_homestory_816001001_0_dialog_content = "¿Miguel?",
  str_homestory_816001001_1_dialog_content = "¿Qué estás mirando?",
  str_homestory_816001001_2_dialog_content = "(Ah, PlayerName.)",
  str_homestory_816001001_3_dialog_content = "(Estoy admirando el candelabro.)",
  str_homestory_816001001_4_dialog_content = "Realmente te debe gustar. ¿Lo quieres?",
  str_homestory_816001001_5_dialog_content = "(No, por favor permítame pagar. ¿Cuánto es?)",
  str_homestory_816001001_6_dialog_content = "(¿Son suficientes 1000 Nightium? <sprite=emo_baiyebi size=60 />)",
  str_homestory_816001001_7_dialog_content = "No, no es necesario pagar tanto.",
  str_homestory_816001001_8_dialog_content = "De hecho, no te lo venderé si pagas.",
  str_homestory_816001001_9_dialog_content = "(¿Cómo?)",
  str_homestory_816001001_10_dialog_content = "¿Por qué te ves tan abatido?",
  str_homestory_816001001_11_dialog_content = "Bien, te gusta coleccionar baratijas, ¿verdad?",
  str_homestory_816001001_12_dialog_content = "Recuerdo haber visto todo tipo de cosas maravillosas en tu habitación.",
  str_homestory_816001001_13_dialog_content = "(¿Es raro mi pasatiempo?)",
  str_homestory_816001001_14_option_content = "(Confirmar)",
  str_homestory_816001001_15_dialog_content = "Muchas de las cosas parecían rotas, pero las guardas de todos modos.",
  str_homestory_816001001_16_dialog_content = "Supongo que es... excéntrico.",
  str_homestory_816001001_17_option_content = "(Negar)",
  str_homestory_816001001_18_dialog_content = "Todos tienen sus pasatiempos, no creo que sea raro.",
  str_homestory_816001001_19_dialog_content = "Creo que te gusta coleccionar una gran variedad de cosas.",
  str_homestory_816001001_20_dialog_content = "(Simplemente los encuentro interesantes, así que quiero coleccionarlos).",
  str_homestory_816001001_21_dialog_content = "(Pero quiero comprar el candelero por otras razones).",
  str_homestory_816001001_22_dialog_content = "¿Que razón?",
  str_homestory_816001001_23_dialog_content = "(La vela es inflamable y me temo que provocará un incendio.<sprite=emo_nuhuo size=60 />)",
  str_homestory_816001001_24_dialog_content = "(Muchos desastres comienzan como peligros pequeños e intrascendentes).",
  str_homestory_816001001_25_dialog_content = "(¿Es difícil de entender?)",
  str_homestory_816001001_26_dialog_content = "No en realidad no.",
  str_homestory_816001001_27_dialog_content = "¿Así que te preocupa mi seguridad?",
  str_homestory_816001001_28_dialog_content = "(Es mi deber proteger a Lumopolis).",
  str_homestory_816001001_29_dialog_content = "(Me ayudaste mucho, así que protegerte también es importante).",
  str_homestory_816001001_30_dialog_content = "Tú también me has ayudado mucho.",
  str_homestory_816001001_31_dialog_content = "No estarás diciendo eso como una excusa para comprar el candelabro, ¿verdad?",
  str_homestory_816001001_32_dialog_content = "(¡Por supuesto no!)",
  str_homestory_816001001_33_dialog_content = "(Debe ser tratado con respeto.)",
  str_homestory_816001001_34_dialog_content = "¿Por qué te ruborizas?",
  str_homestory_816001001_35_dialog_content = "(Es por... de la luz de las velas.)",
  str_homestory_816001001_36_dialog_content = "(Por cierto, vi algo brillante en el río).",
  str_homestory_816001001_37_dialog_content = "(Al igual que la luz de las velas.)",
  str_homestory_816001001_38_dialog_content = "Sigues cambiando de tema...",
  str_homestory_818401001_0_dialog_content = "Hola, Jeriah.",
  str_homestory_818401001_1_dialog_content = "...",
  str_homestory_818401001_2_dialog_content = "¿Jeriah? Hola...?",
  str_homestory_818401001_3_dialog_content = "¿Hmm? Ah, la pequeña Caelestite.",
  str_homestory_818401001_4_dialog_content = "¿Qué estás haciendo? Pareces realmente concentrado.",
  str_homestory_818401001_5_dialog_content = "Cierto... Solo estaba soñando despierta.",
  str_homestory_818401001_6_dialog_content = "¿Soñador?",
  str_homestory_818401001_7_dialog_content = "¿Te dije que he estado en ruinas cerca de aquí antes?",
  str_homestory_818401001_8_dialog_content = "En ese momento, aún no habías regresado.",
  str_homestory_818401001_9_dialog_content = "Aquí solo había ruinas y eclipses. <sprite=emo_kulou size=60 />.",
  str_homestory_818401001_10_dialog_content = "Hombre, ¡ni siquiera quiero hablar sobre cuánto tiempo y esfuerzo tomó limpiar este lugar!",
  str_homestory_818401001_11_dialog_content = "Bien. Eso no podría haber sido fácil.",
  str_homestory_818401001_12_dialog_content = "Hablando de eso, quería preguntarte algo.",
  str_homestory_818401001_13_dialog_content = "¿Crees que la renovación de Cloud Gardens fue un esfuerzo significativo?",
  str_homestory_818401001_14_dialog_content = "Es hermoso en este momento, pero si fuera atacado, o dentro de cien años cuando te hayas ido...",
  str_homestory_818401001_15_dialog_content = "todo aquí podría volver a convertirse en ruinas.",
  str_homestory_818401001_16_option_content = "Fue significativo.",
  str_homestory_818401001_17_dialog_content = "Al menos ahora, podemos tener toda la diversión que queremos aquí.",
  str_homestory_818401001_18_dialog_content = "Si viene algún enemigo, los ahuyentaré a todos.",
  str_homestory_818401001_19_dialog_content = "Si no puedo cuidar este lugar, se lo dejaré a alguien en quien pueda confiar.",
  str_homestory_818401001_20_dialog_content = "¡Siempre habrá una manera!",
  str_homestory_818401001_21_dialog_content = "Seguro que eres optimista.",
  str_homestory_818401001_22_option_content = "Probablemente no.",
  str_homestory_818401001_23_dialog_content = "Puede que no haya tenido sentido si nuestro propósito era hacer que Cloud Gardens existiera para siempre.",
  str_homestory_818401001_24_dialog_content = "Soy consciente de los límites de mis habilidades...",
  str_homestory_818401001_25_dialog_content = "Pero al menos estamos felices, por ahora.",
  str_homestory_818401001_26_dialog_content = "¡Eso es suficiente para mi!",
  str_homestory_818401001_27_dialog_content = "Esta idea de vivir en el presente es encomiable.",
  str_homestory_818401001_28_dialog_content = "Cuando llegué por primera vez a Eraveil, pensé que era un lugar muy triste.",
  str_homestory_818401001_29_dialog_content = "Vajillas volcadas, puertas entreabiertas, montones de ropa desordenada...",
  str_homestory_818401001_30_dialog_content = "Me recordaron que una vez, la gente común había disfrutado de una vida feliz aquí.",
  str_homestory_818401001_31_dialog_content = "Esos días... puf. como dientes de león <sprite=emo_pugongying size=60 />, se los llevó el viento.",
  str_homestory_818401001_32_dialog_content = "Cierto...",
  str_homestory_818401001_33_dialog_content = "Pero los dientes de león llevan semillas de esperanza a tierras lejanas.",
  str_homestory_818401001_34_dialog_content = "¡Todo esto nunca podría carecer de sentido!",
  str_homestory_818401001_35_dialog_content = "Verdadero. Tú mismo eres como una pequeña semilla, vuelve a brotar de nuevo.",
  str_homestory_818401001_36_dialog_content = "Hablar contigo es siempre una experiencia única.",
  str_homestory_818401001_37_dialog_content = "Jeje, me siento halagado.",
  str_homestory_818401001_38_dialog_content = "Hmm... A cambio, déjame decirte algo que te puede interesar.",
  str_homestory_818401001_39_dialog_content = "Cuando estaba en el río antes, vi algo que brillaba en el agua.",
  str_homestory_818401001_40_dialog_content = "Tal vez puedas ir y echar un vistazo. ¡Piensa en ello como una aventura!",
  str_homestory_818401001_41_dialog_content = "Suena interesante... ¡Gracias, Jeriah!",
  str_homestory_818501001_0_dialog_content = "¿Qué pasa?",
  str_homestory_818501001_1_dialog_content = "Me acabo de sentar en una de esas tazas de café que giran y ahora me siento un poco mareado. <sprite=emo_xuanyun size=60 />...",
  str_homestory_818501001_2_dialog_content = "¿Mareado? ¿Las máquinas necesitan ajuste?",
  str_homestory_818501001_3_dialog_content = "Recuerdo que la velocidad ya estaba configurada en la configuración más lenta. Iré a comprobarlo más tarde.",
  str_homestory_818501001_4_dialog_content = "¡Esas cosas son súper peligrosas! ¡Por favor tenga cuidado!",
  str_homestory_818501001_5_dialog_content = "¿Peligroso?",
  str_homestory_818501001_6_dialog_content = "¿No son esas cosas para niños de cuatro años en adelante?",
  str_homestory_818501001_7_dialog_content = "Dudo que sean adecuados incluso para niños de veinte años en adelante...",
  str_homestory_818501001_8_dialog_content = "Algunas personas simplemente no pueden acostumbrarse a la sensación de giro. Es perfectamente normal.",
  str_homestory_818501001_9_dialog_content = "Un buen descanso debería ayudar.",
  str_homestory_818501001_10_dialog_content = "Bueno. voy a ir a descansar Todavía tengo que entregar cartas al norte más tarde...",
  str_homestory_818501001_11_dialog_content = "Esperar. Norte Sur...",
  str_homestory_818501001_12_dialog_content = "¡Oh, no! ¡Ya no puedo diferenciar mis direcciones!",
  str_homestory_818501001_13_dialog_content = "¡Solía estar tan orgullosa de mi sentido de la orientación! ¿¡Cómo puede ser esto!?",
  str_homestory_818501001_14_dialog_content = "*sollozando* <sprite=emo_daku size=60 />Si no puedo ni repartir cartas, ¿qué sería de mi carrera?",
  str_homestory_818501001_15_dialog_content = "Uh, eso es un poco dramático...",
  str_homestory_818501001_16_dialog_content = "PlayerName, ¿puedes decirme hacia dónde está el norte?",
  str_homestory_818501001_17_option_content = "Ve a la izquierda",
  str_homestory_818501001_18_dialog_content = "¿Lo es? No puedo decir nada...",
  str_homestory_818501001_19_option_content = "yo tampoco tengo idea",
  str_homestory_818501001_20_dialog_content = "E-Incluso tú...",
  str_homestory_818501001_21_dialog_content = "¿Vamos a terminar atrapados aquí?",
  str_homestory_818501001_22_dialog_content = "¿¿¿???",
  str_homestory_818501001_23_dialog_content = "¿Cuenta como estar atrapado cuando todavía estás en tu propia casa?",
  str_homestory_818501001_24_dialog_content = "Ahora incluso yo no estoy muy seguro de dónde estoy...",
  str_homestory_818501001_25_dialog_content = "El código de Courier Union dice que siempre debemos mantener un sentido de dirección.",
  str_homestory_818501001_26_dialog_content = "Muchos mensajeros terminan en situaciones peligrosas sin ningún lugar a donde correr solo porque se perdieron.",
  str_homestory_818501001_27_dialog_content = "Creo que ese tipo de cosas solo suceden cuando estás en la naturaleza, como un gran bosque.",
  str_homestory_818501001_28_dialog_content = "¡Estamos en los Jardines de las Nubes! ¿Ves la puerta?",
  str_homestory_818501001_29_dialog_content = "Esta justo ahí. Solo da unos pasos y estarás fuera de aquí.",
  str_homestory_818501001_30_dialog_content = "Pero, ¿y si salgo al desierto y termino tan mareado como ahora?",
  str_homestory_818501001_31_dialog_content = "¿Hay tazas de café en el desierto?",
  str_homestory_818501001_32_dialog_content = "Correcto...",
  str_homestory_818501001_33_dialog_content = "E incluso si los hay, simplemente no monte en ellos.",
  str_homestory_818501001_34_dialog_content = "¡Sí! ¡Tu eres tan inteligente!",
  str_homestory_818501001_35_dialog_content = "jaja claro...",
  str_homestory_818501001_36_dialog_content = "Cuando regrese, agregaré una nueva regla al código de Courier Union:",
  str_homestory_818501001_37_dialog_content = "\"Si te encuentras con tazas de café girando en el desierto, ¡no te sientes en ellas!\"",
  str_homestory_818501001_38_dialog_content = "Las posibilidades de encontrar tazas de café girando en el desierto deberían ser bastante bajas...",
  str_homestory_818501001_39_dialog_content = "\"—Sabiduría cortesía de Caelestite\".",
  str_homestory_818501001_40_dialog_content = "!",
  str_homestory_818501001_41_dialog_content = "¿¡Cuánto quieres que te pague para mantener mi nombre fuera de esto!?",
  str_homestory_818501001_42_dialog_content = "¿Qué? ¡Este es un consejo realmente útil! De todos modos, me voy...",
  str_homestory_818501001_43_dialog_content = "Oh, genial... Voy a ser el hazmerreír de la Unión de Mensajeros...<sprite=emo_tanqi size=60 />",
  str_homestory_802901001_0_dialog_content = "¿Gabriel?",
  str_homestory_802901001_1_dialog_content = "¿Qué crees que estás haciendo?",
  str_homestory_802901001_2_dialog_content = "Actualmente estoy tomando una siesta debajo del árbol, <sprite=emo_kun size=60 />, simplemente tomando casualmente el aliento del árbol.",
  str_homestory_802901001_3_dialog_content = "¿El aliento del árbol?",
  str_homestory_802901001_4_dialog_content = "Así es... Los árboles también son seres vivos.",
  str_homestory_802901001_5_dialog_content = "Puedo sentir el patrón de su respiración constante. Puedes sentirlo, PlayerName?",
  str_homestory_802901001_6_option_content = "Admitir",
  str_homestory_802901001_7_dialog_content = "Cuando sus hojas tiemblan, se siente como si estuviera respirando más rápido.",
  str_homestory_802901001_8_dialog_content = "Creo que es solo el viento...",
  str_homestory_802901001_9_option_content = "Negar",
  str_homestory_802901001_10_dialog_content = "Oh, no puedo sentir nada...",
  str_homestory_802901001_11_dialog_content = "Parece que eres el único con esta habilidad especial para sentir las plantas, Gabriel...",
  str_homestory_802901001_12_dialog_content = "Cada árbol es diferente, al igual que cada persona.",
  str_homestory_802901001_13_dialog_content = "Mientras sientas con tu corazón... puedes conocer su mundo interior.",
  str_homestory_802901001_14_dialog_content = "Por ejemplo, la respiración de este árbol es bastante dificultosa... Parece estar un poco enfermo...",
  str_homestory_802901001_15_dialog_content = "Supongo que debe ser por eso que sus hojas son un poco amarillas en comparación con los otros árboles.",
  str_homestory_802901001_16_dialog_content = "Se ve un poco sin vida.",
  str_homestory_802901001_17_dialog_content = "Los árboles por aquí están realmente floreciendo. Están bloqueando la luz del sol... <sprite=emo_taiyang size=60 />",
  str_homestory_802901001_18_dialog_content = "¡Parece que este pequeño tiene problemas para realizar la fotosíntesis!",
  str_homestory_802901001_19_dialog_content = "Entonces, ¿crees que necesitamos mover este árbol a otro lugar?",
  str_homestory_802901001_20_dialog_content = "No, las plantas tienen sus propias formas de hacer las cosas.",
  str_homestory_802901001_21_dialog_content = "Este árbol no trabajó lo suficiente para crecer alto, por lo que los otros árboles le robaron la luz del sol...",
  str_homestory_802901001_22_dialog_content = "Necesita confiar en sí mismo para crecer y hacerse más fuerte... ¡No deberíamos estropearlo demasiado!",
  str_homestory_802901001_23_dialog_content = "Ya veo... ¡Eso tiene mucho sentido, Gabriel!",
  str_homestory_802901001_24_dialog_content = "Je, me preocupaba que pudiera ser demasiado difícil para ti entender, PlayerName...",
  str_homestory_802901001_25_dialog_content = "¡Entiendo! Pero, lo que en realidad me sorprende un poco es—",
  str_homestory_802901001_26_dialog_content = "Por lo general, parece que siempre andas aturdido, Gabriel, pero hoy pareces tan serio.",
  str_homestory_802901001_27_dialog_content = "Creo que es más exacto decir que siempre actúo de acuerdo con mi entorno...",
  str_homestory_802901001_28_dialog_content = "Las plantas también tienen sus destinos...",
  str_homestory_802901001_29_dialog_content = "¿Destinos...?",
  str_homestory_802901001_30_dialog_content = "Bien. Encontrarte bajo este árbol es parte del destino del árbol.",
  str_homestory_802901001_31_dialog_content = "Hablando de eso, cuando estaba caminando por el río hace un momento, vi algo que brillaba...",
  str_homestory_802901001_32_dialog_content = "¿Pudiste ver lo que era?",
  str_homestory_802901001_33_dialog_content = "¡Bueno, solo estaba planeando pasar por el bosque para tomar una pequeña siesta!",
  str_homestory_802901001_34_dialog_content = "¡El hecho de que no revisé lo que había en el río también era parte del plan del destino!",
  str_homestory_802901001_35_dialog_content = "Creo que entiendo lo que quieres decir sobre el destino...",
  str_homestory_818901001_0_dialog_content = "¿Qué estás haciendo Leyen?",
  str_homestory_818901001_1_dialog_content = "¡Ey! Leyen!",
  str_homestory_818901001_2_dialog_content = "Licores de chocolate, centros afrutados <sprite=emo_sikao size=60 />... ¿Eh?",
  str_homestory_818901001_3_dialog_content = "Oh hola.",
  str_homestory_818901001_4_dialog_content = "¿Qué estás mirando, Leyn? Pareces tan concentrado.",
  str_homestory_818901001_5_dialog_content = "Nada realmente, acabo de ver esta caja de bombones.",
  str_homestory_818901001_6_dialog_content = "Esos son del Día de la Corona de Luna.",
  str_homestory_818901001_7_dialog_content = "Si quieres comértelos, Leyn, ¡ayúdate a ti mismo!",
  str_homestory_818901001_8_dialog_content = "No, no quiero comerlos. Solo estoy interesado en el proceso de producción.",
  str_homestory_818901001_9_dialog_content = "A menudo también hago postres de chocolate en casa.",
  str_homestory_818901001_10_dialog_content = "Pero normalmente solo uso chocolate derretido para la decoración.",
  str_homestory_818901001_11_dialog_content = "No me había dado cuenta de que los postres habían llegado tan lejos en términos de arte.",
  str_homestory_818901001_12_dialog_content = "Digo, ¿te gusta el chocolate?",
  str_homestory_818901001_13_option_content = "¡Me gusta!",
  str_homestory_818901001_14_dialog_content = "En ese caso, tan pronto como aprenda algunas técnicas nuevas, te dejaré intentarlo.",
  str_homestory_818901001_15_dialog_content = "Es un poco pronto para que estés bebiendo licores de chocolate...",
  str_homestory_818901001_16_dialog_content = "Te traeré unos afrutados, entonces.",
  str_homestory_818901001_17_option_content = "No es un fan...",
  str_homestory_818901001_18_dialog_content = "Oh que pena.",
  str_homestory_818901001_19_dialog_content = "La próxima vez, déjame traerte otras delicias.",
  str_homestory_818901001_20_dialog_content = "Si hay algo que le gustaría comer, por favor hágamelo saber. En cualquier momento que desee.",
  str_homestory_818901001_21_dialog_content = "¡Dulce! ¡Gracias, Leyn!",
  str_homestory_818901001_22_dialog_content = "Mmm...",
  str_homestory_818901001_23_dialog_content = "¿Qué pasa? ¿Por qué sigues mirando esos chocolates?",
  str_homestory_818901001_24_dialog_content = "¿De verdad quieres comer un poco?",
  str_homestory_818901001_25_dialog_content = "¡Tengo un poco de curiosidad por saber a qué sabrán! <sprite=emo_hanshui size=60 />",
  str_homestory_818901001_26_dialog_content = "¡Creo que me compraré una caja para seguir investigando!",
  str_homestory_818901001_27_dialog_content = "Oye, ¿por qué sigues siendo tan educado?",
  str_homestory_818901001_28_dialog_content = "Si quieres comerlos, ¡cómelos!",
  str_homestory_818901001_29_dialog_content = "Todo el mundo necesita darse un capricho de vez en cuando.",
  str_homestory_818901001_30_dialog_content = "Yo... erm...",
  str_homestory_818901001_31_dialog_content = "Gracias por su amabilidad. En ese caso, me ayudaré a mí mismo...",
  str_homestory_818601001_0_dialog_content = "Tina?",
  str_homestory_818601001_1_dialog_content = "¿Por qué estás aquí?",
  str_homestory_818601001_2_dialog_content = "Hola, PlayerName!",
  str_homestory_818601001_3_dialog_content = "Esta silla es sumamente curiosa.",
  str_homestory_818601001_4_dialog_content = "¿Te refieres a esa silla de playa?",
  str_homestory_818601001_5_dialog_content = "Correcto... Entonces, esta es una silla de playa...",
  str_homestory_818601001_6_dialog_content = "A decir verdad, no sé nada sobre la playa. Paso la mayor parte de mi tiempo en el Salón de Justicia de Lumopolis.",
  str_homestory_818601001_7_dialog_content = "¿Vas a menudo a la playa, PlayerName?",
  str_homestory_818601001_8_option_content = "Voy todo el tiempo.",
  str_homestory_818601001_9_dialog_content = "A menudo voy a la playa.",
  str_homestory_818601001_10_dialog_content = "La playa es lo mejor!",
  str_homestory_818601001_11_option_content = "Realmente no.",
  str_homestory_818601001_12_dialog_content = "En realidad, no, no voy a menudo.",
  str_homestory_818601001_13_dialog_content = "Pero la playa es bastante divertida. Tengo algunos buenos recuerdos de mi tiempo en la playa.",
  str_homestory_818601001_14_dialog_content = "¡Ya veo!",
  str_homestory_818601001_15_dialog_content = "Si pudiera ir a la playa contigo, PlayerName, eso sería genial!",
  str_homestory_818601001_16_dialog_content = "Pero todavía tengo muchos casos que tratar en el Salón de Justicia. ¡Estoy terriblemente ocupado!",
  str_homestory_818601001_17_dialog_content = "Tal vez tengamos la oportunidad de ir juntos en el futuro.",
  str_homestory_818601001_18_dialog_content = "Pero los bañadores que todo el mundo lleva en la playa... ¿Seguro que te parecen bien?",
  str_homestory_818601001_19_dialog_content = "Trajes de baño... Leí sobre eso en un libro. son bastante escasos<sprite=emo_qunzi size=60 />, ¿no?",
  str_homestory_818601001_20_dialog_content = "Cierto... El atuendo noble de Lumopolis puede ser demasiado sofocante para la playa...",
  str_homestory_818601001_21_dialog_content = "Entiendo completamente que se debe usar ropa diferente en diferentes ocasiones, pero eso no me importa en absoluto.",
  str_homestory_818601001_22_dialog_content = "Sin embargo, los ancianos pueden acusarme de abandonar su código de etiqueta. El mero pensamiento de sus burlas me da escalofríos...",
  str_homestory_818601001_23_dialog_content = "*tos* No necesitas pensar en un futuro tan lejano, Tina...",
  str_homestory_818601001_24_dialog_content = "Después de todo, ni siquiera sabemos cuándo podremos ir a la playa...",
  str_homestory_818601001_25_dialog_content = "¡Estás en lo correcto!",
  str_homestory_818601001_26_dialog_content = "Entonces... ¿Quieres probar esa silla de playa, o qué?",
  str_homestory_818601001_27_dialog_content = "¡Sí! ¡Quiero intentarlo!",
  str_homestory_818601001_28_dialog_content = "No es tan suave como mi sillón reclinable especial, ¡pero sigue siendo muy cómodo!",
  str_homestory_818601001_29_dialog_content = "Este material lo hace aún más práctico para la playa.",
  str_homestory_818601001_30_dialog_content = "¡Hola, Tina! ¿Me estás escuchando?",
  str_homestory_818601001_31_dialog_content = "Ella está profundamente dormida...",
  str_homestory_819001001_0_dialog_content = "Matthieu?",
  str_homestory_819001001_1_dialog_content = "Llegaste justo a tiempo.",
  str_homestory_819001001_2_dialog_content = "Este antiguo pabellón restaurado no está nada mal, nada mal... Es el lugar perfecto para tomar una taza de té y sumergirse en un buen libro.",
  str_homestory_819001001_3_dialog_content = "Pero todavía necesita algo especial para hacerlo aún más perfecto—",
  str_homestory_819001001_4_dialog_content = "¿Qué es?",
  str_homestory_819001001_5_dialog_content = "Es un poco monótono en este momento, ¿no crees?",
  str_homestory_819001001_6_option_content = "No me parece.",
  str_homestory_819001001_7_option_content = "Me vendría bien un poco más de decoración.",
  str_homestory_819001001_8_dialog_content = "Traeré un par de cojines. Eso debería ser suficiente, ¿verdad?",
  str_homestory_819001001_9_dialog_content = "Planeo decorarlo con flores y plantas raras, y juegos de té de oro y plata, para uso de los nobles a bordo.",
  str_homestory_819001001_10_dialog_content = "Flores y plantas raras, juegos de té dorados y plateados... ¿No sería demasiado extravagante?",
  str_homestory_819001001_11_dialog_content = "¿Te preocupa el costo? <sprite=emo_baiyebi size=60 /> Realmente eres bastante frugal Caelestite, ¿no?",
  str_homestory_819001001_12_dialog_content = "No tienes que preocuparte por el dinero. Me encargaré de eso.",
  str_homestory_819001001_13_dialog_content = "No es solo el dinero. Por supuesto, el hecho de que cueste mucho dinero es un problema en sí mismo.",
  str_homestory_819001001_14_dialog_content = "Pero como puedes cuidarlo, no es un problema. Sin embargo...",
  str_homestory_819001001_15_dialog_content = "¿Qué tratas de decir?",
  str_homestory_819001001_16_dialog_content = "Esto es Cloud Gardens, un lugar donde todos hacen todo lo posible por vivir juntos.",
  str_homestory_819001001_17_dialog_content = "No todo el mundo está interesado en cosas como ramos de flores y vajillas de oro y plata.",
  str_homestory_819001001_18_dialog_content = "No quiero hacerlo demasiado elegante, ni quiero que ciertos aurorianos se sientan incómodos.",
  str_homestory_819001001_19_dialog_content = "¿Estás pensando en aquellos que no han disfrutado de la vida cotidiana?",
  str_homestory_819001001_20_dialog_content = "Estar rodeado de flores y oro y plata no constituye exactamente la vida cotidiana...",
  str_homestory_819001001_21_dialog_content = "De todos modos, enviaré a alguien para que comience el trabajo de decoración de inmediato.",
  str_homestory_819001001_22_dialog_content = "Espera un minuto... Estoy a cargo aquí, tengo la última palabra en todas las decisiones.",
  str_homestory_819001001_23_dialog_content = "Si quieres seguir viviendo aquí con nosotros, tienes que aprender a convivir con gente diferente.",
  str_homestory_819001001_24_dialog_content = "¿Mmm? ¿Por qué palabras tan serias de repente?",
  str_homestory_819001001_25_dialog_content = "Espera... ¿Eres sólo...? <size=45>imitando a Schwab</size>!?",
  str_homestory_819001001_26_dialog_content = "¿Mmm? ¿De qué estás hablando?",
  str_homestory_819001001_27_dialog_content = "Escuché que a Schwab también le gusta leer en pabellones llenos de flores, y siempre tiene grandes multitudes de chicas jóvenes que acuden a él cuando lo hace.",
  str_homestory_819001001_28_dialog_content = "Entonces, ¿estás tratando de hacer que las chicas también se vuelvan locas por ti?",
  str_homestory_819001001_29_dialog_content = "Quieres ser tan popular como Schwab, así que lo estás copiando.",
  str_homestory_819001001_30_dialog_content = "Entiendo...",
  str_homestory_819001001_31_dialog_content = "¿¡Qué!? No me mires así, ¡como si acabaras de resolver un gran caso! <sprite=emo_shengqi size=60 />",
  str_homestory_819001001_32_dialog_content = "¡Ese no es el caso en absoluto! ¿Por qué querría ser algo como ese tonto?",
  str_homestory_819001001_33_dialog_content = "La palabra \"tonto\" suena como un insulto al principio.",
  str_homestory_819001001_34_dialog_content = "Pero algunas personas lo usan para disfrazar su cariño por los demás.",
  str_homestory_819001001_35_dialog_content = "Estoy empezando a sentirme mal de repente...",
  str_homestory_819001001_36_dialog_content = "¡Soy un destacado erudito de la Academia Dawn!",
  str_homestory_819001001_37_dialog_content = "¡¿Por qué imitaría a un tonto que solo se preocupa por mantener su imagen frente a una manada de mujeres volubles?!",
  str_homestory_819001001_38_dialog_content = "Entonces, ¿por qué necesitas decorar el viejo pabellón con flores y elegantes juegos de té?",
  str_homestory_819001001_39_dialog_content = "¡Es solo una cuestión de mis preferencias como noble, por supuesto!",
  str_homestory_819001001_40_dialog_content = "Olvídalo. Decoralo como quieras.",
  str_homestory_819001001_41_dialog_content = "No me importa.",
  str_homestory_819001001_42_dialog_content = "(¿Protesta demasiado? Mirando lo nervioso que se puso, claramente no puede haber sugerido todo esto solo porque quería un lugar para leer, ¿o sí?)",
  str_homestory_819101001_0_dialog_content = "Hati?",
  str_homestory_819101001_1_dialog_content = "¿Qué estás haciendo?",
  str_homestory_819101001_2_dialog_content = "Oh, solo hablando con un libro en la estantería.",
  str_homestory_819101001_3_dialog_content = "Uh... ¿Cómo le hablas exactamente a un libro?<sprite=emo_yihuo size=60 />",
  str_homestory_819101001_4_dialog_content = "¡Fácil! ¡Simplemente haga una pregunta y la respuesta aparecerá en sus páginas! A veces la respuesta es tan cierta que se me pone la piel de gallina.",
  str_homestory_819101001_5_dialog_content = "Entonces, ¿qué le preguntaste?",
  str_homestory_819101001_6_dialog_content = "Quería escuchar una historia, así que le pedí que me la contara.",
  str_homestory_819101001_7_dialog_content = "¿Qué tipo de historia? ¿Fue uno de miedo?",
  str_homestory_819101001_8_dialog_content = "¿No tienes miedo?",
  str_homestory_819101001_9_option_content = "Tal vez un poco...",
  str_homestory_819101001_10_dialog_content = "Pero aún así, tengo curiosidad.",
  str_homestory_819101001_11_option_content = "¡De ninguna manera!",
  str_homestory_819101001_12_dialog_content = "¿Estás bromeando? ¿Cómo podría un tipo duro como yo tener miedo de un libro?",
  str_homestory_819101001_13_dialog_content = "La historia que me contó hace un momento fue algo así...",
  str_homestory_819101001_14_dialog_content = "\"En una fría noche de invierno, estabas parado frente a una estantería, leyendo el Libro que todo lo sabe...\"",
  str_homestory_819101001_15_dialog_content = "\"Cuando, de repente, notó que algo se movía detrás de usted. Fue entonces cuando las palabras comenzaron a aparecer lentamente en las páginas...\"",
  str_homestory_819101001_16_dialog_content = "\"No te des la vuelta. <size=45>Alguien</size> está detrás de ti\".",
  str_homestory_819101001_17_dialog_content = "\"A pesar de tu miedo, no pudiste evitar darte la vuelta y mirar\".",
  str_homestory_819101001_18_dialog_content = "Eso fue todo lo que llegué en la historia. Cuando me di la vuelta para mirar, fue cuando entraste en la habitación.",
  str_homestory_819101001_19_dialog_content = "¡Jajaja! Suena como una típica novela de suspenso, pero con un giro de la vida real. ¿Qué pasa después?",
  str_homestory_819101001_20_dialog_content = "\"La persona detrás de ti no es otra que tu casero\".",
  str_homestory_819101001_21_dialog_content = "\"Pero no hay necesidad de tener miedo. Tu casero es débil y podrías enviarlo volando con un solo golpe\".",
  str_homestory_819101001_22_dialog_content = "¡¿Esperar lo?! ¡Ahora solo estás inventando cosas!",
  str_homestory_819101001_23_dialog_content = "Pero aún así, ¡casi da miedo lo adecuada que es la historia! ¡Es por eso que no puedo dejar esta historia!",
  str_homestory_819101001_24_dialog_content = "\"Para vengarte de tu arrendador por asustarte, decides darle un golpe rápido\".",
  str_homestory_819101001_25_dialog_content = "\"Desafortunadamente, tu ligero puñetazo lo tira al suelo. En represalia, él te echa de tu casa a las heladas calles, donde te resfrías y mueres\".",
  str_homestory_819101001_26_dialog_content = "Es espeluznante, ¿eh? Oh, no se preocupe, señor propietario; Nunca soñaría con golpearte.",
  str_homestory_819101001_27_dialog_content = "¡Y yo tampoco te echaría a patadas! No, espera un segundo, ¡no hay forma de que puedas noquearme con un solo golpe!",
  str_homestory_819101001_28_dialog_content = "¿Quieres intentarlo?",
  str_homestory_819101001_29_dialog_content = "¡Vamos a hacerlo!<sprite=emo_dianzan size=60 />",
  str_homestory_819101001_30_dialog_content = "¡Está bien, pero tú lo pediste! Déjame aflojar mi muñeca.",
  str_homestory_819101001_31_dialog_content = "¡E-estaba hablando de ese Libro Omnisciente!",
  str_homestory_819101001_32_dialog_content = "¿Oh? Entonces, ¿qué quieres preguntarle?",
  str_homestory_819101001_33_dialog_content = "¿Puede realmente responder a cualquier pregunta?",
  str_homestory_819101001_34_dialog_content = "Verás, estoy en un pequeño aprieto ahora mismo. Vice me pidió que arreglara las finanzas del Colossus para el mes...",
  str_homestory_819101001_35_dialog_content = "Te escuché mencionar algo sobre eso en la cafetería, sí.",
  str_homestory_819101001_36_dialog_content = "Así que fue lo primero que pregunté, y respondió:",
  str_homestory_819101001_37_dialog_content = "\"Solo soy un libro. No tengo activos, así que no tengo forma de ayudarte a equilibrar tus finanzas\".",
  str_homestory_819101001_38_dialog_content = "Tch... ¡Y aquí pensé que podría responder cualquier pregunta!",
  str_homestory_819101001_39_dialog_content = "No hay necesidad de preguntarle al Libro que todo lo sabe. Podría responder a tu pregunta, no hay problema.",
  str_homestory_819101001_40_dialog_content = "¿Ah, de verdad? Escuchémoslo entonces.",
  str_homestory_819101001_41_dialog_content = "Los gastos del Coloso están completamente fuera de control y estás al borde de la bancarrota. Eventualmente, terminarás en las calles heladas, donde te resfriarás y morirás.",
  str_homestory_819101001_42_dialog_content = "¡No te limites a robar del Libro que todo lo sabe!",
  str_homestory_819101001_43_dialog_content = "Bueno, es una respuesta bastante adecuada, ¿no crees?",
  str_homestory_819101001_44_dialog_content = "¿No es lo que... esperabas? Boo-hoo...",
  str_homestory_817702001_0_dialog_content = "Oye, creo que escuché Goldie ¡cantando!",
  str_homestory_817702001_1_dialog_content = "♪ ¡La-la-laaaa! ♪",
  str_homestory_817702001_2_dialog_content = "Oh, PlayerName! Hola.",
  str_homestory_817702001_3_dialog_content = "Hola, Goldie!",
  str_homestory_817702001_4_dialog_content = "Lo siento, no te estoy interrumpiendo, ¿verdad?",
  str_homestory_817702001_5_dialog_content = "¡De nada, de nada!",
  str_homestory_817702001_6_dialog_content = "¡Simplemente no pude evitar comenzar a cantar cuando vi el violín aquí!",
  str_homestory_817702001_7_dialog_content = "Para ser honesto, me sorprendió mucho saber que tenías uno, PlayerName.",
  str_homestory_817702001_8_dialog_content = "Será que... ¿Te interesan los instrumentos?",
  str_homestory_817702001_9_option_content = "¡Soy!",
  str_homestory_817702001_10_dialog_content = "¡Por supuesto! Me encantan los instrumentos!",
  str_homestory_817702001_11_dialog_content = "Pero no puedo jugar ninguno de ellos, así que realmente no es un gran pasatiempo, jejeje...",
  str_homestory_817702001_12_dialog_content = "¡Pero eso sigue siendo algo maravilloso!",
  str_homestory_817702001_13_dialog_content = "Parece que tenemos otra cosa en común, PlayerName!",
  str_homestory_817702001_14_option_content = "Realmente no.",
  str_homestory_817702001_15_dialog_content = "Bueno, yo no lo llamaría un interés, de verdad...",
  str_homestory_817702001_16_dialog_content = "Pero si alguna vez aprendo a tocar un instrumento, ¡serás el primero en escucharlo!",
  str_homestory_817702001_17_dialog_content = "¿En realidad? Jejeje... ¡Me siento tan honrado! ¡Gracias!",
  str_homestory_817702001_18_dialog_content = "Aunque debo mencionar algo...",
  str_homestory_817702001_19_dialog_content = "Este no es un violín cualquiera.",
  str_homestory_817702001_20_dialog_content = "¡En realidad formaba parte de la colección de un famoso detective!",
  str_homestory_817702001_21_dialog_content = "¿Un detective?",
  str_homestory_817702001_22_dialog_content = "¡Así es! Aparentemente, a este detective le gustaba mucho jugar cuando no estaba investigando casos.",
  str_homestory_817702001_23_dialog_content = "no se mucho mas de ellos...",
  str_homestory_817702001_24_dialog_content = "Pero un detective apasionado por las artes, simplemente suena romántico. <sprite=emo_aixin size=60 />!",
  str_homestory_817702001_25_dialog_content = "¡De acuerdo!",
  str_homestory_817702001_26_dialog_content = "Un detective tranquilo y racional que pasa las noches solo, sin nada más que un violín para hacerle compañía...",
  str_homestory_817702001_27_dialog_content = "Espera un momento... ¡Eso es todo! ¡Esa es la inspiración que necesitaba!",
  str_homestory_817702001_28_dialog_content = "¿Qué inspiración?",
  str_homestory_817702001_29_dialog_content = "La inspiración para mi <sprite=emo_yinfu size=60 /> ¡nueva canción!",
  str_homestory_817702001_30_dialog_content = "¡Tendré que encargar nuevos disfraces y crear una nueva coreografía también!",
  str_homestory_817702001_31_dialog_content = "¡Me emociono tanto solo de pensarlo!",
  str_homestory_817702001_32_dialog_content = "Un concierto de ídolos con temática de detectives, ¿eh?",
  str_homestory_817702001_33_dialog_content = "¡Apuesto a que será un gran éxito!",
  str_homestory_817702001_34_dialog_content = "Si alguien puede lograrlo, eres tú Goldie!",
  str_homestory_817702001_35_dialog_content = "¡Jejeje! ¡Espero verte en la audiencia cuando llegue el día!",
  str_homestory_811602001_0_dialog_content = "Qué Fleur ¿haciendo ahi?",
  str_homestory_811602001_1_dialog_content = "Ey, Fleur! ¿Qué estás haciendo?",
  str_homestory_811602001_2_dialog_content = "¡Hola, Navegador!",
  str_homestory_811602001_3_dialog_content = "Estoy ajustando el adorno.",
  str_homestory_811602001_4_dialog_content = "Lo recogí para jugar con él hace un momento...",
  str_homestory_811602001_5_dialog_content = "Y estaba haciendo un ruido extraño.",
  str_homestory_811602001_6_dialog_content = "¿Un sonido extraño?",
  str_homestory_811602001_7_dialog_content = "Así es. Tal vez uno de los tornillos esté demasiado apretado, o tal vez solo necesite un poco de aceite...",
  str_homestory_811602001_8_dialog_content = "Esta rueda sigue haciendo un chirrido horrible.",
  str_homestory_811602001_9_option_content = "¡Ya veo!",
  str_homestory_811602001_10_dialog_content = "Ahora que lo mencionas, este adorno parece un poco fuera de lugar...",
  str_homestory_811602001_11_dialog_content = "Si está haciendo ese tipo de sonido, ¿no significa que una de sus partes está en mal estado?",
  str_homestory_811602001_12_dialog_content = "¡Así es!",
  str_homestory_811602001_13_dialog_content = "La mayoría de las personas tienen dificultades para entender eso, pero parece que podrías tener una habilidad especial para arreglar máquinas.",
  str_homestory_811602001_14_dialog_content = "¿T-Tú crees? Jejeje...",
  str_homestory_811602001_15_option_content = "no tengo ni idea...",
  str_homestory_811602001_16_dialog_content = "¿Tú crees que...?",
  str_homestory_811602001_17_dialog_content = "Deja que un experto como tú lo averigüe, Fleur. Estoy desesperado cuando se trata de este tipo de cosas.",
  str_homestory_811602001_18_dialog_content = "Ya veo... Esperaba hablar contigo sobre máquinas, pero supongo que eso está fuera de discusión.",
  str_homestory_811602001_19_dialog_content = "No te preocupes, todavía puedo arreglar esto yo mismo.",
  str_homestory_811602001_20_dialog_content = "Hmm... Parece que tenía razón. Este tornillo está demasiado apretado...",
  str_homestory_811602001_21_dialog_content = "Lástima que no tengo las herramientas para aflojarlo en este momento.",
  str_homestory_811602001_22_dialog_content = "Volveré y lo arreglaré una vez que encuentre la herramienta adecuada, ¿de acuerdo?",
  str_homestory_811602001_23_dialog_content = "Cosa segura, Fleur. ¡Gracias de nuevo!",
  str_homestory_811602001_24_dialog_content = "No lo menciones. Es sólo un pequeño tornillo después de todo.",
  str_homestory_811602001_25_dialog_content = "Aún así, un pequeño tornillo puede significar un mundo de diferencia cuando se trata de máquinas, ¿sabes?",
  str_homestory_811602001_26_dialog_content = "Menos mal que es solo un juguete, si fuera un carrito de verdad...",
  str_homestory_811602001_27_dialog_content = "¡La rueda ya se habría roto! ¡Jajaja!",
  str_homestory_811602001_28_dialog_content = "En serio. La gente normal como nosotros solo sabemos que hay que arreglar algo cuando finalmente se rompe...",
  str_homestory_811602001_29_dialog_content = "Si tan solo todas las máquinas pudieran señalarnos sus problemas como Soroz...",
  str_homestory_811602001_30_dialog_content = "¿Está bien?",
  str_homestory_811602001_31_dialog_content = "Si me preguntas, la gente es mucho más difícil de entender. <sprite=emo_sikao size=60 />...",
  str_homestory_811602001_32_dialog_content = "No me malinterpreten, otorgar a cada máquina una personalidad sería un logro enorme...",
  str_homestory_811602001_33_dialog_content = "¡Pero lo último que necesito es que las máquinas me mientan mientras trabajo en ellas!",
  str_homestory_811602001_34_dialog_content = "Jejeje, eso es cierto.",
  str_homestory_811602001_35_dialog_content = "Si ese día llega, estoy seguro de que estarás hasta las orejas de problemas.",
  str_homestory_808401001_0_dialog_content = "También te gustan los acertijos, Istvan?",
  str_homestory_808401001_1_dialog_content = "Llegas justo a tiempo, mi joven amigo.",
  str_homestory_808401001_2_dialog_content = "Dime, ¿qué opinas de esta imagen?",
  str_homestory_808401001_3_dialog_content = "¿Qué hago con eso? Déjeme ver...",
  str_homestory_808401001_4_option_content = "Parece un poco desafiante.",
  str_homestory_808401001_5_dialog_content = "Creo que algunas de estas pistas parecen un poco sospechosas. <sprite=emo_sikao size=60 />.",
  str_homestory_808401001_6_dialog_content = "¡Apuesto a que podría resolverlo con un poco más de tiempo!",
  str_homestory_808401001_7_option_content = "No lo entiendo.",
  str_homestory_808401001_8_dialog_content = "Er... no soy precisamente el mejor resolviendo acertijos. <sprite=emo_tanqi size=60 />.",
  str_homestory_808401001_9_dialog_content = "No puedo envolver mi cabeza alrededor de esto en absoluto...",
  str_homestory_808401001_10_dialog_content = "Comprendo.",
  str_homestory_808401001_11_dialog_content = "Mis disculpas. Primero me hiciste una pregunta y te respondí con otra pregunta.",
  str_homestory_808401001_12_dialog_content = "Supongo que debería haberte dado una respuesta real...",
  str_homestory_808401001_13_dialog_content = "No, amigo mío. No soy aficionado a los acertijos en absoluto.",
  str_homestory_808401001_14_dialog_content = "¿Eh? ¡¿Entonces por qué sigues tratando de averiguarlo?!",
  str_homestory_808401001_15_dialog_content = "Ten por seguro, mi joven amigo, que hay una explicación perfectamente razonable para esto.",
  str_homestory_808401001_16_dialog_content = "A juzgar por tus propias palabras, asumiste que esta imagen era una pista para un acertijo.",
  str_homestory_808401001_17_dialog_content = "Lo que significa que, sin darse cuenta, lo vio desde la perspectiva de un detective.",
  str_homestory_808401001_18_dialog_content = "Er... Así es, ¿supongo?",
  str_homestory_808401001_19_dialog_content = "Sin embargo, hay muchos otros personajes involucrados en este caso.",
  str_homestory_808401001_20_dialog_content = "El detective, el perpetrador, la víctima...",
  str_homestory_808401001_21_dialog_content = "Y, por supuesto, el instigador.",
  str_homestory_808401001_22_dialog_content = "¿El instigador?",
  str_homestory_808401001_23_dialog_content = "En efecto. Como un pastor, el instigador es responsable de todo y se beneficia de ello más que nadie.",
  str_homestory_808401001_24_dialog_content = "Criar ovejas cuidadosamente a mano, pastorearlas con perros leales, protegerlas de los lobos hambrientos...",
  str_homestory_808401001_25_dialog_content = "Un buen pastor nunca entrega su rebaño a los caprichos del destino.",
  str_homestory_808401001_26_dialog_content = "Por eso, en lugar de resolver el acertijo, el instigador elige la respuesta que más lo beneficia.",
  str_homestory_808401001_27_dialog_content = "¡E-Eso es terriblemente complicado!",
  str_homestory_808401001_28_dialog_content = "Pero creo que entiendo lo que estás tratando de decir, Istvan...",
  str_homestory_808401001_29_dialog_content = "Para un líder como tú, a veces la verdad no es tan importante como el resultado final, ¿verdad?",
  str_homestory_808401001_30_dialog_content = "Tus habilidades de deducción son tan agudas como siempre.",
  str_homestory_808401001_31_dialog_content = "Aunque todavía eres joven y tus posibilidades futuras son casi ilimitadas.",
  str_homestory_808401001_32_dialog_content = "Solo espero que un Navegante como tú aprenda a mover otras piezas para su propio beneficio.",
  str_homestory_808401001_33_dialog_content = "Entregarse a los placeres de la mediocridad es un montón de ovejas, no de pastores.",
  str_homestory_808401001_34_dialog_content = "Jejeje... Gracias, pero creo que es un poco pronto para pensar en cosas así...",
  str_homestory_808401001_35_dialog_content = "... Quizás tengas razón. Apurar estas cosas podría resultar perjudicial en algunos casos.",
  str_homestory_808401001_36_dialog_content = "En ese caso, ¿por qué no te ofrezco una tarea más apropiada para tu edad?",
  str_homestory_808401001_37_dialog_content = "Mientras estaba parado junto al río, noté una moneda brillante en el agua. <sprite=emo_baiyebi size=60 />.",
  str_homestory_808401001_38_dialog_content = "No podía estar seguro en ese momento, pero existe la posibilidad de que fuera una baratija bastante rara.",
  str_homestory_808401001_39_dialog_content = "¿Por qué no vas a echar un vistazo?",
  str_homestory_808401001_40_dialog_content = "¡Seguro! Gracias, Istvan!",
  str_homestory_819301001_0_dialog_content = "Kristen?",
  str_homestory_819301001_1_dialog_content = "Qué pasa, Kristen?",
  str_homestory_819301001_2_dialog_content = "¡Hmm-hmm-hmm! <sprite=emo_yinfu size=60 />",
  str_homestory_819301001_3_dialog_content = "¡Oh nada, solo escuchando música!",
  str_homestory_819301001_4_dialog_content = "¡Tu tocadiscos es tan bonito que tenía que probarlo!",
  str_homestory_819301001_5_dialog_content = "¿Entonces, qué piensas?",
  str_homestory_819301001_6_dialog_content = "¡Es impresionante! La calidad del sonido es increíble... ¡Realmente elegiste uno bueno!",
  str_homestory_819301001_7_dialog_content = "¿Cuánto tiempo has sido un amante de la música, PlayerName?",
  str_homestory_819301001_8_dialog_content = "Siempre me ha gustado mucho la música, pero tiendo a aprender cosas interesantes durante mis viajes... ¡Como este tocadiscos!",
  str_homestory_819301001_9_dialog_content = "Aunque estoy seguro de que no es nada comparado con tu propia colección.",
  str_homestory_819301001_10_dialog_content = "Bueno, la casa de mi familia tiene una colección bastante extensa de reproductores de música... ¡Uno de ellos también es muy grande!",
  str_homestory_819301001_11_dialog_content = "apostaría...",
  str_homestory_819301001_12_dialog_content = "Probablemente sea tan alto como la entrada al Salón de la Justicia.",
  str_homestory_819301001_13_dialog_content = "¡¿Q-Qué?!",
  str_homestory_819301001_14_dialog_content = "La entrada al Salón de la Justicia... ¡Eso es enorme!",
  str_homestory_819301001_15_dialog_content = "¡Probablemente podrías celebrar un concierto en algo tan grande!",
  str_homestory_819301001_16_dialog_content = "Mi padre es uno de esos nobles coleccionistas, ¿sabes? ¡A veces se sale un poco de control!",
  str_homestory_819301001_17_dialog_content = "Pero también eres un noble, Kristen...",
  str_homestory_819301001_18_dialog_content = "¡Sí, pero mi padre y yo somos diferentes!",
  str_homestory_819301001_19_dialog_content = "¿O realmente crees que soy como uno de esos viejos nobles estirados?",
  str_homestory_819301001_20_option_content = "¡Usted no es!",
  str_homestory_819301001_21_dialog_content = "Siempre estás buscando cosas nuevas y populares.",
  str_homestory_819301001_22_dialog_content = "¡Como la música, por ejemplo!",
  str_homestory_819301001_23_option_content = "Tal vez un poco...",
  str_homestory_819301001_24_dialog_content = "Quiero decir, eres muy bien educado, como todos los nobles que he conocido.",
  str_homestory_819301001_25_dialog_content = "¡Jejeje! De verdad lo crees, PlayerName?",
  str_homestory_819301001_26_dialog_content = "No puedo decir que no estoy de acuerdo.",
  str_homestory_819301001_27_dialog_content = "Sí, mi nacimiento me hace parte de la nobleza y todo...",
  str_homestory_819301001_28_dialog_content = "¡Pero en el fondo de mi corazón, quiero vivir mi propia vida, en mis propios términos!",
  str_homestory_819301001_29_dialog_content = "¡Y esta nueva música me ha dado la inspiración que necesito para seguir adelante!",
  str_homestory_819301001_30_dialog_content = "¡Esp. un segundo!",
  str_homestory_819301001_31_dialog_content = "Y-Vas a actuar aquí mismo, Kristen? ¡¿Ahora mismo?!",
  str_homestory_819301001_32_dialog_content = "¡Así es! ¡Esta canción también es perfecta para alcanzar algunas notas muy altas! Laaaa— <sprite=emo_yinfu size=60 />",
  str_homestory_819301001_33_dialog_content = "H-Espera!",
  str_homestory_819301001_34_dialog_content = "Oh, ¿mirarías la hora? ¡Olvidé por completo que tenía algo importante que hacer! ¡Nos vemos!",
  str_homestory_819301001_35_dialog_content = "R-¿Ahora mismo?",
  str_homestory_819301001_36_dialog_content = "¡Sí! ¡Pero adelante, diviértete con el tocadiscos! ¡Adiós!",
  str_homestory_819201001_0_dialog_content = "Leo?",
  str_homestory_819201001_1_dialog_content = "Estaba buscando una lupa, y aquí está.",
  str_homestory_819201001_2_dialog_content = "¿Para qué lo vas a usar?",
  str_homestory_819201001_3_dialog_content = "Para mirar este mapa.",
  str_homestory_819201001_4_dialog_content = "Mis subordinados exploraron recientemente las posiciones de varias fortalezas militares a lo largo de la frontera.",
  str_homestory_819201001_5_dialog_content = "Acaban de terminar de dibujar este mapa hoy y lo enviaron.",
  str_homestory_819201001_6_dialog_content = "Pero la letra de este mapa es tan desaliñada y ridículamente pequeña. Me está dando dolor de cabeza. <sprite=emo_xuanyun size=60 />",
  str_homestory_819201001_7_dialog_content = "¿Hay muchas palabras escritas en el mapa?",
  str_homestory_819201001_8_dialog_content = "Véalo usted mismo.",
  str_homestory_819201001_9_dialog_content = "\"Pantalla de exploración y análisis de fortalezas militares dentro de los 80 kilómetros del crepúsculo...\"",
  str_homestory_819201001_10_dialog_content = "También hay una segunda línea.",
  str_homestory_819201001_11_dialog_content = "\"... y la información detallada, como la distribución espacial, la cantidad y las características e interrelaciones cualitativas\"",
  str_homestory_819201001_12_dialog_content = "Uf... uf... <sprite=emo_kun size=60 />",
  str_homestory_819201001_13_dialog_content = "D-¿Los nombres de todos los mapas... son tan complicados?",
  str_homestory_819201001_14_dialog_content = "Apenas puedo recuperar el aliento después de leerlo de una sola vez.",
  str_homestory_819201001_15_dialog_content = "Por supuesto que no tiene por qué ser tan complicado, pero esta vez el cartógrafo fue muy minucioso, así que escribió todo lo que pudo...",
  str_homestory_819201001_16_dialog_content = "Realmente no es necesario.",
  str_homestory_819201001_17_dialog_content = "No es de extrañar que tantos estrategas lleven consigo una lupa.",
  str_homestory_819201001_18_dialog_content = "Si alguna vez tienen que confiar en un cartógrafo tan minucioso como este tipo, una lupa es su única esperanza de poder leer sus mapas con claridad.",
  str_homestory_819201001_19_dialog_content = "(Pero incluso después de poder leer este nombre ridículo, probablemente termines aún más frustrado).",
  str_homestory_819201001_20_dialog_content = "De hecho, hay muchos líderes a los que les gusta usar lupas.",
  str_homestory_819201001_21_dialog_content = "No solo pueden ampliar el texto y las imágenes y ayudar con la observación, sino que también pueden ayudar a hacer fuego cuando brilla el sol.",
  str_homestory_819201001_22_dialog_content = "Se puede decir que son herramientas versátiles, imprescindibles para las tropas en marcha.",
  str_homestory_819201001_23_dialog_content = "Sin embargo, tengo mis reservas sobre las lupas.",
  str_homestory_819201001_24_dialog_content = "¿Por qué?",
  str_homestory_819201001_25_dialog_content = "Tú también eres un comandante en la batalla. ¿Quizás puedas adivinar la razón?",
  str_homestory_819201001_26_option_content = "Dependen de la luz.",
  str_homestory_819201001_27_dialog_content = "Son difíciles de usar por la noche o en la oscuridad.",
  str_homestory_819201001_28_dialog_content = "De hecho, esto es un problema, pero siempre que haya una fuente de luz disponible, este problema se puede evitar.",
  str_homestory_819201001_29_option_content = "Pueden limitar su campo de visión.",
  str_homestory_819201001_30_dialog_content = "Así es.",
  str_homestory_819201001_31_dialog_content = "Una lupa amplía un área, lo que permite al observador ver los detalles con mayor precisión.",
  str_homestory_819201001_32_dialog_content = "Pero al mismo tiempo, el campo de visión del observador está limitado al alcance de la lupa.",
  str_homestory_819201001_33_dialog_content = "Esto hace que uno sea incapaz de observar el entorno más amplio que los rodea.",
  str_homestory_819201001_34_dialog_content = "Pero la guerra a menudo requiere el despliegue de tropas desde una perspectiva más amplia.",
  str_homestory_819201001_35_dialog_content = "A veces evito deliberadamente usar una lupa para evitar que mi campo de visión se enfoque demasiado.",
  str_homestory_819201001_36_dialog_content = "Realmente eres un estratega inspirador.",
  str_homestory_819201001_37_dialog_content = "Es solo un hábito personal. Por ejemplo, no tengo más remedio que pedir una lupa en nuestra situación actual.",
  str_homestory_819201001_38_dialog_content = "Puedes usar la lupa aquí cuando quieras.",
  str_homestory_819201001_39_dialog_content = "Pero asegúrese de volver a colocarlo en su caja después de que termine de usarlo.",
  str_homestory_819201001_40_dialog_content = "Si se expone a la luz solar directa, puede provocar un incendio. <sprite=emo_nuhuo size=60 />",
  str_homestory_819201001_41_dialog_content = "Jaja, es bueno que tengas un fuerte sentido de la conciencia de seguridad contra incendios.",
  str_homestory_819201001_42_dialog_content = "Después de todo, he trabajado muy duro para hacer de este un lugar al que pueda llamar hogar.",
  str_homestory_819201001_43_dialog_content = "Si todo mi dinero se incendia... bueno, mi arduo trabajo habrá sido en vano.",
  str_homestory_819901001_0_dialog_content = "Yingel?",
  str_homestory_819901001_1_dialog_content = "Oh, PlayerName. Estoy a punto de probar este café.",
  str_homestory_819901001_2_dialog_content = "¿Lo elaboraste tú mismo?",
  str_homestory_819901001_3_dialog_content = "Es correcto.",
  str_homestory_819901001_4_dialog_content = "Acabo de ver esta hermosa taza de café, así que pensé en intentar preparar una taza yo mismo.",
  str_homestory_819901001_5_dialog_content = "¡Huele increíble! <sprite=emo_dianzan size=60 />",
  str_homestory_819901001_6_dialog_content = "¿Ves el patrón en la superficie? Esto es lo que llaman arte latte.",
  str_homestory_819901001_7_dialog_content = "¡Sí, lo veo! ¡Es hermoso!",
  str_homestory_819901001_8_dialog_content = "Esta forma parece... ¿Aoha?",
  str_homestory_819901001_9_dialog_content = "¿Puedes decir que es Aoha? Bueno, supongo que no puedo llamar a este intento un fracaso entonces.",
  str_homestory_819901001_10_dialog_content = "¡Claro que no es un fracaso! ¡Es increíble!",
  str_homestory_819901001_11_dialog_content = "Cómo lo hiciste, Yingel?",
  str_homestory_819901001_12_dialog_content = "Hacer un café con leche no es nada difícil, y los ingredientes también son muy básicos.",
  str_homestory_819901001_13_dialog_content = "En primer lugar, debe verter una taza pequeña de espresso en una taza de café...",
  str_homestory_819901001_14_dialog_content = "Luego, haga espuma con un poco de leche fresca y agréguela al espresso.",
  str_homestory_819901001_15_dialog_content = "Al agregar la espuma, ajuste la forma moviendo la taza de leche.",
  str_homestory_819901001_16_dialog_content = "Y así, deberías tener un café con leche con un patrón hermoso.",
  str_homestory_819901001_17_dialog_content = "Lo haces parecer fácil, pero estoy seguro de que no es tan simple como parece...",
  str_homestory_819901001_18_dialog_content = "La práctica hace la perfección. Solo inténtalo unas cuantas veces y estarás bien.",
  str_homestory_819901001_19_dialog_content = "Cada vez que me siento cansada en el trabajo, me preparo un café con leche.",
  str_homestory_819901001_20_dialog_content = "La leche suave y el café suave son una combinación perfecta.",
  str_homestory_819901001_21_dialog_content = "PlayerName, ¿te gustaría probarlo?<sprite=emo_yaosu size=60 />",
  str_homestory_819901001_22_option_content = "Si",
  str_homestory_819901001_23_dialog_content = "Después de todo, tú mismo hiciste este café.",
  str_homestory_819901001_24_option_content = "No",
  str_homestory_819901001_25_dialog_content = "Si tomo café en este momento, me temo que no podré dormir.",
  str_homestory_819901001_26_dialog_content = "Son más de dos tercios de leche, así que no te mantendrá despierto.",
  str_homestory_819901001_27_dialog_content = "¿En realidad? En ese caso, me encantaría intentarlo.",
  str_homestory_819901001_28_dialog_content = "¿Cómo es?",
  str_homestory_819901001_29_dialog_content = "¡Le doy un diez sobre diez por el sabor!",
  str_homestory_819901001_30_dialog_content = "Si tan solo pudiera hacer un café con leche tan delicioso como este.",
  str_homestory_819901001_31_dialog_content = "Deberías intentar hacer uno, sé que puedes hacerlo.",
  str_homestory_819901001_32_dialog_content = "Sin embargo, parece que me he quedado sin leche...",
  str_homestory_819901001_33_dialog_content = "¿Qué, ya se ha ido todo?",
  str_homestory_819901001_34_dialog_content = "Tenía mucha sed en este momento, así que me lo bebí todo.",
  str_homestory_819901001_35_dialog_content = "em, Yingel... no puedes engullir la leche como si fuera agua...",
  str_homestory_820001001_0_dialog_content = "Es Anatoli mirando esa lámpara de exterior?",
  str_homestory_820001001_1_dialog_content = "¿Qué haces aquí, Anatoli?",
  str_homestory_820001001_2_dialog_content = "Estoy observando esta lámpara.",
  str_homestory_820001001_3_option_content = "¿Observar una lámpara?",
  str_homestory_820001001_4_dialog_content = "He encontrado que permanece encendido, incluso durante el día.",
  str_homestory_820001001_5_dialog_content = "Aunque la luz que emite es mucho menos radiante que la luz del sol, nunca se apaga.",
  str_homestory_820001001_6_dialog_content = "¿Alguien le agrega constantemente aceite de lámpara?",
  str_homestory_820001001_7_dialog_content = "Uh, yo tampoco sé la respuesta a eso...",
  str_homestory_820001001_8_option_content = "¿Por qué?",
  str_homestory_820001001_9_dialog_content = "Porque siempre está encendido, día y noche.",
  str_homestory_820001001_10_dialog_content = "Aunque pasa desapercibido durante el día, ilumina la oscuridad por la noche. <sprite=emo_taiyang size=60 />",
  str_homestory_820001001_11_dialog_content = "¡Claro!",
  str_homestory_820001001_12_dialog_content = "¡Es genial tener una luz que ilumine el camino por la noche!",
  str_homestory_820001001_13_dialog_content = "Sin embargo... dejar la luz encendida durante el día se siente un poco inútil.",
  str_homestory_820001001_14_dialog_content = "Sí... ciertamente lo hace.",
  str_homestory_820001001_15_dialog_content = "Después de todo, esta no es la Noche Eterna... Realmente no hay necesidad de mantener las luces encendidas todo el tiempo.",
  str_homestory_820001001_16_dialog_content = "Entonces lo apagaré por ahora y lo encenderé más tarde en la noche.",
  str_homestory_820001001_17_dialog_content = "Sería mejor si lo mantuvieras encendido.",
  str_homestory_820001001_18_dialog_content = "¿Eh? ¿Por qué?",
  str_homestory_820001001_19_dialog_content = "Puede que no sepamos quién ha estado echando aceite a esta lámpara, pero debe tener sus razones.",
  str_homestory_820001001_20_dialog_content = "Sería mejor si no interrumpiéramos su rutina.",
  str_homestory_820001001_21_dialog_content = "Tienes un punto.",
  str_homestory_820001001_22_dialog_content = "¡Realmente quiero saber quién es esta persona misteriosa!",
  str_homestory_820001001_23_dialog_content = "Bueno, intenta observar más y tal vez algún día los conozcas.",
  str_homestory_820001001_24_dialog_content = "Te recuerdo siendo un auténtico genio en lo que a razonamiento y análisis se refiere...",
  str_homestory_820001001_25_dialog_content = "¿Tienes alguna idea de quién podría ser el encendedor de la lámpara misteriosa?",
  str_homestory_820001001_26_dialog_content = "Tengo mis especulaciones.",
  str_homestory_820001001_27_dialog_content = "¿Cómo qué?",
  str_homestory_820001001_28_dialog_content = "Debe ser alguien muy paciente, capaz de persistir en hacer algo durante mucho tiempo.",
  str_homestory_820001001_29_dialog_content = "Y deben tener buena memoria, ya que nunca parecen olvidar una tarea tan trivial.",
  str_homestory_820001001_30_dialog_content = "Por último, parecen muy aficionados a los objetos que emiten una luz modesta.",
  str_homestory_820001001_31_dialog_content = "Sí, eso tiene sentido...",
  str_homestory_820001001_32_dialog_content = "De hecho, me recuerda a algunas personas.",
  str_homestory_820001001_33_dialog_content = "¡Espera, lo tengo!",
  str_homestory_820001001_34_dialog_content = "¡¿No estás hablando solo de ti?!",
  str_homestory_820001001_35_dialog_content = "Excelente deducción.",
  str_homestory_820001001_36_dialog_content = "Entonces, ¿por qué mantienes encendida esta lámpara?",
  str_homestory_820001001_37_dialog_content = "Claramente es de día, así que obviamente no hay necesidad de usar una lámpara...",
  str_homestory_820001001_38_dialog_content = "Aunque el más leve parpadeo de la llama puede parecer apenas visible a la luz del sol, todavía hay algo que solo puede hacer.",
  str_homestory_820001001_39_dialog_content = "Esto es lo que creo.",
  str_homestory_802801001_0_dialog_content = "Conozco esa voz...",
  str_homestory_802801001_1_dialog_content = "Es Raphael!",
  str_homestory_802801001_2_dialog_content = "¡Whoosh! ¡Whoosh! ¡Whoosh!",
  str_homestory_802801001_3_dialog_content = "PlayerName! ¡Es genial verte!",
  str_homestory_802801001_4_dialog_content = "¡Ey! ¡Prueba mis nuevas píldoras Brain Booster!",
  str_homestory_802801001_5_dialog_content = "¡Estas pequeñas cosas pueden llenarte instantáneamente de energía! ¡Incluso pueden permitirte sentir la presencia de un tesoro místico!",
  str_homestory_802801001_6_dialog_content = "¡Edición limitada! ¡No te pierdas esta oportunidad única en la vida!",
  str_homestory_802801001_7_option_content = "No creo que lo necesite, gracias...",
  str_homestory_802801001_8_dialog_content = "¡He estado buscando por todas partes durante un tiempo y finalmente te he encontrado!",
  str_homestory_802801001_9_dialog_content = "No querrás que mi pequeño experimento fracase, ¿verdad?",
  str_homestory_802801001_10_dialog_content = "Para ser honesto, no estaba pensando en eso...",
  str_homestory_802801001_11_option_content = "¡Déjame darles una oportunidad!",
  str_homestory_802801001_12_dialog_content = "Jeje! Estás de un humor inesperadamente alegre hoy, PlayerName!",
  str_homestory_802801001_13_dialog_content = "Mañana te traeré más!",
  str_homestory_802801001_14_dialog_content = "Erm... ¿Realmente no tienes nada más que hacer estos días?",
  str_homestory_802801001_15_dialog_content = "¡Abre la boca y di \"ah\"!",
  str_homestory_802801001_16_dialog_content = "¡E-Espera un minuto!",
  str_homestory_802801001_17_dialog_content = "Ese olor... ¿No son los platos de Vice?",
  str_homestory_802801001_18_dialog_content = "(Uh, esos quemados... <sprite=emo_hanshui size=60 />)",
  str_homestory_802801001_19_dialog_content = "¡¿Eh?! ¿No confías en mí?",
  str_homestory_802801001_20_dialog_content = "Erm... Lo que quiero decir es... ya ves...",
  str_homestory_802801001_21_dialog_content = "¡Entiendo, entiendo! Te gustan los compañeros de confianza en los que puedes confiar, ¿no es así? PlayerName?",
  str_homestory_802801001_22_dialog_content = "¡Estoy haciendo todo lo posible para convertirme en un compañero incomparablemente confiable!",
  str_homestory_802801001_23_dialog_content = "Uno que puede hacer píldoras Brain Booster—",
  str_homestory_802801001_24_dialog_content = "Jeje, pero realmente no debería presumir.",
  str_homestory_802801001_25_dialog_content = "(Ella es sorprendentemente optimista...)",
  str_homestory_802801001_26_dialog_content = "Qué tal esto, Raphael—Puedes seguir adelante y hacer un poco más, y luego dejar Carleen ¡Pruébalos otro día!",
  str_homestory_802801001_27_dialog_content = "Ella siempre está trabajando muy duro... En realidad, podría apreciar algunos Brain Boosters.",
  str_homestory_802801001_28_dialog_content = "¿Eh? Carleen?",
  str_homestory_802801001_29_dialog_content = "¡No me parece!",
  str_homestory_802801001_30_dialog_content = "¿A qué te refieres con eso?",
  str_homestory_802801001_31_dialog_content = "Porque si los llevo a Carleen, sé que ella diría—",
  str_homestory_802801001_32_dialog_content = "\"Raphael! No te atrevas a intentar darme más de tu extraño caramelo, y no preguntes por qué\".",
  str_homestory_802801001_33_dialog_content = "¿Por qué?",
  str_homestory_802801001_34_dialog_content = "¡Ojalá supiera! <sprite=emo_sikao size=60 /> Pero Carleen Ni siquiera me deja preguntar.",
  str_homestory_802801001_35_dialog_content = "Ah, sí, y...",
  str_homestory_802801001_36_dialog_content = "Estas píldoras fueron diseñadas específicamente para ti y tus habilidades psíquicas, PlayerName!",
  str_homestory_802801001_37_dialog_content = "Está bien, entiendo... ¡Solo dámelo entonces!",
  str_homestory_802801001_38_dialog_content = "(Bueno, si son solo dulces...)",
  str_homestory_802801001_39_dialog_content = "Jeje! Sabía que eran perfectos para ti, PlayerName!",
  str_homestory_802801001_40_dialog_content = "Entonces, cómo estuvo...? ¡¿Cómo fue?! ¿Has notado algún cambio?",
  str_homestory_802801001_41_dialog_content = "¿Has visto algo brillante? como un tesoro?",
  str_homestory_802801001_42_dialog_content = "Mi visión parece más clara, y puedo ver más lejos—",
  str_homestory_802801001_43_dialog_content = "¡En el rio! ¡Realmente hay algo brillante en el río!",
  str_homestory_802801001_44_dialog_content = "¡Sí! ¡En el rio! ¡Lo sabía!",
  str_homestory_802801001_45_dialog_content = "¡Mi experimento Brain Booster fue un éxito! <sprite=emo_aixin size=60 />",
  str_homestory_820201001_0_dialog_content = "¿Qué estás haciendo acá?",
  str_homestory_820201001_1_dialog_content = "Aquí estás.",
  str_homestory_820201001_2_dialog_content = "¿Este trono fue establecido específicamente para mí?",
  str_homestory_820201001_3_dialog_content = "Sí...",
  str_homestory_820201001_4_dialog_content = "Apruebo el pensamiento.",
  str_homestory_820201001_5_dialog_content = "Aunque no está al nivel del trono genuino en Lumopolis Gardens...",
  str_homestory_820201001_6_dialog_content = "Sin embargo, es lo suficientemente adecuado para mi estado.",
  str_homestory_820201001_7_dialog_content = "¡Me alegra que te guste!",
  str_homestory_820201001_8_dialog_content = "hay algo mas que usted necesite?",
  str_homestory_820201001_9_dialog_content = "¿Qué tal construir un nuevo palacio de Lumopolis aquí? <sprite=emo_sikao size=60 />",
  str_homestory_820201001_10_dialog_content = "Como ya tenemos un trono, también podríamos construir un palacio para acompañarlo.",
  str_homestory_820201001_11_dialog_content = "¿Quieres construir un palacio aquí?",
  str_homestory_820201001_12_dialog_content = "No creo que haya suficiente espacio...",
  str_homestory_820201001_13_dialog_content = "Mmm, eso es cierto. Además de ser tosco, no es lo suficientemente grande.",
  str_homestory_820201001_14_dialog_content = "¿Qué tal una renovación financiada por mí?",
  str_homestory_820201001_15_option_content = "Esta bien",
  str_homestory_820201001_16_dialog_content = "Aprecio el pensamiento.",
  str_homestory_820201001_17_option_content = "¿Quieres?",
  str_homestory_820201001_18_dialog_content = "Aparte de los materiales, también se necesita mucha mano de obra para la expansión.",
  str_homestory_820201001_19_dialog_content = "No creo que el proyecto esté garantizado si solo vienes de vez en cuando.",
  str_homestory_820201001_20_dialog_content = "Es trivial para mí.",
  str_homestory_820201001_21_dialog_content = "Pero podemos olvidarlo si no lo quieres.",
  str_homestory_820201001_22_dialog_content = "Espera, creo que huelo algo... <sprite=emo_wuzui size=60 />",
  str_homestory_820201001_23_dialog_content = "¿Qué es? ¿Un olor extraño?",
  str_homestory_820201001_24_dialog_content = "No huelo nada.",
  str_homestory_820201001_25_dialog_content = "Eso es exactamente lo que falta.",
  str_homestory_820201001_26_dialog_content = "Debe agregar algunos aromas agradables para que el aire huela más limpio y ordenado.",
  str_homestory_820201001_27_dialog_content = "No me interesan mucho los olores...",
  str_homestory_820201001_28_dialog_content = "Si los visitantes no sienten un aire de elegancia cuando llegan aquí...",
  str_homestory_820201001_29_dialog_content = "¡Eso es una grave falta de etiqueta!",
  str_homestory_820201001_30_dialog_content = "En ese caso, pondré a alguien en ello.",
  str_homestory_820201001_31_dialog_content = "Espero ver un cambio cuando visite de nuevo.",
  str_homestory_820201001_32_dialog_content = "Seguro...",
  str_homestory_820301001_0_dialog_content = "Jakine?",
  str_homestory_820301001_1_dialog_content = "Entiendo...",
  str_homestory_820301001_2_dialog_content = "¿Qué estás haciendo?",
  str_homestory_820301001_3_dialog_content = "¿Qué... cuánto tiempo has estado aquí?",
  str_homestory_820301001_4_dialog_content = "¿Viste la lectura que acabo de hacer?",
  str_homestory_820301001_5_dialog_content = "Acabo de llegar y no vi nada.",
  str_homestory_820301001_6_dialog_content = "¿Estabas haciendo una lectura para algo muy privado?",
  str_homestory_820301001_7_dialog_content = "Lo siento, me iré ahora mismo.",
  str_homestory_820301001_8_dialog_content = "Es para algo muy privado, sin embargo...",
  str_homestory_820301001_9_dialog_content = "Tiene que ver contigo.",
  str_homestory_820301001_10_dialog_content = "¿Conmigo?",
  str_homestory_820301001_11_dialog_content = "Sí. Escuché la conversación que tuviste con Vice.",
  str_homestory_820301001_12_dialog_content = "¿Estás teniendo problemas financieros últimamente?",
  str_homestory_820301001_13_dialog_content = "Bueno, es un poco estrecho.",
  str_homestory_820301001_14_dialog_content = "Estaba preocupado, así que hice una lectura para ti.",
  str_homestory_820301001_15_dialog_content = "Si no quieres saberlo, mantendré el resultado en secreto.",
  str_homestory_820301001_16_dialog_content = "no me importa Entonces, ¿cuál es el resultado?",
  str_homestory_820301001_17_dialog_content = "Bueno, sobre tus finanzas en el futuro...",
  str_homestory_820301001_18_dialog_content = "Espera, todavía no estoy mentalmente preparado para una mala participación...",
  str_homestory_820301001_19_dialog_content = "¡Dice que serás súper rico! ¡Vivir una vida libre de estrés y feliz todos los días! <sprite=emo_yaosu size=60 />",
  str_homestory_820301001_20_dialog_content = "¿En realidad? ¿De verdad va a ser tan increíble?",
  str_homestory_820301001_21_dialog_content = "¿Crees eso?",
  str_homestory_820301001_22_dialog_content = "¿Eh? ¿Entonces me estabas mintiendo?",
  str_homestory_820301001_23_dialog_content = "Sólo respóndeme, ¿lo crees?",
  str_homestory_820301001_24_option_content = "sí",
  str_homestory_820301001_25_dialog_content = "¡Tocar el asunto exacto! ¡Esa es la mejor actitud para tener!",
  str_homestory_820301001_26_option_content = "No",
  str_homestory_820301001_27_dialog_content = "¿Por qué no? ¡Me estás haciendo enojar ahora!",
  str_homestory_820301001_28_dialog_content = "¡El poder de creer es fundamental!",
  str_homestory_820301001_29_dialog_content = "Cuando crees en algo, esa es la dirección en la que todo se mueve.",
  str_homestory_820301001_30_dialog_content = "Pero, ¿qué tiene eso que ver con la adivinación?",
  str_homestory_820301001_31_dialog_content = "Porque el propósito de la lectura es...",
  str_homestory_820301001_32_dialog_content = "¡Para aprovechar el presente!",
  str_homestory_820301001_33_dialog_content = "Hmm, parece que la adivinación es realmente un doble discurso...",
  str_homestory_820301001_34_dialog_content = "Eso es porque la vida es un largo camino, después de todo.",
  str_homestory_820301001_35_dialog_content = "Y en este camino hay muchas bifurcaciones.",
  str_homestory_820301001_36_dialog_content = "Lo que significa que su decisión afectará el camino que emprenderá en el futuro.",
  str_homestory_820301001_37_dialog_content = "Pero independientemente, vi un futuro brillante para ti. <sprite=emo_taiyang size=60 />.",
  str_homestory_820301001_38_dialog_content = "Entiendo.",
  str_homestory_820301001_39_dialog_content = "El futuro está lleno de variables, pero todo depende del aquí y ahora.",
  str_homestory_820301001_40_dialog_content = "Wow, bien dicho... Debo escribirlo en mi diario.",
  str_homestory_820301001_41_dialog_content = "Jaja, de todos modos, esta charla me ha hecho sentir mucho mejor.",
  str_homestory_809801001_0_dialog_content = "Cuscuta?",
  str_homestory_809801001_1_dialog_content = "¿Qué estás mirando, Cuscuta?",
  str_homestory_809801001_2_dialog_content = "Flores <sprite=emo_huaduo size=60 />.",
  str_homestory_809801001_3_dialog_content = "Algunas de las flores del arbusto dan la bienvenida al sol y otras se niegan a ser vistas.",
  str_homestory_809801001_4_dialog_content = "Conozco uno de este último tipo llamado Black Tail. ¿Has oido de esto?",
  str_homestory_809801001_5_option_content = "Si",
  str_homestory_809801001_6_dialog_content = "Pero, ¿qué quiere decir con \"se negó a ser mirado\"?",
  str_homestory_809801001_7_option_content = "No",
  str_homestory_809801001_8_dialog_content = "¿Qué tipo de flor es?",
  str_homestory_809801001_9_dialog_content = "La cola negra es muy rara.",
  str_homestory_809801001_10_dialog_content = "Sus pétalos son frágiles, de tonos profundos y absorben la luz del sol con facilidad.<sprite=emo_taiyang size=60 />.",
  str_homestory_809801001_11_dialog_content = "Por eso, para evitar quemaduras, suele esconderse debajo de las hojas.",
  str_homestory_809801001_12_dialog_content = "Por lo tanto, se negó a ser mirado.",
  str_homestory_809801001_13_dialog_content = "Veo a que te refieres...",
  str_homestory_809801001_14_dialog_content = "Te gusta mucho Black Tails, ¿verdad? Cuscuta?",
  str_homestory_809801001_15_dialog_content = "¿Cómo determino si lo hago o no?",
  str_homestory_809801001_16_dialog_content = "Bueno, tener una visión única de él y comprender cómo crece...",
  str_homestory_809801001_17_dialog_content = "Creo que es solo alguien interesado en eso como tú lo descubrirías, ¿verdad?",
  str_homestory_809801001_18_dialog_content = "¿Tú crees que...?",
  str_homestory_809801001_19_dialog_content = "En realidad, los Black Tails normalmente crecen en cadáveres.",
  str_homestory_809801001_20_dialog_content = "¡¿Cuerpos muertos?!",
  str_homestory_809801001_21_dialog_content = "Sí. Yo creo...",
  str_homestory_809801001_22_dialog_content = "Justo aquí, pronto, verás Black Tails.",
  str_homestory_809801001_23_dialog_content = "¡¿Q-Quieres decir... que hay un cadáver... enterrado aquí debajo?!",
  str_homestory_809801001_24_dialog_content = "No te preocupes, ya lo comprobé.",
  str_homestory_809801001_25_dialog_content = "Me refiero a este cuerpo mío que pronto se marchitará.",
  str_homestory_809801001_26_dialog_content = "Oh, dormiré pronto, lo que significa que Black Tails aparecerá.",
  str_homestory_809801001_27_dialog_content = "N-No, Cuscuta!",
  str_homestory_809801001_28_dialog_content = "Chubbs me dijo que el suelo de Cloud Gardens tiene minerales especiales.",
  str_homestory_809801001_29_dialog_content = "S-Así que no es raro que Black Tails crezca.",
  str_homestory_809801001_30_dialog_content = "¡Quizás incluso las flores de colores sean posibles!",
  str_homestory_809801001_31_dialog_content = "Vistoso...",
  str_homestory_809801001_32_dialog_content = "¿Es eso cierto? <sprite=emo_yundao size=60 />",
  str_homestory_809801001_33_dialog_content = "Sí. Entonces, ¿qué tal si plantamos flores de colores juntos?",
  str_homestory_809801001_34_dialog_content = "Plantar juntos... ¿Eso es... trabajo?",
  str_homestory_809801001_35_dialog_content = "Bueno, no del todo...",
  str_homestory_809801001_36_dialog_content = "A ti también te gustan las flores, PlayerName?",
  str_homestory_809801001_37_dialog_content = "Podría decirse eso.",
  str_homestory_809801001_38_dialog_content = "Siempre sentí que no había suficiente color en Cloud Gardens.",
  str_homestory_809801001_39_dialog_content = "¡Me acabas de recordar que podemos plantar más flores para agregar colores!",
  str_homestory_809801001_40_dialog_content = "¿Estás diciendo que añadir colores hará que la gente sea más feliz?",
  str_homestory_809801001_41_dialog_content = "¡Por supuesto! ¿Por qué no buscamos flores de colores alrededor?",
  str_homestory_809801001_42_dialog_content = "Claro, podemos hacer eso.",
  str_homestory_809801001_43_dialog_content = "¿Pero el colorido que mencionaste incluye oro?",
  str_homestory_809801001_44_dialog_content = "¿Ves esa cosa que brilla en oro en el lago? ¿Es eso una flor?",
  str_homestory_820101001_0_dialog_content = "¿En qué estás empezando?",
  str_homestory_820101001_1_dialog_content = "Si...",
  str_homestory_820101001_2_dialog_content = "Te molesté, Mia?",
  str_homestory_820101001_3_dialog_content = "N-No. Solo estoy reflexionando sobre algunos temas difíciles.",
  str_homestory_820101001_4_dialog_content = "¿Algo en lo que pueda ayudarte?",
  str_homestory_820101001_5_dialog_content = "Sí. ¿Puedo hacerte una pregunta?",
  str_homestory_820101001_6_dialog_content = "Seguro.",
  str_homestory_820101001_7_dialog_content = "Si pudieras recordar un día para siempre, ¿qué día elegirías?",
  str_homestory_820101001_8_dialog_content = "Para siempre, eh... Realmente no puedo pensar en uno.",
  str_homestory_820101001_9_dialog_content = "Así que eso es lo que te está molestando.",
  str_homestory_820101001_10_dialog_content = "Es porque vi la pregunta, así que...",
  str_homestory_820101001_11_dialog_content = "Está bien, déjame pensar.",
  str_homestory_820101001_12_option_content = "El Coloso reiniciando...",
  str_homestory_820101001_13_dialog_content = "Elegiría recordar el día en que Colossus se reinició con éxito.",
  str_homestory_820101001_14_dialog_content = "Esa fue la primera vez que vi cómo se ve Astra.",
  str_homestory_820101001_15_dialog_content = "Tal vez incluso puedas llamarlo el comienzo de mi vida.",
  str_homestory_820101001_16_option_content = "El ascenso del Obelisco del Retorno...",
  str_homestory_820101001_17_dialog_content = "Elegiría recordar el día en que se elevó el Obelisco del Retorno...",
  str_homestory_820101001_18_dialog_content = "Mis poderes mentales aumentaron hasta donde sentí que podía ver todos los rincones de Astra.",
  str_homestory_820101001_19_dialog_content = "Ese sentimiento fue increíble.",
  str_homestory_820101001_20_dialog_content = "Eso suena como un día increíble.",
  str_homestory_820101001_21_dialog_content = "Lo pensaste lo suficientemente rápido, PlayerName",
  str_homestory_820101001_22_dialog_content = "En realidad, antes de que Colossus se reiniciara, cada día era una repetición del día anterior a mí.",
  str_homestory_820101001_23_dialog_content = "Mi vida solo se volvió animada hasta que conocí a todos.",
  str_homestory_820101001_24_dialog_content = "Así que ahora lo atesoro para asegurarme de tener un recuerdo claro de sus rostros.",
  str_homestory_820101001_25_dialog_content = "Y me esforzaré por recordarlo todo y preservarlo para siempre.",
  str_homestory_820101001_26_dialog_content = "Ah... <sprite=emo_sikao size=60 />",
  str_homestory_820101001_27_dialog_content = "¿Qué tal si compartes tus pensamientos, Mia?",
  str_homestory_820101001_28_dialog_content = "Mis pensamientos...",
  str_homestory_820101001_29_dialog_content = "Desde que olvidé algunos recuerdos importantes hasta hace poco...",
  str_homestory_820101001_30_dialog_content = "Me preocupa mucho volver a perderlos, así que quiero retenerlos a todos...",
  str_homestory_820101001_31_dialog_content = "Pero es difícil elegir entre conservar los recuerdos de mi madre, hermana...",
  str_homestory_820101001_32_dialog_content = "Mia...",
  str_homestory_820101001_33_dialog_content = "Perdón por traerte conmigo...",
  str_homestory_820101001_34_dialog_content = "No, debería disculparme. No debí haber dicho todo eso.",
  str_homestory_820101001_35_dialog_content = "No pasa nada, PlayerName.",
  str_homestory_820101001_36_dialog_content = "De hecho, estoy aliviado por lo que dijiste.",
  str_homestory_820101001_37_dialog_content = "¿En serio?",
  str_homestory_820101001_38_dialog_content = "Sí, en lugar de preocuparse por olvidar el pasado, es más importante apreciar el presente. <sprite=emo_yaosu size=60 />.",
  str_homestory_820401001_0_dialog_content = "Dama Joshua?",
  str_homestory_820401001_1_dialog_content = "¿Qué estás haciendo?",
  str_homestory_820401001_2_dialog_content = "Mirar, PlayerName.",
  str_homestory_820401001_3_dialog_content = "¡Esta planta en maceta está creciendo muy bien!",
  str_homestory_820401001_4_dialog_content = "Estoy tratando de averiguar qué variedad es.",
  str_homestory_820401001_5_dialog_content = "Veo. ¿Ya lo identificaste?",
  str_homestory_820401001_6_dialog_content = "Desafortunadamente, no he podido, hasta ahora...",
  str_homestory_820401001_7_dialog_content = "¿Sabes qué planta es esta?",
  str_homestory_820401001_8_option_content = "Asentir",
  str_homestory_820401001_9_dialog_content = "Lo compré en Umbraton no hace mucho.",
  str_homestory_820401001_10_dialog_content = "Elegí al azar lo que estaba disponible.",
  str_homestory_820401001_11_dialog_content = "Creo que el vendedor lo llamó... ¿planta señorial?",
  str_homestory_820401001_12_dialog_content = "Sí, ese es el nombre.",
  str_homestory_820401001_13_dialog_content = "El nombre es bastante simple, ¡pero lo has mantenido en excelente forma!",
  str_homestory_820401001_14_dialog_content = "Bueno, el vendedor dijo que podría crecer muy exuberante si se cuida.",
  str_homestory_820401001_15_option_content = "Sacudir la cabeza",
  str_homestory_820401001_16_dialog_content = "Bueno, yo tampoco estoy seguro.",
  str_homestory_820401001_17_dialog_content = "Solo recuerdo que el vendedor dijo que es una planta perenne.",
  str_homestory_820401001_18_dialog_content = "También puedes criarlo en interiores.",
  str_homestory_820401001_19_dialog_content = "Parece ser una variedad fácil de cuidar.",
  str_homestory_820401001_20_dialog_content = "Tienes muchas plantas verdes aquí, PlayerName.",
  str_homestory_820401001_21_dialog_content = "¿Alguna vez consideró tener flores en la mezcla?<sprite=emo_huaduo size=60 />?",
  str_homestory_820401001_22_dialog_content = "Entonces el ambiente no será monótono.",
  str_homestory_820401001_23_dialog_content = "¡Oye, esa es una gran sugerencia!",
  str_homestory_820401001_24_dialog_content = "Pero no soy muy bueno con las flores...",
  str_homestory_820401001_25_dialog_content = "Es más fácil para mí limitarme a las plantas verdes.",
  str_homestory_820401001_26_dialog_content = "Plantaría diferentes flores en el jardín cuando esté en Lumopolis.",
  str_homestory_820401001_27_dialog_content = "Regarlas y podarlas en mi tiempo libre...",
  str_homestory_820401001_28_dialog_content = "Eso me hace sentir muy sereno por dentro.",
  str_homestory_820401001_29_dialog_content = "¡No sabía que te gustaba eso!",
  str_homestory_820401001_30_dialog_content = "Entonces, ¿me enseñarás a cultivar flores, señora? Joshua?",
  str_homestory_820401001_31_dialog_content = "¡Claro!",
  str_homestory_820401001_32_dialog_content = "Cultivar flores no es difícil, pero requiere paciencia.",
  str_homestory_820401001_33_dialog_content = "Las flores son muy delicadas en su etapa temprana de crecimiento.",
  str_homestory_820401001_34_dialog_content = "Puedes usar la maceta para esta planta exactamente para eso.",
  str_homestory_820401001_35_dialog_content = "Una vez que plantes las semillas, asegúrate de regar regularmente.<sprite=emo_hanshui size=60 /> y esperar a que florezcan.",
  str_homestory_820401001_36_dialog_content = "Pero recuerda no regar en exceso.",
  str_homestory_820401001_37_dialog_content = "Ok, lo tengo. ¿Y luego?",
  str_homestory_820401001_38_dialog_content = "Después de que broten las semillas, cuídalas durante un mes.",
  str_homestory_820401001_39_dialog_content = "¡Nutre las plántulas con más nutrientes mientras tanto!",
  str_homestory_820401001_40_dialog_content = "Cuando vea retoños, transplántelos a un espacio más grande.",
  str_homestory_820401001_41_dialog_content = "Así que necesito moverlos, ya veo...",
  str_homestory_820401001_42_dialog_content = "Sí. Cuando pasas de ser un niño a un joven valiente, PlayerName...",
  str_homestory_820401001_43_dialog_content = "¿No se aventuró también y amplió sus horizontes en otros lugares?",
  str_homestory_820401001_44_dialog_content = "Eso es parte del ciclo de crecimiento.",
  str_homestory_820401001_45_dialog_content = "B-Bueno, eso es precisamente lo que pasó...",
  str_homestory_820401001_46_dialog_content = "Pero en realidad me estás haciendo sonrojar.",
  str_homestory_820401001_47_dialog_content = "eres un buen chico, PlayerName.",
  str_homestory_820501001_0_dialog_content = "¿Señorita Blanca?",
  str_homestory_820501001_1_dialog_content = "Vi que tenías los ojos cerrados. Estabas dormido<sprite=emo_kun size=60 />?",
  str_homestory_820501001_2_dialog_content = "No, estaba meditando.",
  str_homestory_820501001_3_dialog_content = "¿Meditando?",
  str_homestory_820501001_4_dialog_content = "Sí. ¿Sabes qué es la meditación?",
  str_homestory_820501001_5_option_content = "Un poco",
  str_homestory_820501001_6_dialog_content = "Escuché que la meditación puede calmar tu mente y sanar traumas.",
  str_homestory_820501001_7_dialog_content = "Eso es correcto, de hecho puede hacer eso.",
  str_homestory_820501001_8_option_content = "Nop",
  str_homestory_820501001_9_dialog_content = "La meditación es una práctica mental que puede calmar tu mente y sanar traumas.",
  str_homestory_820501001_10_dialog_content = "¿Tienes algún tipo de problema? ¿Te sientes inquieto?",
  str_homestory_820501001_11_dialog_content = "Además de meditar solo, también puedes hablar con un amigo, como yo.",
  str_homestory_820501001_12_dialog_content = "Pensé que te veías bastante solo.",
  str_homestory_820501001_13_dialog_content = "Aprecio el pensamiento.",
  str_homestory_820501001_14_dialog_content = "Disfruto de tu compañía, por supuesto, pero no puedo decirte el motivo de mi meditación.",
  str_homestory_820501001_15_dialog_content = "Más bien, no serviría de nada si te lo dijera, de todos modos.",
  str_homestory_820501001_16_dialog_content = "¿Es algo serio? Puedo intentar ayudar...",
  str_homestory_820501001_17_dialog_content = "Jejeje, tener un amigo como tú podría ser de ayuda.",
  str_homestory_820501001_18_dialog_content = "Ya que mi estado de ánimo se anima cada vez que te veo.",
  str_homestory_820501001_19_dialog_content = "La meditación también es un secreto para lucir joven.",
  str_homestory_820501001_20_dialog_content = "¿Parece juvenil?",
  str_homestory_820501001_21_dialog_content = "Sí. Estaba meditando sobre retrasar el envejecimiento y mantener mi apariencia física.",
  str_homestory_820501001_22_dialog_content = "¿Podrías hacer eso simplemente meditando?",
  str_homestory_820501001_23_dialog_content = "No subestimes el poder de los pensamientos.",
  str_homestory_820501001_24_dialog_content = "Entonces, ¿te gustaría probarlo?",
  str_homestory_820501001_25_dialog_content = "¿Puede hacerme un luchador fuerte y poderoso?",
  str_homestory_820501001_26_dialog_content = "¿Es eso lo que quieres?",
  str_homestory_820501001_27_dialog_content = "Sí, entonces puedo proteger mejor a las personas y las cosas que quiero proteger.",
  str_homestory_820501001_28_dialog_content = "Apruebo mucho ese pensamiento ya que también he estado luchando para proteger.",
  str_homestory_820501001_29_dialog_content = "Pero permítanme recordarles que la protección toma muchas formas.",
  str_homestory_820501001_30_dialog_content = "Tómame, por ejemplo. Incluso como guía, estoy defendiendo a Lumopolis de diferentes maneras.",
  str_homestory_820501001_31_dialog_content = "¿Por qué el recordatorio? ¿Es porque no puedo manifestar lo que quiero a través de la meditación?",
  str_homestory_820501001_32_dialog_content = "Realmente no sé si la meditación mejorará y aumentará la masa muscular.",
  str_homestory_820501001_33_dialog_content = "Sin embargo, aún puedes intentarlo.",
  str_homestory_820501001_34_dialog_content = "Bueno, yo tampoco creo que lo haga...",
  str_homestory_807501001_0_dialog_content = "Odi?",
  str_homestory_807501001_1_dialog_content = "¡No puedo creer que haya algo tan bueno aquí!",
  str_homestory_807501001_2_dialog_content = "¿Dónde está mi llave inglesa? ¡Voy a empezar a desarmar cosas!",
  str_homestory_807501001_3_dialog_content = "Espera, ¿qué estás desmantelando ahora?",
  str_homestory_807501001_4_dialog_content = "La luz de la calle. ¿Por qué?",
  str_homestory_807501001_5_option_content = "No puedes hacer eso.",
  str_homestory_807501001_6_option_content = "¿Está rota la luz de la calle?",
  str_homestory_807501001_7_dialog_content = "No, solo quiero desmontarlo.",
  str_homestory_807501001_8_dialog_content = "No puedo hacer eso, entonces.<sprite=emo_shengqi size=60 />",
  str_homestory_807501001_9_dialog_content = "¡Por qué tú! ¿Por qué no puedo? ¡Es solo una simple farola vieja!",
  str_homestory_807501001_10_dialog_content = "No está roto, entonces, ¿por qué lo quitarías?",
  str_homestory_807501001_11_dialog_content = "Para estudiarlo, por supuesto.",
  str_homestory_807501001_12_dialog_content = "Mira, esta luz es completamente diferente del resto.",
  str_homestory_807501001_13_dialog_content = "Uh, no veo mucha diferencia en absoluto.",
  str_homestory_807501001_14_dialog_content = "Puedo decir que tiene engranajes internos intrincados y cableado por el exterior.",
  str_homestory_807501001_15_dialog_content = "No creo que así funcionen las luces de la calle en Lumopolis...",
  str_homestory_807501001_16_dialog_content = "Te lo dije, no lo entenderías.",
  str_homestory_807501001_17_dialog_content = "No, no me dijiste eso.",
  str_homestory_807501001_18_dialog_content = "Veo que has mejorado en el descaro.",
  str_homestory_807501001_19_dialog_content = "De acuerdo, te decidiste a mantener esta luz, ¿verdad?",
  str_homestory_807501001_20_dialog_content = "Pues bien, vamos a ello.",
  str_homestory_807501001_21_dialog_content = "¡Y veremos si puedo golpearte para que no funcione bien!",
  str_homestory_807501001_22_dialog_content = "¡No soy una máquina, no puedo fallar!",
  str_homestory_807501001_23_dialog_content = "Tu cable es lo único que va a fallar.",
  str_homestory_807501001_24_dialog_content = "¿Me estás amenazando?",
  str_homestory_807501001_25_dialog_content = "solo expongo los hechos...",
  str_homestory_807501001_26_dialog_content = "No nos menosprecies a los técnicos. Puede que seas un caelestita, pero aún así...",
  str_homestory_807501001_27_dialog_content = "¿¿¿???",
  str_homestory_807501001_28_dialog_content = "Ups, no sé con qué amenazarte.<sprite=emo_sikao size=60 />",
  str_homestory_807501001_29_dialog_content = "Jajaja...",
  str_homestory_807501001_30_dialog_content = "¡Oye, ríete de mí otra vez y pediré refuerzos!",
  str_homestory_807501001_31_dialog_content = "¡Jajajajaja!",
  str_homestory_807501001_32_dialog_content = "Deja de reír, o voy a conseguir Sinsa para venir!",
  str_homestory_807501001_33_dialog_content = "Seguro Sinsa se pondrá de tu lado?",
  str_homestory_807501001_34_dialog_content = "Eh... Bueno, en realidad no...",
  str_homestory_807501001_35_dialog_content = "Entonces, ¿solo quieres estudiar esta luz?",
  str_homestory_807501001_36_dialog_content = "Sí. Parece lo suficientemente interesante como para desglosar y ver.",
  str_homestory_807501001_37_dialog_content = "Pero está funcionando muy bien en este momento, por lo que el interior también debería estar bien.",
  str_homestory_807501001_38_dialog_content = "¿Por qué no esperas a que no funcione? Entonces te pediré que lo repares.",
  str_homestory_807501001_39_dialog_content = "Esa no es una mala idea. ¡Arreglar cosas es lo que hago!",
  str_homestory_807501001_40_dialog_content = "Bien, no lo desarmaré ahora.",
  str_homestory_807501001_41_dialog_content = "Permítame darle las gracias en nombre de la luz.",
  str_homestory_807501001_42_dialog_content = "Hablando de eso, acabo de ver un destello en el agua. ¡Podría ser algún tipo de cosa mecánica!",
  str_homestory_807501001_43_dialog_content = "¡Debería sacarlo y desarmarlo!",
  str_homestory_807501001_44_dialog_content = "Uh, tal vez debería ir a salvar lo que sea que esté en el agua...",
  str_homestory_820601001_0_dialog_content = "¿Qué está haciendo ella?",
  str_homestory_820601001_1_dialog_content = "¿Qué estás mirando?<sprite=emo_yihuo size=60 />",
  str_homestory_820601001_2_dialog_content = "¡La vista desde aquí arriba es increíble!",
  str_homestory_820601001_3_dialog_content = "Llevas un rato buscando. ¿Seguro que es solo por la vista?",
  str_homestory_820601001_4_dialog_content = "No te preocupes por eso. ¿Te interesa trabajar conmigo?",
  str_homestory_820601001_5_dialog_content = "¡Tu aguda percepción de Caelestite sin duda me ayudará en futuras competencias empresariales!",
  str_homestory_820601001_6_dialog_content = "¿Ayudarte? ¿Competencia?",
  str_homestory_820601001_7_dialog_content = "Dicen que \"Los negocios son guerra\" y un talento como tú es exactamente lo que necesito!",
  str_homestory_820601001_8_dialog_content = "Ofrezco bonificaciones de proyecto más opciones de acciones. Entonces, ¿te unes?",
  str_homestory_820601001_9_dialog_content = "Eso depende de los proyectos y cuánto stock—",
  str_homestory_820601001_10_dialog_content = "Espera, ¡aún no he dicho sí!",
  str_homestory_820601001_11_dialog_content = "¿De qué se trata la competencia empresarial? ¿Y qué tiene que ver eso con la vista desde aquí arriba?",
  str_homestory_820601001_12_dialog_content = "De hecho, acabo de pensar en una idea de negocio maravillosa... No se lo digas a nadie.",
  str_homestory_820601001_13_dialog_content = "Yo-yo no lo haré.",
  str_homestory_820601001_14_dialog_content = "¡Es una incursión en el mar azul!",
  str_homestory_820601001_15_option_content = "¿Mar azul?",
  str_homestory_820601001_16_dialog_content = "Océano, ¡como dice!",
  str_homestory_820601001_17_dialog_content = "Entonces, ¿quieres entrar en el mundo del envío?",
  str_homestory_820601001_18_option_content = "¿Industria naviera?",
  str_homestory_820601001_19_dialog_content = "¡No!",
  str_homestory_820601001_20_dialog_content = "¡El mar azul es una metáfora, una comparación!",
  str_homestory_820601001_21_dialog_content = "¿Para qué es una metáfora?",
  str_homestory_820601001_22_dialog_content = "En los negocios, ¡eso significa territorio inexplorado lleno de oportunidades!",
  str_homestory_820601001_23_dialog_content = "Pero, ¿qué tiene eso que ver contigo observando desde la torre de vigilancia?",
  str_homestory_820601001_24_dialog_content = "¡Me di cuenta de que las islas en el mar aún no han sido realmente desarrolladas!",
  str_homestory_820601001_25_dialog_content = "Ya sea literal o figurativamente, ¡es ambos mar azul!",
  str_homestory_820601001_26_dialog_content = "Si puedo descubrir islas en el océano y convertirlas en resorts...",
  str_homestory_820601001_27_dialog_content = "Vacaciones de verano, aventura, búsqueda del tesoro, deportes, natación, parque de juegos para niños...",
  str_homestory_820601001_28_dialog_content = "¡Podría seguir y seguir solo hablando de temas!",
  str_homestory_820601001_29_dialog_content = "Entonces, ¿quieres desarrollar islas? ¿Algo específico en este momento?",
  str_homestory_820601001_30_dialog_content = "Aún no hay prospectos adecuados. Por eso quiero conseguir un barco y buscar uno.",
  str_homestory_820601001_31_dialog_content = "¡Tan grande como es el océano, seguro que hay una isla deshabitada en algún lugar!",
  str_homestory_820601001_32_dialog_content = "¡Solo tenemos que vencer a todos y reclamar la isla, luego podemos construirla como queramos!",
  str_homestory_820601001_33_dialog_content = "¿Nosotros? ¿Yo también voy?",
  str_homestory_820601001_34_dialog_content = "¡Claro! Esa vista y oído sobrenaturales que tienes serán muy útiles.",
  str_homestory_820601001_35_dialog_content = "Suena bastante increíble en esa descripción.",
  str_homestory_820601001_36_dialog_content = "Entonces, ¿el primer paso es encontrar una isla adecuada?",
  str_homestory_820601001_37_dialog_content = "Así es. Me preguntaba si podríamos ver más lejos si movemos la torre de vigilancia a un barco.",
  str_homestory_820601001_38_dialog_content = "Y ya que estás aquí, negociemos el precio.",
  str_homestory_820601001_39_dialog_content = "No tengo intención de venderlo...<sprite=emo_tanqi size=60 />",
  str_homestory_820601001_40_dialog_content = "¿Lo llamaremos entonces tu parte del dinero inicial? Veo que estás bastante interesado en esta empresa.",
  str_homestory_820601001_41_dialog_content = "Eso no es lo que quise decir.",
  str_homestory_820601001_42_dialog_content = "¿Necesitas más tiempo para pensarlo? Sin problema. Aún no se ha redactado ningún contrato, así que todo es negociable antes de firmar en la línea punteada.",
  str_homestory_820601001_43_dialog_content = "Armaré los planes lo más rápido que pueda. ¡Solo intenta tomar una decisión rápido!",
  str_homestory_820601001_44_dialog_content = "... E-Está bien. Hasta entonces.",
  str_homestory_820701001_0_dialog_content = "¿Está él montándolo?",
  str_homestory_820701001_1_dialog_content = "Parece que lo estás pasando muy bien.",
  str_homestory_820701001_2_dialog_content = "¡Es muy moderno de tu parte conseguir el nuevo transporte hacia los jardines de nubes! ¡Muy genial!",
  str_homestory_820701001_3_dialog_content = "Pero escuché que es mejor con dos personas.",
  str_homestory_820701001_4_dialog_content = "Escuché que jugar en dúo puede servir como una especie de prueba, especialmente para las parejas...<sprite=emo_sikao size=60 />",
  str_homestory_820701001_5_dialog_content = "¿Una prueba?",
  str_homestory_820701001_6_dialog_content = "Dos personas que están juntas se suben y dan unas vueltas...",
  str_homestory_820701001_7_dialog_content = "Y si aún pueden preguntar cómo está el otro justo después de bajarse...",
  str_homestory_820701001_8_dialog_content = "Eso significa que la relación es sólida. De lo contrario, tsk...",
  str_homestory_820701001_9_dialog_content = "Entonces, ¿por qué estás montando esto solo? ¿Te estás preparando para una futura prueba?",
  str_homestory_820701001_10_dialog_content = "¡Incorrecto, amigo!",
  str_homestory_820701001_11_dialog_content = "Es un viaje mareado y nauseabundo, pero también muy emocionante.",
  str_homestory_820701001_12_dialog_content = "Suficientemente emocionante como para recordar aquellos días...",
  str_homestory_820701001_13_dialog_content = "No creo que quiera saber por lo que has pasado, pero supongo que es hora de contar historias, de todos modos.",
  str_homestory_820701001_14_dialog_content = "Solía ser un cazador, especializado en perseguir a ciertos malhechores.",
  str_homestory_820701001_15_dialog_content = "¿Quieres decir como un alguacil? ¿Pero no venías del desierto de Rediesel?",
  str_homestory_820701001_16_dialog_content = "No podría haber algo así. Solo bandas como Rediesel Wrench deambulan por el lugar.",
  str_homestory_820701001_17_dialog_content = "Lo hice por mi cuenta, por eso dije cazador y no alguacil.",
  str_homestory_820701001_18_dialog_content = "Entonces, ¿a qué tipo de malhechores perseguiste? ¿Tuvo algo que ver con tu pasado?",
  str_homestory_820701001_19_dialog_content = "Escuché que una vez saquearon un pueblo en el Valle de Denuo. ¿Están relacionados?",
  str_homestory_820701001_20_dialog_content = "¿Por dónde debería empezar...? Comencemos con una historia.",
  str_homestory_820701001_21_dialog_content = "Adelante.",
  str_homestory_820701001_22_dialog_content = "Había una vez, un gran pescador con habilidades de pesca inigualables.",
  str_homestory_820701001_23_dialog_content = "El punto es que, las redes que él hizo eran muy resistentes y ajustadas, que ningún pez podía escapar.",
  str_homestory_820701001_24_dialog_content = "Obtuvo grandes capturas cada vez que salía al mar, volviéndose así adinerado.",
  str_homestory_820701001_25_dialog_content = "Pero luego comenzó a atrapar menos y menos peces...",
  str_homestory_820701001_26_dialog_content = "¿Se acabó el pescado?",
  str_homestory_820701001_27_dialog_content = "¡Es correcto! Las redes estaban tan ajustadas que incluso los jóvenes no se quedaron afuera.",
  str_homestory_820701001_28_dialog_content = "Así que la población de peces disminuyó hasta desaparecer, hasta que un día...",
  str_homestory_820701001_29_dialog_content = "Veo venir un giro en la trama.<sprite=emo_yaosu tamaño=60 />",
  str_homestory_820701001_30_dialog_content = "¡El hijo del pescador vio un hermoso pez en un arrecife escondido!",
  str_homestory_820701001_31_dialog_content = "Su tamaño indicaba que era joven, pero realmente hermoso.",
  str_homestory_820701001_32_dialog_content = "El hijo no pudo evitar contarle a su padre, el pescador, cuando llegó a casa.",
  str_homestory_820701001_33_dialog_content = "Apuesto a que el pescador fue tras él inmediatamente.",
  str_homestory_820701001_34_dialog_content = "Esta vez, trajo la red más resistente y ajustada que tenía, jurando atrapar al pez.",
  str_homestory_820701001_35_dialog_content = "Porque sabía que era un pez de acuario precioso que podía conseguir muy buen dinero.",
  str_homestory_820701001_36_dialog_content = "Guiado por su hijo, llegó al arrecife aislado...",
  str_homestory_820701001_37_dialog_content = "Apuesto a que fue entonces cuando comenzaron los problemas.",
  str_homestory_820701001_38_dialog_content = "¡Correcto! Volvieron a ver el pez, ¡pero esta vez era aún más grande y bonito!",
  str_homestory_820701001_39_dialog_content = "¿Fue un progenitor del pez que el hijo vio?",
  str_homestory_820701001_40_dialog_content = "Probablemente.",
  str_homestory_820701001_41_dialog_content = "Cuando el gran y hermoso pez vio el barco, comenzó a sumergirse y esquivar en el arrecife.",
  str_homestory_820701001_42_dialog_content = "El pescador lo persiguió en una búsqueda caliente...",
  str_homestory_820701001_43_dialog_content = "Solo para estrellar el barco contra el arrecife.",
  str_homestory_820701001_44_dialog_content = "El barco se hundió. Tanto el pescador como el hijo murieron.",
  str_homestory_820701001_45_dialog_content = "Oh...",
  str_homestory_820701001_46_dialog_content = "Entonces, ¿quién es el malo del que hablaste, ya que el pescador y su hijo murieron en la historia?",
  str_homestory_820701001_47_dialog_content = "Por eso es solo una historia. No leas demasiado en ello.",
  str_homestory_820801001_0_dialog_content = "Ella ha estado obsesionada durante mucho tiempo...",
  str_homestory_820801001_1_dialog_content = "¿Qué estás haciendo?",
  str_homestory_820801001_2_dialog_content = "¿Qué? ¡Oh, eres tú! ¿¡Me notaste?!<sprite=emo_wuzui tamaño=60 />",
  str_homestory_820801001_3_dialog_content = "Eso es porque has estado mirando el monumento durante mucho tiempo. ¿No están cansados tus ojos?",
  str_homestory_820801001_4_dialog_content = "Sí lo siento ahora que lo mencionas...",
  str_homestory_820801001_5_dialog_content = "Espera un segundo, ¡el punto es que me notaste!",
  str_homestory_820801001_6_dialog_content = "¿Puede ser este el poder del monumento, haciendo que otros noten a aquellos que son insignificantes?",
  str_homestory_820801001_7_dialog_content = "No, es realmente porque has estado aquí parado durante demasiado tiempo.",
  str_homestory_820801001_8_dialog_content = "¡Mira las imágenes en eso! ¿Puedes descifrar lo que significan, PlayerName?",
  str_homestory_820801001_9_dialog_content = "Realmente no... Parece ser antiguo.",
  str_homestory_820801001_10_dialog_content = "Es tan viejo, no creo que nadie pueda decir qué se supone que debe transmitir.",
  str_homestory_820801001_11_dialog_content = "Es eso así... Suspiro...",
  str_homestory_820801001_12_dialog_content = "¿Por qué la cara larga ahora? Te ves bastante decaído...",
  str_homestory_820801001_13_dialog_content = "Eso es porque estoy reflexionando sobre el futuro de la Llave Rediesel.",
  str_homestory_820801001_14_option_content = "¿A qué te refieres con futuro?",
  str_homestory_820801001_15_dialog_content = "Aún no me he decidido, pero sé que tiene que ser un objetivo a largo plazo, no las tonterías que hacemos ahora.",
  str_homestory_820801001_16_dialog_content = "¡Pero ese es el estilo Rediesel! Mucha gente se unió por eso.",
  str_homestory_820801001_17_dialog_content = "Cierto, ¡pero siempre es bueno tener planes! Aún no se me ocurre ninguno, ¡pero debemos tener uno!",
  str_homestory_820801001_18_option_content = "¿No estás pensándolo demasiado?",
  str_homestory_820801001_19_dialog_content = "...",
  str_homestory_820801001_20_dialog_content = "Bopper¿",
  str_homestory_820801001_21_dialog_content = "No sé por qué, ¡pero siento que alguien tiene que hacerlo!",
  str_homestory_820801001_22_dialog_content = "Pasar el tiempo y merodear todos los días con objetivos aleatorios en mente... Eso es simplemente indisciplinado.",
  str_homestory_820801001_23_dialog_content = "Parece que lo has estado pensando seriamente...",
  str_homestory_820801001_24_dialog_content = "No creo que esté en la agenda de Sinsa.",
  str_homestory_820801001_25_dialog_content = "Entiendo que como jefe, solo tiene que ser el líder genial.",
  str_homestory_820801001_26_dialog_content = "Mientras que depende de mí elaborar planes como estratega.",
  str_homestory_820801001_27_dialog_content = "Pero, ¿qué tiene que ver eso con los monumentos?",
  str_homestory_820801001_28_dialog_content = "¡Atribúyelo a la espontaneidad!<span color=\"#ffb400\"></span>",
  str_homestory_820801001_29_dialog_content = "Escuché que hay monumentos como este en Lumopolis, Federación de Illumina e incluso en Northland.",
  str_homestory_820801001_30_dialog_content = "¡Construido para conmemorar personas famosas, méritos o hazañas!",
  str_homestory_820801001_31_dialog_content = "Pero nosotros, Rediesel Wrench, no tenemos nada parecido...",
  str_homestory_820801001_32_dialog_content = "Además, no tenemos nuestro propio territorio como ellos...",
  str_homestory_820801001_33_dialog_content = "Entonces, ¿qué va a pasar si el futuro sale mal o todos se enredan en una gran discusión y siguen caminos separados?",
  str_homestory_820801001_34_dialog_content = "Eso sí parece una preocupación legítima.",
  str_homestory_820801001_35_dialog_content = "¡Mira!",
  str_homestory_820801001_36_dialog_content = "Pero, ¿has pensado en cómo debería tomar forma el monumento?",
  str_homestory_820801001_37_dialog_content = "¿Forma?",
  str_homestory_820801001_38_dialog_content = "No necesariamente tiene que ser un monumento, simplemente algo representativo de la Llave Rediesel.",
  str_homestory_820801001_39_dialog_content = "¿Quieres decir como...",
  str_homestory_820801001_40_dialog_content = "¿Graffiti en coches?",
  str_homestory_820801001_41_dialog_content = "Si es tu estilo, siempre puedes reconocer que es Rediesel Wrench dondequiera que estés.",
  str_homestory_820801001_42_dialog_content = "O como si matáramos un gusano de arena, podemos dibujar uno con una X encima.",
  str_homestory_820801001_43_dialog_content = "Sí, ¡es una gran idea!",
  str_homestory_820801001_44_dialog_content = "¡Sin mencionar que Rediesel Wrench está lleno de increíbles artistas de graffiti!",
  str_homestory_820801001_45_dialog_content = "Tengo que ir a averiguar el plan para el Gran Concurso de Graffiti de Coches Rediesel Wrench!<sprite=emo_yaosu tamaño=60 />",
  str_homestory_820901001_0_dialog_content = "¿Qué está mirando?",
  str_homestory_820901001_1_dialog_content = "Comandante Wrath... ¿Qué estás haciendo aquí?",
  str_homestory_820901001_2_dialog_content = "No estoy haciendo nada. Acabo de ver algo realmente interesante.",
  str_homestory_820901001_3_dialog_content = "Así que así es como Illumina realiza la contratación hoy en día...",
  str_homestory_820901001_4_dialog_content = "¿No eres el Gran Mariscal? ¿Por qué parece que te estás dando cuenta de esto ahora...?",
  str_homestory_820901001_5_dialog_content = "Porque el Gran Mariscal no es responsable de supervisar la conscripción externa...",
  str_homestory_820901001_6_dialog_content = "Eso es lo que supongo... ¿Qué dices tú?",
  str_homestory_820901001_7_option_content = "Así es.",
  str_homestory_820901001_8_dialog_content = "No creo que el Gran Mariscal realmente tenga tiempo para cosas así.",
  str_homestory_820901001_9_option_content = "¿Por qué me preguntas?!",
  str_homestory_820901001_10_dialog_content = "¡Eres el Gran Mariscal! ¿Aún estás adivinando cuáles se supone que son tus responsabilidades?",
  str_homestory_820901001_11_dialog_content = "Lo primero que hice después de convertirme en Gran Mariscal fue liderar una expedición.",
  str_homestory_820901001_12_dialog_content = "Pero ahora... Es hora de ocuparnos de otros asuntos.",
  str_homestory_820901001_13_dialog_content = "Por ejemplo, ¿dónde encontraron ustedes esta cosa?",
  str_homestory_820901001_14_dialog_content = "Fue en Umbraton... Estábamos filmando una película en ese momento.",
  str_homestory_820901001_15_dialog_content = "¿Una película? Ya veo... <sprite=emo_sikao size=60 />",
  str_homestory_820901001_16_dialog_content = "¿Qué se te viene a la mente?",
  str_homestory_820901001_17_dialog_content = "Estos anuncios de reclutamiento... ¿Cómo esperan conseguir que los mejores y más valientes de la nación se alisten en el ejército con ese patético tablero?",
  str_homestory_820901001_18_dialog_content = "Mientras esté al mando, quiero hacer que Illumina sea más fuerte que nunca antes.",
  str_homestory_820901001_19_dialog_content = "¿Entonces?",
  str_homestory_820901001_20_dialog_content = "¿Qué tal si hacemos una película sobre los soldados de Illumina? Una pieza de propaganda para ayudar a reclutar a la próxima generación de héroes de esta nación...",
  str_homestory_820901001_21_option_content = "¿Estás hablando en serio ahora mismo?",
  str_homestory_820901001_22_dialog_content = "Incluso cuando lo dices así... Rodar una película aún no suena como algo de Illumina.",
  str_homestory_820901001_23_dialog_content = "Es cierto que el enfoque de Illumina en la educación se inclina más hacia la tecnología y el arte de la guerra que hacia las artes en sí mismas...",
  str_homestory_820901001_24_dialog_content = "Seré el primero en admitir eso.",
  str_homestory_820901001_25_dialog_content = "Por eso quiero que dispares a esta cosa.",
  str_homestory_820901001_26_option_content = "¡Hagámoslo!",
  str_homestory_820901001_27_dialog_content = "Por mucho que esos lemas sean emocionantes e inspiradores, nunca podrían compararse con una película.",
  str_homestory_820901001_28_dialog_content = "Si pudiéramos mostrar al mundo la valentía de un verdadero héroe de Illumina en la gran pantalla, enviaríamos ondas de choque a través de todo el continente.",
  str_homestory_820901001_29_dialog_content = "¡No puedo esperar para hacer que esto suceda!",
  str_homestory_820901001_30_dialog_content = "Bueno, ¡eso lo resuelve! Ahora este asunto de la película está completamente en tus manos. Iré a recaudar los fondos y prepararé sus salarios.",
  str_homestory_820901001_31_dialog_content = "Pero... ¡No sé lo más mínimo sobre cómo hacer una película!",
  str_homestory_820901001_32_dialog_content = "Pensé que eras del tipo creativo, ¿no? Recuerdo que incluso escribiste poesía en aquel entonces.",
  str_homestory_820901001_33_dialog_content = "Escribir poesía y hacer una película son dos cosas muy diferentes. Además, mi poesía ni siquiera es tan buena...",
  str_homestory_820901001_34_dialog_content = "Según mi entendimiento, las artes están bastante interconectadas, ¿no es así?",
  str_homestory_820901001_35_dialog_content = "¡Ese no es el problema aquí!",
  str_homestory_820901001_36_dialog_content = "Además, ¡ni siquiera hay un solo cine en todo Illumina!",
  str_homestory_820901001_37_dialog_content = "Bueno, tenemos salas de proyección, pero solo están abiertas en días de descanso.",
  str_homestory_820901001_38_dialog_content = "Entonces la gente ni siquiera tendrá la oportunidad de ver películas...",
  str_homestory_820901001_39_dialog_content = "Illumina recluta a todos sus ciudadanos de todos modos. Una campaña de reclutamiento como esta es obviamente para posibles reclutas fuera de la federación.",
  str_homestory_820901001_40_dialog_content = "Pero ahora que lo mencionas, dejar que los Illuminans vean la federación a través del lente del director podría aumentar su moral, tal vez.",
  str_homestory_820901001_41_dialog_content = "Y si ese es el caso... será una oportunidad única en verdad. Entonces, voy a tener que protagonizar esto.",
  str_homestory_820901001_42_dialog_content = "¿Qué tal si bajamos a Reinhardt aquí y vemos quién tiene más presencia en pantalla, eh?",
  str_homestory_820901001_43_dialog_content = "Oye, si ponemos a unos cuantos comandantes en pantalla, incluso podría encender una pequeña competencia entre las legiones.",
  str_homestory_820901001_44_dialog_content = "Realmente te estás dejando llevar aquí...",
  str_homestory_820901001_45_dialog_content = "Oh sí, y también puedes actuar y dirigir esto al mismo tiempo.",
  str_homestory_820901001_46_dialog_content = "Como el único Caelestite y director, sin duda deberías tener un papel protagonista.",
  str_homestory_820901001_47_dialog_content = "No me estás escuchando en absoluto, ¿verdad? Tal vez debería rendirme... <sprite=emo_yundao size=60 />",
  str_homestory_820901001_48_dialog_content = "Oh, cierto. Acabo de pensar en el nombre perfecto para esta película.",
  str_homestory_820901001_49_dialog_content = "\"Salvar a Caelestite PlayerName\"... ¿Qué dices?",
  str_homestory_821001001_0_dialog_content = "Joselyne está rezando frente a la bandera...",
  str_homestory_821001001_1_dialog_content = "Joselyne¿?",
  str_homestory_821001001_2_dialog_content = "No hace falta quedarse ahí esperando todo ese tiempo. Podrías haberme llamado.",
  str_homestory_821001001_3_dialog_content = "Temía que pudiera molestarte.",
  str_homestory_821001001_4_dialog_content = "El Dios de la Luz no cuestiona nuestra fe simplemente porque nuestras oraciones sean interrumpidas.",
  str_homestory_821001001_5_dialog_content = "Y nunca me enojaría por un asunto tan insignificante. ¿Necesitas mi ayuda con algo?",
  str_homestory_821001001_6_dialog_content = "No, solo te vi parado frente a esta bandera y pensé en acercarme.",
  str_homestory_821001001_7_dialog_content = "¿Estabas rezando a esta bandera justo ahora?",
  str_homestory_821001001_8_dialog_content = "¿Orar? Bueno, es cierto que si uno reza a través de un medio específico, sus oraciones serán escuchadas más claramente.",
  str_homestory_821001001_9_option_content = "¿Un medio como esta bandera?",
  str_homestory_821001001_10_dialog_content = "Umm. Creer en el Dios de la Luz siempre ha sido parte integral de la vida convencional en Lumopolis...",
  str_homestory_821001001_11_dialog_content = "Entonces, supongo que tiene sentido que utilices la bandera de Lumopolis como medio para rezar.",
  str_homestory_821001001_12_option_content = "¿Quieres decir como una reliquia sagrada?",
  str_homestory_821001001_13_dialog_content = "Por lo que entiendo, las personas que buscan la comunión con su dios a menudo intentan hacerlo mediante el uso de reliquias sagradas, ¿verdad?",
  str_homestory_821001001_14_dialog_content = "De esta manera, pueden comunicarse con lo divino cara a cara, ¿no? ¡Suena súper efectivo!",
  str_homestory_821001001_15_dialog_content = "En realidad, cualquier objeto puede ser utilizado como medio para lograr el mismo efecto.",
  str_homestory_821001001_16_dialog_content = "La gracia de la Luz <sprite=emo_taiyang size=60 /> se extiende por toda la tierra. Todo lo que existe bajo el sol está conectado a la luz de Dios.",
  str_homestory_821001001_17_dialog_content = "A menudo rezo a las flores de tomate cuando cuido el huerto.",
  str_homestory_821001001_18_dialog_content = "¿De verdad?",
  str_homestory_821001001_19_dialog_content = "Sin embargo, es importante seleccionar temas adecuados al realizar oraciones específicas.",
  str_homestory_821001001_20_dialog_content = "Entonces, ¿por qué rezabas cuando mirabas la bandera de Lumopolis?",
  str_homestory_821001001_21_dialog_content = "...",
  str_homestory_821001001_22_dialog_content = "Perdón, solo tengo curiosidad.",
  str_homestory_821001001_23_dialog_content = "Si dije algo fuera de lugar, por favor ignórame, Joselyne.",
  str_homestory_821001001_24_dialog_content = "No, no... Después de todo, es mi deber difundir la gracia del Dios de la Luz a todos.",
  str_homestory_821001001_25_dialog_content = "Cuando se trata de fe, compartiré todo lo que sé.",
  str_homestory_821001001_26_dialog_content = "Pero justo ahora, yo...",
  str_homestory_821001001_27_dialog_content = "¿Tú qué...?",
  str_homestory_821001001_28_dialog_content = "Solo quería echar un vistazo más de cerca al bordado de la bandera.",
  str_homestory_821001001_29_dialog_content = "Lumopolis realmente brilla en el campo de la creación de objetos relacionados con la religión.",
  str_homestory_821001001_30_dialog_content = "Especialmente banderas como esta. Son faros que guían a todos los que las contemplan. No hace falta decir que deben ser lo suficientemente resistentes.",
  str_homestory_821001001_31_dialog_content = "Si encuentro una manera de mejorar mis habilidades de costura, puedo hacer más para ayudar a las personas necesitadas allí.",
  str_homestory_821001001_32_dialog_content = "Jaja, y ahora no puedo quitarme de la cabeza esta imagen tuya levantando heroicamente una bandera en el aire...",
  str_homestory_821001001_33_dialog_content = "No me encontrarás levantando banderas. No es tan fácil como parece, ¿sabes?",
  str_homestory_821001001_34_dialog_content = "Aunque los lugareños me han etiquetado como una \"Santa\", estoy lejos de ser la líder espiritual que necesitan.",
  str_homestory_821001001_35_dialog_content = "Por ahora, necesito comenzar cosiendo la bandera de los Caballeros de Ironthorn.",
  str_homestory_821001001_36_dialog_content = "Cierto. Hacer una bandera decente que lidere la carga en la batalla es tan importante como ondearla. También ayudaré, si quieres.",
  str_homestory_821001001_37_dialog_content = "¿También sabes coser?",
  str_homestory_821001001_38_dialog_content = "Bueno, aprendí algunos trucos pequeños de Soroz cuando era niño...",
  str_homestory_821001001_39_dialog_content = "Te enseñaré todo lo que he aprendido. Esto también debería reforzar y mejorar mis habilidades.",
  str_homestory_821001001_40_dialog_content = "Lo primero es lo primero: trae toda tu ropa hacia mí.",
  str_homestory_821001001_41_dialog_content = "¿A-Todos ellos?",
  str_homestory_821001001_42_dialog_content = "La única forma de dominar los fundamentos es mediante la práctica extensiva.",
  str_homestory_821001001_43_dialog_content = "Hablar y no actuar solo nos llevará más hacia la oscuridad, de la cual incluso el Dios de la Luz no podrá liberarnos.",
  str_homestory_821001001_44_dialog_content = "Creo que no eres ese tipo de Celestita, ¿verdad?",
  str_homestory_821001001_45_dialog_content = "¡Por supuesto que no! ¡Iré a buscar esas prendas ahora mismo!",
  str_homestory_821201001_0_dialog_content = "Antony¿?",
  str_homestory_821201001_1_dialog_content = "Antony, llevas parado junto al Corredor Dentado durante media hora.",
  str_homestory_821201001_2_dialog_content = "¿Estás interesado en esta cosa?",
  str_homestory_821201001_3_dialog_content = "Oh... Hola, PlayerName.",
  str_homestory_821201001_4_dialog_content = "La verdad sea dicha, realmente estoy bastante interesado en ello.",
  str_homestory_821201001_5_dialog_content = "La primera vez que lo vi, estaba seguro de una cosa—",
  str_homestory_821201001_6_dialog_content = "¡No se puede negar su valor para la investigación!",
  str_homestory_821201001_7_dialog_content = "May Pregunto, ¿de qué tipo de criatura son realmente estos huesos?",
  str_homestory_821201001_8_dialog_content = "Ahora esa es una pregunta que incluso a mí me tiene perplejo...",
  str_homestory_821201001_9_dialog_content = "Actualmente, el jurado no se ha pronunciado sobre ese punto en particular. Hay todo tipo de opiniones con respecto a estos huesos.",
  str_homestory_821201001_10_dialog_content = "En tu opinión personal, ¿qué tipo de huesos dirías que son?",
  str_homestory_821201001_11_dialog_content = "Confío en tu juicio.",
  str_homestory_821201001_12_dialog_content = "Déjame pensar<sprite=emo_sikao size=60 />... Tal vez ellos estén...",
  str_homestory_821201001_13_option_content = "Los huesos de cierto animal.",
  str_homestory_821201001_14_dialog_content = "¿Huesos de animales?",
  str_homestory_821201001_15_dialog_content = "He viajado a muchos lugares y nunca había visto huesos como estos.",
  str_homestory_821201001_16_dialog_content = "En ese caso, ¡estos podrían ser los restos de alguna criatura extinta!",
  str_homestory_821201001_17_dialog_content = "¿En realidad...?",
  str_homestory_821201001_18_option_content = "Es la caja torácica de un Coloso.",
  str_homestory_821201001_19_dialog_content = "¡¿Qué?!",
  str_homestory_821201001_20_dialog_content = "¿Hablas en serio?",
  str_homestory_821201001_21_dialog_content = "¿P-Podrían ser realmente los huesos que se usaron para hacer un Coloso?!",
  str_homestory_821201001_22_dialog_content = "Es solo una suposición, eso es todo.",
  str_homestory_821201001_23_dialog_content = "No, no, ¡eres un Celestita! ¡No puedes estar equivocado!",
  str_homestory_821201001_24_dialog_content = "De todos modos, ¡necesito estudiar este Corredor Dentado detenidamente!",
  str_homestory_821201001_25_dialog_content = "¿Puedo mover una parte de esto a mi habitación para ayudarme en mi investigación?!",
  str_homestory_821201001_26_dialog_content = "¡Oye, no vas a mover nada a tu habitación, ¿de acuerdo?!",
  str_homestory_821201001_27_dialog_content = "Después de todo, esto es propiedad pública...",
  str_homestory_821201001_28_dialog_content = "Dicho eso, tengo un poco de curiosidad por saber cuál es la verdad en realidad.",
  str_homestory_821201001_29_dialog_content = "De acuerdo, puedes realizar tu investigación aquí y, si necesitas ayuda, estoy seguro de que podrás encontrar a alguien dispuesto a ayudarte.",
  str_homestory_821201001_30_dialog_content = "¡No te preocupes!",
  str_homestory_821201001_31_dialog_content = "¡Sé que llegaré al fondo de esto!<sprite=emo_dianzan size=60 />",
  str_homestory_821101001_0_dialog_content = "Zarya, ¿qué estás haciendo?",
  str_homestory_821101001_1_dialog_content = "Oh, PlayerName, ¿tienes alguna idea de qué es esto?",
  str_homestory_821101001_2_dialog_content = "Tiene \"Auto del Detective\" escrito en él.",
  str_homestory_821101001_3_dialog_content = "¿Qué es un... coche?",
  str_homestory_821101001_4_dialog_content = "Bueno, básicamente, es un modo de transporte conveniente.",
  str_homestory_821101001_5_dialog_content = "¿Este es un medio de transporte?",
  str_homestory_821101001_6_dialog_content = "¿La gente ya no usa carruajes...?",
  str_homestory_821101001_7_dialog_content = "Aún utilizan carruajes en algunos lugares, pero verás que las personas ricas en la mayoría de las áreas, generalmente conducen autos.",
  str_homestory_821101001_8_dialog_content = "Oh...",
  str_homestory_821101001_9_dialog_content = "¿Te interesan los carruajes, Zarya?",
  str_homestory_821101001_10_dialog_content = "Me interesa ver cómo es algo que nunca he visto antes.",
  str_homestory_821101001_11_dialog_content = "¿Puedes llevarme a ver el verdadero negocio más tarde?",
  str_homestory_821101001_12_option_content = "Seguro.",
  str_homestory_821101001_13_dialog_content = "Pero tienes que prometer que te sentarás en el asiento trasero y te portarás bien.",
  str_homestory_821101001_14_dialog_content = "Bajo ninguna circunstancia tienes permitido conducir.",
  str_homestory_821101001_15_option_content = "No me parece.",
  str_homestory_821101001_16_dialog_content = "¿Eh? ¿Por qué no...?<sprite=emo_yihuo size=60 />",
  str_homestory_821101001_17_dialog_content = "Siento que siempre estás a momentos de hacer algo increíblemente peligroso.",
  str_homestory_821101001_18_dialog_content = "Como tomar el control de un carruaje, por ejemplo.",
  str_homestory_821101001_19_dialog_content = "Impresionante, PlayerName.",
  str_homestory_821101001_20_dialog_content = "¿Cómo supiste que quería montarlo?",
  str_homestory_821101001_21_dialog_content = "¿Paseo?",
  str_homestory_821101001_22_dialog_content = "¿No dijiste que era un medio de transporte... como cualquier otro carruaje?",
  str_homestory_821101001_23_dialog_content = "Entonces debería ser el mismo principio, ¿verdad?",
  str_homestory_821101001_24_dialog_content = "Todo lo que necesitas hacer es darle un pequeño látigo y te llevará a donde quieras ir.",
  str_homestory_821101001_25_dialog_content = "¿O tienes que darle una orden?",
  str_homestory_821101001_26_dialog_content = "No soy el mejor controlando mis Luminatics, ¡pero sé cómo manejar un caballo!",
  str_homestory_821101001_27_dialog_content = "...",
  str_homestory_821101001_28_dialog_content = "¿Eh? ¿El gato te comió la lengua?",
  str_homestory_821101001_29_dialog_content = "Tengo la sensación de que realmente necesitas repasar tus conocimientos sobre el mundo moderno...",
  str_homestory_821101001_30_dialog_content = "¿Ah?",
  str_homestory_821301001_0_dialog_content = "No. 33¿?",
  str_homestory_821301001_1_dialog_content = "¿Planeas ir de picnic?",
  str_homestory_821301001_2_dialog_content = "Sí, como puedes ver.",
  str_homestory_821301001_3_dialog_content = "Por esta razón estoy haciendo los preparativos necesarios.",
  str_homestory_821301001_4_dialog_content = "¿No me digas que planeas ir solo?",
  str_homestory_821301001_5_dialog_content = "Parece que me malentendiste.",
  str_homestory_821301001_6_dialog_content = "Naturalmente, invitaré a mis otros amigos aurorianos a unirse a mí.",
  str_homestory_821301001_7_dialog_content = "Eso te incluye a ti, por supuesto.",
  str_homestory_821301001_8_dialog_content = "Sería mi honor.",
  str_homestory_821301001_9_dialog_content = "...",
  str_homestory_821301001_10_dialog_content = "Hablando de eso, ¿por qué no invitas a Vice y a los demás?",
  str_homestory_821301001_11_dialog_content = "Estoy realizando un importante trabajo de análisis.",
  str_homestory_821301001_12_dialog_content = "Al preguntar a quienes me rodean, me he enterado de los estándares de comida en sus picnics anteriores.",
  str_homestory_821301001_13_dialog_content = "Basándome en la comida de picnic que he recibido hasta ahora de mis amigos aurorianos, he llegado a una sorprendente conclusión:",
  str_homestory_821301001_14_dialog_content = "Un exceso de calorías puede tener un efecto catastrófico en la salud de uno.",
  str_homestory_821301001_15_dialog_content = "¿Ah?",
  str_homestory_821301001_16_dialog_content = "¿Qué opinas, nombre del jugador?",
  str_homestory_821301001_17_option_content = "Absolutamente correcto.",
  str_homestory_821301001_18_dialog_content = "Si lo ves desde una perspectiva puramente nutricional, claro, este tipo de comida tiene demasiadas calorías.",
  str_homestory_821301001_19_dialog_content = "No es frecuente que estés tan de acuerdo con mi punto de vista.",
  str_homestory_821301001_20_dialog_content = "Pero...",
  str_homestory_821301001_21_option_content = "Eso no es cierto.",
  str_homestory_821301001_22_dialog_content = "En cuanto a tu afirmación \"eso no es cierto\", ¿qué enfoque analítico utilizaste para llegar a esa conclusión?",
  str_homestory_821301001_23_dialog_content = "Considero que el juicio que compartí contigo es completamente sólido.",
  str_homestory_821301001_24_dialog_content = "Cuando vamos de picnic, nuestro objetivo es, naturalmente, simplemente desahogarnos.",
  str_homestory_821301001_25_dialog_content = "No lograrás ese objetivo si pasas tiempo preocupándote por las cosas pequeñas.",
  str_homestory_821301001_26_dialog_content = "¿Preocupándote por cosas pequeñas? ¿Necesitas desahogarte?",
  str_homestory_821301001_27_dialog_content = "Sé que tus intenciones son buenas, No. 33, pero a veces necesitas soltarte un poco.",
  str_homestory_821301001_28_dialog_content = "Puedes ser estricto cuando sea necesario, e intenta relajarte cuando sea el momento de relajarse. De esa manera, a la gente le agradarás más.",
  str_homestory_821301001_29_dialog_content = "Información recibida. Analizando información...",
  str_homestory_821301001_30_dialog_content = "Entiendo.",
  str_homestory_821301001_31_dialog_content = "Entonces reajustaré mis recetas de picnic.",
  str_homestory_821301001_32_dialog_content = "Por favor, espera mi invitación.",
  str_homestory_821401001_0_dialog_content = "Rebecca?",
  str_homestory_821401001_1_dialog_content = "Navegador...",
  str_homestory_821401001_2_dialog_content = "¿Quieres sentarte en la silla colgante?",
  str_homestory_821401001_3_dialog_content = "No... solo siento un poco de nostalgia...",
  str_homestory_821401001_4_dialog_content = "En el pasado... solía haber una silla colgante similar en el patio de mi casa.",
  str_homestory_821401001_5_dialog_content = "Antes, mi hermana mayor, Eleanor, y yo solíamos jugar juntas en la silla colgante.",
  str_homestory_821401001_6_dialog_content = "Pero solo dos personas podían jugar en él porque la silla colgante era demasiado pequeña y tenía espacio limitado...",
  str_homestory_821401001_7_dialog_content = "Lo que significaba que uno de nosotros siempre se perdería algo...",
  str_homestory_821401001_8_dialog_content = "¿En serio? Entonces, ¿cómo decidiste quién se quedaría fuera?",
  str_homestory_821401001_9_dialog_content = "Jugamos piedra, papel o tijera.",
  str_homestory_821401001_10_dialog_content = "Es extraño ahora que lo pienso. Nunca perdí en ese entonces. Ni siquiera una vez.",
  str_homestory_821401001_11_dialog_content = "¿Quizás ya habían discutido esto entre ellos?",
  str_homestory_821401001_12_dialog_content = "Es posible. Para ser honesto, la relación entre mi hermana mayor y Eleanor... nunca fue muy buena...",
  str_homestory_821401001_13_dialog_content = "Recuerdo que hubo un momento en que me bajé de la silla colgante para mecerla...",
  str_homestory_821401001_14_dialog_content = "Al final, mi hermana mayor y Eleanor casi tuvieron una pelea en la silla colgante.",
  str_homestory_821401001_15_dialog_content = "Casi lo rompen también esa vez...",
  str_homestory_821401001_16_dialog_content = "Parece que realmente extrañas esos momentos <sprite=emo_sikao size=60 />.",
  str_homestory_821401001_17_dialog_content = "¿Te gustaría sentarte en él?",
  str_homestory_821401001_18_dialog_content = "¿Ah? ¿Yo? Bueno...",
  str_homestory_821401001_19_dialog_content = "Creo que paso.",
  str_homestory_821401001_20_option_content = "¿Por qué?",
  str_homestory_821401001_21_option_content = "Inténtalo.",
  str_homestory_821401001_22_dialog_content = "En realidad... mi veneno ha estado un poco inquieto últimamente...",
  str_homestory_821401001_23_dialog_content = "Si accidentalmente me quedo dormido mientras estoy sentado en él, me temo que el veneno se derramará y destruirá la silla colgante.",
  str_homestory_821401001_24_dialog_content = "Entonces, simplemente le echaré un vistazo.",
  str_homestory_821401001_25_dialog_content = "Si me paro cerca y cierro los ojos, siento como si todo hubiera vuelto a cómo era en el pasado...",
  str_homestory_821401001_26_dialog_content = "No te preocupes por eso. Estoy aquí.",
  str_homestory_821401001_27_dialog_content = "Te despertaré de inmediato si te duermes.",
  str_homestory_821401001_28_dialog_content = "¿Te causaría demasiada molestia...?",
  str_homestory_821401001_29_dialog_content = "Estará bien.",
  str_homestory_821401001_30_dialog_content = "Um... ¿Puedes esperar un poco más por mí?",
  str_homestory_821401001_31_dialog_content = "Tengo algunos recados que hacer en la clínica. Vendré de inmediato después de terminar.",
  str_homestory_821401001_32_dialog_content = "Gracias, Navegador.",
  str_homestory_821501001_0_dialog_content = "Isa¿?",
  str_homestory_821501001_1_dialog_content = "Oh, es tú.",
  str_homestory_821501001_2_dialog_content = "¿Hay algo malo con este coche? No dejas de mirarlo.",
  str_homestory_821501001_3_dialog_content = "¡Ajá! Buena pregunta.",
  str_homestory_821501001_4_dialog_content = "¿No crees que este coche... es súper genial?",
  str_homestory_821501001_5_option_content = "Realmente no.",
  str_homestory_821501001_6_dialog_content = "Creo que puedes decir que es hermoso.",
  str_homestory_821501001_7_option_content = "Sin duda.",
  str_homestory_821501001_8_dialog_content = "En cierto sentido, se puede considerar que es genial.",
  str_homestory_821501001_9_dialog_content = "De todos modos, ¡este coche es exactamente mi estilo!",
  str_homestory_821501001_10_dialog_content = "Si conduzco este coche para recoger a Rebecca...",
  str_homestory_821501001_11_dialog_content = "¡Definitivamente estará muy emocionada!",
  str_homestory_821501001_12_dialog_content = "¿Estás pensando en recoger a Rebecca en este coche?",
  str_homestory_821501001_13_dialog_content = "Sí, Rebecca no se encuentra bien.",
  str_homestory_821501001_14_dialog_content = "Pero aún necesita caminar al trabajo todos los días. ¿No crees que está siendo demasiado dura consigo misma?",
  str_homestory_821501001_15_dialog_content = "Suena difícil.",
  str_homestory_821501001_16_dialog_content = "¿Verdad? Esto es lo que se me ocurrió después de una cuidadosa consideración.",
  str_homestory_821501001_17_dialog_content = "Rebecca siempre dice que no sé lo que quiere. Jeje, definitivamente necesita esta herramienta de transporte esta vez.",
  str_homestory_821501001_18_dialog_content = "Pero... este coche es demasiado llamativo. A Rebecca no le gustará.",
  str_homestory_821501001_19_dialog_content = "No te preocupes. La entiendo bien. Estoy seguro de que sé lo que le gusta.",
  str_homestory_821501001_20_dialog_content = "Rebecca ama las flores. Mira las flores por todo el coche. No hay manera de que las odie.",
  str_homestory_821501001_21_dialog_content = "... Eh, ¿entonces lo intentamos?",
  str_homestory_821501001_22_dialog_content = "Está bien, se lo diré a Rebecca ahora.",
  str_homestory_821501001_23_dialog_content = "Ella estaría encantada.",
  str_homestory_821501001_24_dialog_content = "La mejor de las suertes.",
  str_homestory_821601001_0_dialog_content = "¿Qué pasa con esta máquina, Xuan Ji?",
  str_homestory_821601001_1_dialog_content = "Fue utilizado por los Caelestites en el pasado. ¿Te interesa?",
  str_homestory_821601001_2_dialog_content = "Es un telar mecánico, ¿verdad?",
  str_homestory_821601001_3_dialog_content = "Sí. Hay registros sobre ello en Soroz.",
  str_homestory_821601001_4_dialog_content = "Eraveil utilizó una vez estas máquinas para producir textiles, logrando un estilo de vida autosuficiente.",
  str_homestory_821601001_5_dialog_content = "Probablemente requiere mantenimiento regular, pero no se ha utilizado durante mucho tiempo...",
  str_homestory_821601001_6_dialog_content = "¿Quieres usarlo, Xuan Ji?",
  str_homestory_821601001_7_dialog_content = "Realmente no.",
  str_homestory_821601001_8_dialog_content = "Simplemente me parece nostálgico.",
  str_homestory_821601001_9_dialog_content = "¿Nostálgico?",
  str_homestory_821601001_10_dialog_content = "Me recuerda a las máquinas para fines educativos que usaba cuando era pequeño.",
  str_homestory_821601001_11_dialog_content = "Los maestros comenzaban a enseñarnos, a nosotros los jóvenes alumnos, con modelos prototipo.",
  str_homestory_821601001_12_dialog_content = "Telares como este son comunes. Incluso puedes llamarlo mi segundo maestro.",
  str_homestory_821601001_13_dialog_content = "No es de extrañar que lo encuentres interesante.",
  str_homestory_821601001_14_dialog_content = "Además, los prototipos suelen ser muy frágiles.",
  str_homestory_821601001_15_dialog_content = "Ese es el caso con el que me dieron, con ciertas estructuras idénticas también...",
  str_homestory_821601001_16_dialog_content = "También lo hacen para que apreciemos la artesanía.",
  str_homestory_821601001_17_dialog_content = "Me encantaría apreciarlo también, ¡pero se averiaba más veces de las que no!",
  str_homestory_821601001_18_option_content = "¿Porque intentaste ajustarlo?",
  str_homestory_821601001_19_dialog_content = "Bingo.",
  str_homestory_821601001_20_option_content = "Es tan frágil",
  str_homestory_821601001_21_dialog_content = "No, es porque lo ajusté mucho...",
  str_homestory_821601001_22_dialog_content = "Entonces no duró hasta mi graduación.",
  str_homestory_821601001_23_dialog_content = "Cuando finalmente fui lo suficientemente competente, ya estaba irreparablemente dañado.",
  str_homestory_821601001_24_dialog_content = "Comprendo.",
  str_homestory_821601001_25_dialog_content = "Entonces, ¿quieres que arregle este telar?",
  str_homestory_821601001_26_dialog_content = "Para esta versión actual de mí, debería ser muy fácil.",
  str_homestory_821601001_27_dialog_content = "Incluso puedo mejorar el diseño para que funcione y se mantenga de la mejor manera posible.",
  str_homestory_821601001_28_dialog_content = "Uh<sprite=emo_sikao size=60 />, eso no será necesario, aunque.",
  str_homestory_821601001_29_dialog_content = "Aunque se arreglara, sería difícil encontrar los materiales para que lo procese.",
  str_homestory_821601001_30_dialog_content = "Por no mencionar que ahora podemos conseguir fácilmente telas bonitas y económicas en las tiendas.",
  str_homestory_821601001_31_dialog_content = "Cierto, igual en Longzhou.",
  str_homestory_821601001_32_dialog_content = "Para la gente común, los gremios son más importantes que los artesanos ahora.",
  str_homestory_821601001_33_dialog_content = "Eso es progreso, ¿verdad?",
  str_homestory_821601001_34_dialog_content = "Umm, no puedo refutar eso. Esta máquina ya cumplió su propósito.",
  str_homestory_821601001_35_dialog_content = "Entonces, mejor dejarlo descansar en paz.",
  str_homestory_818702001_0_dialog_content = "¿Tianxian? ¿Maestro Li?",
  str_homestory_818702001_1_dialog_content = "¿Cómo es que te quedaste dormido de pie?",
  str_homestory_818702001_2_dialog_content = "Despierta y vuelve a tu habitación.",
  str_homestory_818702001_3_dialog_content = "¡Oye!",
  str_homestory_818702001_4_dialog_content = "Acabo de estar en los cielos charlando con los ángeles hace un momento.",
  str_homestory_818702001_5_dialog_content = "¿Qué tan rápido caí de vuelta a la tierra...",
  str_homestory_818702001_6_dialog_content = "Supongo que todavía tengo un largo camino por recorrer.",
  str_homestory_818702001_7_dialog_content = "Me rindo. ¿No te diste cuenta?",
  str_homestory_818702001_8_dialog_content = "La cosa junto a la que te quedaste dormido y casi te apoyaste en...",
  str_homestory_818702001_9_dialog_content = "Es un reloj.",
  str_homestory_818702001_10_dialog_content = "¡Increíble! ¿Cómo puedes dormir tan profundamente al lado de un reloj tan grande...",
  str_homestory_818702001_11_dialog_content = "Al contrario, mi hermano.",
  str_homestory_818702001_12_dialog_content = "Hasta donde sé, muchas personas en Astra tenían un despertador junto a sus almohadas.",
  str_homestory_818702001_13_dialog_content = "Sin embargo, prefería el cielo como mi manta, la tierra como mi cama y un reloj de sol como mi despertador.",
  str_homestory_818702001_14_dialog_content = "Entonces, en este caso, me estoy adaptando a lo que hacen los lugareños.",
  str_homestory_818702001_15_dialog_content = "Pero ellos lo hicieron para levantarse a tiempo, y tú solo intentabas tomar una siesta <sprite=emo_kun size=60 />!",
  str_homestory_818702001_16_dialog_content = "¿No sientes que el tiempo se escapa en absoluto?",
  str_homestory_818702001_17_dialog_content = "Es porque el tiempo vuela y la vida es corta que uno debe aprovechar la oportunidad cuando se presenta.",
  str_homestory_818702001_18_dialog_content = "Deberías dormir cuando te sientas somnoliento, no esperar hasta que bosteces.",
  str_homestory_818702001_19_dialog_content = "¿Por qué no te recuestas y tomas una siesta? Entonces lo entenderás.",
  str_homestory_818702001_20_option_content = "No.",
  str_homestory_818702001_21_dialog_content = "Todavía joven e inexperto, ya veo.",
  str_homestory_818702001_22_dialog_content = "He visto mi parte del mundo y nunca renunciaré a ninguna oportunidad de echar una cabezadita.",
  str_homestory_818702001_23_option_content = "Lo intentaré.",
  str_homestory_818702001_24_dialog_content = "¡Finalmente estás iluminado!",
  str_homestory_818702001_25_dialog_content = "Pero incluso si me estrello aquí, tengo que prepararme.",
  str_homestory_818702001_26_dialog_content = "Tengo que traer mi saco de dormir, manta de picnic y todo lo demás.",
  str_homestory_818702001_27_dialog_content = "Seguro que sabes disfrutar de la vida. Apenas tengo algo para sentirme cómodo.",
  str_homestory_818702001_28_dialog_content = "Suspiro, creo que el reloj de sol es probablemente el más afortunado de todos.",
  str_homestory_818702001_29_dialog_content = "Cumple el mismo propósito tanto en Longzhou como en Astra.",
  str_homestory_818702001_30_dialog_content = "Tiene tiempo libre siempre que el sol no esté afuera.",
  str_homestory_818702001_31_dialog_content = "¿Has llegado al punto de envidiar una roca?",
  str_homestory_818702001_32_dialog_content = "No subestimes las rocas. ¡Incluso hay héroes legendarios nacidos de las rocas!",
  str_homestory_818702001_33_dialog_content = "Lamentablemente, solo podía convertirme en una roca en mis sueños.",
  str_homestory_818702001_34_dialog_content = "Hablando de eso, siento que se acerca otra siesta.",
  str_homestory_818702001_35_dialog_content = "Todavía no veo ese sentido de urgencia, parece...",
  str_homestory_818702001_36_dialog_content = "No te tomes todo tan en serio, PlayerName.",
  str_homestory_818702001_37_dialog_content = "¿Qué tiene de malo reducir el ritmo en el trabajo y detenerse a oler las rosas?<sprite=emo_qingsong size=60 />",
  str_homestory_818702001_38_dialog_content = "Cierto... Ese es el Li Tianxian que conozco.",
  str_homestory_818802001_0_dialog_content = "Dantang¿?",
  str_homestory_818802001_1_dialog_content = "La artesanía de esta cometa es bastante única.",
  str_homestory_818802001_2_dialog_content = "El patrón angular y el esquema de colores sencillo...",
  str_homestory_818802001_3_dialog_content = "Es muy parecido a la variedad más común vista en Longzhou.",
  str_homestory_818802001_4_dialog_content = "¿Los Caelestites también prefieren una elegancia similar? Eso es bastante raro.",
  str_homestory_818802001_5_option_content = "¿A la gente de Longzhou le gusta volar cometas?",
  str_homestory_818802001_6_dialog_content = "Seguro que sí.",
  str_homestory_818802001_7_option_content = "¿Has volado una cometa antes, Dantang?",
  str_homestory_818802001_8_dialog_content = "Sí, me encantan mucho las cometas.",
  str_homestory_818802001_9_dialog_content = "En Longzhou, volar cometas es una de las actividades favoritas para los niños.",
  str_homestory_818802001_10_dialog_content = "Cuando era joven, era un placer raro volar cometas con mis hermanas.",
  str_homestory_818802001_11_dialog_content = "En aquel entonces, nuestras cometas solían enredarse.",
  str_homestory_818802001_12_dialog_content = "A veces, incluso causaba peleas.",
  str_homestory_818802001_13_dialog_content = "Aunque siempre nos reconciliábamos al final,",
  str_homestory_818802001_14_dialog_content = "¿Qué tipo de cometas volaste, Dantang?",
  str_homestory_818802001_15_dialog_content = "Mis cometas? Oh, he volado muchas cometas.",
  str_homestory_818802001_16_dialog_content = "Mis hermanas preferían cometas con formas de aves, pero para mí eran las flores.",
  str_homestory_818802001_17_dialog_content = "No he visto cometas como esa.",
  str_homestory_818802001_18_dialog_content = "Bueno, las cometas en Longzhou variaban mucho en estilo.",
  str_homestory_818802001_19_dialog_content = "Tomemos el Reino Ye, por ejemplo. A ellos les gusta agregar artilugios a las cometas.",
  str_homestory_818802001_20_dialog_content = "Lo que haría que cada parte se mueva y baile.",
  str_homestory_818802001_21_dialog_content = "Todas las cometas que volé en ese momento fueron hechas por los artesanos del palacio.",
  str_homestory_818802001_22_dialog_content = "Decorado lujosamente con elegancia regia.",
  str_homestory_818802001_23_dialog_content = "Realmente lo extraño... Me encantaría volver a volar cometas.",
  str_homestory_818802001_24_dialog_content = "Me temo que esta cometa aquí no puede compararse con lo que tenías antes.",
  str_homestory_818802001_25_dialog_content = "Está bien. Lo que extraño son los momentos despreocupados del pasado.",
  str_homestory_818802001_26_dialog_content = "El uso de cometas es en realidad incidental.",
  str_homestory_818802001_27_dialog_content = "Hmm, no tengo tareas ni mandados por hacer.",
  str_homestory_818802001_28_dialog_content = "Puedo permitirme un descanso, y sería el momento perfecto para volar esta cometa.",
  str_homestory_818802001_29_dialog_content = "Entonces, ¿te gustaría ir a volar cometas conmigo?",
  str_homestory_818802001_30_dialog_content = "No es divertido volarlo solo.",
  str_homestory_818802001_31_dialog_content = "Lástima que solo tengamos uno aquí...",
  str_homestory_818802001_32_dialog_content = "No es un problema. Podemos turnarnos o puedo hacer uno yo mismo.",
  str_homestory_822001001_0_dialog_content = "¿Virgilio?",
  str_homestory_822001001_1_dialog_content = "¿Por qué sigues mirando al espantapájaros, Vergil?",
  str_homestory_822001001_2_dialog_content = "Este espantapájaros...<sprite=emo_sikao size=60 />",
  str_homestory_822001001_3_dialog_content = "¿Qué pasa? ¡No me digas que este espantapájaros es una antigüedad!",
  str_homestory_822001001_4_dialog_content = "A primera vista, parece que es así...",
  str_homestory_822001001_5_dialog_content = "¿En serio? ¿Qué tiene de especial el espantapájaros?",
  str_homestory_822001001_6_dialog_content = "Los accesorios en él... Podrían ser antigüedades.",
  str_homestory_822001001_7_dialog_content = "¿Antigüedades? ¿En serio?",
  str_homestory_822001001_8_dialog_content = "Sí. Este chaleco debería ser una edición limitada de una marca de Umbraton.",
  str_homestory_822001001_9_dialog_content = "Estaba de moda hace cincuenta años.",
  str_homestory_822001001_10_dialog_content = "La característica más destacada de esta oferta limitada es...",
  str_homestory_822001001_11_dialog_content = "Su patrón blanco sobre negro eran rayas blancas teñidas en tela negra.",
  str_homestory_822001001_12_dialog_content = "En lugar del convencional, con rayas negras impresas en tela blanca.",
  str_homestory_822001001_13_dialog_content = "Y hay un número cosido detrás del cuello con hilo de oro.",
  str_homestory_822001001_14_dialog_content = "Yo sí lo veo...<sprite=emo_wuzui size=60 />",
  str_homestory_822001001_15_dialog_content = "Además, si miras de cerca, los ojos del espantapájaros están hechos de obsidiana.",
  str_homestory_822001001_16_dialog_content = "El pulido y el color son ambos de calidad de piedra preciosa.",
  str_homestory_822001001_17_dialog_content = "Los nobles en Lumopolis solían convertir estas gemas en botones hace décadas.",
  str_homestory_822001001_18_dialog_content = "Estos dos no están lejos de eso.",
  str_homestory_822001001_19_dialog_content = "Ni siquiera me di cuenta hasta que lo mencionaste.",
  str_homestory_822001001_20_dialog_content = "Por último, el tronco que sostiene al espantapájaros...",
  str_homestory_822001001_21_dialog_content = "Parece ser madera de agar.",
  str_homestory_822001001_22_dialog_content = "A pesar de ser más delgado, aún puedes oler un ligero aroma cuando te acercas.",
  str_homestory_822001001_23_dialog_content = "Los bastones de Agarwood valen bastante.",
  str_homestory_822001001_24_dialog_content = "¡Vaya, eso significa que este espantapájaros no tiene precio?",
  str_homestory_822001001_25_dialog_content = "Bueno, las antigüedades se juzgan por su totalidad.",
  str_homestory_822001001_26_dialog_content = "Un conjunto completo sería invaluable, pero mucho menos cuando falta incluso un componente.",
  str_homestory_822001001_27_dialog_content = "Y viceversa, justo como este espantapájaros, una compilación de objetos completamente no relacionados.",
  str_homestory_822001001_28_dialog_content = "Incluso desde la perspectiva de una obra de arte...",
  str_homestory_822001001_29_dialog_content = "Es de tercera categoría en el mejor de los casos, ahora no vale nada.",
  str_homestory_822001001_30_dialog_content = "Es una lástima...<sprite=emo_tanqi size=60 />",
  str_homestory_822001001_31_dialog_content = "A menos que...",
  str_homestory_822001001_32_dialog_content = "¿A menos que qué?",
  str_homestory_822001001_33_dialog_content = "A menos que lo desarmes. ¿Deseas hacer eso?",
  str_homestory_822001001_34_dialog_content = "Bueno no.",
  str_homestory_822001001_35_dialog_content = "Prefiero cómo está aquí para que lo disfrutemos tal como está.",
  str_homestory_822001001_36_dialog_content = "Sabía que dirías eso, PlayerName.",
  str_homestory_821901001_0_dialog_content = "¿Qué pasa?",
  str_homestory_821901001_1_dialog_content = "La forma en que te ves... ¿Podría ser...?",
  str_homestory_821901001_2_dialog_content = "Debes gustarte mucho este reloj, ¿no?",
  str_homestory_821901001_3_dialog_content = "Es un estilo que nunca había visto antes.",
  str_homestory_821901001_4_dialog_content = "¿Es un reloj Caelestita?",
  str_homestory_821901001_5_dialog_content = "Eso creo.",
  str_homestory_821901001_6_dialog_content = "Todo en Soroz es Caelestita.",
  str_homestory_821901001_7_dialog_content = "No es una máquina, pero utiliza la reflexión de la luz solar.",
  str_homestory_821901001_8_dialog_content = "Qué concepto tan maravilloso...",
  str_homestory_821901001_9_dialog_content = "Podría llamarse Arte de Sombra.",
  str_homestory_821901001_10_dialog_content = "Realmente te gusta el reloj, veo.",
  str_homestory_821901001_11_dialog_content = "Estoy asombrado por el tiempo fugaz.",
  str_homestory_821901001_12_dialog_content = "Por lo tanto, también me encanta coleccionar relojes de diferentes marcas.",
  str_homestory_821901001_13_dialog_content = "¿Qué? ¿Quieres decir que hay muchos tipos de relojes en el mundo exterior?",
  str_homestory_821901001_14_dialog_content = "Los relojes en Lumopolis son clásicos y elegantes.",
  str_homestory_821901001_15_dialog_content = "Los relojes de Northland son simples y prácticos.",
  str_homestory_821901001_16_dialog_content = "Los relojes del desierto de Rediesel están llenos de trucos y artilugios.",
  str_homestory_821901001_17_dialog_content = "Y los relojes de Umbraton son discretos pero hermosos.",
  str_homestory_821901001_18_dialog_content = "Lo entiendo. Definitivamente eres un aficionado a las colecciones.",
  str_homestory_821901001_19_dialog_content = "Nunca pensé que un artículo común pudiera tener tanto.",
  str_homestory_821901001_20_dialog_content = "Has abierto mis ojos.",
  str_homestory_821901001_21_dialog_content = "Los relojes que mencioné son todos productos de los tiempos modernos.",
  str_homestory_821901001_22_dialog_content = "Mientras que el reloj Caelestite me hizo darme cuenta de la gravedad del pasado.",
  str_homestory_821901001_23_dialog_content = "Ese sentimiento es especial y único.",
  str_homestory_821901001_24_dialog_content = "Si así es como te sientes...<sprite=emo_sikao size=60 />",
  str_homestory_821901001_25_dialog_content = "Me gustaría dártelo.",
  str_homestory_821901001_26_dialog_content = "¿Por qué harías eso?",
  str_homestory_821901001_27_option_content = "Porque somos amigos.",
  str_homestory_821901001_28_dialog_content = "¿Es por amistad, verdad?",
  str_homestory_821901001_29_dialog_content = "Esa es una declaración de sinceridad.",
  str_homestory_821901001_30_option_content = "Parece que te gusta mucho.",
  str_homestory_821901001_31_dialog_content = "Aun así, no quiero simplemente tomarlo.",
  str_homestory_821901001_32_dialog_content = "Aprecio mucho el pensamiento, aunque.",
  str_homestory_821901001_33_dialog_content = "Pero, ¿por qué no dejamos que simplemente se quede en \"casa\"?",
  str_homestory_821901001_34_dialog_content = "No lo entiendo. ¿No te gusta?",
  str_homestory_821901001_35_dialog_content = "Tengo otros relojes aquí, así que...",
  str_homestory_821901001_36_dialog_content = "Me alegra mucho saber que compartirías cualquier cosa con un amigo.",
  str_homestory_821901001_37_dialog_content = "Sin embargo, creo que está destinado a no estar en ningún otro lugar sino aquí.",
  str_homestory_821901001_38_dialog_content = "El pasado representa recuerdos, y los recuerdos consisten en historia.",
  str_homestory_821901001_39_dialog_content = "Todo lo Caelestita está aquí, PlayerName.",
  str_homestory_821901001_40_dialog_content = "Todo esto significa algo para ti.",
  str_homestory_821901001_41_dialog_content = "No quiero llevarme nada de eso.",
  str_homestory_821901001_42_dialog_content = "Istvan...",
  str_homestory_821901001_43_dialog_content = "Adiós, que la sombra te vigile.",
  str_homestory_821801001_0_dialog_content = "¿Señorita Sheol?",
  str_homestory_821801001_1_dialog_content = "¡Me alegra verte aquí! Es una señal de que algo bueno sucederá hoy.",
  str_homestory_821801001_2_dialog_content = "¿No estás de acuerdo, PlayerName?",
  str_homestory_821801001_3_dialog_content = "No es inesperado, Señorita Sheol. Sabes que estamos en los Jardines de la Nube, ¿verdad...",
  str_homestory_821801001_4_dialog_content = "Por supuesto que sí.",
  str_homestory_821801001_5_dialog_content = "Pero necesitas esas coincidencias ocasionales, ya sea en los negocios o en la vida.",
  str_homestory_821801001_6_dialog_content = "Lo siento, aún no entiendo.",
  str_homestory_821801001_7_dialog_content = "Está bien. Déjame explicar.",
  str_homestory_821801001_8_dialog_content = "Por ejemplo, necesitabas renovar Cloud Gardens y el Gremio de Explorador Nublar...",
  str_homestory_821801001_9_dialog_content = "Justo tenía un plan para eso.",
  str_homestory_821801001_10_dialog_content = "¿No sería eso una coincidencia?",
  str_homestory_821801001_11_dialog_content = "Y con eso, ¿estás diciendo...?",
  str_homestory_821801001_12_dialog_content = "Cloud Gardens es realmente especial, pero ¿no crees que los dormitorios son demasiado sencillos?",
  str_homestory_821801001_13_option_content = "¿Lo son?",
  str_homestory_821801001_14_dialog_content = "Por supuesto, ¿por qué más mencionaría eso?",
  str_homestory_821801001_15_dialog_content = "Probablemente estás acostumbrado, por eso no lo sientes de esa manera.",
  str_homestory_821801001_16_dialog_content = "Pero creo que los dormitorios simples simplemente no son adecuados para Cloud Gardens.",
  str_homestory_821801001_17_option_content = "Yo también siento lo mismo",
  str_homestory_821801001_18_dialog_content = "¡Lo sabía!",
  str_homestory_821801001_19_dialog_content = "En ese caso, ¿no crees que se debería hacer algo al respecto?",
  str_homestory_821801001_20_dialog_content = "¿Como renovarlos?",
  str_homestory_821801001_21_dialog_content = "Lo que quiero decir es, podemos hacer los dormitorios más elegantes.",
  str_homestory_821801001_22_dialog_content = "¿Más elegante?",
  str_homestory_821801001_23_dialog_content = "No es una mala idea, pero el presupuesto<sprite=emo_baiyebi size=60 /> es ajustado...",
  str_homestory_821801001_24_dialog_content = "¡No te preocupes! ¡Puedes confiar el proyecto a mi Gremio de Explorador Nublar!",
  str_homestory_821801001_25_dialog_content = "¡Remodelaré los dormitorios para que coincidan con la grandeza de Cloud Gardens gratis!",
  str_homestory_821801001_26_dialog_content = "¿Gratis? ¿Todo?!",
  str_homestory_821801001_27_dialog_content = "No estoy seguro de eso...",
  str_homestory_821801001_28_dialog_content = "Sé que somos amigos, pero esto es aprovecharse demasiado de ti, Lady Sheol.",
  str_homestory_821801001_29_dialog_content = "Como sabes, no hago tratos que no sean rentables.",
  str_homestory_821801001_30_dialog_content = "Cuando los dormitorios estén terminados, cambiaremos la marca de Cloud Gardens a un complejo hotelero.",
  str_homestory_821801001_31_dialog_content = "¿Complejo hotelero?!",
  str_homestory_821801001_32_dialog_content = "Simplemente siéntate y déjame todo a mí.",
  str_homestory_821801001_33_dialog_content = "O déjame decirlo de esta manera, ¡te garantizo que estarás contando dinero hasta que te canses!",
  str_homestory_821801001_34_dialog_content = "¿Contar dinero hasta que me canse?!",
  str_homestory_821801001_35_dialog_content = "¿Es este el proyecto que mencionaste antes?",
  str_homestory_821801001_36_dialog_content = "¡Esta es verdaderamente una propuesta que no puedo rechazar<sprite=emo_aixin size=60 />!",
  str_homestory_821801001_37_dialog_content = "Perfecto, entonces está resuelto...",
  str_homestory_821801001_38_dialog_content = "¡Espera, Señora Sheol!",
  str_homestory_821801001_39_dialog_content = "Lo siento, pero solo quiero mantener Cloud Gardens tal como está por ahora.",
  str_homestory_821801001_40_dialog_content = "No estoy seguro de cómo los habitantes de Cloud Gardens recibirán la noticia...",
  str_homestory_821801001_41_dialog_content = "Entonces, si nos lanzamos al proyecto de inmediato...",
  str_homestory_821801001_42_dialog_content = "Veo. Lo entiendo.",
  str_homestory_821801001_43_dialog_content = "Eso significa que tenemos la oportunidad de hacer del turismo algo en el futuro, ¿verdad?",
  str_homestory_821801001_44_dialog_content = "¿Turismo?",
  str_homestory_821801001_45_dialog_content = "¡Entonces, espero saber de ti!",
  str_homestory_822101001_0_dialog_content = "¿Intrigado?",
  str_homestory_822101001_1_dialog_content = "Te vi mirándolo todo el tiempo, aparentemente muy emocionado.",
  str_homestory_822101001_2_dialog_content = "¿Es esto<sprite=emo_sikao size=60 />...",
  str_homestory_822101001_3_dialog_content = "¿Un contenedor de basura capaz de clasificar automáticamente la basura reciclada?",
  str_homestory_822101001_4_dialog_content = "¡Vaya! ¿Cómo sabes eso?!",
  str_homestory_822101001_5_dialog_content = "Es un cubo de basura estilo Caelestite, diferente a los que sueles ver.",
  str_homestory_822101001_6_dialog_content = "Pero aún pensé que no sería tan fácilmente reconocible.",
  str_homestory_822101001_7_dialog_content = "Jeje, ¿me estás subestimando de nuevo?",
  str_homestory_822101001_8_dialog_content = "Entonces, elaboraré sobre mi análisis.",
  str_homestory_822101001_9_dialog_content = "En primer lugar, hackeé su programa de control y le eché un vistazo...",
  str_homestory_822101001_10_dialog_content = "¿Qué? ¿Por qué harías eso con los muebles de otras personas?!",
  str_homestory_822101001_11_dialog_content = "Estaba en otro lenguaje de programación que es avanzado y conciso. ¡Definitivamente una obra maestra de la alta tecnología Caelestite!",
  str_homestory_822101001_12_dialog_content = "Pero en términos de funciones, pude discernir sus similitudes con las del sistema de clasificación automática en la Cafetería de Illumina.",
  str_homestory_822101001_13_dialog_content = "Lo que significa que esto también tiene la misma función de categorización.",
  str_homestory_822101001_14_dialog_content = "Por cierto, escribí el programa para la Cafetería Illumina.",
  str_homestory_822101001_15_dialog_content = "¡Podría clasificar y dispensar alimentos basándose en sus niveles nutricionales!",
  str_homestory_822101001_16_dialog_content = "Agradable.",
  str_homestory_822101001_17_dialog_content = "Me pregunto si habrá un ingrediente nutritivo que pueda reducir el deseo de jugar con los muebles de un amigo.",
  str_homestory_822101001_18_dialog_content = ".... De todos modos, no está mal que asocies \"clasificar\" con un cubo de basura.",
  str_homestory_822101001_19_dialog_content = "Bueno, hay una razón más concluyente para eso.",
  str_homestory_822101001_20_dialog_content = "¿Oh?",
  str_homestory_822101001_21_dialog_content = "Hay una gran imagen de basura en ella.",
  str_homestory_822101001_22_dialog_content = "...",
  str_homestory_822101001_23_dialog_content = "¡Simplemente maravilloso!",
  str_homestory_822101001_24_dialog_content = "La auto-organización realmente no es lo mejor desde el pan rebanado.",
  str_homestory_822101001_25_dialog_content = "Pero empacar un sistema en un volumen tan compacto...",
  str_homestory_822101001_26_dialog_content = "Con tales características de clasificación detalladas en la parte superior... Eso es algo con lo que la tecnología actual de Illumina solo puede soñar.",
  str_homestory_822101001_27_dialog_content = "¡Los Caelestitas son verdaderamente personas geniales!",
  str_homestory_822101001_28_dialog_content = "Em...",
  str_homestory_822101001_29_option_content = "¿De verdad lo crees?",
  str_homestory_822101001_30_dialog_content = "Es solo un cubo de basura.",
  str_homestory_822101001_31_dialog_content = "\"Simplemente un bote de basura\" es lo que lo hizo genial.",
  str_homestory_822101001_32_option_content = "No pensé que te interesaría tanto una \"papelera de reciclaje automática\".",
  str_homestory_822101001_33_dialog_content = "¡Eso incluso me ha emocionado mucho!",
  str_homestory_822101001_34_dialog_content = "¡Deberías serlo!",
  str_homestory_822101001_35_dialog_content = "Las tecnologías de vanguardia siempre se aplican primero a usos militares.",
  str_homestory_822101001_36_dialog_content = "Solo cuando se vuelvan más prevalentes que la suciedad podrán ser accesibles para la gente normal.",
  str_homestory_822101001_37_dialog_content = "En este caso, es solo porque esta papelera de reciclaje automática es una papelera de basura...",
  str_homestory_822101001_38_dialog_content = "¡Eso muestra la grandeza de la cultura Caelestita!",
  str_homestory_822101001_39_dialog_content = "¡Ah! Eso tiene sentido, ahora que lo pienso!",
  str_homestory_822101001_40_dialog_content = "Aunque todavía me molesta que hayas hackeado el programa...",
  str_homestory_822101001_41_dialog_content = "Pero siempre aprendo algo al hablar contigo. Lo digo en serio.",
  str_homestory_822101001_42_dialog_content = "Gracias, Algol.",
  str_homestory_822101001_43_dialog_content = "¡No lo menciones! Aunque preferiría que me dieras permiso para desmontar el contenedor para un estudio exhaustivo...",
  str_homestory_822101001_44_dialog_content = "¡Olvida eso!",
  str_homestory_822301001_0_dialog_content = "Esta estatua de piedra...",
  str_homestory_822301001_1_dialog_content = "Apenas veo cosas así en tu cueva, PlayerName.",
  str_homestory_822301001_2_dialog_content = "¿Esta estatua tiene algún tipo de significado especial para ti?",
  str_homestory_822301001_3_dialog_content = "Lo adivinaste... Es una estatua de una niña Caelestita.",
  str_homestory_822301001_4_dialog_content = "Un Celestita... ¿Uno de tu gente de hace mucho tiempo, sí?",
  str_homestory_822301001_5_dialog_content = "Puedo sentir el aliento del tiempo proveniente de cada grieta y rasguño en esta estatua.",
  str_homestory_822301001_6_dialog_content = "Las historias dicen que ella era una viajera, una que visitó cada punto de referencia famoso de nuestro continente.",
  str_homestory_822301001_7_dialog_content = "Y tienes razón, Chen'ni. Esta estatua es de hace mucho tiempo...",
  str_homestory_822301001_8_dialog_content = "Sería peligroso para un Caelestite viajar por nuestro mundo infestado de Eclipsites <sprite=emo_kulou size=60 /> todo por su cuenta ahora...",
  str_homestory_822301001_9_dialog_content = "Conmigo a tu lado, ¿qué hay que temer?",
  str_homestory_822301001_10_dialog_content = "¿Quizás algún día, también se erigirá una estatua en tu memoria?",
  str_homestory_822301001_11_dialog_content = "¿Eh? ¿M-Me?! De ninguna manera, no soy nada especial en absoluto...",
  str_homestory_822301001_12_dialog_content = "¿Por qué no? Por ejemplo, ¿qué pasaría si hubiera una sequía severa en el mundo y yo convocara una lluvia intensa para traer salvación a todos...",
  str_homestory_822301001_13_dialog_content = "Y luego después, me llevaste a comprar unos melones de azúcar...",
  str_homestory_822301001_14_dialog_content = "¡Entonces todos nos verían a ambos, y harían estatuas de los dos!",
  str_homestory_822301001_15_dialog_content = "Ese es un ejemplo extrañamente específico, casi como si realmente hubiera sucedido en algún momento...",
  str_homestory_822301001_16_dialog_content = "¡O tal vez un invierno, rescato a treinta y ocho personas de un naufragio en el mar de un solo golpe!",
  str_homestory_822301001_17_dialog_content = "Y una vez que lleguen a la orilla, enciendes fuegos y proporcionas mantas para que puedan sobrevivir al frío intenso...",
  str_homestory_822301001_18_dialog_content = "¡Colocarán una estatua tuya justo al lado de la mía, y la gente encenderá incienso en nuestro honor durante generaciones!",
  str_homestory_822301001_19_dialog_content = "...",
  str_homestory_822301001_20_dialog_content = "¿Qué pasa? ¿No te parecen interesantes estas historias?",
  str_homestory_822301001_21_option_content = "Lo están.",
  str_homestory_822301001_22_dialog_content = "Pero también suenan realmente tristes.",
  str_homestory_822301001_23_option_content = "Es difícil de decir...",
  str_homestory_822301001_24_dialog_content = "Siento que esa no es una buena manera de considerarlos.",
  str_homestory_822301001_25_dialog_content = "Principalmente porque no son solo historias, ¿verdad?",
  str_homestory_822301001_26_dialog_content = "Cuando estuve en Longzhou, vi tantas estatuas tuyas en diferentes lugares.",
  str_homestory_822301001_27_dialog_content = "Imagino que has ayudado a innumerables personas en todo Longzhou, dejando atrás leyendas e historias como las que acabas de mencionar.",
  str_homestory_822301001_28_dialog_content = "En cuanto a las personas en tus historias, como la que te compró melones de azúcar o la que te ayudó a salvar a esas personas...",
  str_homestory_822301001_29_dialog_content = "Probablemente ya no sean parte de este mundo... Eres el único que aún queda.",
  str_homestory_822301001_30_dialog_content = "¿Sientes lástima por mí, PlayerName?",
  str_homestory_822301001_31_dialog_content = "Solo lamento que tengas que seguir diciendo adiós a las personas a tu alrededor...",
  str_homestory_822301001_32_dialog_content = "¿Está mal que yo sienta eso por una diosa dragón?",
  str_homestory_822301001_33_dialog_content = "Como un ser de carne y sangre, es perfectamente natural que te sientas de esta manera.",
  str_homestory_822301001_34_dialog_content = "También siento lo mismo por ti.",
  str_homestory_822301001_35_dialog_content = "El tiempo es insondablemente largo y lleva todo a su fin.",
  str_homestory_822301001_36_dialog_content = "A pesar de mi longevidad, incluso mi propia existencia es solo un parpadeo en comparación con el mundo.",
  str_homestory_822301001_37_dialog_content = "Pero nuestra naturaleza efímera es precisamente lo que hace precioso nuestro encuentro. Poder caminar uno al lado del otro es entrelazar nuestros destinos.",
  str_homestory_822301001_38_dialog_content = "Sería arrogante de mi parte sentir lástima por los mortales por su corta esperanza de vida.",
  str_homestory_822301001_39_dialog_content = "Eso tiene sentido... Por alguna razón, mi estado de ánimo se siente mucho mejor ahora.",
  str_homestory_822301001_40_dialog_content = "\"La amistad no teme al paso del tiempo\". ¿No es eso lo que dicen en Longzhou?",
  str_homestory_822301001_41_dialog_content = "¡Eso es exactamente correcto! Realmente has aprendido mucho últimamente.",
  str_homestory_822301001_42_dialog_content = "El tiempo puede ser cruel, pero también tiene un buen lado.",
  str_homestory_822301001_43_dialog_content = "<sprite=emo_qingsong size=60 /> Jeje... Supongo que no puedo permitirme el lujo de malgastar mi tiempo sentado en un solo lugar!",
  str_homestory_822301001_44_dialog_content = "Además, si no fuera por el paso del tiempo, nunca nos habríamos conocido...",
  str_homestory_822301001_45_dialog_content = "Y nunca hubiera tenido la oportunidad de pasar tantos días felices aquí con todos.",
  str_homestory_822401001_0_dialog_content = "¿Luo Song?",
  str_homestory_822401001_1_dialog_content = "¿Quieres usar esto?",
  str_homestory_822401001_2_dialog_content = "¡Por supuesto que sí! Está tan finamente hecho, después de todo!",
  str_homestory_822401001_3_dialog_content = "¿Finamente... Hecho?",
  str_homestory_822401001_4_dialog_content = "¡Sí! ¡Solo mira cómo su expresión inspira un impulso de confrontación!",
  str_homestory_822401001_5_dialog_content = "¡Y su marco tampoco es demasiado duro ni demasiado suave!",
  str_homestory_822401001_6_dialog_content = "No importa cuán fuerte lo golpees, siempre vuelve a su posición original...",
  str_homestory_822401001_7_dialog_content = "¡Es la herramienta de entrenamiento perfecta para mis puños!",
  str_homestory_822401001_8_option_content = "Entiendo.",
  str_homestory_822401001_9_dialog_content = "Sabía<sprite=emo_guilian size=60 /> que entenderías, PlayerName.",
  str_homestory_822401001_10_option_content = "Realmente no lo entiendo...",
  str_homestory_822401001_11_dialog_content = "Realmente tampoco puedo explicarlo <sprite=emo_sikao size=60 />. Supongo que podrías llamarlo intuición de guerrero?",
  str_homestory_822401001_12_dialog_content = "Durante mis viajes en Longzhou, me sometí a un amargo entrenamiento todos los días.",
  str_homestory_822401001_13_dialog_content = "Fortalecimiento, meditación, boxeo de sombra, lo que quieras.",
  str_homestory_822401001_14_dialog_content = "Incluso un solo día sin entrenamiento puede hacer que una persona se oxide.",
  str_homestory_822401001_15_dialog_content = "Pero el objetivo de entrenar de esta manera es fortalecer el cuerpo.",
  str_homestory_822401001_16_dialog_content = "Algunas personas se dejan llevar por la parte \"amarga\" de ello, y terminan lastimándose como resultado.",
  str_homestory_822401001_17_dialog_content = "Y eso derrota completamente el propósito.",
  str_homestory_822401001_18_dialog_content = "¡Así es!",
  str_homestory_822401001_19_dialog_content = "Es como cuando algunas personas se estrellan repetidamente contra árboles al practicar la técnica de \"Inclinación de la Montaña de Hierro\".",
  str_homestory_822401001_20_dialog_content = "Debido al alto riesgo de lesiones personales, es una forma extremadamente imprudente de practicar ese movimiento.",
  str_homestory_822401001_21_dialog_content = "Ya veo. Cuanto más sabes, eh...",
  str_homestory_822401001_22_dialog_content = "Durante mis viajes, también tuve que usar árboles para entrenar ya que no pude encontrar una mejor manera.",
  str_homestory_822401001_23_dialog_content = "Tal vez es porque era joven, pero apenas sentí dolor o incomodidad.",
  str_homestory_822401001_24_dialog_content = "Pero más tarde, comencé a entrenar a Ah Ding y a los demás.",
  str_homestory_822401001_25_dialog_content = "Y rápidamente me di cuenta de que seguir mi rutina era una forma fácil de que ellos resultaran heridos.",
  str_homestory_822401001_26_dialog_content = "También me di cuenta de que los métodos de entrenamiento y el equipo que utilicé en el pasado eran demasiado rudimentarios.",
  str_homestory_822401001_27_dialog_content = "Por eso he comenzado a prestar más atención a la seguridad durante el entrenamiento, e incluir cosas como equipo de protección.",
  str_homestory_822401001_28_dialog_content = "Incluso he hecho equipo de entrenamiento personalizado solo para Ah Ding y los otros pequeños demonios...",
  str_homestory_822401001_29_dialog_content = "Me costó mucho tiempo y esfuerzo diseñar equipo teniendo en cuenta sus necesidades.",
  str_homestory_822401001_30_dialog_content = "Especialmente esos pilares de flores de ciruelo. ¡Tomó tantos intentos hacer algo que funcione con sus patas cortas y pequeñas!",
  str_homestory_822401001_31_dialog_content = "Eres un chico bastante considerado.",
  str_homestory_822401001_32_dialog_content = "Por supuesto. Además, realmente no tengo ningún pasatiempo fuera del entrenamiento.",
  str_homestory_822401001_33_dialog_content = "Así que naturalmente voy a hacer lo mejor para el entrenamiento de mis amigos también.",
  str_homestory_822401001_34_dialog_content = "¡Cuando tenga algo de tiempo, asegúrate de que también diseñaré algunas cosas para ti!",
  str_homestory_822501001_0_dialog_content = "Esa linterna allí...",
  str_homestory_822501001_1_dialog_content = "¿Te gusta esa linterna de la corte, Tiare?",
  str_homestory_822501001_2_dialog_content = "Siéntete libre de echar un vistazo más de cerca, si quieres.",
  str_homestory_822501001_3_dialog_content = "Esta es la distancia perfecta, de hecho.",
  str_homestory_822501001_4_dialog_content = "Me recuerda al faro en Northland desde aquí.",
  str_homestory_822501001_5_dialog_content = "Veo lo que dices, ahora que lo mencionas.",
  str_homestory_822501001_6_dialog_content = "Es una lástima que sea solo una linterna común y no cuide a las criaturas de Northland como un faro.",
  str_homestory_822501001_7_dialog_content = "...",
  str_homestory_822501001_8_dialog_content = "Solía sentarme en la cima de los cedros y observar el faro cuando era pequeño.",
  str_homestory_822501001_9_dialog_content = "Fue asombrosamente brillante...",
  str_homestory_822501001_10_dialog_content = "Su resplandor podría llegar a cualquier lugar, sin importar cuán oscuro fuera y cuánta niebla hubiera.",
  str_homestory_822501001_11_dialog_content = "La luz mantenía el Bosque de Pino de Nieve tranquilo e inmóvil.",
  str_homestory_822501001_12_dialog_content = "Sin Eclipsites chillando, sin Aurorians gritando... La serenidad era inestimable.",
  str_homestory_822501001_13_dialog_content = "Solo nosotros, los Northlanders, tenemos ese faro especial.",
  str_homestory_822501001_14_dialog_content = "Puedo decir cuánto aprecian y reverencian esto.",
  str_homestory_822501001_15_dialog_content = "En realidad, lo que apreciamos y reverenciamos no es el faro...",
  str_homestory_822501001_16_dialog_content = "Una vez, estaba tan ocupado persiguiendo una presa astuta que no me di cuenta de lo lejos que había ido.",
  str_homestory_822501001_17_dialog_content = "¡Hasta que los gritos de los Eclipsites me asustaron! Para entonces, estaba demasiado lejos de casa.",
  str_homestory_822501001_18_dialog_content = "Fue entonces cuando vi las luces de un faro.",
  str_homestory_822501001_19_dialog_content = "¿Todavía puedes verlo tan lejos de casa?",
  str_homestory_822501001_20_dialog_content = "No, lo que vi no era el faro que nos protegía.",
  str_homestory_822501001_21_dialog_content = "Pero un faro normal junto al mar.",
  str_homestory_822501001_22_dialog_content = "Se convertiría en un escondite de Eclipsites después del anochecer.",
  str_homestory_822501001_23_dialog_content = "¡Santo cielo!",
  str_homestory_822501001_24_dialog_content = "Me escondí en el bosque, sin atreverme a moverme.",
  str_homestory_822501001_25_dialog_content = "La luz seguía pasando por mi lado.",
  str_homestory_822501001_26_dialog_content = "Lo observé mientras los Eclipsites se movían debajo.",
  str_homestory_822501001_27_dialog_content = "¿Sabes lo que me di cuenta entonces?",
  str_homestory_822501001_28_dialog_content = "¿Qué?",
  str_homestory_822501001_29_dialog_content = "Ese faro era exactamente igual al faro que apreciaba y reverenciaba.",
  str_homestory_822501001_30_dialog_content = "...",
  str_homestory_822501001_31_dialog_content = "Tenía el mismo resplandor que podía penetrar la noche más oscura y la niebla más densa...",
  str_homestory_822501001_32_dialog_content = "Pero no pudo protegerme. Durante toda la noche, si tan solo hubiera hecho el más mínimo movimiento...",
  str_homestory_822501001_33_dialog_content = "Los Eclipsites me habrían despedazado.",
  str_homestory_822501001_34_dialog_content = "Tiare...",
  str_homestory_822501001_35_dialog_content = "Finalmente entendí esa noche.",
  str_homestory_822501001_36_dialog_content = "El faro en sí mismo no era nada especial.",
  str_homestory_822501001_37_dialog_content = "Como esta linterna común que vemos, era solo un edificio ordinario.",
  str_homestory_822501001_38_dialog_content = "No habría sido nada si nadie lo hubiera encendido, mantenido y respaldado con determinación.",
  str_homestory_822501001_39_dialog_content = "Lo que había estado protegiendo a los norteños nunca fue el faro...",
  str_homestory_822501001_40_dialog_content = "Pero Queen Bethlehem.",
  str_homestory_822501001_41_dialog_content = "...",
  str_homestory_822501001_42_option_content = "La determinación de Su Majestad es simplemente inquebrantable.",
  str_homestory_822501001_43_dialog_content = "Incluso sin el faro, ella haría todo lo posible para defender a su gente.",
  str_homestory_822501001_44_option_content = "Esa debe haber sido una noche importante en tu vida.",
  str_homestory_822501001_45_dialog_content = "Esa noche fue cuando forjaste tu propia determinación.",
  str_homestory_822501001_46_dialog_content = "Es correcto.",
  str_homestory_822501001_47_dialog_content = "Incluso si no puedo igualar a Su Majestad, la seguiré hasta el amargo final.",
  str_homestory_822501001_48_dialog_content = "He dedicado mi vida a defender y proteger a mi gente, como ella.",
  str_homestory_822501001_49_dialog_content = "Así es como me siento también.",
  str_homestory_822501001_50_dialog_content = "Especialmente la parte sobre \"no poder sostener una vela a Su Majestad\".",
  str_homestory_822501001_51_dialog_content = "Jaja, ¿quién podría tenerle una vela de todos modos?",
  str_homestory_822501001_52_dialog_content = "Pero mientras ella esté allí, nunca me perderé.",
  str_homestory_822601001_0_dialog_content = "Hey...",
  str_homestory_822601001_1_dialog_content = "¿No crees que este caballito balancín es bastante interesante, Rachel?",
  str_homestory_822601001_2_dialog_content = "Sé que es un poco infantil, pero es sorprendentemente divertido montarlo.",
  str_homestory_822601001_3_dialog_content = "¿Quieres intentarlo? ¡Adelante!",
  str_homestory_822601001_4_dialog_content = "Preferiría no...",
  str_homestory_822601001_5_dialog_content = "No importa lo que digas, soy demasiado viejo para este tipo de cosas.",
  str_homestory_822601001_6_dialog_content = "En cuanto a ti, no sabía que eras un gran fan de los caballitos balancín.",
  str_homestory_822601001_7_dialog_content = "No diría que soy un \"fan\" de ellos ni nada...",
  str_homestory_822601001_8_dialog_content = "(Pensé que ella estaba demasiado avergonzada para montarlo, ¡pero ahora mi secreto ha salido a la luz!)",
  str_homestory_822601001_9_dialog_content = "Aun así, es un juguete bastante bien hecho.",
  str_homestory_822601001_10_dialog_content = "Cuando miras más allá de su apariencia simple, el diseño y la artesanía son ambos excelentes.",
  str_homestory_822601001_11_dialog_content = "Una poderosa combinación de ergonomía y mecánica estructural.",
  str_homestory_822601001_12_dialog_content = "Incluso yo estoy algo cautivado por ello.",
  str_homestory_822601001_13_dialog_content = "Wow... Nunca me di cuenta de nada de eso por mí mismo.",
  str_homestory_822601001_14_dialog_content = "¿Quieres decir que puedes discernir todas esas cosas con solo mirar algo?",
  str_homestory_822601001_15_dialog_content = "Sí. Es una habilidad básica para cualquier ingeniero.",
  str_homestory_822601001_16_dialog_content = "La capacidad de dibujar una representación tridimensional de cualquier objeto con un solo vistazo es muy importante.",
  str_homestory_822601001_17_dialog_content = "De hecho, ya tengo una buena idea de cómo replicar este caballito balancín.",
  str_homestory_822601001_18_dialog_content = "Eso me suena a un superpoder...",
  str_homestory_822601001_19_dialog_content = "¡Está bien, entonces te lo dejaré!",
  str_homestory_822601001_20_dialog_content = "¿Ah?",
  str_homestory_822601001_21_option_content = "Puedes llevártelo a casa para fines de investigación.",
  str_homestory_822601001_22_dialog_content = "Entiendo. Quieres que me vaya, así puedo dejar de molestarte, ¿verdad?",
  str_homestory_822601001_23_dialog_content = "¡Para nada!",
  str_homestory_822601001_24_option_content = "Parece que te gusta mucho.",
  str_homestory_822601001_25_dialog_content = "Sí, pero me gusta tu Coloso más que cualquier otra cosa.",
  str_homestory_822601001_26_dialog_content = "¡Soroz no está en la mesa!",
  str_homestory_822601001_27_dialog_content = "Je... Solo bromeando.",
  str_homestory_822601001_28_dialog_content = "Gracias por la oferta, pero...",
  str_homestory_822601001_29_dialog_content = "Quiero hacer el regalo de mi hermana con mis propias dos manos.",
  str_homestory_822601001_30_dialog_content = "... ¿Hermana?",
  str_homestory_822601001_31_dialog_content = "Sí. En el momento en que vi este caballito balancín, decidí hacer uno igual para mi hermanita.",
  str_homestory_822601001_32_dialog_content = "Nunca tuve la oportunidad de jugar con juguetes así cuando era niño, pero al menos mi hermana lo hará...",
  str_homestory_822601001_33_dialog_content = "Aunque tal vez sea solo mi forma de compensar mi propio pasado.",
  str_homestory_822601001_34_dialog_content = "Rachel...",
  str_homestory_822601001_35_dialog_content = "Estaba hablando en serio justo ahora.",
  str_homestory_822601001_36_dialog_content = "Este caballito balancín... ¡Es mucho más divertido de lo que piensas!",
  str_homestory_822601001_37_dialog_content = "¿E-Eh?",
  str_homestory_822601001_38_dialog_content = "¡Así que dale una vuelta! No puedes hacer la réplica perfecta para tu hermana a menos que hayas probado la original por ti mismo, ¿verdad?",
  str_homestory_822601001_39_dialog_content = "¡Vamos, no seas tímido!",
  str_homestory_822601001_40_dialog_content = "Uh... Bien entonces... Pero sólo esta vez.",
  str_homestory_822601001_41_dialog_content = "¡Apuesto a que también te engancharás!",
  str_homestory_822701001_0_dialog_content = "Zeta?",
  str_homestory_822701001_1_dialog_content = "¿Qué es esta cosa?",
  str_homestory_822701001_2_dialog_content = "Estas alas adorables, esta artesanía experta...",
  str_homestory_822701001_3_dialog_content = "Si me preguntas, esto debe ser algún tipo de tesoro invaluable del pasado lejano.",
  str_homestory_822701001_4_dialog_content = "Es una Muñeca Windelion.",
  str_homestory_822701001_5_dialog_content = "Bueno, si no es el Último Caelestite. Llegaste justo a tiempo.",
  str_homestory_822701001_6_dialog_content = "Dado que conoces su nombre, debes estar muy familiarizado con esta maravillosa creación.",
  str_homestory_822701001_7_dialog_content = "Es solo una decoración para Windelion.",
  str_homestory_822701001_8_dialog_content = "¿Windelion?",
  str_homestory_822701001_9_dialog_content = "Es una festividad Caelestite. Alguien una vez me dijo que es similar a cómo los Aurorians conmemoran a sus santos y al Dios de la Luz.",
  str_homestory_822701001_10_dialog_content = "¿Santos? ¿El Dios de la Luz? ¡Eso suena increíble!",
  str_homestory_822701001_11_dialog_content = "¡No tenía idea de que este mundo tuviera una fiesta tan genial!",
  str_homestory_822701001_12_dialog_content = "Un amigo mío también aprendió sobre Windelion de los libros.",
  str_homestory_822701001_13_dialog_content = "Para nosotros, los Caelestites, es una fiesta increíblemente importante.",
  str_homestory_822701001_14_dialog_content = "Cada año en Windelion, damos gracias a la naturaleza organizando un gran festín.",
  str_homestory_822701001_15_dialog_content = "Oh... Eso no suena muy diferente a cualquier otra festividad.",
  str_homestory_822701001_16_dialog_content = "Ejem... En cualquier caso, esta muñeca es solo otra decoración utilizada para celebrar Windelion.",
  str_homestory_822701001_17_dialog_content = "Llenamos la barriga de la muñeca con dulces y deseos.",
  str_homestory_822701001_18_dialog_content = "¿Dijiste... dulces y deseos?",
  str_homestory_822701001_19_dialog_content = "¡Hagámoslo entonces! ¡Quiero celebrar Windelion ahora mismo!",
  str_homestory_822701001_20_dialog_content = "¿Por qué estás tan emocionado de repente?",
  str_homestory_822701001_21_dialog_content = "¡También quiero hacer una Muñeca Windelion!",
  str_homestory_822701001_22_option_content = "También puedes hacerlos fuera de las vacaciones, ya sabes.",
  str_homestory_822701001_23_dialog_content = "¿Es eso así? Entonces muéstrame cómo hacer uno.",
  str_homestory_822701001_24_option_content = "Claro, no veo por qué no.",
  str_homestory_822701001_25_dialog_content = "¿De veras? ¡Eres el mejor!",
  str_homestory_822701001_26_dialog_content = "Jejeje, y una vez que termine, llenaré su barriga con mis últimas obras maestras...",
  str_homestory_822701001_27_dialog_content = "Cuando todos comienzan a preguntarse qué hay dentro...",
  str_homestory_822701001_28_dialog_content = "¡Boom! ¡Pop! ¡Whoosh! ¡Un montón de humo y dulces saldrán volando!",
  str_homestory_822701001_29_dialog_content = "¿Eh? No vas a poner bombas en eso, ¿verdad?",
  str_homestory_822701001_30_dialog_content = "¡Sí, lo estoy, pero no te preocupes! ¡Solo usaré lo suficiente para enviar dulces volando en todas direcciones!",
  str_homestory_822801001_0_dialog_content = "Batia",
  str_homestory_822801001_1_dialog_content = "¡Por fin saliste!",
  str_homestory_822801001_2_dialog_content = "Oh, hola...",
  str_homestory_822801001_3_dialog_content = "¿Puedo ayudarte?",
  str_homestory_822801001_4_dialog_content = "No, es solo que sigues pasando todo el día en tu tienda jugando juegos.",
  str_homestory_822801001_5_dialog_content = "Estaba a punto de decirte que salgas y tomes un poco de aire fresco.",
  str_homestory_822801001_6_dialog_content = "Ah... Uf...",
  str_homestory_822801001_7_dialog_content = "Ahí está, terminado. Nos vemos.",
  str_homestory_822801001_8_dialog_content = "¡E-Espera! Deberías al menos dar un paseo antes de volver a entrar, ¿no crees?",
  str_homestory_822801001_9_dialog_content = "Ugh, el aire libre...",
  str_homestory_822801001_10_dialog_content = "¿Por qué odias tanto salir, Batia?",
  str_homestory_822801001_11_dialog_content = "¿No te gusta por aquí?",
  str_homestory_822801001_12_dialog_content = "¡Para nada! No es que este lugar me desagrade o algo así...",
  str_homestory_822801001_13_dialog_content = "¡De hecho, me gusta mucho más que las calles de Umbraton!",
  str_homestory_822801001_14_dialog_content = "Oh... Así que has estado comparando este lugar con Umbraton todo el tiempo...",
  str_homestory_822801001_15_dialog_content = "L-Lo siento, no lo quise decir así!",
  str_homestory_822801001_16_dialog_content = "R-Realmente solo estoy familiarizado con las calles de Umbraton...",
  str_homestory_822801001_17_dialog_content = "¡Lo que es una razón más para visitar diferentes lugares!",
  str_homestory_822801001_18_option_content = "Entonces, ¿dónde deberíamos ir?",
  str_homestory_822801001_19_dialog_content = "Por el rio.",
  str_homestory_822801001_20_dialog_content = "¿Podríamos ir a pescar en uno de los ríos cercanos?",
  str_homestory_822801001_21_dialog_content = "¡Oh, como una versión en la vida real de Maestro Pescador!",
  str_homestory_822801001_22_dialog_content = "No estoy seguro de poder atrapar un pez real, aunque...",
  str_homestory_822801001_23_dialog_content = "Jajaja, bueno, las reglas son un poco diferentes a las de tus juegos.",
  str_homestory_822801001_24_option_content = "El bosque.",
  str_homestory_822801001_25_dialog_content = "Vamos a acampar en el bosque. Podemos encender una fogata, buscar frutas silvestres y cocinar al aire libre.",
  str_homestory_822801001_26_dialog_content = "Oh, eso suena justo como un juego de estilo de gestión.",
  str_homestory_822801001_27_dialog_content = "Trazando el desarrollo de nuestro campamento y siguiendo diferentes procesos de fabricación para asegurar la máxima eficiencia...",
  str_homestory_822801001_28_dialog_content = "Sabes que acampar no tiene puntos ni logros, ¿verdad?",
  str_homestory_822801001_29_dialog_content = "Oh, está bien. Supongo que puedo darle una oportunidad.",
  str_homestory_822801001_30_dialog_content = "Pero, ¿puedo al menos traer mi tienda de campaña si vamos a salir?",
  str_homestory_822801001_31_dialog_content = "Si nos cansamos, siempre podemos entrar y jugar juegos.",
  str_homestory_822801001_32_dialog_content = "Bueno, supongo que no estaría de más.",
  str_homestory_822901001_0_dialog_content = "Dama Victoria, ¿por qué sigues mirando la silla colgante?",
  str_homestory_822901001_1_dialog_content = "¿Hay algo malo con eso?",
  str_homestory_822901001_2_dialog_content = "Simplemente me recuerda a una silla colgante similar en la Orden Verdadera.",
  str_homestory_822901001_3_dialog_content = "Es su silla favorita.",
  str_homestory_822901001_4_dialog_content = "¿Qué paso?",
  str_homestory_822901001_5_dialog_content = "Ocho de cada diez veces que pasaba por allí, veía a Beryl acurrucada leyendo en él.",
  str_homestory_822901001_6_dialog_content = "En cuanto a los otros dos, se quedó dormida en uno de sus libros.",
  str_homestory_822901001_7_dialog_content = "¡Entonces ella lo ha tomado para sí misma!",
  str_homestory_822901001_8_dialog_content = "A veces, veo a Eicy dando vueltas en círculos.",
  str_homestory_822901001_9_dialog_content = "Y siempre está murmurando cosas que la mayoría de las personas nunca entenderían, como...",
  str_homestory_822901001_10_dialog_content = "¡Sería un dispositivo de tortura perfecto con algunos pinchos de hierro añadidos al asiento y al respaldo!",
  str_homestory_822901001_11_dialog_content = "Debes proteger bien esa silla colgante antes de que ella ponga sus manos en ella... ¡Y Beryl también!",
  str_homestory_822901001_12_dialog_content = "No puedes culpar a Eicy por pensar de esa manera.",
  str_homestory_822901001_13_dialog_content = "Realmente parecía un instrumento de tortura cuando estaba cubierto con la sangre de Nails.",
  str_homestory_822901001_14_dialog_content = "¿Incluso Nails?!",
  str_homestory_822901001_15_dialog_content = "No puedes culpar a Nails por eso. Es una silla realmente cómoda.",
  str_homestory_822901001_16_dialog_content = "Incluso nuestro devoto asceta le gustaría sentarse allí a veces.",
  str_homestory_822901001_17_dialog_content = "...",
  str_homestory_822901001_18_dialog_content = "Entonces... ¿Eres el único que no se ha sentado en ello?",
  str_homestory_822901001_19_dialog_content = "Ahora que lo pienso, tienes razón.",
  str_homestory_822901001_20_dialog_content = "Tal vez lo estoy evitando.",
  str_homestory_822901001_21_dialog_content = "¿Evitando... una silla?",
  str_homestory_822901001_22_dialog_content = "Es de la antigua casa de Varaki y una vez perteneció a mi padre.",
  str_homestory_822901001_23_dialog_content = "No sé qué estaba pensando Faust cuando me lo devolvió.",
  str_homestory_822901001_24_dialog_content = "Verlo me recuerda a mis padres, mi infancia y el destino impotente de Varaki.",
  str_homestory_822901001_25_dialog_content = "Yo... no quiero seguir recordando todo eso.",
  str_homestory_822901001_26_dialog_content = "Faust debería aprender a mantener sus manos para sí mismo.",
  str_homestory_822901001_27_dialog_content = "Quizás estaba tratando de recordarme que enfrentar al destino es parte de la Verdad.",
  str_homestory_822901001_28_dialog_content = "La silla colgante es un recuerdo de tu infancia.",
  str_homestory_822901001_29_dialog_content = "Esos recuerdos pueden ser dolorosos, pero también hay alegría en ellos, ¿verdad?",
  str_homestory_822901001_30_dialog_content = "Je, supongo. Papá una vez me sostuvo en sus brazos mientras leía en la silla colgante. Ese es un hermoso recuerdo.",
  str_homestory_822901001_31_dialog_content = "Sin embargo, después de experimentar eventos recientes, finalmente entiendo ahora.",
  str_homestory_822901001_32_dialog_content = "El dolor del pasado solo existe en mi corazón.",
  str_homestory_822901001_33_dialog_content = "Si puedo superarlo, entonces la silla colgante no será más que una silla colgante.",
  str_homestory_822901001_34_dialog_content = "Tal como tu sabiduría natural señaló.",
  str_homestory_822901001_35_dialog_content = "No debería mirarlo fijamente, debería sentarme cómodamente en él.",
  str_homestory_822901001_36_dialog_content = "¡S-Sí! Eso es lo que estaba tratando de decirte!",
  str_homestory_822901001_37_dialog_content = "Por favor, toma asiento. Siempre eres bienvenido a sentarte en mi silla colgante.",
  str_homestory_822901001_38_dialog_content = "Gracias por la hospitalidad, PlayerName.",
  str_homestory_823001001_0_dialog_content = "Esta casa se ve extraña, ¿no es así?",
  str_homestory_823001001_1_dialog_content = "¡Pero su apariencia engaña porque es muy cómodo por dentro!",
  str_homestory_823001001_2_dialog_content = "¿Raro? Para nada...",
  str_homestory_823001001_3_dialog_content = "Su estructura similar a una torre y la colocación de las ventanas hacen que se parezca a un pequeño castillo.",
  str_homestory_823001001_4_dialog_content = "Si lo permites, me gustaría entrenar aquí de vez en cuando.",
  str_homestory_823001001_5_dialog_content = "¡No hay problema!",
  str_homestory_823001001_6_dialog_content = "Usa el lugar cuando quieras.",
  str_homestory_823001001_7_dialog_content = "Ninguno en absoluto...",
  str_homestory_823001001_8_dialog_content = "Si puedes garantizar que no se derramará sangre aquí...",
  str_homestory_823001001_9_dialog_content = "Estoy eternamente agradecido por tu generosidad.",
  str_homestory_823001001_10_dialog_content = "Por cierto, el Sr. Wilhelm está entrenando en reclusión en un castillo, ¿verdad?",
  str_homestory_823001001_11_dialog_content = "¡Oh! S-Sí... ¿Por qué de repente mencionaste a mi mentor?",
  str_homestory_823001001_12_dialog_content = "Estaba pensando... ¿Quieres entrenar en una casa parecida a un castillo...",
  str_homestory_823001001_13_dialog_content = "¿Debido a la influencia del Sr. Wilhelm?",
  str_homestory_823001001_14_dialog_content = "...",
  str_homestory_823001001_15_dialog_content = "Mentir es un pecado. Dado que has visto a través de mis intenciones, solo puedo admitirlo.",
  str_homestory_823001001_16_dialog_content = "Tengo un pequeño deseo de... imitar a mi mentor.",
  str_homestory_823001001_17_dialog_content = "Aunque le prometí que no lo haría.",
  str_homestory_823001001_18_dialog_content = "¡Un ser tan insignificante como yo intentando convertirme en mi mentor es un pecado terrible! Yo...",
  str_homestory_823001001_19_dialog_content = "¡Eso no es cierto! ¿No es muy normal tener el deseo de imitar a alguien a quien respetas?",
  str_homestory_823001001_20_dialog_content = "¿Qué has intentado imitar?",
  str_homestory_823001001_21_dialog_content = "Yo...",
  str_homestory_823001001_22_dialog_content = "Intenté... dejar crecer mi cabello.",
  str_homestory_823001001_23_dialog_content = "...",
  str_homestory_823001001_24_dialog_content = "Pero mi cabello no parece ser adecuado para eso. Un par de gorriones pensaron que mi cabeza era su nido...",
  str_homestory_823001001_25_dialog_content = "Para cuando terminé de arrepentirme, ya había eclosionado un pollito en mi cabeza.",
  str_homestory_823001001_26_dialog_content = "Realmente te arrepentiste durante mucho tiempo...",
  str_homestory_823001001_27_dialog_content = "Después de cortarme el pelo, intenté mantenerme despierto y leer toda la noche como mi mentor.",
  str_homestory_823001001_28_dialog_content = "Pero me quedé dormido mientras caminaba y rodé por las escaleras...",
  str_homestory_823001001_29_dialog_content = "¡Hey, hey!",
  str_homestory_823001001_30_dialog_content = "La espada de mi mentor, Flujo Carmesí, es realmente genial.",
  str_homestory_823001001_31_dialog_content = "Pero mi mentor me detuvo cuando intenté imitar el Flujo Carmesí con mi propia sangre.",
  str_homestory_823001001_32_dialog_content = "¡Oh! Él debe haberte dicho que solo seas tú mismo, ¿verdad?",
  str_homestory_823001001_33_dialog_content = "Mi mentor me preguntó con ternura, \"Nails, mira hacia arriba y dime qué ves.\"",
  str_homestory_823001001_34_dialog_content = "Respondí, \"El cielo, Mentor. El Señor de la Verdad nos está observando desde allí.\"",
  str_homestory_823001001_35_dialog_content = "Mi mentor preguntó, \"¿Sabes por qué podemos ver el cielo?\"",
  str_homestory_823001001_36_dialog_content = "Respondí, \"Porque el Señor lo creó.\"",
  str_homestory_823001001_37_dialog_content = "Mi mentor dijo, \"Es porque tu Flujo Carmesí acaba de cortar nuestro techo.\"",
  str_homestory_823001001_38_dialog_content = "...",
  str_homestory_823001001_39_dialog_content = "Me arrepentí profundamente de mis pecados.",
  str_homestory_823001001_40_dialog_content = "Entonces me di cuenta de que no había aprendido lo más valioso de mi mentor.",
  str_homestory_823001001_41_dialog_content = "Mi mentor nunca se desvió de sus creencias.",
  str_homestory_823001001_42_dialog_content = "Y debería hacer lo mismo. Debería vivir como nací.",
  str_homestory_823001001_43_dialog_content = "Si pudiste llegar a esa conclusión a partir de esa cadena de desastres... quiero decir incidentes...",
  str_homestory_823001001_44_dialog_content = "Debes ser muy perspicaz.",
  str_homestory_823001001_45_dialog_content = "Gracias por las amables palabras, PlayerName.",
  str_homestory_823001001_46_dialog_content = "A cambio, siempre estoy feliz de escuchar tus confesiones en este pequeño castillo.",
  str_homestory_823001001_47_dialog_content = "Ejem, ¡hagámoslo una vez que lo descubra!",
  str_homestory_823101001_0_dialog_content = "Sr. Wilhelm, ¿por qué estás mirando ese pabellón? No hay nada allí.",
  str_homestory_823101001_1_dialog_content = "Me pregunto si este pabellón tuyo tiene un rompecabezas enterrado debajo de él.",
  str_homestory_823101001_2_dialog_content = "¿Un rompecabezas? ¿E-En serio...? ¿Qué te hace pensar eso?",
  str_homestory_823101001_3_dialog_content = "Un solitario pabellón en la naturaleza tiene una afinidad natural con la aventura y los acertijos.",
  str_homestory_823101001_4_dialog_content = "Cosas similares han ocurrido en muchas leyendas.",
  str_homestory_823101001_5_dialog_content = "Inspirado por esto, una vez propuse una pregunta a Victoria.",
  str_homestory_823101001_6_dialog_content = "¿E-En el pabellón?",
  str_homestory_823101001_7_dialog_content = "Comencé irritándola...",
  str_homestory_823101001_8_dialog_content = "¡¿Por qué harías eso?!",
  str_homestory_823101001_9_dialog_content = "Fue una tarea fácil ya que siempre tuvo un sentido de hostilidad hacia mí.",
  str_homestory_823101001_10_dialog_content = "Pero de cómo gritó \"¡Vete al infierno! ¡Demonio!\" y se escapó con los ojos inyectados en sangre...",
  str_homestory_823101001_11_dialog_content = "Puede que haya ido demasiado lejos.",
  str_homestory_823101001_12_dialog_content = "La Dama Victoria era muy... animada en aquel entonces, ¿eh?",
  str_homestory_823101001_13_dialog_content = "Después de eso, dejé deliberadamente todo tipo de \"pistas\" para hacerla pensar que los Varaki tenían un tesoro ancestral.",
  str_homestory_823101001_14_dialog_content = "Y si lo encontrara, podría derrocarme y recuperar la posición de jefa de familia.",
  str_homestory_823101001_15_dialog_content = "Tienes una relación tan retorcida...",
  str_homestory_823101001_16_dialog_content = "No decepcionó. Ella descifró exitosamente las pistas y llegó a la conclusión correcta.",
  str_homestory_823101001_17_dialog_content = "La ubicación del tesoro ancestral estaba inscrita en el pabellón en lo profundo del jardín.",
  str_homestory_823101001_18_dialog_content = "What happened next?",
  str_homestory_823101001_19_dialog_content = "Por supuesto, localizar el pabellón no fue el final de todo.",
  str_homestory_823101001_20_dialog_content = "Tuvo que resolver los acertijos tallados en las losas de piedra del pabellón y descubrir la verdadera ubicación del tesoro.",
  str_homestory_823101001_21_dialog_content = "Debería mencionar que mi envejecimiento artificial de las losas de piedra fue impecable.",
  str_homestory_823101001_22_dialog_content = "...",
  str_homestory_823101001_23_dialog_content = "Entonces... ¿Se te ocurrieron esos acertijos? ¿Cuáles eran?",
  str_homestory_823101001_24_dialog_content = "No eran nada. Solo algunas preguntas de conocimiento general sobre historia, mitos y fábulas, y algunos problemas de matemáticas.",
  str_homestory_823101001_25_dialog_content = "Solo tendría que estudiar durante una semana para pasar por todo con facilidad.",
  str_homestory_823101001_26_dialog_content = "Tengo la sensación de que no terminó bien...",
  str_homestory_823101001_27_dialog_content = "Depende de cómo lo mires. Ella tuvo éxito, justo como pensé que lo haría.",
  str_homestory_823101001_28_dialog_content = "Pero realmente no pude entender por qué se enojó tanto después de encontrar el tesoro...",
  str_homestory_823101001_29_dialog_content = "Permíteme preguntarte ahora. ¿Qué enterraste como el tesoro?",
  str_homestory_823101001_30_dialog_content = "La miel favorita de Victoria. Un tarro entero que fue cosechado fresco ese año.",
  str_homestory_823101001_31_dialog_content = "¡¿Eso es todo?!",
  str_homestory_823101001_32_dialog_content = "¿No es eso suficiente? Estaba claramente escrito en \"Cómo lidiar con chicas adolescentes rebeldes\"—",
  str_homestory_823101001_33_dialog_content = "\"Prepara algo que le guste. Nunca puedes equivocarte con cosas dulces.\"",
  str_homestory_823101001_34_dialog_content = "Realmente no entiendo cuál es el problema.",
  str_homestory_823101001_35_dialog_content = "¿¡Por qué simplemente no le diste la miel!?",
  str_homestory_823101001_36_dialog_content = "¿Recuerdas cómo es hostil hacia mí?",
  str_homestory_823101001_37_dialog_content = "Provocarse el uno al otro no es demasiado aburrido, pero es realmente agotador.",
  str_homestory_823101001_38_dialog_content = "Entonces, no me importaba distraerla con algo más.",
  str_homestory_823101001_39_dialog_content = "Pasó una semana esforzando su mente y estudiando historia, fábulas y matemáticas mientras ardía de anticipación...",
  str_homestory_823101001_40_dialog_content = "Sin embargo, al final, todo lo que encontró fue un nuevo tarro de miel. No era diferente a que tú te burlaras de ella por ser engañada...",
  str_homestory_823101001_41_dialog_content = "¿Todavía no entiendes por qué estaba enfadada?",
  str_homestory_823101001_42_dialog_content = "Tienes un punto.",
  str_homestory_823101001_43_dialog_content = "Pero esa no es razón para verter miel sobre mi asiento antes de la reunión de los jefes de familia...",
  str_homestory_823101001_44_dialog_content = "¡No tuve más opción que sentarme en la miel y actuar como si nada estuviera mal durante toda la duración de la reunión!",
  str_homestory_823101001_45_dialog_content = "¿Qué piensas?",
  str_homestory_823101001_46_dialog_content = "Te lo merecías.",
  str_homestory_823101001_47_dialog_content = "Obtuviste lo que te merecías.",
  str_homestory_823101001_48_dialog_content = "Tch..."
}
return config
